    public array $advisoryLocks = [];

    /** Simulate a database router without usable MySQL named locks. */
    public bool $namedLocksUnavailable = false;

    /** @var array<int,string|array{0:string,1:float,2:string}> */
    public array $queries = [];

    /** @var array<int,array{sql:string,args:array<int,mixed>}> */
