    /** @var array<int,array<string,int>> */
    public array $docLengths = [];

    /** @var array<int,array<string,mixed>> */
    public array $docMeta = [];

    /** @var array<string,array<string,int>> */
    public array $meta = [];

    /** @var array<int|string,array<string,mixed>> */
    public array $queue = [];

    /** Durable cursor epoch is metadata, not pending queue work. */
    public int $searchEpoch = 0;

    /** Random identity retained across epoch increments and replaced only with the row. */
    public string $searchEpochIncarnation = '';

    /** @var array<string,int> */
    private array $termIdsByKey = [];

    /** @var array<int,string> */
    private array $termKeysById = [];

    private int $nextTermId = 1;

    /** @var array<string,mixed>|null */
    private ?array $transactionSnapshot = null;

    /** @var array<int,object> */
    public array $postRows = [];

    /** @var array<int,array{kind:string,post_id:int,key:string,occurrence:int}> */
    private array $dependencySources = [];

    /** @var array<string,int> */
    private array $dependencySourceIds = [];

    private int $nextDependencySourceId = 1;

    /** @var int[] */
    public array $dependencyValueSourceIdsRequested = [];

    /** @var string[] */
    public array $dependencyValueQueries = [];

    public int $dependencyValueBytesProjected = 0;

    /** @var array<string,string[]> */
    public array $schemaColumns = [
        'wp_posts' => ['ID', 'post_type', 'post_status'],
        'wp_term_relationships' => ['object_id', 'term_taxonomy_id'],
        'wp_fts_terms' => ['term_id', 'lang', 'kind', 'term', 'doc_freq'],
        'wp_fts_postings' => ['term_id', 'post_id', 'impact'],
        'wp_fts_documents' => ['post_id', 'primary_lang', 'content_hash', 'snippet_text', 'indexed_at'],
        'wp_fts_work' => ['job_key', 'kind', 'post_id', 'generation', 'state', 'available_at', 'attempts', 'claim_token', 'claimed_generation', 'claim_expires_at', 'cursor_post_id', 'scope_coverage', 'scope_incarnation', 'scope_subject_type', 'scope_subject_id', 'payload', 'last_error_code', 'last_error_at'],
    ];

    /** @var array<string,array<string,array{Type?:string,Null?:string,Extra?:string}>> */
    public array $schemaColumnDefinitions = [];

    /** @var array<string,array<string,string[]>> */
    public array $schemaIndexes = [
        'wp_posts' => [
            'PRIMARY' => ['ID'],
            'wp_fts_type_status_id' => ['post_type', 'post_status', 'ID'],
        ],
        'wp_term_relationships' => [
            'PRIMARY' => ['object_id', 'term_taxonomy_id'],
            'term_taxonomy_id' => ['term_taxonomy_id'],
            'wp_fts_term_object' => ['term_taxonomy_id', 'object_id'],
        ],
        'wp_fts_terms' => ['PRIMARY' => ['term_id'], 'term_identity' => ['lang', 'kind', 'term'], 'empty_terms' => ['doc_freq']],
        'wp_fts_postings' => ['PRIMARY' => ['term_id', 'post_id'], 'post_term_impact' => ['post_id', 'term_id', 'impact']],
        'wp_fts_documents' => ['PRIMARY' => ['post_id']],
        'wp_fts_work' => ['PRIMARY' => ['job_key'], 'ready' => ['kind', 'state', 'available_at', 'post_id', 'job_key'], 'recoverable' => ['kind', 'state', 'claim_expires_at', 'available_at', 'post_id', 'job_key'], 'claim_token' => ['claim_token', 'post_id'], 'kind_job' => ['kind', 'job_key'], 'scope_subject' => ['kind', 'scope_coverage', 'scope_subject_type', 'scope_subject_id'], 'dirty' => ['post_id', 'kind']],
    ];

    /** @var array<string,array<string,bool>> */
    public array $schemaUniqueIndexes = [
        'wp_posts' => ['PRIMARY' => true],
        'wp_term_relationships' => ['PRIMARY' => true],
        'wp_fts_terms' => ['PRIMARY' => true, 'term_identity' => true],
        'wp_fts_postings' => ['PRIMARY' => true],
        'wp_fts_documents' => ['PRIMARY' => true],
        'wp_fts_work' => ['PRIMARY' => true],
    ];

    /** @var array<string,array<string,array<int,int>>> */
    public array $schemaIndexSubParts = [];

    /** @var array<string,array<string,bool>> */
    public array $schemaInvisibleIndexes = [];

    /** @var array<string,string> Overrides; known fake tables default to InnoDB. */
    public array $schemaEngines = [];

    public function prepare(string $sql, mixed ...$args): WP_FTS_Test_Prepared_SQL
    {
        $this->prepared[] = ['sql' => $sql, 'args' => $args];

        return new WP_FTS_Test_Prepared_SQL($sql, $args);
    }

    public function esc_like(string $text): string
    {
        return addcslashes($text, '_%\\');
    }

    public function get_blog_prefix(int $blog_id = 0): string
    {
        return $blog_id <= 1 ? $this->base_prefix : $this->base_prefix . $blog_id . '_';
    }

    /** Emulates scalar wpdb reads while recording their statement cost. */
    public function get_var(mixed $statement, int $x = 0, int $y = 0): mixed
    {
        [$sql, $args] = $this->statement_parts($statement);
        $this->record_read_query($sql);
        $this->last_error = '';
        if ($sql === 'SELECT 1 FROM wp_options WHERE option_name = %s LIMIT 1') {
            $options =& wp_fts_test_option_store();
            return array_key_exists((string) ($args[0] ?? ''), $options) ? 1 : null;
        }
        if (
            str_starts_with($sql, 'SELECT option_value FROM wp_options WHERE option_name = %s')
            && (string) ($args[0] ?? '') === 'wp_fts_network_lifecycle_lock'
        ) {
            return $GLOBALS['wp_fts_test_network_lifecycle_rows']['wp_fts_network_lifecycle_lock'] ?? null;
        }
        if (str_starts_with($sql, 'SELECT option_value FROM wp_options WHERE option_name = %s')) {
            $options =& wp_fts_test_option_store();
            $name = (string) ($args[0] ?? '');

            return array_key_exists($name, $options) ? maybe_serialize($options[$name]) : null;
        }
        if (
            str_starts_with($sql, 'SELECT generation FROM ' . $this->prefix . 'fts_work')
            && (string) ($args[0] ?? '') === WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY
        ) {
            return $this->searchEpoch > 0 ? $this->searchEpoch : null;
        }
        if ($sql === 'SHOW TABLES LIKE %s') {
            $requested = (string) ($args[0] ?? '');
            $literal = str_replace(['\\_', '\\%'], ['_', '%'], $requested);
            return $this->queueTableExists && $literal === $this->prefix . 'fts_work'
                ? $literal
                : null;
        }
        if ($sql === 'SELECT COUNT(*) FROM wp_fts_work') {
            return count($this->queue);
        }
        if ($sql === "SELECT COUNT(*) FROM wp_fts_work WHERE kind IN ('post','scope')") {
            return count(array_filter(
                $this->queue,
                static fn(array $row): bool => in_array((string) ($row['kind'] ?? ''), ['post', 'scope'], true)
            ));
        }
        if (str_contains($sql, 'bounded_pending_work')) {
            foreach ($this->queue as $row) {
                if (in_array((string) ($row['kind'] ?? ''), ['post', 'scope'], true)) {
                    return 1;
                }
            }
            return null;
        }
        if (
            str_starts_with($sql, "SELECT 1 FROM wp_fts_work\nWHERE kind = 'scope'")
            && str_contains($sql, "scope_coverage IN ('global','corpus')")
        ) {
            foreach ($this->queue as $row) {
                if (
                    (string) ($row['kind'] ?? '') === 'scope'
                    && in_array((string) ($row['scope_coverage'] ?? ''), ['global', 'corpus'], true)
                ) {
                    return 1;
                }
            }
            return null;
        }
        if ($sql === "SELECT COUNT(*) FROM wp_fts_work WHERE state IN ('ready','retry','leased','guarded')") {
            return count(array_filter(
                $this->queue,
                static fn(array $row): bool => in_array((string) ($row['kind'] ?? ''), ['post', 'scope'], true)
                    && in_array((string) ($row['state'] ?? ''), ['ready', 'retry', 'leased', 'guarded'], true)
            ));
        }
        if (
            $sql === "SELECT COUNT(*) FROM wp_fts_work\nWHERE kind IN ('post','scope') AND state IN ('ready','retry','leased','guarded')"
        ) {
            return count(array_filter(
                $this->queue,
                static fn(array $row): bool => in_array((string) ($row['kind'] ?? ''), ['post', 'scope'], true)
                    && in_array((string) ($row['state'] ?? ''), ['ready', 'retry', 'leased', 'guarded'], true)
            ));
        }
        if (
            (str_starts_with($sql, 'SELECT MIN(CASE') || str_contains($sql, 'bounded_next_available'))
            && str_contains($sql, 'FROM wp_fts_work')
        ) {
            $available = [];
            $foregroundWatchdogAt = time() + WP_FTS_Index_Queue::FOREGROUND_OWNER_WATCHDOG_SECONDS;
            $projectFencesToWatchdog = str_contains($sql, 'wp_fts:nonfree-fence-watchdog');
            $onlyGuardedFencesAreRunnable = str_contains($sql, 'wp_fts:only-guarded-fence-recovery');
            $preserveLaterFenceDue = str_contains($sql, '.due_at < ');
            $states = $onlyGuardedFencesAreRunnable
                ? ['guarded', 'ready', 'retry', 'leased']
                : ['guarded', 'fenced', 'ready', 'retry', 'leased'];
            foreach (['post', 'scope'] as $kind) {
                foreach ($states as $state) {
                    $rows = array_values(array_filter(
                        $this->queue,
                        static fn(array $row): bool => (string) ($row['kind'] ?? '') === $kind
                            && (string) ($row['state'] ?? '') === $state
                    ));
                    usort($rows, static function (array $left, array $right) use ($state): int {
                        return ($state === 'leased'
                                ? ((int) ($left['claim_expires_at'] ?? 0) <=> (int) ($right['claim_expires_at'] ?? 0))
                                    ?: ((int) ($left['available_at'] ?? 0) <=> (int) ($right['available_at'] ?? 0))
                                : ((int) ($left['available_at'] ?? 0) <=> (int) ($right['available_at'] ?? 0)))
                            ?: ((int) ($left['post_id'] ?? 0) <=> (int) ($right['post_id'] ?? 0))
                            ?: strcmp((string) ($left['job_key'] ?? ''), (string) ($right['job_key'] ?? ''));
                    });
                    $row = $rows[0] ?? null;
                    if (!is_array($row)) {
                        continue;
                    }
                    $actualDue = $state === 'leased'
                        ? max(1, (int) ($row['claim_expires_at'] ?? 0))
                        : max(1, (int) ($row['available_at'] ?? 0));
                    $projectFence = in_array($state, ['guarded', 'fenced'], true)
                        && $projectFencesToWatchdog;
                    $at = $projectFence
                        ? ($preserveLaterFenceDue ? max($foregroundWatchdogAt, $actualDue) : $foregroundWatchdogAt)
                        : $actualDue;
                    $available[] = $at;
                }
            }

            return $available === [] ? null : min($available);
        }
        if ($sql === 'SELECT RELEASE_LOCK(%s)') {
            $lockName = (string) ($args[0] ?? '');
            if (($this->advisoryLocks[$lockName] ?? 0) !== 1) {
                return 0;
            }
            unset($this->advisoryLocks[$lockName]);
            return 1;
        }
        if ($sql === 'SELECT GET_LOCK(%s, %d)') {
            if ($this->namedLocksUnavailable) {
                return null;
            }
            $lockName = (string) ($args[0] ?? '');
            if (isset($this->advisoryLocks[$lockName]) && $this->advisoryLocks[$lockName] !== 1) {
                return 0;
            }
            $this->advisoryLocks[$lockName] = 1;
            return 1;
        }
        if ($sql === 'SELECT CASE WHEN IS_USED_LOCK(%s) IS NULL THEN GET_LOCK(%s, 0) ELSE 0 END') {
            $lockName = (string) ($args[0] ?? '');
            if (isset($this->advisoryLocks[$lockName])) {
                return 0;
            }
            $this->advisoryLocks[$lockName] = 1;
            return 1;
        }
        if ($sql === 'SELECT COUNT(*) FROM wp_fts_queue') {
            return count($this->queue);
        }

        if (str_starts_with($sql, 'SELECT COALESCE(MAX(d.post_id), 0)') && str_contains($sql, 'FROM ' . $this->prefix . 'fts_documents d')) {
            return $this->docs === [] ? 0 : max(array_map('intval', array_keys($this->docs)));
        }

        if (str_starts_with($sql, 'SELECT COUNT(*)') && str_contains($sql, 'FROM wp_fts_documents d')) {
            $afterCursor = max(0, (int) ($args[0] ?? 0));
            $maxDocId = max(0, (int) ($args[1] ?? PHP_INT_MAX));

            return count(array_filter(
                $this->docs,
                static fn(array $_doc, int $docId): bool => $docId > $afterCursor && $docId <= $maxDocId,
                ARRAY_FILTER_USE_BOTH
            ));
        }

        if (str_starts_with($sql, 'SELECT COALESCE(MAX(d.doc_id), 0)') && str_contains($sql, 'FROM ' . $this->prefix . 'fts_docs d')) {
            $ids = array_keys(array_filter(
                $this->docs,
                static fn(array $doc): bool => ($doc['is_deleted'] ?? 1) === 0
            ));

            return $ids === [] ? 0 : max(array_map('intval', $ids));
        }

        if (str_starts_with($sql, 'SELECT COUNT(*)') && str_contains($sql, 'FROM wp_fts_docs d')) {
            $afterCursor = max(0, (int) ($args[0] ?? 0));
            $maxDocId = max(0, (int) ($args[1] ?? 0));

            return count(array_filter(
                $this->docs,
                static fn(array $doc, int $docId): bool => $docId > $afterCursor && $docId <= $maxDocId && ($doc['is_deleted'] ?? 1) === 0,
                ARRAY_FILTER_USE_BOTH
            ));
        }

        if (str_starts_with($sql, 'SELECT COUNT(DISTINCT p.ID)')) {
            $offset = 0;
            $usesUnifiedVisibility = !str_contains($sql, 'p.post_status = %s')
                && str_contains($sql, 'p.post_type IN (')
                && str_contains($sql, 'p.post_status IN (');
            $eligibleTypes = $usesUnifiedVisibility
                ? array_map('strval', $this->prepared_in_args($sql, 'p.post_type', '%s', $args, $offset))
                : [];
            $eligibleStatuses = $usesUnifiedVisibility
                ? array_map('strval', $this->prepared_in_args($sql, 'p.post_status', '%s', $args, $offset))
                : [];
            $publicStatus = !$usesUnifiedVisibility && str_contains($sql, 'p.post_status = %s')
                ? (string) ($args[$offset++] ?? '')
                : '';
            $publicTypes = !$usesUnifiedVisibility
                ? $this->prepared_in_args($sql, 'p.post_type', '%s', $args, $offset)
                : [];
            $adminType = null;
            $adminStatuses = [];
            if (str_contains($sql, 'p.post_type = %s')) {
                $adminType = (string) ($args[$offset++] ?? '');
                $adminStatuses = $this->prepared_in_args($sql, 'p.post_status', '%s', $args, $offset);
            }
            $afterCursor = str_contains($sql, 'p.ID > %d') ? max(0, (int) ($args[$offset++] ?? 0)) : 0;
            $requiresIndexedDoc = str_contains($sql, 'JOIN wp_fts_docs d') || str_contains($sql, 'JOIN wp_fts_documents d');

            $counted = [];
            foreach ($this->postRows as $row) {
                $postId = isset($row->ID) ? (int) $row->ID : 0;
                if ($postId <= 0) {
                    continue;
                }

                if ($afterCursor > 0 && $postId <= $afterCursor) {
                    continue;
                }

                if ($requiresIndexedDoc && !isset($this->docs[$postId])) {
                    continue;
                }

                if (isset($row->post_password) && (string) $row->post_password !== '') {
                    continue;
                }

                $type = isset($row->post_type) ? (string) $row->post_type : 'post';
                $status = isset($row->post_status) ? (string) $row->post_status : 'draft';
                if ($usesUnifiedVisibility) {
                    if (in_array($type, $eligibleTypes, true) && in_array($status, $eligibleStatuses, true)) {
                        $counted[$postId] = true;
                    }
                    continue;
                }
                $publicEligible = $publicStatus !== '' && $status === $publicStatus && in_array($type, array_map('strval', $publicTypes), true);
                $adminEligible = $adminType !== null && $type === $adminType && in_array($status, array_map('strval', $adminStatuses), true);
                if ($publicEligible || $adminEligible) {
                    $counted[$postId] = true;
                }
            }

            return count($counted);
        }

        return null;
    }

    /** Applies a mutating SQL statement to the in-memory wpdb fixture. */
    public function query(mixed $statement): int|bool
    {
        [$sql, $args] = $this->statement_parts($statement);
        $this->queries[] = $sql;
        if (is_callable($this->queryObserver)) {
            ($this->queryObserver)($sql);
        }
        $docWriteFailure = $this->doc_write_failure($sql, $args);
        if ($docWriteFailure !== null) {
            [$docId, $message] = $docWriteFailure;
            $this->failedDocWriteAttempts[$docId] = ($this->failedDocWriteAttempts[$docId] ?? 0) + 1;
            $this->last_error = $message;
            return false;
        }
        if ($this->failQueryPrefix !== null && str_starts_with($sql, $this->failQueryPrefix)) {
            $this->last_error = "simulated failure for {$this->failQueryPrefix}";
            return false;
        }
        if ($this->failQueryNeedle !== null && str_contains($sql, $this->failQueryNeedle)) {
            $this->failQueryNeedleMatches++;
            if ($this->failQueryNeedleMatches === $this->failQueryNeedleOccurrence) {
                $this->last_error = "simulated failure for occurrence {$this->failQueryNeedleOccurrence} of {$this->failQueryNeedle}";
                return false;
            }
        }
        $this->last_error = '';

        if ($sql === 'START TRANSACTION') {
            $this->transactionSnapshot = [
                'terms' => $this->ftsTerms,
                'postings' => $this->postings,
                'docs' => $this->docs,
                'queue' => $this->queue,
                'searchEpoch' => $this->searchEpoch,
                'docLengths' => $this->docLengths,
                'docMeta' => $this->docMeta,
                'meta' => $this->meta,
                'termIdsByKey' => $this->termIdsByKey,
                'termKeysById' => $this->termKeysById,
                'nextTermId' => $this->nextTermId,
                'options' => wp_fts_test_option_store(),
            ];
            return true;
        }

        if ($sql === 'COMMIT') {
            $this->transactionSnapshot = null;
            if ($this->failCommitAfterApply) {
                $this->last_error = 'simulated failure after applying COMMIT';
                return false;
            }
            return true;
        }

        if ($sql === 'ROLLBACK') {
            if ($this->transactionSnapshot !== null) {
                $this->ftsTerms = $this->transactionSnapshot['terms'];
                $this->postings = $this->transactionSnapshot['postings'];
                $this->docs = $this->transactionSnapshot['docs'];
                $this->queue = $this->transactionSnapshot['queue'];
                $this->searchEpoch = $this->transactionSnapshot['searchEpoch'];
                $this->docLengths = $this->transactionSnapshot['docLengths'];
                $this->docMeta = $this->transactionSnapshot['docMeta'];
                $this->meta = $this->transactionSnapshot['meta'];
                $this->termIdsByKey = $this->transactionSnapshot['termIdsByKey'];
                $this->termKeysById = $this->transactionSnapshot['termKeysById'];
                $this->nextTermId = $this->transactionSnapshot['nextTermId'];
                $options =& wp_fts_test_option_store();
                $options = $this->transactionSnapshot['options'];
            }
            $this->transactionSnapshot = null;
            return true;
        }

        if (
            (str_starts_with($sql, 'INSERT IGNORE INTO wp_options ')
                || str_starts_with($sql, 'INSERT OR IGNORE INTO wp_options '))
            && (string) ($args[0] ?? '') === 'wp_fts_network_lifecycle_lock'
        ) {
            $name = (string) $args[0];
            if (isset($GLOBALS['wp_fts_test_network_lifecycle_rows'][$name])) {
                return 0;
            }
            $GLOBALS['wp_fts_test_network_lifecycle_rows'][$name] = (string) ($args[1] ?? '');
            return 1;
        }
        if (
            str_starts_with($sql, 'UPDATE wp_options SET option_value = %s WHERE option_name = %s AND option_value = %s')
            && (string) ($args[1] ?? '') === 'wp_fts_network_lifecycle_lock'
        ) {
            $name = (string) $args[1];
            if (($GLOBALS['wp_fts_test_network_lifecycle_rows'][$name] ?? null) !== (string) ($args[2] ?? '')) {
                return 0;
            }
            $GLOBALS['wp_fts_test_network_lifecycle_rows'][$name] = (string) ($args[0] ?? '');
            return 1;
        }
        if (
            str_starts_with($sql, 'DELETE FROM wp_options WHERE option_name = %s AND option_value = %s')
            && (string) ($args[0] ?? '') === 'wp_fts_network_lifecycle_lock'
        ) {
            $name = (string) $args[0];
            if (($GLOBALS['wp_fts_test_network_lifecycle_rows'][$name] ?? null) !== (string) ($args[1] ?? '')) {
                return 0;
            }
            unset($GLOBALS['wp_fts_test_network_lifecycle_rows'][$name]);
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM `wp_sitemeta` WHERE site_id = %d')) {
            $optionName = (string) ($args[1] ?? '');
            $expected = (string) ($args[2] ?? '');
            $stored = $GLOBALS['wp_fts_test_network_options'][$optionName] ?? null;
            if (!is_scalar($stored) || maybe_serialize($stored) !== $expected) {
                return 0;
            }
            unset($GLOBALS['wp_fts_test_network_options'][$optionName]);
            return 1;
        }

        $createLikeTokens = explode('`', $sql);
        if (
            count($createLikeTokens) === 5
            && $createLikeTokens[0] === 'CREATE TABLE '
            && $createLikeTokens[2] === ' LIKE '
            && $createLikeTokens[4] === ''
            && $createLikeTokens[1] !== ''
            && $createLikeTokens[3] !== ''
            && strspn($createLikeTokens[1], 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_') === strlen($createLikeTokens[1])
            && strspn($createLikeTokens[3], 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_') === strlen($createLikeTokens[3])
        ) {
            $target = $createLikeTokens[1];
            $source = $createLikeTokens[3];
            $this->schemaColumns[$target] = $this->schemaColumns[$source] ?? [];
            $this->schemaIndexes[$target] = $this->schemaIndexes[$source] ?? [];
            $this->schemaUniqueIndexes[$target] = $this->schemaUniqueIndexes[$source] ?? [];
            $this->schemaEngines[$target] = $this->schemaEngines[$source] ?? 'InnoDB';
            return true;
        }

        if (str_starts_with($sql, 'CREATE TABLE')) {
            $parts = explode(' ', trim(strtok($sql, "\r\n") ?: ''));
            $this->restore_schema_contract(trim((string) ($parts[2] ?? ''), '`'));
            return true;
        }

        $recoverableIndexSql = 'CREATE INDEX recoverable ON `' . $this->prefix
            . 'fts_work`(kind,state,claim_expires_at,available_at,post_id,job_key)';
        if ($sql === $recoverableIndexSql) {
            $this->schemaIndexes[$this->prefix . 'fts_work']['recoverable'] = [
                'kind',
                'state',
                'claim_expires_at',
                'available_at',
                'post_id',
                'job_key',
            ];
            return true;
        }

        $scopeIndexes = [
            'targeted' => [
                'table' => $this->term_relationships,
                'name' => WP_FTS_Storage_Mysql::TARGETED_SCOPE_INDEX_NAME,
                'columns' => ['term_taxonomy_id', 'object_id'],
            ],
            'filtered' => [
                'table' => $this->posts,
                'name' => WP_FTS_Storage_Mysql::FILTERED_SCOPE_INDEX_NAME,
                'columns' => ['post_type', 'post_status', 'ID'],
            ],
        ];
        foreach ($scopeIndexes as $scopeIndex) {
            $table = (string) $scopeIndex['table'];
            $name = (string) $scopeIndex['name'];
            $columns = array_map('strval', $scopeIndex['columns']);
            $quotedColumns = implode(',', array_map(static fn(string $column): string => "`{$column}`", $columns));
            if ($sql === "CREATE INDEX `{$name}` ON `{$table}`({$quotedColumns})") {
                $this->schemaIndexes[$table][$name] = $columns;
                return true;
            }
            if ($sql === "DROP INDEX `{$name}` ON `{$table}`") {
                if (!isset($this->schemaIndexes[$table][$name])) {
                    return 0;
                }
                unset($this->schemaIndexes[$table][$name]);
                return true;
            }
        }

        if (str_starts_with($sql, 'DROP TABLE ')) {
            $list = substr($sql, strlen('DROP TABLE '));
            if (str_starts_with($list, 'IF EXISTS ')) {
                $list = substr($list, strlen('IF EXISTS '));
            }
            foreach (explode(',', $list) as $rawTable) {
                $table = trim($rawTable, " `\t\r\n");
                unset($this->schemaColumns[$table], $this->schemaIndexes[$table], $this->schemaUniqueIndexes[$table], $this->schemaEngines[$table]);
                if ($table === $this->prefix . 'fts_terms') {
                    $this->ftsTerms = [];
                    $this->termIdsByKey = [];
                    $this->termKeysById = [];
                } elseif ($table === $this->prefix . 'fts_postings') {
                    $this->postings = [];
                } elseif ($table === $this->prefix . 'fts_documents') {
                    $this->docs = [];
                } elseif ($table === $this->prefix . 'fts_work') {
                    $this->queue = [];
                }
            }
            return true;
        }

        if (str_starts_with($sql, 'RENAME TABLE ')) {
            $renames = explode(',', substr($sql, strlen('RENAME TABLE ')));
            foreach ($renames as $rename) {
                $renameTokens = explode('`', trim($rename));
                if (
                    count($renameTokens) !== 5
                    || $renameTokens[0] !== ''
                    || $renameTokens[2] !== ' TO '
                    || $renameTokens[4] !== ''
                    || $renameTokens[1] === ''
                    || $renameTokens[3] === ''
                    || strspn($renameTokens[1], 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_') !== strlen($renameTokens[1])
                    || strspn($renameTokens[3], 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_') !== strlen($renameTokens[3])
                ) {
                    continue;
                }
                $source = $renameTokens[1];
                $target = $renameTokens[3];
                foreach (['schemaColumns', 'schemaIndexes', 'schemaUniqueIndexes', 'schemaEngines'] as $property) {
                    if (isset($this->{$property}[$source])) {
                        $this->{$property}[$target] = $this->{$property}[$source];
                        unset($this->{$property}[$source]);
                    }
                }
            }
            $this->ftsTerms = [];
            $this->postings = [];
            $this->docs = [];
            $this->queue = [];
            $this->termIdsByKey = [];
            $this->termKeysById = [];
            $this->nextTermId = 1;
            return true;
        }

        if (
            $this->options !== null
            && str_starts_with($sql, 'INSERT IGNORE INTO ' . $this->options . ' (option_name,option_value,autoload)')
        ) {
            $options =& wp_fts_test_option_store();
            if (
                str_contains($sql, 'WHERE NOT EXISTS')
                && array_key_exists((string) ($args[3] ?? ''), $options)
            ) {
                return 0;
            }
            if (str_contains($sql, 'WHERE NOT EXISTS')) {
                $args = array_slice($args, 0, 2);
            }
            $inserted = 0;
            for ($offset = 0; $offset + 1 < count($args); $offset += 2) {
                $optionName = (string) $args[$offset];
                if ($optionName === '' || array_key_exists($optionName, $options)) {
                    continue;
                }
                $serializedValue = $args[$offset + 1];
                $value = is_string($serializedValue)
                    ? @unserialize($serializedValue, ['allowed_classes' => false])
                    : $serializedValue;
                $options[$optionName] = $value;
                $inserted++;
            }
            return $inserted;
        }

        if (
            $this->options !== null
            && str_starts_with($sql, 'UPDATE ' . $this->options . ' SET option_value = %s')
            && str_contains($sql, 'WHERE option_name = %s AND option_value = %s')
        ) {
            $serializedReplacement = $args[0] ?? null;
            $optionName = (string) ($args[1] ?? '');
            $expectedValue = $args[2] ?? null;
            $options =& wp_fts_test_option_store();
            if (
                !array_key_exists($optionName, $options)
                || maybe_serialize($options[$optionName]) !== $expectedValue
            ) {
                return 0;
            }
            if (
                $this->mysqlMatchedNoopUpdatesReturnZero
                && maybe_serialize($options[$optionName]) === $serializedReplacement
            ) {
                $this->mysqlMatchedNoopUpdateCount++;
                return 0;
            }
            $options[$optionName] = is_string($serializedReplacement)
                ? @unserialize($serializedReplacement, ['allowed_classes' => false])
                : $serializedReplacement;
            return 1;
        }

        if (
            $this->options !== null
            && str_starts_with($sql, 'DELETE FROM ' . $this->options . ' WHERE option_name = %s AND option_value = %s')
        ) {
            $optionName = (string) ($args[0] ?? '');
            $expectedValue = $args[1] ?? null;
            $options =& wp_fts_test_option_store();
            if (
                !array_key_exists($optionName, $options)
                || maybe_serialize($options[$optionName]) !== $expectedValue
            ) {
                return 0;
            }
            unset($options[$optionName]);
            $GLOBALS['wp_fts_test_deleted_options'][] = [
                'blog_id' => wp_fts_test_current_option_blog_id(),
                'name' => $optionName,
                'existed' => true,
            ];
            return 1;
        }

        if (str_contains($sql, 'fts_work')) {
            $result = $this->query_v4_work($sql, $args);
            $this->persist_direct_durability_fixture();
            return $result;
        }

        if (
            str_contains($sql, 'wp_fts_documents')
            || str_contains($sql, 'wp_fts_postings')
            || str_contains($sql, 'wp_fts_terms')
        ) {
            $handled = $this->query_v4_storage($sql, $args);
            if ($handled !== null) {
                return $handled;
            }
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_queue')) {
            $postId = (int) ($args[0] ?? 0);
            $now = max(0, (int) ($args[1] ?? 0));
            if (isset($this->queue[$postId])) {
                $this->queue[$postId]['available_at'] = $now;
                if (str_contains($sql, 'generation = generation + 1')) {
                    $this->queue[$postId]['generation']++;
                    $this->queue[$postId]['attempts'] = 0;
                }
            } else {
                $this->queue[$postId] = [
                    'generation' => 1,
                    'available_at' => $now,
                    'attempts' => 0,
                    'claim_token' => '',
                    'claimed_generation' => 0,
                    'claim_expires_at' => 0,
                ];
            }
            ksort($this->queue, SORT_NUMERIC);
            return 1;
        }

        if (str_starts_with($sql, "UPDATE wp_fts_queue\nSET claim_token = %s")) {
            $token = (string) ($args[0] ?? '');
            $expiresAt = max(0, (int) ($args[1] ?? 0));
            $postId = (int) ($args[2] ?? 0);
            $generation = (int) ($args[3] ?? 0);
            $availableAt = (int) ($args[4] ?? 0);
            $expiredAt = (int) ($args[5] ?? 0);
            $row = $this->queue[$postId] ?? null;
            if (
                $row === null
                || $row['generation'] !== $generation
                || $row['available_at'] > $availableAt
                || ($row['claim_token'] !== '' && $row['claim_expires_at'] > $expiredAt)
            ) {
                return 0;
            }

            $this->queue[$postId]['claim_token'] = $token;
            $this->queue[$postId]['claimed_generation'] = $generation;
            $this->queue[$postId]['claim_expires_at'] = $expiresAt;
            return 1;
        }

        if (str_starts_with($sql, "DELETE FROM wp_fts_queue\nWHERE post_id = %d")) {
            $postId = (int) ($args[0] ?? 0);
            $token = (string) ($args[1] ?? '');
            $claimedGeneration = (int) ($args[2] ?? 0);
            $generation = (int) ($args[3] ?? 0);
            $row = $this->queue[$postId] ?? null;
            if (
                $row === null
                || $row['claim_token'] !== $token
                || $row['claimed_generation'] !== $claimedGeneration
                || $row['generation'] !== $generation
            ) {
                return 0;
            }

            unset($this->queue[$postId]);
            return 1;
        }

        if (str_starts_with($sql, "UPDATE wp_fts_queue\nSET attempts = %d")) {
            $attempts = max(0, (int) ($args[0] ?? 0));
            $availableAt = max(0, (int) ($args[1] ?? 0));
            $postId = (int) ($args[2] ?? 0);
            $token = (string) ($args[3] ?? '');
            $claimedGeneration = (int) ($args[4] ?? 0);
            $generation = (int) ($args[5] ?? 0);
            $row = $this->queue[$postId] ?? null;
            if (
                $row === null
                || $row['claim_token'] !== $token
                || $row['claimed_generation'] !== $claimedGeneration
                || $row['generation'] !== $generation
            ) {
                return 0;
            }

            $this->queue[$postId]['attempts'] = $attempts;
            $this->queue[$postId]['available_at'] = $availableAt;
            $this->queue[$postId]['claim_token'] = '';
            $this->queue[$postId]['claimed_generation'] = 0;
            $this->queue[$postId]['claim_expires_at'] = 0;
            return 1;
        }

        if (str_starts_with($sql, "UPDATE wp_fts_queue\nSET attempts = 0")) {
            $availableAt = max(0, (int) ($args[0] ?? 0));
            $postId = (int) ($args[1] ?? 0);
            $token = (string) ($args[2] ?? '');
            $claimedGeneration = (int) ($args[3] ?? 0);
            $olderGeneration = (int) ($args[4] ?? 0);
            $row = $this->queue[$postId] ?? null;
            if (
                $row === null
                || $row['claim_token'] !== $token
                || $row['claimed_generation'] !== $claimedGeneration
                || $row['generation'] <= $olderGeneration
            ) {
                return 0;
            }

            $this->queue[$postId]['attempts'] = 0;
            $this->queue[$postId]['available_at'] = $availableAt;
            $this->queue[$postId]['claim_token'] = '';
            $this->queue[$postId]['claimed_generation'] = 0;
            $this->queue[$postId]['claim_expires_at'] = 0;
            return 1;
        }

        if (str_starts_with($sql, "UPDATE wp_fts_queue\nSET available_at = %d")) {
            $availableAt = max(0, (int) ($args[0] ?? 0));
            $postId = (int) ($args[1] ?? 0);
            $token = (string) ($args[2] ?? '');
            $claimedGeneration = (int) ($args[3] ?? 0);
            $row = $this->queue[$postId] ?? null;
            if (
                $row === null
                || $row['claim_token'] !== $token
                || $row['claimed_generation'] !== $claimedGeneration
            ) {
                return 0;
            }

            $this->queue[$postId]['available_at'] = $availableAt;
            $this->queue[$postId]['claim_token'] = '';
            $this->queue[$postId]['claimed_generation'] = 0;
            $this->queue[$postId]['claim_expires_at'] = 0;
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_queue WHERE post_id IN')) {
            $deleted = 0;
            foreach ($args as $postId) {
                $postId = (int) $postId;
                if (isset($this->queue[$postId])) {
                    unset($this->queue[$postId]);
                    $deleted++;
                }
            }
            return $deleted;
        }

        if ($sql === 'DELETE FROM wp_fts_queue') {
            $count = count($this->queue);
            $this->queue = [];
            return $count;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_terms')) {
            $affected = 0;
            for ($offset = 0; $offset + 1 < count($args); $offset += 2) {
                $term = (string) $args[$offset];
                $value = max(0, (int) $args[$offset + 1]);
                if (str_contains($sql, 'doc_freq = doc_freq + VALUES(doc_freq)')) {
                    $value += (int) ($this->ftsTerms[$term]['doc_freq'] ?? 0);
                }
                $this->ftsTerms[$term] = ['doc_freq' => $value];
                $affected++;
            }
            ksort($this->ftsTerms, SORT_STRING);
            return $affected;
        }

        if (str_starts_with($sql, "UPDATE wp_fts_terms\nSET doc_freq = GREATEST(0, CAST(doc_freq AS SIGNED) - CASE term")) {
            $termCount = intdiv(count($args), 3);
            for ($offset = 0; $offset < $termCount * 2; $offset += 2) {
                $term = (string) $args[$offset];
                if (isset($this->ftsTerms[$term])) {
                    $this->ftsTerms[$term]['doc_freq'] = max(0, $this->ftsTerms[$term]['doc_freq'] - abs((int) $args[$offset + 1]));
                }
            }
            return $termCount;
        }

        if (str_starts_with($sql, 'UPDATE wp_fts_terms')) {
            $term = (string) $args[1];
            if (isset($this->ftsTerms[$term])) {
                $this->ftsTerms[$term]['doc_freq'] = max(0, $this->ftsTerms[$term]['doc_freq'] - abs((int) $args[0]));
            }
            return 1;
        }

        if ($sql === 'DELETE FROM wp_fts_terms') {
            $count = count($this->ftsTerms);
            $this->ftsTerms = [];
            return $count;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_terms WHERE term = %s AND doc_freq = 0')) {
            $term = (string) $args[0];
            if (($this->ftsTerms[$term]['doc_freq'] ?? null) === 0) {
                unset($this->ftsTerms[$term]);
            }
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_terms WHERE term = %s')) {
            unset($this->ftsTerms[(string) $args[0]]);
            return 1;
        }

        if (str_starts_with($sql, "DELETE FROM wp_fts_terms\nWHERE term IN")) {
            $affected = 0;
            foreach ($args as $term) {
                $term = (string) $term;
                if (($this->ftsTerms[$term]['doc_freq'] ?? null) === 0) {
                    unset($this->ftsTerms[$term]);
                    $affected++;
                }
            }
            return $affected;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_postings')) {
            $affected = 0;
            for ($offset = 0; $offset + 2 < count($args); $offset += 3) {
                $term = (string) $args[$offset];
                $docId = (int) $args[$offset + 1];
                $this->postings[$term][$docId] = max(1, (int) $args[$offset + 2]);
                ksort($this->postings[$term], SORT_NUMERIC);
                $affected++;
            }
            ksort($this->postings, SORT_STRING);
            return $affected;
        }

        if ($sql === 'DELETE FROM wp_fts_postings') {
            $count = array_sum(array_map('count', $this->postings));
            $this->postings = [];
            return $count;
        }

        if (str_starts_with($sql, 'DELETE old_posting, empty_term')) {
            $deletedIds = array_fill_keys(array_map('intval', $args), true);
            $affected = 0;
            foreach ($this->postings as $key => $postings) {
                foreach ($deletedIds as $postId => $_) {
                    if (isset($postings[$postId])) {
                        unset($postings[$postId]);
                        $affected++;
                    }
                }
                if ((int) ($this->ftsTerms[$key]['doc_freq'] ?? -1) === 0) {
                    $termId = $this->termIdsByKey[$key] ?? null;
                    unset($this->ftsTerms[$key], $this->postings[$key], $this->termIdsByKey[$key]);
                    if ($termId !== null) {
                        unset($this->termKeysById[$termId]);
                    }
                } elseif ($postings === []) {
                    unset($this->postings[$key]);
                } else {
                    $this->postings[$key] = $postings;
                }
            }
            return $affected;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_postings WHERE doc_id = %d')) {
            $docId = (int) $args[0];
            foreach ($this->postings as $term => $postings) {
                unset($postings[$docId]);
                if ($postings === []) {
                    unset($this->postings[$term]);
                    continue;
                }
                $this->postings[$term] = $postings;
            }
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_postings WHERE term = %s')) {
            unset($this->postings[(string) $args[0]]);
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_postings WHERE doc_id IN')) {
            $deleted = array_fill_keys(array_map('intval', $args), true);
            foreach ($this->postings as $term => $postings) {
                foreach ($deleted as $docId => $_) {
                    unset($postings[$docId]);
                }
                if ($postings === []) {
                    unset($this->postings[$term]);
                    continue;
                }
                $this->postings[$term] = $postings;
            }
            return 1;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_docs') && count($args) === 4) {
            $docId = (int) $args[0];
            $this->docs[$docId] = [
                'lang' => (string) $args[1],
                'doc_len' => (int) $args[2],
                'content_hash' => (string) $args[3],
                'is_deleted' => 0,
            ];
            ksort($this->docs, SORT_NUMERIC);
            return 1;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_docs') && count($args) === 2) {
            $docId = (int) $args[0];
            $this->docs[$docId] ??= [
                'lang' => (string) $args[1],
                'doc_len' => 0,
                'content_hash' => null,
                'is_deleted' => 0,
            ];
            $this->docs[$docId]['is_deleted'] = 1;
            return 1;
        }

        if ($sql === 'DELETE FROM wp_fts_doc_lengths') {
            $count = array_sum(array_map('count', $this->docLengths));
            $this->docLengths = [];
            return $count;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_doc_lengths WHERE doc_id = %d')) {
            unset($this->docLengths[(int) $args[0]]);
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_doc_lengths WHERE doc_id IN')) {
            foreach ($args as $docId) {
                unset($this->docLengths[(int) $docId]);
            }
            return 1;
        }

        if ($sql === 'DELETE FROM wp_fts_docmeta') {
            $count = count($this->docMeta);
            $this->docMeta = [];
            return $count;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_docmeta WHERE doc_id IN')) {
            foreach ($args as $docId) {
                unset($this->docMeta[(int) $docId]);
            }
            return 1;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_doc_lengths')) {
            $docId = (int) $args[0];
            $this->docLengths[$docId][(string) $args[1]] = (int) $args[2];
            ksort($this->docLengths[$docId], SORT_STRING);
            return 1;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_docmeta')) {
            $docId = (int) $args[0];
            $this->docMeta[$docId] = [
                'doc_id' => $docId,
                'post_id' => (int) $args[1],
                'post_type' => (string) $args[2],
                'post_status' => (string) $args[3],
                'post_date_gmt' => (string) $args[4],
                'title' => (string) $args[5],
                'excerpt' => (string) $args[6],
                'search_text' => (string) $args[7],
                'data' => (string) $args[8],
            ];
            ksort($this->docMeta, SORT_NUMERIC);
            return 1;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_meta')) {
            $lang = (string) $args[0];
            $key = (string) $args[1];
            $delta = (int) $args[3];
            $this->meta[$lang][$key] = max(0, ($this->meta[$lang][$key] ?? 0) + $delta);
            ksort($this->meta[$lang], SORT_STRING);
            ksort($this->meta, SORT_STRING);
            return 1;
        }

        if ($sql === 'DELETE FROM wp_fts_meta') {
            $count = count($this->meta);
            $this->meta = [];
            return $count;
        }

        if ($sql === 'DELETE FROM wp_fts_docs') {
            $count = count($this->docs);
            $this->docs = [];
            return $count;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_docs WHERE doc_id IN')) {
            foreach ($args as $docId) {
                unset($this->docs[(int) $docId]);
                unset($this->docMeta[(int) $docId]);
            }
            return 1;
        }

        return true;
    }

    /** Persist fake durable work immediately for the SIGKILL direct-durability test. */
    private function persist_direct_durability_fixture(): void
    {
        $path = getenv('WP_FTS_DIRECT_DURABILITY_QUEUE_FILE');
        if (!is_string($path) || $path === '') {
            return;
        }

        file_put_contents($path, json_encode([
            'queue' => $this->queue,
            'fts_write_queries' => count(array_filter(
                $this->queries,
                static fn(string $query): bool => str_contains($query, 'wp_fts_work')
                    && (str_starts_with($query, 'INSERT ') || str_starts_with($query, 'DELETE ') || str_starts_with($query, 'UPDATE '))
            )),
        ], JSON_THROW_ON_ERROR), LOCK_EX);
    }

    /**
     * Emulate the v4 set-oriented storage mutations used by production tests.
     *
     * @return iterable<int,array{ordinal:int,lang:string,kind:int,term:string}>
     */
    private function v4_literal_identity_rows(string $sql): iterable
    {
        $sqliteValuesStart = strpos($sql, 'FROM (VALUES ');
        if ($sqliteValuesStart !== false) {
            $cursor = $sqliteValuesStart + strlen('FROM (VALUES ');
            $sqlBytes = strlen($sql);
            while ($cursor < $sqlBytes && $sql[$cursor] === '(') {
                $rowEnd = strpos($sql, ')', $cursor + 1);
                if ($rowEnd === false) {
                    break;
                }
                $columns = explode(',', substr($sql, $cursor + 1, $rowEnd - $cursor - 1));
                if (count($columns) !== 4) {
                    break;
                }
                $ordinal = trim($columns[0]);
                $lang = $this->v4_binary_literal_value($columns[1]);
                $kind = trim($columns[2]);
                $term = $this->v4_binary_literal_value($columns[3]);
                if (
                    !wp_fts_test_is_ascii_digits($ordinal)
                    || $lang === null
                    || !wp_fts_test_is_ascii_digits($kind)
                    || $term === null
                ) {
                    break;
                }
                yield [
                    'ordinal' => (int) $ordinal,
                    'lang' => $lang,
                    'kind' => (int) $kind,
                    'term' => $term,
                ];
                $cursor = $rowEnd + 1;
                if ($cursor >= $sqlBytes || $sql[$cursor] !== ',') {
                    break;
                }
                $cursor++;
            }

            return;
        }

        $lineStart = 0;
        $sqlBytes = strlen($sql);
        while ($lineStart < $sqlBytes) {
            $lineEnd = strpos($sql, "\n", $lineStart);
            $lineEnd = $lineEnd === false ? $sqlBytes : $lineEnd;
            $line = substr($sql, $lineStart, $lineEnd - $lineStart);
            $binaryValues = [];
            $offset = 0;
            while (true) {
                $hexStart = strpos($line, "UNHEX('", $offset);
                $base64Start = strpos($line, "FROM_BASE64('", $offset);
                if ($hexStart === false && $base64Start === false) {
                    break;
                }
                $isBase64 = $hexStart === false
                    || ($base64Start !== false && $base64Start < $hexStart);
                $start = $isBase64 ? $base64Start : $hexStart;
                $marker = $isBase64 ? "FROM_BASE64('" : "UNHEX('";
                $start += strlen($marker);
                $end = strpos($line, "')", $start);
                if ($end === false) {
                    break;
                }
                $encoded = substr($line, $start, $end - $start);
                if ($isBase64) {
                    $decoded = base64_decode($encoded, true);
                } else {
                    $decoded = $encoded !== ''
                        && (strlen($encoded) % 2) === 0
                        && wp_fts_test_is_ascii_hex($encoded)
                            ? hex2bin($encoded)
                            : false;
                }
                if (!is_string($decoded)) {
                    break;
                }
                $binaryValues[] = $decoded;
                $offset = $end + 2;
            }
            if (count($binaryValues) !== 2) {
                $lineStart = $lineEnd + 1;
                continue;
            }
            $trimmed = trim($line);
            $selectOffset = strpos($trimmed, 'SELECT ');
            $afterSelect = $selectOffset === false
                ? ''
                : substr($trimmed, $selectOffset + strlen('SELECT '));
            $firstSpace = strpos($afterSelect, ' ');
            $ordinalToken = $firstSpace === false ? '' : substr($afterSelect, 0, $firstSpace);
            $ordinalToken = rtrim($ordinalToken, ',');
            $columns = explode(', ', $trimmed);
            $kindToken = ltrim((string) ($columns[2] ?? '0'));
            $kindDigits = strspn($kindToken, '0123456789');
            yield [
                'ordinal' => wp_fts_test_is_ascii_digits($ordinalToken) ? (int) $ordinalToken : 0,
                'lang' => $binaryValues[0],
                'kind' => $kindDigits > 0 ? (int) substr($kindToken, 0, $kindDigits) : 0,
                'term' => $binaryValues[1],
            ];
            $lineStart = $lineEnd + 1;
        }
    }

    /**
     * Decode the exact internally-generated dictionary VALUES grammar.
     *
     * Base64 and hexadecimal alphabets contain none of the tuple delimiters,
     * so this narrow scanner can split emitted rows without pretending to be
     * a general SQL parser.
     *
     * @return iterable<int,array{lang:string,kind:int,term:string,doc_freq:int}>
     */
    private function v4_inline_dictionary_rows(string $sql, array $args = []): iterable
    {
        $valuesStart = strpos($sql, "\nVALUES ");
        if ($valuesStart === false) {
            return;
        }
        $valuesStart += strlen("\nVALUES ");
        $mysqlEnd = strpos($sql, "\nON DUPLICATE KEY UPDATE", $valuesStart);
        $sqliteEnd = strpos($sql, "\nON CONFLICT", $valuesStart);
        $valuesEnd = $mysqlEnd === false ? $sqliteEnd : $mysqlEnd;
        if ($sqliteEnd !== false && $valuesEnd !== false) {
            $valuesEnd = min($valuesEnd, $sqliteEnd);
        }
        if ($valuesEnd === false) {
            return;
        }
        if (
            $valuesStart >= $valuesEnd
            || $sql[$valuesStart] !== '('
            || $sql[$valuesEnd - 1] !== ')'
        ) {
            return;
        }

        // Scan the generated VALUES grammar in place. Copying the complete
        // near-4-MiB clause and then exploding every row made this fake require
        // materially more memory than the SQLite execution it represents.
        $argOffset = 0;
        $cursor = $valuesStart;
        while ($cursor < $valuesEnd) {
            $delimiter = strpos($sql, '),(', $cursor);
            $lastRow = $delimiter === false || $delimiter >= $valuesEnd;
            $rowEnd = $lastRow ? $valuesEnd - 1 : $delimiter;
            $encodedRow = substr($sql, $cursor + 1, $rowEnd - $cursor - 1);
            $columns = explode(',', $encodedRow);
            if (count($columns) !== 4) {
                return;
            }
            $lang = $this->v4_binary_literal_value($columns[0]);
            $term = $this->v4_binary_literal_value($columns[2]);
            $kind = trim($columns[1]);
            $docFreq = trim($columns[3]);
            if ($kind === '%d' && array_key_exists($argOffset, $args)) {
                $kind = (string) $args[$argOffset++];
            }
            if ($docFreq === '%d' && array_key_exists($argOffset, $args)) {
                $docFreq = (string) $args[$argOffset++];
            }
            if (
                $lang === null
                || $term === null
                || !wp_fts_test_is_ascii_digits($kind)
                || !wp_fts_test_is_ascii_digits($docFreq)
            ) {
                return;
            }
            yield [
                'lang' => $lang,
                'kind' => (int) $kind,
                'term' => $term,
                'doc_freq' => (int) $docFreq,
            ];
            if ($lastRow) {
                return;
            }
            $cursor = $rowEnd + 2;
        }
    }

    /** Decode one exact binary literal emitted by the relational writer. */
    private function v4_binary_literal_value(string $expression): ?string
    {
        $expression = trim($expression);
        foreach ([
            ["FROM_BASE64('", "')", 'base64'],
            ["UNHEX('", "')", 'hex'],
            ["X'", "'", 'hex'],
        ] as [$prefix, $suffix, $encoding]) {
            if (!str_starts_with($expression, $prefix) || !str_ends_with($expression, $suffix)) {
                continue;
            }
            $encoded = substr($expression, strlen($prefix), -strlen($suffix));
            if ($encoding === 'base64') {
                $decoded = base64_decode($encoded, true);
            } else {
                $decoded = $encoded !== ''
                    && (strlen($encoded) % 2) === 0
                    && wp_fts_test_is_ascii_hex($encoded)
                        ? hex2bin($encoded)
                        : false;
            }

            return is_string($decoded) ? $decoded : null;
        }

        return null;
    }

    /** Applies relational-v4 writer statements to the in-memory storage model. */
    private function query_v4_storage(string $sql, array $args): int|bool|null
    {
        if (
            str_starts_with($sql, 'INSERT INTO wp_fts_terms')
            && str_contains($sql, '(lang,kind,term,doc_freq)')
        ) {
            $affected = 0;
            $hasInlineRows = false;
            foreach ($this->v4_inline_dictionary_rows($sql, $args) as $row) {
                $hasInlineRows = true;
                $lang = WP_FTS_TermNamespace::canonicalize_lang($row['lang'], 'und');
                $kind = max(0, $row['kind']);
                $key = $this->v4_storage_term_key($lang, $row['term'], $kind);
                $this->ensure_term_id($key);
                $this->ftsTerms[$key] = [
                    'doc_freq' => (int) ($this->ftsTerms[$key]['doc_freq'] ?? 0)
                        + max(0, $row['doc_freq']),
                ];
                $affected++;
            }
            if (!$hasInlineRows) {
                for ($offset = 0; $offset + 3 < count($args); $offset += 4) {
                    $lang = WP_FTS_TermNamespace::canonicalize_lang((string) $args[$offset], 'und');
                    $kind = max(0, (int) $args[$offset + 1]);
                    $term = (string) $args[$offset + 2];
                    $key = $this->v4_storage_term_key($lang, $term, $kind);
                    $this->ensure_term_id($key);
                    $incomingDocFreq = max(0, (int) $args[$offset + 3]);
                    $this->ftsTerms[$key] = [
                        'doc_freq' => (int) ($this->ftsTerms[$key]['doc_freq'] ?? 0) + $incomingDocFreq,
                    ];
                    $affected++;
                }
            }
            ksort($this->ftsTerms, SORT_STRING);
            return $affected;
        }

        if (
            str_starts_with($sql, 'INSERT INTO wp_fts_postings')
            && str_contains($sql, 'wp_fts:posting-replacement')
        ) {
            $this->ensure_term_identity_maps();
            $affected = 0;
            $valuesOffset = strpos($sql, "\nVALUES ");
            $encodedRows = $valuesOffset === false
                ? []
                : explode('),(', trim(substr($sql, $valuesOffset + strlen("\nVALUES ")), "() \t\r\n"));
            foreach ($encodedRows as $encodedRow) {
                $tuple = explode(',', $encodedRow);
                if (count($tuple) !== 3) {
                    continue;
                }
                $termId = max(0, (int) $tuple[0]);
                $key = $this->termKeysById[$termId] ?? null;
                $postId = max(0, (int) $tuple[1]);
                if ($key === null || !isset($this->ftsTerms[$key]) || $postId <= 0) {
                    continue;
                }
                $this->ensure_term_id($key);
                $this->postings[$key][$postId] = max(1, (int) $tuple[2]);
                ksort($this->postings[$key], SORT_NUMERIC);
                $affected++;
            }
            ksort($this->postings, SORT_STRING);
            return $affected;
        }

        if (
            str_starts_with($sql, 'INSERT INTO wp_fts_postings')
            && str_contains($sql, '(term_id,post_id,impact)')
        ) {
            $this->ensure_term_identity_maps();
            $affected = 0;
            for ($offset = 0; $offset + 2 < count($args); $offset += 3) {
                $termId = max(0, (int) $args[$offset]);
                $postId = max(0, (int) $args[$offset + 1]);
                $key = $this->termKeysById[$termId] ?? null;
                if ($key === null || $postId <= 0) {
                    continue;
                }
                $this->postings[$key][$postId] = max(1, (int) $args[$offset + 2]);
                ksort($this->postings[$key], SORT_NUMERIC);
                $affected++;
            }
            ksort($this->postings, SORT_STRING);
            return $affected;
        }

        if (str_starts_with($sql, 'DELETE old_posting, retired_term, retired_document')) {
            $affectedPosts = [];
            $deleteDocumentIds = [];
            for ($offset = 0; $offset + 1 < count($args); $offset += 2) {
                $postId = max(0, (int) $args[$offset]);
                if ($postId <= 0) {
                    continue;
                }
                $affectedPosts[$postId] = true;
                if ((int) $args[$offset + 1] === 1) {
                    $deleteDocumentIds[$postId] = true;
                }
            }
            $affected = 0;
            foreach ($this->postings as $key => $postings) {
                $retireTerm = (int) ($this->ftsTerms[$key]['doc_freq'] ?? -1) === 0
                    && array_intersect_key($postings, $affectedPosts) !== [];
                foreach ($affectedPosts as $postId => $_present) {
                    if (isset($postings[$postId])) {
                        unset($postings[$postId]);
                        $affected++;
                    }
                }
                if ($retireTerm) {
                    $termId = $this->termIdsByKey[$key] ?? null;
                    unset($this->ftsTerms[$key], $this->postings[$key], $this->termIdsByKey[$key]);
                    if ($termId !== null) {
                        unset($this->termKeysById[$termId]);
                    }
                    $affected++;
                } elseif ($postings === []) {
                    unset($this->postings[$key]);
                } else {
                    $this->postings[$key] = $postings;
                }
            }
            foreach ($deleteDocumentIds as $postId => $_present) {
                if (isset($this->docs[$postId])) {
                    unset($this->docs[$postId], $this->docLengths[$postId], $this->docMeta[$postId]);
                    $affected++;
                }
            }
            return $affected;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_postings WHERE term_id = %d')) {
            $this->ensure_term_identity_maps();
            $key = $this->termKeysById[(int) ($args[0] ?? 0)] ?? null;
            $count = $key === null ? 0 : count($this->postings[$key] ?? []);
            if ($key !== null) {
                unset($this->postings[$key]);
            }
            return $count;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_postings WHERE post_id')) {
            $deletedIds = array_fill_keys(array_map('intval', $args), true);
            $affected = 0;
            foreach ($this->postings as $key => $postings) {
                foreach ($deletedIds as $postId => $_) {
                    if (isset($postings[$postId])) {
                        unset($postings[$postId]);
                        $affected++;
                    }
                }
                if ($postings === []) {
                    unset($this->postings[$key]);
                } else {
                    $this->postings[$key] = $postings;
                }
            }
            return $affected;
        }

        if ($sql === 'DELETE FROM wp_fts_postings') {
            $count = array_sum(array_map('count', $this->postings));
            $this->postings = [];
            return $count;
        }

        if (str_starts_with($sql, 'INSERT INTO wp_fts_documents')) {
            if (str_contains($sql, "VALUES (%d, 'und', NULL")) {
                $postId = max(0, (int) ($args[0] ?? 0));
                if ($postId <= 0) {
                    return 0;
                }
                $snippet = $this->decode_v4_text_argument((string) ($args[1] ?? ''), $sql);
                $this->docs[$postId] ??= $this->v4_document_row($postId, 'und', 0, '', '', 0);
                $this->docs[$postId]['snippet_text'] = $snippet;
                $this->sync_v4_doc_metadata($postId, $snippet);
                return 1;
            }

            $usesEncodedSnippet = str_contains($sql, 'FROM_BASE64(%s)');
            $stride = $usesEncodedSnippet ? 5 : 4;
            $affected = 0;
            for ($offset = 0; $offset + $stride - 1 < count($args); $offset += $stride) {
                $postId = max(0, (int) $args[$offset]);
                if ($postId <= 0) {
                    continue;
                }
                $lang = WP_FTS_TermNamespace::canonicalize_lang((string) $args[$offset + 1], 'und');
                $contentHash = (string) $args[$offset + 2];
                $snippet = $usesEncodedSnippet
                    ? $this->decode_v4_text_argument((string) $args[$offset + 3], $sql)
                    : '';
                $indexedAt = max(0, (int) $args[$offset + $stride - 1]);
                $this->docs[$postId] = $this->v4_document_row(
                    $postId,
                    $lang,
                    0,
                    $contentHash,
                    $snippet,
                    $indexedAt
                );
                $this->docLengths[$postId] = [];
                $this->sync_v4_doc_metadata($postId, $snippet);
                $affected++;
            }
            ksort($this->docs, SORT_NUMERIC);
            ksort($this->docLengths, SORT_NUMERIC);
            return $affected;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_documents WHERE post_id')) {
            $affected = 0;
            foreach (array_map('intval', $args) as $postId) {
                if (isset($this->docs[$postId])) {
                    unset($this->docs[$postId], $this->docLengths[$postId], $this->docMeta[$postId]);
                    $affected++;
                }
            }
            return $affected;
        }

        if (str_starts_with($sql, "UPDATE wp_fts_documents SET snippet_text = '', indexed_at = %d WHERE post_id = %d")) {
            $postId = max(0, (int) ($args[1] ?? 0));
            if (!isset($this->docs[$postId])) {
                return 0;
            }
            $this->docs[$postId]['snippet_text'] = '';
            $this->docs[$postId]['indexed_at'] = max(0, (int) ($args[0] ?? 0));
            $this->sync_v4_doc_metadata($postId, '');
            return 1;
        }

        if ($sql === 'DELETE FROM wp_fts_documents') {
            $count = count($this->docs);
            $this->docs = [];
            $this->docLengths = [];
            $this->docMeta = [];
            return $count;
        }

        if (
            str_contains($sql, 'wp_fts:dictionary-decrement')
            && str_contains($sql, 'affected.document_delta')
            && str_contains($sql, 'changed.post_id IN (')
        ) {
            $postIds = array_map('intval', $args);
            $subtract = str_contains($sql, '- affected.document_delta');
            $this->ensure_term_identity_maps();
            $affected = 0;
            foreach ($this->termKeysById as $termId => $key) {
                $delta = 0;
                foreach ($postIds as $postId) {
                    $delta += isset($this->postings[$key][$postId]) ? 1 : 0;
                }
                if ($delta === 0) {
                    continue;
                }
                $current = (int) ($this->ftsTerms[$key]['doc_freq'] ?? 0);
                $this->ftsTerms[$key]['doc_freq'] = max(0, $current + ($subtract ? -$delta : $delta));
                $affected++;
            }
            return $affected;
        }

        if (
            str_starts_with($sql, 'UPDATE wp_fts_terms AS t')
            && str_contains($sql, 'old_posting.post_id IN (')
            && str_contains($sql, 'old_filter.post_id IN (')
        ) {
            $firstListStart = strpos($sql, 'old_posting.post_id IN (');
            $firstListStart = $firstListStart === false ? false : $firstListStart + strlen('old_posting.post_id IN (');
            $firstListEnd = $firstListStart === false ? false : strpos($sql, ')', $firstListStart);
            $postCount = $firstListStart === false || $firstListEnd === false
                ? 0
                : substr_count(substr($sql, $firstListStart, $firstListEnd - $firstListStart), '%d');
            $newCount = substr_count($sql, 'WHEN %d THEN %d');
            $postIds = array_map('intval', array_slice($args, 0, $postCount));
            $newCounts = [];
            $offset = $postCount;
            for ($index = 0; $index < $newCount; $index++) {
                $termId = max(0, (int) ($args[$offset++] ?? 0));
                $newCounts[$termId] = max(0, (int) ($args[$offset++] ?? 0));
            }

            $this->ensure_term_identity_maps();
            $affected = 0;
            foreach ($this->termKeysById as $termId => $key) {
                $oldCount = 0;
                foreach ($postIds as $postId) {
                    $oldCount += isset($this->postings[$key][$postId]) ? 1 : 0;
                }
                if ($oldCount === 0 && !isset($newCounts[$termId])) {
                    continue;
                }
                $this->ftsTerms[$key]['doc_freq'] = max(
                    0,
                    (int) ($this->ftsTerms[$key]['doc_freq'] ?? 0) - $oldCount + (int) ($newCounts[$termId] ?? 0)
                );
                $affected++;
            }
            return $affected;
        }

        if (str_starts_with($sql, 'UPDATE wp_fts_terms') && str_contains($sql, 'SET doc_freq = (SELECT COUNT(*)')) {
            $this->ensure_term_identity_maps();
            $ids = $args === [] ? array_keys($this->termKeysById) : array_map('intval', $args);
            $affected = 0;
            foreach ($ids as $termId) {
                $key = $this->termKeysById[$termId] ?? null;
                if ($key === null || !isset($this->ftsTerms[$key])) {
                    continue;
                }
                $this->ftsTerms[$key]['doc_freq'] = count($this->postings[$key] ?? []);
                $affected++;
            }
            return $affected;
        }

        if (
            (str_starts_with($sql, 'DELETE FROM wp_fts_terms') || str_starts_with($sql, 'DELETE retired_term'))
            && (str_contains($sql, 'WHERE doc_freq = 0') || str_contains($sql, 'WHERE retired_term.doc_freq = 0'))
            && (
                str_contains($sql, 'SELECT term_id FROM wp_fts_postings')
                || str_contains($sql, 'FROM wp_fts_postings AS retired_posting')
            )
        ) {
            $postIds = array_fill_keys(array_map('intval', $args), true);
            $this->ensure_term_identity_maps();
            $affected = 0;
            foreach ($this->ftsTerms as $key => $term) {
                if ((int) ($term['doc_freq'] ?? -1) !== 0 || array_intersect_key($this->postings[$key] ?? [], $postIds) === []) {
                    continue;
                }
                $termId = $this->termIdsByKey[$key] ?? null;
                unset($this->ftsTerms[$key], $this->postings[$key], $this->termIdsByKey[$key]);
                if ($termId !== null) {
                    unset($this->termKeysById[$termId]);
                }
                $affected++;
            }
            return $affected;
        }

        if (
            (str_starts_with($sql, "DELETE FROM wp_fts_terms\nWHERE term_id IN")
                || str_contains($sql, '/* wp_fts:cleanup-empty-terms */'))
            && str_contains($sql, 'bounded_empty_terms')
        ) {
            $this->ensure_term_identity_maps();
            $termIds = array_keys($this->termKeysById);
            sort($termIds, SORT_NUMERIC);
            $affected = 0;
            foreach ($termIds as $termId) {
                $key = $this->termKeysById[$termId] ?? null;
                if ($key === null || (int) ($this->ftsTerms[$key]['doc_freq'] ?? -1) !== 0) {
                    continue;
                }
                unset($this->ftsTerms[$key], $this->postings[$key], $this->termIdsByKey[$key], $this->termKeysById[$termId]);
                $affected++;
                if ($affected >= WP_FTS_Storage_Mysql::MAX_EMPTY_TERM_CLEANUP) {
                    break;
                }
            }

            return $affected;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_terms WHERE doc_freq = 0')) {
            $this->ensure_term_identity_maps();
            $ids = $args === [] ? array_keys($this->termKeysById) : array_map('intval', $args);
            $affected = 0;
            foreach ($ids as $termId) {
                $key = $this->termKeysById[$termId] ?? null;
                if ($key === null || (int) ($this->ftsTerms[$key]['doc_freq'] ?? -1) !== 0) {
                    continue;
                }
                unset($this->ftsTerms[$key], $this->postings[$key], $this->termIdsByKey[$key], $this->termKeysById[$termId]);
                $affected++;
            }
            return $affected;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_terms WHERE term_id = %d')) {
            $this->ensure_term_identity_maps();
            $termId = (int) ($args[0] ?? 0);
            $key = $this->termKeysById[$termId] ?? null;
            if ($key === null) {
                return 0;
            }
            unset($this->ftsTerms[$key], $this->postings[$key], $this->termIdsByKey[$key], $this->termKeysById[$termId]);
            return 1;
        }

        if ($sql === 'DELETE FROM wp_fts_terms') {
            $count = count($this->ftsTerms);
            $this->ftsTerms = [];
            $this->postings = [];
            $this->termIdsByKey = [];
            $this->termKeysById = [];
            $this->nextTermId = 1;
            return $count;
        }

        return null;
    }

    /** @param array<int,mixed> $args */
    private function query_v4_work(string $sql, array $args): int|bool
    {
        if (
            str_starts_with($sql, "DELETE work_row\nFROM wp_fts_work work_row")
            || str_contains($sql, '/* wp_fts:acknowledge-batch */')
            || str_contains($sql, '/* wp_fts:atomic-worker-ack */')
            || str_contains($sql, '/* wp_fts:replaced-scope-delete */')
        ) {
            if (count($args) < 4 || count($args) % 4 !== 0) {
                throw new RuntimeException('Malformed atomic worker acknowledgement test SQL.');
            }

            $affected = 0;
            for ($offset = 0; $offset < count($args); $offset += 4) {
                $jobKey = (string) ($args[$offset] ?? '');
                $claimToken = (string) ($args[$offset + 1] ?? '');
                $claimedGeneration = max(0, (int) ($args[$offset + 2] ?? 0));
                $generation = max(0, (int) ($args[$offset + 3] ?? 0));
                $rowKey = $this->v4_queue_key_for_job($jobKey);
                if ($rowKey === null) {
                    continue;
                }
                $row = $this->queue[$rowKey];
                if (
                    !hash_equals((string) ($row['claim_token'] ?? ''), $claimToken)
                    || (int) ($row['claimed_generation'] ?? 0) !== $claimedGeneration
                    || (int) ($row['generation'] ?? 0) !== $generation
                ) {
                    continue;
                }
                unset($this->queue[$rowKey]);
                $affected++;
            }

            return $affected;
        }

        if (
            str_starts_with($sql, 'INSERT INTO ')
            && str_contains($sql, 'fts_work')
            && str_contains($sql, "VALUES (%s, 'meta', 0, %d, 'meta'")
        ) {
            $this->searchEpoch = max(1, (int) ($args[1] ?? 1));
            return 1;
        }
        if (
            str_starts_with($sql, 'INSERT INTO ')
            && str_contains($sql, 'fts_work')
            && str_contains($sql, "VALUES (%s, 'meta', 0, 1, 'meta'")
            && !str_contains($sql, "'post'")
            && !str_contains($sql, "'scope'")
        ) {
            $this->searchEpoch++;
            $this->capture_search_epoch_incarnation((string) ($args[1] ?? ''));
            return 1;
        }

        if (
            str_starts_with($sql, 'INSERT INTO wp_fts_work')
            && str_contains($sql, "SELECT CONCAT('post:', tr.object_id)")
        ) {
            $availableAt = max(1, (int) ($args[0] ?? 0));
            $termId = max(0, (int) ($args[1] ?? 0));
            $taxonomy = (string) ($args[2] ?? '');
            $objectIds = $GLOBALS['wp_fts_test_term_object_ids'][$taxonomy . ':' . $termId] ?? [];
            $affected = 0;
            foreach (array_values(array_unique(array_filter(array_map('intval', $objectIds)))) as $postId) {
                if ($postId <= 0) {
                    continue;
                }

                $storageKey = $postId;
                if (isset($this->queue[$storageKey])) {
                    $this->queue[$storageKey]['generation'] = (int) $this->queue[$storageKey]['generation'] + 1;
                    $this->queue[$storageKey]['state'] = 'ready';
                    $this->queue[$storageKey]['available_at'] = $availableAt;
                    $this->queue[$storageKey]['attempts'] = 0;
                    $this->queue[$storageKey]['claim_token'] = '';
                    $this->queue[$storageKey]['claimed_generation'] = 0;
                    $this->queue[$storageKey]['claim_expires_at'] = 0;
                    $this->queue[$storageKey]['payload'] = '';
                    if (str_contains($sql, "last_error_code = 'operator_retry'")) {
                        $this->queue[$storageKey]['last_error_code'] = 'operator_retry';
                        $this->queue[$storageKey]['last_error_at'] = 0;
                    } elseif (str_contains($sql, "last_error_code = ''")) {
                        $this->queue[$storageKey]['last_error_code'] = '';
                        $this->queue[$storageKey]['last_error_at'] = 0;
                    }
                } else {
                    $this->queue[$storageKey] = [
                        'job_key' => 'post:' . $postId,
                        'kind' => 'post',
                        'post_id' => $postId,
                        'generation' => 1,
                        'state' => 'ready',
                        'available_at' => $availableAt,
                        'attempts' => 0,
