                $row['claim_token'] = $guardToken;
                $row['claimed_generation'] = (int) ($row['generation'] ?? 0);
                $row['claim_expires_at'] = 0;
                $affected++;
            }
            unset($row);
            return $affected;
        }

        if (
            (str_starts_with($sql, 'UPDATE wp_fts_work')
                || str_contains($sql, '/* wp_fts:claim-batch */')
                || str_contains($sql, '/* wp_fts:claim-posts */'))
            && (str_contains($sql, "SET state = 'leased'") || str_contains($sql, "SET claim_target.state = 'leased'"))
        ) {
            $token = (string) ($args[0] ?? '');
            $expiresAt = max(0, (int) ($args[1] ?? 0));
            if (str_contains($sql, 'WHERE job_key = %s AND generation = %d')) {
                $jobKey = (string) ($args[2] ?? '');
                $generation = max(0, (int) ($args[3] ?? 0));
                $rowKey = $this->v4_queue_key_for_job($jobKey);
                $now = max(0, (int) ($args[4] ?? PHP_INT_MAX));
                $rowState = $rowKey === null ? '' : (string) ($this->queue[$rowKey]['state'] ?? '');
                $rowDue = $rowKey !== null
                    && (int) ($this->queue[$rowKey]['available_at'] ?? 0) <= $now
                    && (
                        in_array($rowState, ['ready', 'retry'], true)
                        || ($rowState === 'leased' && (int) ($this->queue[$rowKey]['claim_expires_at'] ?? 0) <= $now)
                        || ($rowState === 'guarded' && str_contains($sql, "state = 'guarded'"))
                    );
                if (
                    $rowKey === null
                    || (int) $this->queue[$rowKey]['generation'] !== $generation
                    || !$rowDue
                ) {
                    return 0;
                }
                $this->lease_v4_queue_row($rowKey, $token, $expiresAt);
                if (is_callable($this->afterQueueClaimWriteObserver)) {
                    $observer = $this->afterQueueClaimWriteObserver;
                    $this->afterQueueClaimWriteObserver = null;
                    $observer($sql);
                }
                return 1;
            }

            $now = max(0, (int) ($args[count($args) - 2] ?? 0));
            $recoverGuardedFences = !str_contains($sql, 'wp_fts:fences-require-free-guard');
            $selected = [];
            if (str_contains($sql, "WHERE kind = 'scope'")) {
                $scope = $this->claimable_v4_queue_keys('scope', 1, $now, $recoverGuardedFences);
                array_push($selected, ...$scope);
                if (str_contains($sql, 'post_choice')) {
                    $limit = $this->bounded_v4_candidate_limit($sql, 'post');
                    array_push($selected, ...$this->claimable_v4_queue_keys('post', $limit, $now, $recoverGuardedFences));
                }
            } else {
                $limit = $this->bounded_v4_candidate_limit($sql, 'post');
                $selected = $this->claimable_v4_queue_keys('post', $limit, $now, $recoverGuardedFences);
            }
            foreach ($selected as $rowKey) {
                $this->lease_v4_queue_row($rowKey, $token, $expiresAt);
            }
            if (is_callable($this->afterQueueClaimWriteObserver)) {
                $observer = $this->afterQueueClaimWriteObserver;
                $this->afterQueueClaimWriteObserver = null;
                $observer($sql);
            }
            return count($selected);
        }

        if (
            str_starts_with($sql, 'DELETE FROM wp_fts_work')
            && str_contains($sql, 'job_key = %s')
            && str_contains($sql, "kind = 'scope'")
        ) {
            $rowKey = $this->v4_queue_key_for_job((string) ($args[0] ?? ''));
            if ($rowKey === null || (string) ($this->queue[$rowKey]['kind'] ?? '') !== 'scope') {
                return 0;
            }
            unset($this->queue[$rowKey]);
            return 1;
        }

        if (str_starts_with($sql, 'DELETE FROM wp_fts_work') && str_contains($sql, 'job_key = %s')) {
            $deleted = 0;
            for ($offset = 0; $offset + 3 < count($args); $offset += 4) {
                $jobKey = (string) $args[$offset];
                $rowKey = $this->v4_queue_key_for_job($jobKey);
                if ($rowKey === null) {
                    continue;
                }
                $row = $this->queue[$rowKey];
                if (
                    (string) $row['claim_token'] !== (string) $args[$offset + 1]
                    || (int) $row['claimed_generation'] !== (int) $args[$offset + 2]
                    || (int) $row['generation'] !== (int) $args[$offset + 3]
                ) {
                    continue;
                }
                unset($this->queue[$rowKey]);
                $deleted++;
            }
            return $deleted;
        }

        if ($sql === 'DELETE FROM wp_fts_work') {
            $count = count($this->queue);
            $this->queue = [];
            return $count;
        }

        if (
            str_starts_with($sql, 'DELETE FROM ')
            && str_contains($sql, 'fts_work')
            && str_contains($sql, "WHERE kind IN ('post','scope')")
            && !str_contains($sql, 'job_key = %s')
        ) {
            $before = count($this->queue);
            $this->queue = array_filter(
                $this->queue,
                static fn(array $row): bool => !in_array((string) ($row['kind'] ?? ''), ['post', 'scope'], true)
                    && (
                        (string) ($row['kind'] ?? '') !== 'meta'
                        || (string) ($row['job_key'] ?? '') === WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY
                    )
            );
            return $before - count($this->queue);
        }

        if (str_starts_with($sql, 'UPDATE wp_fts_work') && str_contains($sql, 'SET cursor_post_id = %d')) {
            $payloadOffset = str_contains($sql, 'payload = %s') ? 1 : 0;
            $rowKey = $this->v4_queue_key_for_job((string) ($args[1 + $payloadOffset] ?? ''));
            if (!$this->v4_queue_claim_matches($rowKey, (string) ($args[2 + $payloadOffset] ?? ''), (int) ($args[3 + $payloadOffset] ?? 0))) {
                return 0;
            }
            $this->queue[$rowKey]['cursor_post_id'] = max(0, (int) $args[0]);
            if ($payloadOffset === 1) {
                $this->queue[$rowKey]['payload'] = (string) ($args[1] ?? '');
            }
            $this->queue[$rowKey]['last_error_code'] = '';
            $this->queue[$rowKey]['last_error_at'] = 0;
            $this->release_v4_queue_row($rowKey, (int) $this->queue[$rowKey]['available_at']);
            return 1;
        }

        if (str_contains($sql, '/* wp_fts:scope-yield-to-posts */')) {
            $rowKey = $this->v4_queue_key_for_job((string) ($args[2] ?? ''));
            if (!$this->v4_queue_claim_matches(
                $rowKey,
                (string) ($args[3] ?? ''),
                (int) ($args[4] ?? 0),
                (int) ($args[5] ?? 0)
            )) {
                return 0;
            }
            $this->queue[$rowKey]['last_error_code'] = (string) ($args[1] ?? '');
            $this->queue[$rowKey]['last_error_at'] = 0;
            $this->release_v4_queue_row($rowKey, max(1, (int) ($args[0] ?? 0)));
            return 1;
        }

        if (str_contains($sql, '/* wp_fts:yield-scope-release-posts */')) {
            $releasedAt = max(1, (int) ($args[0] ?? 0));
            $claimOffset = str_contains($sql, 'STRAIGHT_JOIN') ? 1 : 4;
            $affected = 0;
            for ($offset = $claimOffset; $offset + 3 < count($args); $offset += 4) {
                $rowKey = $this->v4_queue_key_for_job((string) $args[$offset]);
                if (!$this->v4_queue_claim_matches(
                    $rowKey,
                    (string) $args[$offset + 1],
                    (int) $args[$offset + 2],
                    (int) $args[$offset + 3]
                )) {
                    continue;
                }
                if ($offset === $claimOffset) {
                    $this->queue[$rowKey]['last_error_code'] = WP_FTS_Index_Queue::SCOPE_EXPANSION_TURN_CODE;
                    $this->queue[$rowKey]['last_error_at'] = 0;
                }
                $this->release_v4_queue_row($rowKey, $releasedAt);
                $affected++;
            }
            return $affected;
        }

        if (str_starts_with($sql, 'UPDATE wp_fts_work') && str_contains($sql, 'SET available_at = %d + CASE')) {
            $now = max(1, (int) ($args[0] ?? 0));
            $affected = 0;
            for ($offset = 2; $offset + 3 < count($args); $offset += 4) {
                $rowKey = $this->v4_queue_key_for_job((string) $args[$offset]);
                if (!$this->v4_queue_claim_matches($rowKey, (string) $args[$offset + 1], (int) $args[$offset + 2], (int) $args[$offset + 3])) {
                    continue;
                }
                $attempts = (int) $this->queue[$rowKey]['attempts'] + 1;
                $this->queue[$rowKey]['attempts'] = $attempts;
                $this->queue[$rowKey]['state'] = 'retry';
                $this->queue[$rowKey]['available_at'] = $now + min(WP_FTS_Index_Queue::MAX_BACKOFF_SECONDS, WP_FTS_Index_Queue::BASE_BACKOFF_SECONDS * (2 ** max(0, $attempts - 1)));
                $this->queue[$rowKey]['last_error_code'] = 'content_failure';
                $this->queue[$rowKey]['last_error_at'] = $now;
                $this->release_v4_queue_row($rowKey, (int) $this->queue[$rowKey]['available_at'], false);
                $affected++;
            }
            return $affected;
        }

        if (str_contains($sql, '/* wp_fts:fail-batch */')) {
            $now = max(1, (int) ($args[0] ?? 0));
            $affected = 0;
            for ($offset = 1; $offset + 3 < count($args); $offset += 4) {
                $rowKey = $this->v4_queue_key_for_job((string) $args[$offset]);
                if (!$this->v4_queue_claim_matches(
                    $rowKey,
                    (string) $args[$offset + 1],
                    (int) $args[$offset + 2],
                    (int) $args[$offset + 3]
                )) {
                    continue;
                }
                $attempts = (int) $this->queue[$rowKey]['attempts'] + 1;
                $this->queue[$rowKey]['attempts'] = $attempts;
                $this->queue[$rowKey]['state'] = 'retry';
                $this->queue[$rowKey]['available_at'] = $now + min(
                    WP_FTS_Index_Queue::MAX_BACKOFF_SECONDS,
                    WP_FTS_Index_Queue::BASE_BACKOFF_SECONDS * (2 ** max(0, $attempts - 1))
                );
                $this->queue[$rowKey]['last_error_code'] = 'content_failure';
                $this->queue[$rowKey]['last_error_at'] = $now;
                $this->release_v4_queue_row($rowKey, (int) $this->queue[$rowKey]['available_at'], false);
                $affected++;
            }
            return $affected;
        }

        if (str_contains($sql, '/* wp_fts:release-batch */')) {
            $releasedAt = max(1, (int) ($args[0] ?? 0));
            $affected = 0;
            for ($offset = 1; $offset + 3 < count($args); $offset += 4) {
                $rowKey = $this->v4_queue_key_for_job((string) $args[$offset]);
                if (!$this->v4_queue_claim_matches(
                    $rowKey,
                    (string) $args[$offset + 1],
                    (int) $args[$offset + 2]
                )) {
                    continue;
                }
                $this->release_v4_queue_row($rowKey, $releasedAt);
                $affected++;
            }
            return $affected;
        }

        if (str_starts_with($sql, 'UPDATE wp_fts_work') && str_contains($sql, "SET state = 'retry'")) {
            $rowKey = $this->v4_queue_key_for_job((string) ($args[3] ?? ''));
            if (!$this->v4_queue_claim_matches($rowKey, (string) ($args[4] ?? ''), (int) ($args[5] ?? 0), (int) ($args[6] ?? 0))) {
                return 0;
            }
            $this->queue[$rowKey]['state'] = 'retry';
            $this->queue[$rowKey]['attempts'] = max(0, (int) $args[0]);
            $this->queue[$rowKey]['available_at'] = max(1, (int) $args[1]);
            $this->queue[$rowKey]['last_error_code'] = str_contains($sql, "last_error_code = 'scope_failure'")
                ? 'scope_failure'
                : 'content_failure';
            $this->queue[$rowKey]['last_error_at'] = max(1, (int) $args[2]);
            $this->release_v4_queue_row($rowKey, (int) $this->queue[$rowKey]['available_at'], false);
            return 1;
        }

        if (str_starts_with($sql, 'UPDATE wp_fts_work') && str_contains($sql, "SET state = 'ready'")) {
            if (str_contains($sql, 'attempts = 0')) {
                $rowKey = $this->v4_queue_key_for_job((string) ($args[1] ?? ''));
                if (!$this->v4_queue_claim_matches($rowKey, (string) ($args[2] ?? ''), (int) ($args[3] ?? 0))) {
                    return 0;
                }
                if (str_contains($sql, 'generation > %d') && (int) $this->queue[$rowKey]['generation'] <= (int) ($args[4] ?? PHP_INT_MAX)) {
                    return 0;
                }
                $this->queue[$rowKey]['attempts'] = 0;
                $this->queue[$rowKey]['cursor_post_id'] = 0;
                $this->release_v4_queue_row($rowKey, max(1, (int) $args[0]));
                return 1;
            }

            $affected = 0;
            for ($offset = 1; $offset + 2 < count($args); $offset += 3) {
                $rowKey = $this->v4_queue_key_for_job((string) $args[$offset]);
                if (!$this->v4_queue_claim_matches($rowKey, (string) $args[$offset + 1], (int) $args[$offset + 2])) {
                    continue;
                }
                $this->release_v4_queue_row($rowKey, max(1, (int) $args[0]));
                $affected++;
            }
            return $affected;
        }

        return true;
    }

    /** Returns the stable synthetic ID assigned to one storage term key. */
    private function ensure_term_id(string $key): int
    {
        if (isset($this->termIdsByKey[$key])) {
            return $this->termIdsByKey[$key];
        }
        $id = $this->nextTermId++;
        $this->termIdsByKey[$key] = $id;
        $this->termKeysById[$id] = $key;
        return $id;
    }

    /** Backfills term-ID maps for directly seeded fixture terms and postings. */
    private function ensure_term_identity_maps(): void
    {
        foreach (array_unique([...array_keys($this->ftsTerms), ...array_keys($this->postings)]) as $key) {
            $this->ensure_term_id((string) $key);
        }
    }

    /** Materializes one relational-v4 dictionary row from fixture state. */
    private function v4_term_row(string $key, string $rowKind = 'new'): object
    {
        $id = $this->ensure_term_id($key);
        [$kind, $canonicalKey] = $this->v4_decode_storage_term_key($key);
        $split = WP_FTS_TermNamespace::split_term($canonicalKey);
        $lang = WP_FTS_TermNamespace::canonicalize_lang((string) ($split['lang'] ?? 'und'), 'und');
        $term = (string) ($split['term'] ?? $canonicalKey);
        return (object) [
            'row_kind' => $rowKind,
            'term_id' => $id,
            'lang' => $lang,
            'kind' => $kind,
            'term' => $term,
            'doc_freq' => max(0, (int) ($this->ftsTerms[$key]['doc_freq'] ?? count($this->postings[$key] ?? []))),
        ];
    }

    /** Encodes language, term kind, and term into the fixture storage key. */
    private function v4_storage_term_key(string $lang, string $term, int $kind): string
    {
        $canonical = WP_FTS_TermNamespace::namespace_term($lang, $term);
        return $kind === 0 ? $canonical : "\x01" . $kind . "\0" . $canonical;
    }

    /** @return array{0:int,1:string} */
    private function v4_decode_storage_term_key(string $key): array
    {
        if (!str_starts_with($key, "\x01")) {
            return [0, $key];
        }
        $separator = strpos($key, "\0", 1);
        if ($separator === false) {
            return [0, $key];
        }

        return [max(0, (int) substr($key, 1, $separator - 1)), substr($key, $separator + 1)];
    }

    /** @return array<string,mixed> */
    private function v4_document_row(
        int $postId,
        string $lang,
        int $docLen,
        string $contentHash,
        string $snippet,
        int $indexedAt
    ): array {
        return [
            'post_id' => $postId,
            'primary_lang' => $lang,
            'lang' => $lang,
            'doc_len' => $docLen,
            'content_hash' => $contentHash,
            'snippet_text' => $snippet,
            'indexed_at' => $indexedAt,
            // Compatibility assertions use this field to distinguish a row
            // that exists from one deleted by the v4 writer.
            'is_deleted' => 0,
        ];
    }

    /** Decodes text placeholders when the production statement uses base64 transport. */
    private function decode_v4_text_argument(string $value, string $sql): string
    {
        if (!str_contains($sql, 'FROM_BASE64(%s)')) {
            return $value;
        }
        $decoded = base64_decode($value, true);
        return is_string($decoded) ? $decoded : '';
    }

    /** Keeps compatibility metadata aligned with a relational-v4 document write. */
    private function sync_v4_doc_metadata(int $postId, string $snippet): void
    {
        $post = $this->v4_post_row($postId);
        $this->docMeta[$postId] = [
            'doc_id' => $postId,
            'post_id' => $postId,
            'post_type' => (string) ($post->post_type ?? $this->docMeta[$postId]['post_type'] ?? 'post'),
            'post_status' => (string) ($post->post_status ?? $this->docMeta[$postId]['post_status'] ?? 'publish'),
            'post_date_gmt' => (string) ($post->post_date_gmt ?? $this->docMeta[$postId]['post_date_gmt'] ?? '1970-01-01 00:00:00'),
            'title' => (string) ($post->post_title ?? $this->docMeta[$postId]['title'] ?? ''),
            'excerpt' => (string) ($post->post_excerpt ?? $this->docMeta[$postId]['excerpt'] ?? ''),
            'search_text' => $snippet,
            'data' => '{}',
        ];
        ksort($this->docMeta, SORT_NUMERIC);
    }

    /** Finds or synthesizes the canonical WordPress row for a fixture post. */
    private function v4_post_row(int $postId): object
    {
        $global = $GLOBALS['wp_fts_test_posts'][$postId] ?? null;
        if (is_object($global)) {
            return $global;
        }
        foreach ($this->postRows as $row) {
            if (is_object($row) && (int) ($row->ID ?? 0) === $postId) {
                return $row;
            }
        }
        $metadata = $this->docMeta[$postId] ?? [];
        return (object) [
            'ID' => $postId,
            'post_type' => (string) ($metadata['post_type'] ?? 'post'),
            'post_status' => (string) ($metadata['post_status'] ?? 'publish'),
            'post_password' => '',
            'post_date_gmt' => (string) ($metadata['post_date_gmt'] ?? '1970-01-01 00:00:00'),
            'post_title' => (string) ($metadata['title'] ?? ''),
            'post_excerpt' => (string) ($metadata['excerpt'] ?? ''),
            'post_content' => (string) ($metadata['search_text'] ?? ''),
        ];
    }

    /** @param array<int,mixed> $args @return int[] */
    private function dependency_post_ids_from_args(array $args): array
    {
        $ids = [];
        foreach ($args as $value) {
            if (!is_int($value) && !(is_string($value) && wp_fts_test_is_ascii_digits($value))) {
                continue;
            }
            $postId = (int) $value;
            if ($this->dependency_fixture_post($postId) !== null) {
                $ids[$postId] = true;
            }
        }
        $ids = array_map('intval', array_keys($ids));
        sort($ids, SORT_NUMERIC);
        return $ids;
    }

    /** Finds a canonical fixture post for dependency-source emulation. */
    private function dependency_fixture_post(int $postId): ?object
    {
        $post = $GLOBALS['wp_fts_test_posts'][$postId] ?? null;
        if (is_object($post)) {
            return $post;
        }
        foreach ($this->postRows as $candidate) {
            if (is_object($candidate) && (int) ($candidate->ID ?? 0) === $postId) {
                return $candidate;
            }
        }
        return null;
    }

    /** @return array<int,mixed> */
    private function dependency_meta_values(int $postId, object $post, string $key): array
    {
        $values = $GLOBALS['wp_fts_test_post_meta'][$postId][$key]
            ?? (is_array($post->custom_fields ?? null) ? ($post->custom_fields[$key] ?? []) : []);
        return is_array($values) ? array_values($values) : [$values];
    }

    /** Returns a stable synthetic ID for one indexed dependency occurrence. */
    private function dependency_source_id(string $kind, int $postId, string $key, int $occurrence): int
    {
        $identity = $kind . ':' . $postId . ':' . $key . ':' . $occurrence;
        if (isset($this->dependencySourceIds[$identity])) {
            return $this->dependencySourceIds[$identity];
        }

        $sourceId = $this->nextDependencySourceId++;
        $this->dependencySourceIds[$identity] = $sourceId;
        $this->dependencySources[$sourceId] = [
            'kind' => $kind,
            'post_id' => $postId,
            'key' => $key,
            'occurrence' => $occurrence,
        ];

        return $sourceId;
    }

    /** Reports a dependency value’s real or deliberately virtual byte size. */
    private function dependency_fixture_value_bytes(
        string $kind,
        int $postId,
        string $key,
        int $occurrence,
        string $value
    ): int {
        $virtual = $GLOBALS['wp_fts_test_dependency_virtual_value_bytes'][$postId][$kind][$key][$occurrence]
            ?? null;

        return is_numeric($virtual) ? max(0, (int) $virtual) : strlen($value);
    }

    /** @return array{key:string,value:string}|null */
    private function dependency_source_value(int $sourceId): ?array
    {
        $source = $this->dependencySources[$sourceId] ?? null;
        if (!is_array($source)) {
            return null;
        }
        $post = $this->dependency_fixture_post($source['post_id']);
        if ($post === null) {
            return null;
        }

        if ($source['kind'] === 'meta') {
            $values = $this->dependency_meta_values($source['post_id'], $post, $source['key']);
        } else {
            $configured = is_array($post->terms ?? null) ? ($post->terms[$source['key']] ?? []) : [];
            $values = array_values(array_filter(
                is_array($configured) ? $configured : [$configured],
                static fn(mixed $value): bool => is_scalar($value) && trim((string) $value) !== ''
            ));
        }
        $value = $values[$source['occurrence']] ?? null;
        if (!is_scalar($value)) {
            return null;
        }

        return ['key' => $source['key'], 'value' => (string) $value];
    }

    /**
     * Read literal source-id lists and their projection caps from generated SQL.
     *
     * @return array<int,int> source id => byte cap
     */
    private function dependency_value_requests(string $sql): array
    {
        $requests = [];
        foreach (explode("\nUNION ALL\n", $sql) as $branch) {
            $kind = str_contains($branch, "SELECT 'term' AS source_kind") ? 'term'
                : (str_contains($branch, "SELECT 'meta' AS source_kind") ? 'meta' : '');
            $needle = $kind === 'term' ? 'WHERE tt.term_taxonomy_id IN (' : 'WHERE pm.meta_id IN (';
            if ($kind === '' || !str_contains($branch, $needle)) {
                continue;
            }
            $idsStart = strpos($branch, $needle);
            $idsStart = $idsStart === false ? false : $idsStart + strlen($needle);
            $idsEnd = $idsStart === false ? false : strpos($branch, ')', $idsStart);
            if ($idsStart === false || $idsEnd === false) {
                continue;
            }

            $cap = 0;
            foreach (['LEFT(' => ', ', 'SUBSTR(' => ', 1, '] as $function => $separator) {
                $functionStart = strpos($branch, $function);
                $capStart = $functionStart === false ? false : strpos($branch, $separator, $functionStart);
                if ($capStart === false) {
                    continue;
                }
                $capStart += strlen($separator);
                $capEnd = strpos($branch, ')', $capStart);
                $cap = $capEnd === false ? 0 : (int) trim(substr($branch, $capStart, $capEnd - $capStart));
                break;
            }

            foreach (explode(',', substr($branch, $idsStart, $idsEnd - $idsStart)) as $literal) {
                $sourceId = (int) trim($literal);
                if ($sourceId > 0) {
                    $requests[$sourceId] = max(0, $cap);
                }
            }
        }

        return $requests;
    }

    /** Orders the mixed-key queue deterministically like the production contract. */
    private function sort_v4_queue(): void
    {
        uksort($this->queue, static function (int|string $left, int|string $right): int {
            if (is_int($left) && is_int($right)) {
                return $left <=> $right;
            }
            if (is_int($left)) {
                return -1;
            }
            if (is_int($right)) {
                return 1;
            }
            return strcmp($left, $right);
        });
    }

    /** Read the literal outer LIMIT from a bounded candidate relation. */
    private function bounded_v4_candidate_limit(string $sql, string $kind): int
    {
        $marker = ') bounded_' . $kind . '_candidates';
        $offset = strpos($sql, $marker);
        if ($offset === false) {
            return $kind === 'scope' ? 1 : WP_FTS_Index_Queue::MAX_CLAIM_POSTS;
        }
        $offset = strpos($sql, "\nLIMIT ", $offset + strlen($marker));
        if ($offset === false) {
            return $kind === 'scope' ? 1 : WP_FTS_Index_Queue::MAX_CLAIM_POSTS;
        }
        $offset += strlen("\nLIMIT ");
        $end = strpos($sql, "\n", $offset);
        $literal = trim(substr($sql, $offset, $end === false ? null : $end - $offset));

        return max(0, min(WP_FTS_Index_Queue::MAX_CLAIM_POSTS, (int) $literal));
    }

    /** Remove the epoch row's key and insert-only nonce from a simulated UPSERT. */
    private function consume_search_epoch_insert_args(array &$args): void
    {
        $offset = array_search(WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY, $args, true);
        if ($offset === false) {
            return;
        }
        $this->searchEpoch++;
        $this->capture_search_epoch_incarnation((string) ($args[$offset + 1] ?? ''));
        array_splice($args, $offset, 2);
    }

    /** Captures the first valid incarnation inserted for the search epoch. */
    private function capture_search_epoch_incarnation(string $candidate): void
    {
        if ($this->searchEpochIncarnation === '' && preg_match('/^[a-f0-9]{32}$/D', $candidate) === 1) {
            $this->searchEpochIncarnation = $candidate;
        }
    }

    /** Maps a durable job key to its in-memory queue key when present. */
    private function v4_queue_key_for_job(string $jobKey): int|string|null
    {
        if (str_starts_with($jobKey, 'post:')) {
            $postId = (int) substr($jobKey, strlen('post:'));
            return isset($this->queue[$postId]) ? $postId : null;
        }
        return isset($this->queue[$jobKey]) ? $jobKey : null;
    }

    /** @return array<int,int|string> */
    private function claimable_v4_queue_keys(
        string $kind,
        int $limit,
        int $now,
        bool $recoverGuardedFences = true
    ): array
    {
        if ($limit <= 0) {
            return [];
        }
        $keys = [];
        $states = $recoverGuardedFences
            ? ['guarded', 'ready', 'retry', 'leased']
            : ['ready', 'retry', 'leased'];
        foreach ($states as $state) {
            $stateKeys = [];
            foreach ($this->queue as $key => $row) {
                if (
                    (string) ($row['kind'] ?? '') !== $kind
                    || (string) ($row['state'] ?? '') !== $state
                    || (int) ($row['available_at'] ?? 0) > $now
                    || ($state === 'leased' && (int) ($row['claim_expires_at'] ?? 0) > $now)
                ) {
                    continue;
                }
                $stateKeys[] = $key;
            }
            usort($stateKeys, function (int|string $left, int|string $right) use ($state): int {
                $a = $this->queue[$left];
                $b = $this->queue[$right];
                return ($state === 'leased'
                        ? ((int) ($a['claim_expires_at'] ?? 0) <=> (int) ($b['claim_expires_at'] ?? 0))
                            ?: ((int) ($a['available_at'] ?? 0) <=> (int) ($b['available_at'] ?? 0))
                        : ((int) ($a['available_at'] ?? 0) <=> (int) ($b['available_at'] ?? 0)))
                    ?: ((int) $a['post_id'] <=> (int) $b['post_id'])
                    ?: strcmp((string) $a['job_key'], (string) $b['job_key']);
            });
            // Production bounds every indexed state arm. The guarded arm is
            // omitted entirely when the filesystem probe observes an owner.
            $stateKeys = array_slice($stateKeys, 0, $limit);
            array_push($keys, ...$stateKeys);
        }
        usort($keys, function (int|string $left, int|string $right): int {
            $a = $this->queue[$left];
            $b = $this->queue[$right];
            return (((string) ($a['state'] ?? '') === 'guarded' ? 0 : 1)
                    <=> ((string) ($b['state'] ?? '') === 'guarded' ? 0 : 1))
                ?: (((string) ($a['state'] ?? '') === 'leased'
                        ? (int) ($a['claim_expires_at'] ?? 0)
                        : (int) ($a['available_at'] ?? 0))
                    <=> ((string) ($b['state'] ?? '') === 'leased'
                        ? (int) ($b['claim_expires_at'] ?? 0)
                        : (int) ($b['available_at'] ?? 0)))
                ?: ((int) $a['post_id'] <=> (int) $b['post_id'])
                ?: strcmp((string) $a['job_key'], (string) $b['job_key']);
        });
        return array_slice($keys, 0, $limit);
    }

    /** Applies a worker lease to one in-memory queue row. */
    private function lease_v4_queue_row(int|string $rowKey, string $token, int $expiresAt): void
    {
        $this->queue[$rowKey]['state'] = 'leased';
        $this->queue[$rowKey]['claim_token'] = $token;
        $this->queue[$rowKey]['claimed_generation'] = (int) $this->queue[$rowKey]['generation'];
        $this->queue[$rowKey]['claim_expires_at'] = $expiresAt;
    }

    /** Clears a worker lease and optionally returns its row to ready state. */
    private function release_v4_queue_row(int|string $rowKey, int $availableAt, bool $setReady = true): void
    {
        if ($setReady) {
            $this->queue[$rowKey]['state'] = 'ready';
        }
        $this->queue[$rowKey]['available_at'] = $availableAt;
        $this->queue[$rowKey]['claim_token'] = '';
        $this->queue[$rowKey]['claimed_generation'] = 0;
        $this->queue[$rowKey]['claim_expires_at'] = 0;
    }

    /** Checks that an in-memory row still belongs to the expected lease generation. */
    private function v4_queue_claim_matches(
        int|string|null $rowKey,
        string $token,
        int $claimedGeneration,
        ?int $generation = null
    ): bool {
        if ($rowKey === null) {
            return false;
        }
        $row = $this->queue[$rowKey];
        return (string) ($row['claim_token'] ?? '') === $token
            && (int) ($row['claimed_generation'] ?? 0) === $claimedGeneration
            && ($generation === null || (int) ($row['generation'] ?? 0) === $generation);
    }

    /**
     * @param array<int,mixed> $args
     * @return array{0:int,1:string}|null
     */
    private function doc_write_failure(string $sql, array $args): ?array
    {
        if (!str_starts_with($sql, 'INSERT INTO wp_fts_docs') && !str_starts_with($sql, 'INSERT INTO wp_fts_documents')) {
            return null;
        }

        $docId = (int) ($args[0] ?? 0);
        if ($docId <= 0 || !array_key_exists($docId, $this->failDocWriteErrors)) {
            return null;
        }

        $message = $this->failDocWriteErrors[$docId];

        return [
            $docId,
            $message !== '' ? $message : "simulated failure for doc {$docId}",
        ];
    }

    /**
     * @return object[]
     */
    public function get_results(mixed $statement): array
    {
        [$sql, $args] = $this->statement_parts($statement);
        $this->record_read_query($sql);
        $this->last_error = '';
        if ($this->failReadQueryPrefix !== null && str_starts_with($sql, $this->failReadQueryPrefix)) {
            $this->last_error = "simulated read failure for {$this->failReadQueryPrefix}";
            return [];
        }
        if (str_starts_with($sql, '/* wp_fts:filtered-scope-page */')) {
            $laneCount = max(0, intdiv(max(0, count($args) - 1), 4));
            $lanes = [];
            $cursor = 0;
            for ($lane = 0; $lane < $laneCount; $lane++) {
                $offset = $lane * 4;
                $type = strtolower((string) ($args[$offset] ?? ''));
                $status = strtolower((string) ($args[$offset + 1] ?? ''));
                $cursor = max($cursor, max(0, (int) ($args[$offset + 2] ?? 0)));
                $lanes[$type . "\0" . $status] = true;
            }
            $limit = max(1, (int) ($args[count($args) - 1] ?? 1));
            $posts = [];
            foreach ($this->postRows as $row) {
                if (is_object($row) && (int) ($row->ID ?? 0) > 0) {
                    $posts[(int) $row->ID] = $row;
                }
            }
            foreach ($GLOBALS['wp_fts_test_posts'] ?? [] as $postId => $row) {
                if (is_object($row)) {
                    $posts[(int) $postId] = $row;
                }
            }
            ksort($posts, SORT_NUMERIC);
            $rows = [];
            foreach ($posts as $postId => $post) {
                if ($postId <= $cursor) {
                    continue;
                }
                $key = strtolower((string) ($post->post_type ?? 'post'))
                    . "\0" . strtolower((string) ($post->post_status ?? 'publish'));
                if (!isset($lanes[$key])) {
                    continue;
                }
                $rows[] = (object) ['post_id' => $postId, 'should_process' => 1];
                if (count($rows) >= $limit) {
                    break;
                }
            }

            return $rows;
        }
        if (str_starts_with($sql, '/* wp_fts:corpus-scope-page */')) {
            $statusNames = ['publish', 'draft', 'pending', 'future', 'private', 'trash', 'inherit', 'auto-draft'];
            $allowedStatuses = [];
            $allowedTypes = [];
            $numbers = [];
            foreach ($args as $value) {
                if (is_int($value)) {
                    $numbers[] = $value;
                } elseif (is_string($value) && in_array($value, $statusNames, true)) {
                    $allowedStatuses[$value] = true;
                } elseif (is_string($value) && isset($GLOBALS['wp_fts_test_post_types'][$value])) {
                    $allowedTypes[$value] = true;
                }
            }
            $hasPostBranch = str_contains($sql, 'FROM wp_posts raw_posts');
            $postCursor = $hasPostBranch ? max(0, (int) ($numbers[0] ?? 0)) : 0;
            $postLimit = $hasPostBranch ? max(1, (int) ($numbers[1] ?? 1)) : 0;
            $documentOffset = $hasPostBranch ? 2 : 0;
            $documentCursor = max(0, (int) ($numbers[$documentOffset] ?? 0));
            $documentLimit = max(1, (int) ($numbers[$documentOffset + 1] ?? 1));
            $outerLimit = max(1, (int) ($numbers[$documentOffset + 2] ?? 1));
            $candidates = [];
            if ($hasPostBranch) {
                $posts = [];
                foreach ($this->postRows as $row) {
                    if (is_object($row) && (int) ($row->ID ?? 0) > 0) {
                        $posts[(int) $row->ID] = $row;
                    }
                }
                foreach ($GLOBALS['wp_fts_test_posts'] ?? [] as $postId => $row) {
                    if (is_object($row)) {
                        $posts[(int) $postId] = $row;
                    }
                }
                ksort($posts, SORT_NUMERIC);
                $read = 0;
                foreach ($posts as $postId => $post) {
                    if ($postId <= $postCursor) {
                        continue;
                    }
                    $candidates[$postId] = !empty($candidates[$postId])
                        || (
                            (string) ($post->post_password ?? '') === ''
                            && isset($allowedTypes[(string) ($post->post_type ?? '')])
                            && isset($allowedStatuses[(string) ($post->post_status ?? '')])
                        );
                    if (++$read >= $postLimit) {
                        break;
                    }
                }
            }
            $documentIds = array_map('intval', array_keys($this->docs));
            sort($documentIds, SORT_NUMERIC);
            $read = 0;
            foreach ($documentIds as $postId) {
                if ($postId <= $documentCursor) {
                    continue;
                }
                $candidates[$postId] = true;
                if (++$read >= $documentLimit) {
                    break;
                }
            }
            ksort($candidates, SORT_NUMERIC);
            $rows = [];
            foreach ($candidates as $postId => $shouldProcess) {
                $rows[] = (object) [
                    'post_id' => (int) $postId,
                    'should_process' => $shouldProcess ? 1 : 0,
                ];
                if (count($rows) >= $outerLimit) {
                    break;
                }
            }

            return $rows;
        }
        if (str_starts_with($sql, '/* wp_fts:targeted-scope-page */')) {
            $termTaxonomyId = max(0, (int) ($args[0] ?? 0));
            $cursor = max(0, (int) ($args[1] ?? 0));
            $limit = max(1, (int) ($args[2] ?? 1));
            $relationshipRows = $GLOBALS['wp_fts_test_term_relationship_rows'] ?? null;
            if (!is_array($relationshipRows)) {
                $relationshipRows = [];
                foreach ($GLOBALS['wp_fts_test_term_taxonomy_object_ids'] ?? [] as $subjectId => $objectIds) {
                    foreach (is_array($objectIds) ? $objectIds : [] as $objectId) {
                        $relationshipRows[] = [
                            'object_id' => (int) $objectId,
                            'term_taxonomy_id' => (int) $subjectId,
                        ];
                    }
                }
                if ($relationshipRows === [] && count($GLOBALS['wp_fts_test_term_object_ids'] ?? []) === 1) {
                    foreach ((array) reset($GLOBALS['wp_fts_test_term_object_ids']) as $objectId) {
                        $relationshipRows[] = [
                            'object_id' => (int) $objectId,
                            'term_taxonomy_id' => $termTaxonomyId,
                        ];
                    }
                }
            }
            $objects = [];
            foreach ($relationshipRows as $relationshipRow) {
                if (!is_array($relationshipRow)) {
                    continue;
                }
                $objectId = (int) ($relationshipRow['object_id'] ?? 0);
                if ($objectId > $cursor && (int) ($relationshipRow['term_taxonomy_id'] ?? 0) === $termTaxonomyId) {
                    $objects[$objectId] = true;
                }
            }
            ksort($objects, SORT_NUMERIC);
            $objects = array_slice($objects, 0, $limit, true);

            return array_map(
                static fn(int $objectId): object => (object) [
                    'post_id' => $objectId,
                    'should_process' => 1,
                ],
                array_map('intval', array_keys($objects))
            );
        }
        if (str_starts_with($sql, '/* wp_fts:resolve-prepared-terms */')) {
            $this->ensure_term_identity_maps();
            $resolved = [];
            foreach ($this->v4_literal_identity_rows($sql) as $identity) {
                $ordinal = max(0, (int) $identity['ordinal']);
                $key = $this->v4_storage_term_key(
                    (string) $identity['lang'],
                    (string) $identity['term'],
                    max(0, (int) ($identity['kind'] ?? 0))
                );
                if ($ordinal <= 0) {
                    continue;
                }
                $this->ftsTerms[$key] ??= ['doc_freq' => 1];
                $this->ensure_term_id($key);
                $resolved[] = (object) [
                    'term_ordinal' => $ordinal,
                    'term_id' => $this->termIdsByKey[$key],
                ];
            }

            return $resolved;
        }
        if (str_starts_with($sql, 'SELECT RELEASE_LOCK(%s) AS released_')) {
            $released = [];
            foreach ($args as $offset => $lockName) {
                $lockName = (string) $lockName;
                $value = ($this->advisoryLocks[$lockName] ?? 0) === 1 ? 1 : 0;
                if ($value === 1) {
                    unset($this->advisoryLocks[$lockName]);
                }
                $released['released_' . $offset] = $value;
            }
            return [(object) $released];
        }
        if (str_starts_with($sql, 'PRAGMA table_info(')) {
            $table = trim(substr($sql, strlen('PRAGMA table_info('), -1), " \"'");
            $primary = $this->schemaIndexes[$table]['PRIMARY'] ?? [];

            return array_map(
                static fn(string $column): object => (object) [
                    'name' => $column,
                    'pk' => (($position = array_search($column, $primary, true)) === false ? 0 : $position + 1),
                ],
                $this->schemaColumns[$table] ?? []
            );
        }

        if (
            str_starts_with($sql, 'WITH named_indexes AS (')
            && preg_match("/pragma_index_list\\('([^']+)'\\)/", $sql, $matches) === 1
        ) {
            $table = (string) $matches[1];
            $rows = [];
            $unexpected = false;
            foreach ($this->schemaIndexes[$table] ?? [] as $name => $columns) {
                if ($name === 'PRIMARY') {
                    continue;
                }
                $physicalName = $table . '_' . $name;
                if (!str_contains($sql, "'{$physicalName}'")) {
                    $unexpected = true;
                    continue;
                }
                foreach (array_values($columns) as $offset => $column) {
                    $rows[] = (object) [
                        'index_name' => $physicalName,
                        'is_unique' => !empty($this->schemaUniqueIndexes[$table][$name]) ? 1 : 0,
                        'is_partial' => 0,
                        'column_position' => $offset,
                        'column_name' => $column,
                    ];
                }
            }
            if ($unexpected) {
                $rows[] = (object) [
                    'index_name' => '<unexpected>',
                    'is_unique' => 0,
                    'is_partial' => 0,
                    'column_position' => -1,
                    'column_name' => '<uninspected>',
                ];
            }

            return $rows;
        }

        if (str_starts_with($sql, 'PRAGMA index_list(')) {
            $table = trim(substr($sql, strlen('PRAGMA index_list('), -1), " \"'");
            $rows = [];
            foreach ($this->schemaIndexes[$table] ?? [] as $name => $columns) {
                if ($name !== 'PRIMARY') {
                    $rows[] = (object) [
                        'name' => $table . '__' . $name,
                        'unique' => !empty($this->schemaUniqueIndexes[$table][$name]) ? 1 : 0,
                    ];
                }
            }

            return $rows;
        }

        if (str_starts_with($sql, 'PRAGMA index_info(')) {
            $qualified = trim(substr($sql, strlen('PRAGMA index_info('), -1), " \"'");
            $separator = strrpos($qualified, '__');
            $table = $separator === false ? '' : substr($qualified, 0, $separator);
            $name = $separator === false ? '' : substr($qualified, $separator + 2);
            $columns = $this->schemaIndexes[$table][$name] ?? [];

            return array_map(
                static fn(string $column, int $offset): object => (object) ['name' => $column, 'seqno' => $offset],
                array_values($columns),
                array_keys(array_values($columns))
            );
        }

        if (str_starts_with($sql, '/* wp_fts:physical-schema-capabilities */')) {
            return [
                (object) ['column_name' => 'IS_VISIBLE'],
                (object) ['column_name' => 'EXPRESSION'],
            ];
        }

        if (str_starts_with($sql, '/* wp_fts:physical-schema-snapshot */')) {
            if ($args === []) {
                $rows = [];
                foreach ($this->schemaColumns as $table => $columns) {
                    if (!str_contains($sql, "'{$table}'")) {
                        continue;
                    }
                    $rows[] = (object) [
                        'row_kind' => 'table',
                        'table_name' => $table,
                        'table_exists' => 1,
                    ];
                    $primary = $this->schemaIndexes[$table]['PRIMARY'] ?? [];
                    foreach ($columns as $columnOffset => $column) {
                        $primaryOffset = array_search($column, $primary, true);
                        $rows[] = (object) [
                            'row_kind' => 'column',
                            'table_name' => $table,
                            'column_name' => $column,
                            'ordinal_position' => $columnOffset,
                            'primary_position' => $primaryOffset === false ? 0 : $primaryOffset + 1,
                        ];
                    }
                    $unexpected = false;
                    foreach ($this->schemaIndexes[$table] ?? [] as $name => $indexColumns) {
                        if ($name === 'PRIMARY') {
                            continue;
                        }
                        $physicalName = $table . '_' . $name;
                        if (!str_contains($sql, "'{$physicalName}'")) {
                            $unexpected = true;
                            continue;
                        }
                        foreach (array_values($indexColumns) as $indexOffset => $column) {
                            $rows[] = (object) [
                                'row_kind' => 'index',
                                'table_name' => $table,
                                'index_name' => $physicalName,
                                'is_unique' => !empty($this->schemaUniqueIndexes[$table][$name]) ? 1 : 0,
                                'is_partial' => 0,
                                'index_position' => $indexOffset,
                                'index_column' => $column,
                            ];
                        }
                    }
                    if ($unexpected) {
                        $rows[] = (object) [
                            'row_kind' => 'index',
                            'table_name' => $table,
                            'index_name' => '<unexpected>',
                            'is_unique' => 0,
                            'is_partial' => 0,
                            'index_position' => -1,
                            'index_column' => '<uninspected>',
                        ];
                    }
                }

                return $rows;
            }

            $tableCount = 0;
            $firstTable = is_scalar($args[0] ?? null) ? (string) $args[0] : '';
            for ($offset = 1; $offset < count($args); $offset++) {
                if ((string) $args[$offset] === $firstTable) {
                    $tableCount = $offset;
                    break;
                }
            }
            $tables = array_map('strval', array_slice($args, 0, $tableCount));
            $rows = [];
            foreach ($tables as $table) {
                if (!isset($this->schemaColumns[$table])) {
                    continue;
                }
                $rows[] = (object) [
                    'row_kind' => 'table',
                    'table_name' => $table,
                    'engine' => $this->schemaEngines[$table] ?? 'InnoDB',
                ];
                foreach ($this->schemaColumns[$table] as $columnOffset => $column) {
                    $definition = $this->schema_column_definition($table, $column);
                    $rows[] = (object) [
                        'row_kind' => 'column',
                        'table_name' => $table,
                        'column_name' => $column,
                        'column_type' => $definition['Type'],
                        'is_nullable' => $definition['Null'],
                        'column_extra' => $definition['Extra'],
                        'ordinal_position' => $columnOffset + 1,
                    ];
                }
                foreach ($this->schemaIndexes[$table] ?? [] as $name => $columns) {
                    foreach (array_values($columns) as $indexOffset => $column) {
                        $rows[] = (object) [
                            'row_kind' => 'index',
                            'table_name' => $table,
                            'index_name' => $name,
                            'index_column' => $column,
                            'index_position' => $indexOffset + 1,
                            'non_unique' => !empty($this->schemaUniqueIndexes[$table][$name]) ? 0 : 1,
                            'sub_part' => $this->schemaIndexSubParts[$table][$name][$indexOffset] ?? null,
                            'index_type' => 'BTREE',
                            'index_visible' => !empty($this->schemaInvisibleIndexes[$table][$name]) ? 'NO' : 'YES',
                            'index_ignored' => '',
                            'index_expression' => '',
                        ];
                    }
                }
            }

            return $rows;
        }

        if ($sql === 'SHOW TABLE STATUS LIKE %s') {
            $table = str_replace(['\\_', '\\%'], ['_', '%'], (string) ($args[0] ?? ''));
            return isset($this->schemaColumns[$table])
                ? [(object) ['Name' => $table, 'Engine' => $this->schemaEngines[$table] ?? 'InnoDB']]
                : [];
        }

        if (str_starts_with($sql, 'SHOW COLUMNS FROM ')) {
            $table = trim(substr($sql, strlen('SHOW COLUMNS FROM ')), " `\t\r\n");

            return array_map(
                fn(string $column): object => (object) $this->schema_column_definition($table, $column),
                $this->schemaColumns[$table] ?? []
            );
        }

        if (str_starts_with($sql, 'SHOW INDEX FROM ')) {
            $remainder = trim(substr($sql, strlen('SHOW INDEX FROM ')));
            $where = stripos($remainder, ' WHERE ');
            $table = trim($where === false ? $remainder : substr($remainder, 0, $where), " `\t\r\n");
            $requestedName = $where === false ? null : (string) ($args[0] ?? '');
            $rows = [];
            foreach ($this->schemaIndexes[$table] ?? [] as $name => $columns) {
                if ($requestedName !== null && strcasecmp($name, $requestedName) !== 0) {
                    continue;
                }
                foreach (array_values($columns) as $offset => $column) {
                    $rows[] = (object) [
                        'Key_name' => $name,
                        'Column_name' => $column,
                        'Seq_in_index' => $offset + 1,
                        'Non_unique' => !empty($this->schemaUniqueIndexes[$table][$name]) ? 0 : 1,
                        'Sub_part' => $this->schemaIndexSubParts[$table][$name][$offset] ?? null,
                        'Index_type' => 'BTREE',
                        'Visible' => !empty($this->schemaInvisibleIndexes[$table][$name]) ? 'NO' : 'YES',
                    ];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, '/* wp_fts:polylang-languages */')) {
            $requested = array_fill_keys(array_filter(array_map('intval', $args), static fn(int $post_id): bool => $post_id > 0), true);
            $rows = [];
            foreach ($GLOBALS['wp_fts_ldgf_polylang_post_languages'] ?? [] as $post_id => $language) {
                $post_id = (int) $post_id;
                if (!isset($requested[$post_id]) || !is_scalar($language) || trim((string) $language) === '') {
                    continue;
                }
                $canonical = WP_FTS_TermNamespace::canonicalize_lang((string) $language);
                $rows[] = (object) [
                    'post_id' => $post_id,
                    'language_slug' => explode('-', $canonical, 2)[0],
                    'language_description' => serialize(['locale' => str_replace('-', '_', (string) $language)]),
                ];
            }
            usort($rows, static fn(object $left, object $right): int => (int) $left->post_id <=> (int) $right->post_id);
            return $rows;
        }

        if (str_starts_with($sql, '/* wp_fts:wpml-languages */')) {
            $requested = array_fill_keys(array_filter(array_map('intval', $args), static fn(int $post_id): bool => $post_id > 0), true);
            $rows = [];
            foreach ($GLOBALS['wp_fts_ldgf_wpml_post_languages'] ?? [] as $post_id => $language) {
                $post_id = (int) $post_id;
                if (!isset($requested[$post_id]) || !is_scalar($language) || trim((string) $language) === '') {
                    continue;
                }
                $rows[] = (object) ['post_id' => $post_id, 'language_code' => (string) $language];
            }
            usort($rows, static fn(object $left, object $right): int => (int) $left->post_id <=> (int) $right->post_id);
            return $rows;
        }

        if (str_starts_with($sql, "SELECT p.ID, OCTET_LENGTH(COALESCE(p.post_title, ''))")) {
            $rows = [];
            foreach (array_values(array_unique(array_map('intval', $args))) as $postId) {
                $post = $GLOBALS['wp_fts_test_posts'][$postId] ?? null;
                if (!is_object($post)) {
                    foreach ($this->postRows as $candidate) {
                        if (is_object($candidate) && (int) ($candidate->ID ?? 0) === $postId) {
                            $post = $candidate;
                            break;
                        }
                    }
                }
                if (!is_object($post)) {
                    continue;
                }
                $rows[] = (object) [
                    'ID' => $postId,
                    'fts_post_source_bytes' => strlen((string) ($post->post_title ?? ''))
                        + strlen((string) ($post->post_content ?? ''))
                        + strlen((string) ($post->post_excerpt ?? '')),
                    'fts_canonical_post_bytes' => $this->v4_canonical_post_bytes($post),
                ];
            }
            return $rows;
        }

        if (str_starts_with($sql, '/* wp_fts:hydrate */')) {
            $snapshotReady = $this->v4_search_snapshot_ready($sql, $args, true);
            if (!$snapshotReady) {
                return [(object) ['doc_id' => null, 'snapshot_ready' => 0]];
            }
            $controlArgCount = 9;
            $idCount = substr_count($sql, 'SELECT %d AS post_id');
            $ids = array_values(array_unique(array_map('intval', array_slice($args, $controlArgCount, $idCount))));
            $offset = $controlArgCount + $idCount;
            $statuses = array_map('strval', $this->prepared_in_args($sql, 'wp_h.post_status', '%s', $args, $offset));
            $types = array_map('strval', $this->prepared_in_args($sql, 'wp_h.post_type', '%s', $args, $offset));
            $dateAfter = str_contains($sql, 'wp_h.post_date_gmt >= %s') ? (string) ($args[$offset++] ?? '') : '';
            $dateBefore = str_contains($sql, 'wp_h.post_date_gmt <= %s') ? (string) ($args[$offset++] ?? '') : '';
            $hasGlobalScope = false;
            $dirty = [];
            foreach ($this->queue as $work) {
                if ((string) ($work['kind'] ?? '') === 'post') {
                    $dirty[(int) ($work['post_id'] ?? 0)] = true;
                } elseif (
                    (string) ($work['kind'] ?? '') === 'scope'
                    && (string) ($work['scope_subject_type'] ?? '') === ''
                ) {
                    $hasGlobalScope = true;
                }
            }
            if ($hasGlobalScope) {
                return [(object) ['doc_id' => null, 'snapshot_ready' => 0]];
            }

            $rows = [];
            foreach ($ids as $postId) {
                if ($postId <= 0 || !isset($this->docs[$postId]) || isset($dirty[$postId])) {
                    continue;
                }
                $post = $this->v4_post_row($postId);
                $status = (string) ($post->post_status ?? 'draft');
                $type = (string) ($post->post_type ?? 'post');
                $date = (string) ($post->post_date_gmt ?? '1970-01-01 00:00:00');
                if (
                    (string) ($post->post_password ?? '') !== ''
                    || ($statuses !== [] && !in_array($status, $statuses, true))
                    || ($types !== [] && !in_array($type, $types, true))
                    || ($dateAfter !== '' && strcmp($date, $dateAfter) < 0)
                    || ($dateBefore !== '' && strcmp($date, $dateBefore) > 0)
                ) {
                    continue;
                }
                $doc = $this->docs[$postId];
                $detail = (object) [
                    'doc_id' => $postId,
                    'snapshot_ready' => 1,
                    'primary_lang' => (string) ($doc['primary_lang'] ?? $doc['lang'] ?? 'und'),
                    'snippet_text' => (string) ($doc['snippet_text'] ?? $this->docMeta[$postId]['search_text'] ?? ''),
                    'post_type' => $type,
                    'post_status' => $status,
                    'post_date_gmt' => $date,
                    'post_title' => (string) ($post->post_title ?? ''),
                    'post_excerpt' => (string) ($post->post_excerpt ?? ''),
                ];
                if (str_contains($sql, 'canonical_post_ID')) {
                    foreach ([
                        'ID', 'post_author', 'post_date', 'post_date_gmt', 'post_content', 'post_title',
                        'post_excerpt', 'post_status', 'comment_status', 'ping_status', 'post_password',
                        'post_name', 'to_ping', 'pinged', 'post_modified', 'post_modified_gmt',
                        'post_content_filtered', 'post_parent', 'guid', 'menu_order', 'post_type',
                        'post_mime_type', 'comment_count',
                    ] as $column) {
                        $detail->{'canonical_post_' . $column} = $post->{$column} ?? ($column === 'ID' ? $postId : '');
                    }
                }
                $rows[] = $detail;
            }

            return $rows !== [] ? $rows : [(object) ['doc_id' => null, 'snapshot_ready' => 1]];
        }

        if (str_starts_with($sql, '/* wp_fts:rank */')) {
            return $this->get_v4_rank_results($sql, $args);
        }

        if (str_contains($sql, 'wp_fts_terms') || str_contains($sql, 'wp_fts_postings') || str_contains($sql, 'wp_fts_documents')) {
            $rows = $this->get_v4_storage_results($sql, $args);
            if ($rows !== null) {
                return $rows;
            }
        }

        if (str_contains($sql, 'FROM wp_fts_work')) {
            return $this->get_v4_work_results($sql, $args);
        }

        if (str_starts_with($sql, 'SELECT post_id, generation, attempts')) {
            $availableAt = (int) ($args[0] ?? 0);
            $expiredAt = (int) ($args[1] ?? 0);
            $limit = max(0, (int) ($args[2] ?? 0));
            $rows = [];
            foreach ($this->queue as $postId => $row) {
                if (
                    $row['available_at'] > $availableAt
                    || ($row['claim_token'] !== '' && $row['claim_expires_at'] > $expiredAt)
                ) {
                    continue;
                }
                $rows[] = (object) [
                    'post_id' => $postId,
                    'generation' => $row['generation'],
                    'attempts' => $row['attempts'],
                    'available_at' => $row['available_at'],
                ];
            }
            usort($rows, static function (object $left, object $right): int {
                return ((int) $left->available_at <=> (int) $right->available_at)
                    ?: ((int) $left->post_id <=> (int) $right->post_id);
            });

            return array_slice($rows, 0, $limit);
        }

        if (str_starts_with($sql, 'SELECT ID, post_type, post_status, post_password FROM `wp_posts` WHERE ID IN (')) {
            $requested = array_fill_keys(array_map('intval', $args), true);
            $rows = [];
            foreach ($GLOBALS['wp_fts_test_posts'] as $post_id => $post) {
                if (!is_object($post) || !isset($requested[(int) $post_id])) {
                    continue;
                }
                $rows[] = (object) [
                    'ID' => (int) $post_id,
                    'post_type' => isset($post->post_type) ? (string) $post->post_type : 'post',
                    'post_status' => isset($post->post_status) ? (string) $post->post_status : 'draft',
                    'post_password' => isset($post->post_password) ? (string) $post->post_password : '',
                ];
            }
            usort($rows, static fn(object $left, object $right): int => (int) $left->ID <=> (int) $right->ID);

            return $rows;
        }

        if (str_starts_with($sql, 'SELECT * FROM wp_posts WHERE ID IN (')) {
            $requested = array_fill_keys(array_map('intval', $args), true);
            $rows = [];
            foreach ($requested as $postId => $_) {
                $post = $GLOBALS['wp_fts_test_posts'][$postId] ?? null;
                if (!is_object($post)) {
                    foreach ($this->postRows as $candidate) {
                        if (is_object($candidate) && (int) ($candidate->ID ?? 0) === $postId) {
                            $post = $candidate;
                            break;
                        }
                    }
                }
                if (is_object($post)) {
                    $rows[] = clone $post;
                }
            }
            return $rows;
        }

        if (
            str_contains($sql, 'source_id')
            && (
                str_contains($sql, 'WHERE tt.term_taxonomy_id IN (')
                || str_contains($sql, 'WHERE pm.meta_id IN (')
            )
        ) {
            $requests = $this->dependency_value_requests($sql);
            $this->dependencyValueQueries[] = $sql;
            $this->dependencyValueSourceIdsRequested = array_values(array_unique([
                ...$this->dependencyValueSourceIdsRequested,
                ...array_keys($requests),
            ]));
            sort($this->dependencyValueSourceIdsRequested, SORT_NUMERIC);
            $rows = [];
            foreach ($requests as $sourceId => $cap) {
                $source = $this->dependencySources[$sourceId] ?? null;
                $current = $this->dependency_source_value($sourceId);
                if (!is_array($source) || $current === null) {
                    continue;
                }
                $value = substr($current['value'], 0, $cap);
                $this->dependencyValueBytesProjected += strlen($value);
                $rows[] = (object) [
                    'source_kind' => $source['kind'],
                    'source_id' => $sourceId,
                    'item_key' => $current['key'],
                    'item_value' => $value,
                    'item_value_bytes' => strlen($current['value']),
                ];
            }

            return $rows;
        }

        if (str_starts_with($sql, 'SELECT bounded.post_order, bounded.row_order, bounded.source_kind,')) {
            $postIds = [];
            foreach ($args as $arg) {
                if (!is_int($arg) || $this->dependency_fixture_post($arg) === null) {
                    continue;
                }
                $postIds[$arg] = true;
            }
            $postIds = array_map('intval', array_keys($postIds));
            sort($postIds, SORT_NUMERIC);
            $selectedKeys = array_fill_keys(array_values(array_unique(array_map(
                'strval',
                array_filter($args, static fn(mixed $value): bool => is_string($value))
            ))), true);
            $metaRows = [];
            $termRows = [];
            $polylangRows = [];
            $wpmlRows = [];
            foreach ($postIds as $postId) {
                $post = $this->dependency_fixture_post($postId);
                if ($post === null) {
                    continue;
                }

                $meta = [];
                if (is_array($post->custom_fields ?? null)) {
                    $meta = $post->custom_fields;
                }
                foreach ($GLOBALS['wp_fts_test_post_meta'][$postId] ?? [] as $key => $values) {
                    $meta[(string) $key] = $values;
                }
                foreach ($meta as $key => $values) {
                    foreach (is_array($values) ? array_values($values) : [$values] as $occurrence => $value) {
                        $value = is_scalar($value) ? (string) $value : serialize($value);
                        $sourceId = $this->dependency_source_id('meta', $postId, (string) $key, (int) $occurrence);
                        $selected = isset($selectedKeys[(string) $key]);
                        $metaRows[] = (object) [
                            'post_order' => $postId,
                            'row_order' => 0,
                            'source_kind' => 'meta',
                            'post_id' => $postId,
                            'item_key' => (string) $key,
                            'source_id' => $sourceId,
                            'item_value_bytes' => $selected
                                ? $this->dependency_fixture_value_bytes(
                                    'meta',
                                    $postId,
                                    (string) $key,
                                    (int) $occurrence,
                                    $value
                                )
                                : 0,
                            'source_order' => $sourceId,
                            'is_selected' => 0,
                        ];
                    }
                }

                foreach (is_array($post->terms ?? null) ? $post->terms : [] as $taxonomy => $values) {
                    $occurrence = 0;
                    foreach (is_array($values) ? $values : [$values] as $value) {
                        if (!is_scalar($value) || trim((string) $value) === '') {
                            continue;
                        }
                        $value = (string) $value;
                        $sourceId = $this->dependency_source_id('term', $postId, (string) $taxonomy, $occurrence++);
                        $termRows[] = (object) [
                            'post_order' => $postId,
                            'row_order' => 0,
                            'source_kind' => 'term',
                            'post_id' => $postId,
                            'item_key' => (string) $taxonomy,
                            'source_id' => $sourceId,
                            'item_value_bytes' => $this->dependency_fixture_value_bytes(
                                'term',
                                $postId,
                                (string) $taxonomy,
                                $occurrence - 1,
                                $value
                            ),
                            'source_order' => $sourceId,
                            'is_selected' => 1,
                        ];
                    }
                }

                if (str_contains($sql, 'wp_fts:polylang-languages')) {
                    $language = $GLOBALS['wp_fts_ldgf_polylang_post_languages'][$postId] ?? null;
                    if (is_scalar($language) && trim((string) $language) !== '') {
                        $canonical = WP_FTS_TermNamespace::canonicalize_lang((string) $language);
                        $sourceId = $this->dependency_source_id('polylang', $postId, 'language', 0);
                        $polylangRows[] = (object) [
                            'post_order' => $postId,
                            'row_order' => 0,
                            'source_kind' => 'polylang',
                            'post_id' => $postId,
                            'item_key' => explode('-', $canonical, 2)[0],
                            'source_id' => $sourceId,
                            'item_value_bytes' => 0,
                            'source_order' => $sourceId,
                            'is_selected' => 0,
                            'item_value' => serialize(['locale' => str_replace('-', '_', (string) $language)]),
                        ];
                    }
                }
                if (str_contains($sql, 'wp_fts:wpml-languages')) {
                    $language = $GLOBALS['wp_fts_ldgf_wpml_post_languages'][$postId] ?? null;
                    if (is_scalar($language) && trim((string) $language) !== '') {
                        $sourceId = $this->dependency_source_id('wpml', $postId, 'language', 0);
                        $wpmlRows[] = (object) [
                            'post_order' => $postId,
                            'row_order' => 0,
                            'source_kind' => 'wpml',
                            'post_id' => $postId,
                            'item_key' => '',
                            'source_id' => $sourceId,
                            'item_value_bytes' => 0,
                            'source_order' => $sourceId,
                            'is_selected' => 0,
                            'item_value' => (string) $language,
                        ];
                    }
                }
            }

            $sourceSort = static function (object $left, object $right): int {
                return (int) $left->post_id <=> (int) $right->post_id
                    ?: (int) $left->source_order <=> (int) $right->source_order;
            };
            usort($termRows, $sourceSort);
            usort($metaRows, $sourceSort);
            usort($polylangRows, $sourceSort);
            usort($wpmlRows, $sourceSort);
            $rows = [
                ...array_slice($termRows, 0, 2049),
                ...array_slice($polylangRows, 0, 2049),
                ...array_slice($metaRows, 0, 2049),
                ...array_slice($wpmlRows, 0, WP_FTS_Index_Queue::MAX_CLAIM_POSTS + 1),
            ];
            foreach ($postIds as $postId) {
                $rows[] = (object) [
                    'post_order' => $postId,
                    'row_order' => 1,
                    'source_kind' => 'complete',
                    'post_id' => $postId,
                    'item_key' => '',
                    'source_id' => 0,
                    'item_value_bytes' => 0,
                    'source_order' => 0,
                    'is_selected' => 0,
                ];
            }

            $afterMeasurement = $GLOBALS['wp_fts_test_dependency_after_measurement'] ?? null;
            if (is_callable($afterMeasurement)) {
                unset($GLOBALS['wp_fts_test_dependency_after_measurement']);
                $afterMeasurement($this, $rows);
            }

            return $rows;
        }

        if (str_starts_with($sql, 'SELECT dependency.post_id,')) {
            $keys = array_values(array_unique(array_map(
                'strval',
                array_filter($args, static fn(mixed $value): bool => is_string($value))
            )));
            $rows = [];
            foreach ($this->dependency_post_ids_from_args($args) as $postId) {
                $post = $this->dependency_fixture_post($postId);
                if ($post === null) {
                    continue;
                }
                $count = 0;
                $bytes = 0;
                $maxValueBytes = 0;
                foreach (is_array($post->terms ?? null) ? $post->terms : [] as $taxonomy => $values) {
                    foreach (is_array($values) ? $values : [$values] as $value) {
                        if (!is_scalar($value) || trim((string) $value) === '') {
                            continue;
                        }
                        $valueBytes = strlen((string) $value);
                        $count++;
                        $bytes += strlen((string) $taxonomy) + $valueBytes;
                        $maxValueBytes = max($maxValueBytes, $valueBytes);
                    }
                }
                foreach ($keys as $key) {
                    foreach ($this->dependency_meta_values($postId, $post, $key) as $value) {
                        $valueBytes = strlen((string) $value);
                        $count++;
                        $bytes += strlen($key) + $valueBytes;
                        $maxValueBytes = max($maxValueBytes, $valueBytes);
                    }
                }
                if ($count > 0) {
                    $rows[] = (object) [
                        'post_id' => $postId,
                        'dependency_rows' => $count,
                        'dependency_bytes' => $bytes,
                        'max_value_bytes' => $maxValueBytes,
                    ];
                }
            }
            return $rows;
        }

        if (
            str_contains($sql, 'item_value_bytes')
            && (
                (str_contains($sql, "SELECT 'term' AS source_kind") && str_contains($sql, 'FROM wp_term_relationships'))
                || (str_contains($sql, "SELECT 'meta' AS source_kind") && str_contains($sql, 'FROM wp_postmeta'))
            )
        ) {
            $keys = array_values(array_unique(array_map(
                'strval',
                array_filter($args, static fn(mixed $value): bool => is_string($value))
            )));
            $rows = [];
            $sourceOrder = 1;
            foreach ($this->dependency_post_ids_from_args($args) as $postId) {
                $post = $this->dependency_fixture_post($postId);
                if ($post === null) {
                    continue;
                }
                foreach (is_array($post->terms ?? null) ? $post->terms : [] as $taxonomy => $values) {
                    foreach (is_array($values) ? $values : [$values] as $value) {
                        if (!is_scalar($value) || trim((string) $value) === '') {
                            continue;
                        }
                        $rows[] = (object) [
                            'source_kind' => 'term',
                            'post_id' => $postId,
                            'item_key' => (string) $taxonomy,
                            'item_value' => substr((string) $value, 0, 262145),
                            'item_value_bytes' => strlen((string) $value),
                            'source_order' => $sourceOrder++,
                        ];
                    }
                }
                foreach ($keys as $key) {
                    foreach ($this->dependency_meta_values($postId, $post, $key) as $value) {
                        $rows[] = (object) [
                            'source_kind' => 'meta',
                            'post_id' => $postId,
                            'item_key' => $key,
                            'item_value' => substr((string) $value, 0, 262145),
                            'item_value_bytes' => strlen((string) $value),
                            'source_order' => $sourceOrder++,
                        ];
                    }
                }
            }
            usort($rows, static fn(object $left, object $right): int => ((int) $left->post_id <=> (int) $right->post_id)
                ?: strcmp((string) $left->source_kind, (string) $right->source_kind)
                ?: ((int) $left->source_order <=> (int) $right->source_order));
            $limit = max(0, (int) ($args[count($args) - 1] ?? count($rows)));
            return array_slice($rows, 0, $limit);
        }

        if (
            (str_contains($sql, "SELECT 'term' AS source_kind") && str_contains($sql, 'FROM wp_term_relationships'))
            || (str_contains($sql, "SELECT 'meta' AS source_kind") && str_contains($sql, 'FROM wp_postmeta'))
        ) {
            $offset = 0;
            $rows = [];
            $sourceOrder = 1;
            $termPostIds = array_map('intval', $this->prepared_in_args($sql, 'tr.object_id', '%d', $args, $offset));
            foreach ($termPostIds as $postId) {
                $post = $this->v4_post_row($postId);
                foreach (is_array($post->terms ?? null) ? $post->terms : [] as $taxonomy => $values) {
                    foreach (is_array($values) ? $values : [$values] as $value) {
                        if (!is_scalar($value) || trim((string) $value) === '') {
                            continue;
                        }
                        $rows[] = (object) [
                            'source_kind' => 'term',
                            'post_id' => $postId,
                            'item_key' => (string) $taxonomy,
                            'item_value' => (string) $value,
                            'source_order' => $sourceOrder++,
                        ];
                    }
                }
            }

            $metaPostIds = array_map('intval', $this->prepared_in_args($sql, 'post_id', '%d', $args, $offset));
            $keys = array_map('strval', $this->prepared_in_args($sql, 'meta_key', '%s', $args, $offset));
            foreach ($metaPostIds as $postId) {
                $post = $this->v4_post_row($postId);
                foreach ($keys as $key) {
                    $values = $GLOBALS['wp_fts_test_post_meta'][$postId][$key]
                        ?? (is_array($post->custom_fields ?? null) ? ($post->custom_fields[$key] ?? []) : []);
                    foreach (is_array($values) ? $values : [$values] as $value) {
                        $rows[] = (object) [
                            'source_kind' => 'meta',
                            'post_id' => $postId,
                            'item_key' => $key,
                            'item_value' => $value,
                            'source_order' => $sourceOrder++,
                        ];
                    }
                }
            }
            return $rows;
        }

        if ($this->missPreparedTermLookups && $args !== [] && (
            str_starts_with($sql, 'SELECT term, doc_freq FROM wp_fts_terms')
            || str_starts_with($sql, 'SELECT term, doc_id, tf FROM wp_fts_postings')
        ) && $this->binary_term_literals($sql) === []) {
            return [];
        }

        if (str_starts_with($sql, 'SELECT term, doc_freq FROM wp_fts_terms')) {
            $rows = [];
            $terms = $this->binary_term_literals($sql);
            if ($terms === []) {
                $terms = $args === [] ? array_keys($this->ftsTerms) : $args;
            }
            foreach ($terms as $term) {
                $term = (string) $term;
                if (isset($this->ftsTerms[$term])) {
                    $rows[] = (object) [
                        'term' => $term,
                        'doc_freq' => $this->ftsTerms[$term]['doc_freq'],
                    ];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term FROM wp_fts_terms') && str_contains($sql, 'WHERE term >=')) {
            $termLiterals = $this->binary_term_literals($sql);
            $lower = (string) ($termLiterals[0] ?? $args[0] ?? '');
            $hasUpper = str_contains($sql, 'term <');
            $upper = $hasUpper ? (string) ($termLiterals[1] ?? $args[1] ?? '') : null;
            if ($termLiterals !== []) {
                $limitArg = $args[0] ?? 0;
            } else {
                $limitArg = $hasUpper ? ($args[2] ?? 0) : ($args[1] ?? 0);
            }
            $limit = max(0, (int) $limitArg);
            $terms = array_keys($this->ftsTerms);
            sort($terms, SORT_STRING);

            $rows = [];
            foreach ($terms as $term) {
                if (strcmp($term, $lower) < 0 || ($upper !== null && strcmp($term, $upper) >= 0)) {
                    continue;
                }

                $rows[] = (object) ['term' => $term];
                if (count($rows) >= $limit) {
                    break;
                }
            }

            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term, doc_id, tf FROM (') && str_contains($sql, 'AS budgeted_postings')) {
            $rowLimit = max(0, (int) array_pop($args));
            $rows = [];
            for ($index = 0; $index + 1 < count($args); $index += 2) {
                $term = (string) $args[$index];
                $termLimit = max(0, (int) $args[$index + 1]);
                $postings = $this->postings[$term] ?? [];
                ksort($postings, SORT_NUMERIC);
                foreach (array_slice($postings, 0, $termLimit, true) as $docId => $tf) {
                    $rows[] = (object) ['term' => $term, 'doc_id' => (int) $docId, 'tf' => (int) $tf];
                }
            }
            usort($rows, static function (object $a, object $b): int {
                $term = strcmp((string) $a->term, (string) $b->term);
                return $term !== 0 ? $term : ((int) $a->doc_id <=> (int) $b->doc_id);
            });

            return array_slice($rows, 0, $rowLimit);
        }

        if (
            str_starts_with($sql, 'SELECT term, doc_id, tf FROM wp_fts_postings')
            && str_contains($sql, 'WHERE term IN')
            && str_contains($sql, 'LIMIT %d')
        ) {
            $rowLimit = max(0, (int) array_pop($args));
            $terms = $this->binary_term_literals($sql);
            if ($terms === []) {
                $terms = $args;
            }
            $rows = [];
            foreach ($terms as $term) {
                $term = (string) $term;
                $postings = $this->postings[$term] ?? [];
                ksort($postings, SORT_NUMERIC);
                foreach ($postings as $docId => $tf) {
                    $rows[] = (object) ['term' => $term, 'doc_id' => (int) $docId, 'tf' => (int) $tf];
                    if (count($rows) >= $rowLimit) {
                        break 2;
                    }
                }
            }

            return $rows;
        }

        if (
            str_starts_with($sql, 'SELECT term, doc_id, tf FROM wp_fts_postings')
            && str_contains($sql, 'WHERE term =')
            && str_contains($sql, 'LIMIT %d')
        ) {
            $termLiterals = $this->binary_term_literals($sql);
            $term = (string) ($termLiterals[0] ?? $args[0] ?? '');
            $limitArg = $termLiterals !== [] ? ($args[0] ?? 0) : ($args[1] ?? 0);
            $limit = max(0, (int) $limitArg);
            $rows = [];
            $postings = $this->postings[$term] ?? [];
            ksort($postings, SORT_NUMERIC);
            foreach (array_slice($postings, 0, $limit, true) as $docId => $tf) {
                $rows[] = (object) ['term' => $term, 'doc_id' => (int) $docId, 'tf' => (int) $tf];
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term, doc_id, tf FROM wp_fts_postings')) {
            $rows = [];
            $terms = $this->binary_term_literals($sql);
            if ($terms === []) {
                $terms = $args === [] ? array_keys($this->postings) : $args;
            }
            foreach ($terms as $term) {
                $term = (string) $term;
                foreach ($this->postings[$term] ?? [] as $docId => $tf) {
                    $rows[] = (object) ['term' => $term, 'doc_id' => (int) $docId, 'tf' => (int) $tf];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term FROM wp_fts_postings WHERE doc_id = %d')) {
            $docId = (int) $args[0];
            $rows = [];
            foreach ($this->postings as $term => $postings) {
                if (isset($postings[$docId])) {
                    $rows[] = (object) ['term' => $term];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term, COUNT(*) AS c FROM wp_fts_postings')) {
            $docIds = array_fill_keys(array_map('intval', $args), true);
            $counts = [];
            foreach ($this->postings as $term => $postings) {
                foreach ($postings as $docId => $_) {
                    if (isset($docIds[(int) $docId])) {
                        $counts[$term] = ($counts[$term] ?? 0) + 1;
                    }
                }
            }
            ksort($counts, SORT_STRING);

            $rows = [];
            foreach ($counts as $term => $count) {
                $rows[] = (object) ['term' => $term, 'c' => $count];
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT dl.doc_id, dl.doc_len FROM wp_fts_doc_lengths')) {
            $lang = (string) $args[0];
            $ids = array_map('intval', array_slice($args, 1));
            $rows = [];
            foreach ($ids as $docId) {
                if (($this->docs[$docId]['is_deleted'] ?? 1) === 0 && isset($this->docLengths[$docId][$lang])) {
                    $rows[] = (object) ['doc_id' => $docId, 'doc_len' => $this->docLengths[$docId][$lang]];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT doc_id, doc_len FROM wp_fts_docs')) {
            $rows = [];
            foreach (array_map('intval', $args) as $docId) {
                if (($this->docs[$docId]['is_deleted'] ?? 1) === 0) {
                    $rows[] = (object) ['doc_id' => $docId, 'doc_len' => $this->docs[$docId]['doc_len']];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT lang, doc_len FROM wp_fts_doc_lengths')) {
            $rows = [];
            foreach ($this->docLengths[(int) $args[0]] ?? [] as $lang => $docLen) {
                $rows[] = (object) ['lang' => $lang, 'doc_len' => $docLen];
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT m.doc_id, m.post_id, m.post_type')) {
            $rows = [];
            foreach (array_map('intval', $args) as $docId) {
                if (($this->docs[$docId]['is_deleted'] ?? 1) === 0 && isset($this->docMeta[$docId])) {
                    $rows[] = (object) $this->docMeta[$docId];
                }
            }
            usort($rows, static fn(object $a, object $b): int => (int) $a->doc_id <=> (int) $b->doc_id);

            return $rows;
        }

        if (str_starts_with($sql, 'SELECT m.doc_id') && str_contains($sql, 'FROM wp_fts_docmeta')) {
            $offset = 0;
            $docIds = $this->prepared_in_args($sql, 'm.doc_id', '%d', $args, $offset);
            $postTypes = $this->prepared_in_args($sql, 'm.post_type', '%s', $args, $offset);
            $postStatuses = $this->prepared_in_args($sql, 'm.post_status', '%s', $args, $offset);
            $dateAfter = str_contains($sql, 'm.post_date_gmt >= %s') ? (string) ($args[$offset++] ?? '') : null;
            $dateBefore = str_contains($sql, 'm.post_date_gmt <= %s') ? (string) ($args[$offset++] ?? '') : null;

            $rows = [];
            foreach (array_map('intval', $docIds) as $docId) {
                if (($this->docs[$docId]['is_deleted'] ?? 1) !== 0 || !isset($this->docMeta[$docId])) {
                    continue;
                }

                if (WP_FTS_StorageCompat::metadata_matches_filters(
                    $this->docMeta[$docId],
                    array_map('strval', $postTypes),
                    array_map('strval', $postStatuses),
                    $dateAfter,
                    $dateBefore
                )) {
                    $rows[] = (object) ['doc_id' => $docId];
                }
            }
            usort($rows, static fn(object $a, object $b): int => (int) $a->doc_id <=> (int) $b->doc_id);

            return $rows;
        }

        if (str_starts_with($sql, 'SELECT k, v FROM wp_fts_meta WHERE lang = %s')) {
            $rows = [];
            foreach ($this->meta[(string) $args[0]] ?? [] as $key => $value) {
                $rows[] = (object) ['k' => $key, 'v' => $value];
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT k, COALESCE(SUM(v), 0) AS v FROM wp_fts_meta')) {
            $aggregate = [];
            foreach ($this->meta as $row) {
                foreach ($row as $key => $value) {
                    $aggregate[$key] = ($aggregate[$key] ?? 0) + $value;
                }
            }
            $rows = [];
            foreach ($aggregate as $key => $value) {
                $rows[] = (object) ['k' => $key, 'v' => $value];
            }
            return $rows;
        }

        if (
            str_starts_with($sql, 'SELECT d.doc_id AS ID, p.post_content, p.post_title')
            && str_contains($sql, 'FROM wp_fts_docs d')
        ) {
            $last = max(0, (int) ($args[0] ?? 0));
            $maxDocId = max(0, (int) ($args[1] ?? 0));
            $limit = max(0, (int) ($args[2] ?? 0));
            $postsById = [];
            foreach ($this->postRows as $row) {
                if (is_object($row) && isset($row->ID)) {
                    $postsById[(int) $row->ID] = $row;
                }
            }

            $rows = [];
            foreach ($this->docs as $docId => $doc) {
                $docId = (int) $docId;
                if ($docId <= $last || $docId > $maxDocId || ($doc['is_deleted'] ?? 1) !== 0) {
                    continue;
                }

                $rows[] = $postsById[$docId] ?? (object) ['ID' => $docId];
            }
            usort($rows, static fn(object $a, object $b): int => (int) $a->ID <=> (int) $b->ID);

            return array_slice($rows, 0, $limit);
        }

        if (
            str_starts_with($sql, 'SELECT p.ID, p.post_content, p.post_title')
            && str_contains($sql, 'INNER JOIN wp_fts_docs d')
        ) {
            $offset = 0;
            $publicStatus = str_contains($sql, 'p.post_status = %s') ? (string) ($args[$offset++] ?? '') : '';
            $publicTypes = $this->prepared_in_args($sql, 'p.post_type', '%s', $args, $offset);
            $adminType = null;
            $adminStatuses = [];
            if (str_contains($sql, 'p.post_type = %s')) {
                $adminType = (string) ($args[$offset++] ?? '');
                $adminStatuses = $this->prepared_in_args($sql, 'p.post_status', '%s', $args, $offset);
            }
            $last = max(0, (int) ($args[$offset++] ?? 0));
            $limit = max(0, (int) ($args[$offset] ?? $args[count($args) - 1] ?? 0));

            $rows = [];
            foreach ($this->postRows as $row) {
                $postId = isset($row->ID) ? (int) $row->ID : 0;
                if ($postId <= $last || ($this->docs[$postId]['is_deleted'] ?? 1) !== 0) {
                    continue;
                }

                if (isset($row->post_password) && (string) $row->post_password !== '') {
                    continue;
                }

                $type = isset($row->post_type) ? (string) $row->post_type : 'post';
                $status = isset($row->post_status) ? (string) $row->post_status : 'draft';
                $publicEligible = $publicStatus !== '' && $status === $publicStatus && in_array($type, array_map('strval', $publicTypes), true);
                $adminEligible = $adminType !== null && $type === $adminType && in_array($status, array_map('strval', $adminStatuses), true);
                if ($publicEligible || $adminEligible) {
                    $rows[] = $row;
                }
            }

            usort($rows, static fn(object $a, object $b): int => (int) $a->ID <=> (int) $b->ID);

            return array_slice($rows, 0, $limit);
        }

        if (str_starts_with($sql, 'SELECT p.ID, p.post_content, p.post_title')) {
            $offset = 0;
            $publicStatus = str_contains($sql, 'p.post_status = %s') ? (string) ($args[$offset++] ?? '') : '';
            $publicTypes = $this->prepared_in_args($sql, 'p.post_type', '%s', $args, $offset);
            $adminType = null;
            $adminStatuses = [];
            if (str_contains($sql, 'p.post_type = %s')) {
                $adminType = (string) ($args[$offset++] ?? '');
                $adminStatuses = $this->prepared_in_args($sql, 'p.post_status', '%s', $args, $offset);
            }
            $limit = max(0, (int) ($args[$offset] ?? $args[count($args) - 1] ?? 0));

            $rows = [];
            foreach ($this->postRows as $row) {
                $postId = isset($row->ID) ? (int) $row->ID : 0;
                if ($postId <= 0 || ($this->docs[$postId]['is_deleted'] ?? 1) === 0) {
                    continue;
                }

                if (isset($row->post_password) && (string) $row->post_password !== '') {
                    continue;
                }

                $type = isset($row->post_type) ? (string) $row->post_type : 'post';
                $status = isset($row->post_status) ? (string) $row->post_status : 'draft';
                $publicEligible = $publicStatus !== '' && $status === $publicStatus && in_array($type, array_map('strval', $publicTypes), true);
                $adminEligible = $adminType !== null && $type === $adminType && in_array($status, array_map('strval', $adminStatuses), true);
                if ($publicEligible || $adminEligible) {
                    $rows[] = $row;
                }
            }

            usort($rows, static fn(object $a, object $b): int => (int) $a->ID <=> (int) $b->ID);

            return array_slice($rows, 0, $limit);
        }

        if (str_starts_with($sql, "SELECT ID\nFROM {$this->posts}")) {
            $offset = 0;
            $statuses = $this->prepared_in_args($sql, 'post_status', '%s', $args, $offset);
            $types = $this->prepared_in_args($sql, 'post_type', '%s', $args, $offset);
            $last = max(0, (int) ($args[$offset++] ?? 0));
            $limit = max(0, (int) ($args[$offset] ?? 0));
            $rows = [];
            foreach ($this->postRows as $row) {
                $postId = isset($row->ID) ? (int) $row->ID : 0;
                $status = isset($row->post_status) ? (string) $row->post_status : 'draft';
                $type = isset($row->post_type) ? (string) $row->post_type : 'post';
                if (
                    $postId > $last
                    && in_array($status, array_map('strval', $statuses), true)
                    && in_array($type, array_map('strval', $types), true)
                ) {
                    $rows[] = (object) ['ID' => $postId];
                }
            }
            usort($rows, static fn(object $a, object $b): int => (int) $a->ID <=> (int) $b->ID);

            return array_slice($rows, 0, $limit);
        }

        if (str_starts_with($sql, 'SELECT ID, post_content, post_title')) {
            $last = (int) $args[count($args) - 2];
            $limit = (int) $args[count($args) - 1];
            $rows = array_values(array_filter(
                $this->postRows,
                static fn(object $row): bool => (int) $row->ID > $last
            ));
            usort($rows, static fn(object $a, object $b): int => (int) $a->ID <=> (int) $b->ID);
            return array_slice($rows, 0, $limit);
        }

        if (str_starts_with($sql, 'SELECT dl.lang, COUNT(*) AS doc_count')) {
            $aggregate = [];
            foreach ($this->docLengths as $docId => $lengths) {
                if (($this->docs[$docId]['is_deleted'] ?? 1) !== 0) {
                    continue;
                }
                foreach ($lengths as $lang => $docLen) {
                    if ($docLen <= 0) {
                        continue;
                    }
                    $aggregate[$lang] ??= ['doc_count' => 0, 'len_sum' => 0];
                    $aggregate[$lang]['doc_count']++;
                    $aggregate[$lang]['len_sum'] += $docLen;
                }
            }

            $rows = [];
            foreach ($aggregate as $lang => $row) {
                $rows[] = (object) ['lang' => $lang, 'doc_count' => $row['doc_count'], 'len_sum' => $row['len_sum']];
            }
            return $rows;
        }

        return [];
    }

    /**
     * @param array<int,mixed> $args
     * @return object[]
     */
    private function get_v4_work_results(string $sql, array $args): array
    {
        if (str_starts_with($sql, "SELECT 'post' AS kind, COUNT(*) AS work_count")) {
            $limit = WP_FTS_Index_Queue::STATUS_COUNT_LIMIT;
            $byKind = ['post' => [], 'scope' => []];
            foreach ($this->queue as $jobKey => $row) {
                $kind = (string) ($row['kind'] ?? '');
                if (isset($byKind[$kind])) {
                    $byKind[$kind][(string) $jobKey] = $row;
                }
            }
            foreach ($byKind as &$kindRows) {
                ksort($kindRows, SORT_STRING);
                $kindRows = array_slice($kindRows, 0, $limit, true);
            }
            unset($kindRows);

            $scopeCursor = 0;
            foreach ($byKind['scope'] as $row) {
                $scopeCursor = max($scopeCursor, (int) ($row['cursor_post_id'] ?? 0));
            }

            return [
                (object) [
                    'kind' => 'post',
                    'work_count' => count($byKind['post']),
                    'max_cursor_post_id' => 0,
                ],
                (object) [
                    'kind' => 'scope',
                    'work_count' => count($byKind['scope']),
                    'max_cursor_post_id' => $scopeCursor,
                ],
            ];
        }

        if (
            str_contains($sql, "WHERE state = 'guarded' AND available_at <= %d")
            || str_contains($sql, "WHERE state = 'fenced' AND available_at <= %d")
            || str_contains($sql, "WHERE kind IN ('post','scope') AND state = 'guarded' AND available_at <= %d")
            || str_contains($sql, "WHERE kind IN ('post','scope') AND state = 'fenced' AND available_at <= %d")
        ) {
            $now = max(0, (int) ($args[0] ?? 0));
            $targetState = str_contains($sql, "state = 'guarded'") ? 'guarded' : 'fenced';
            $candidates = array_filter($this->queue, static function (array $row) use ($now, $targetState): bool {
                $state = (string) ($row['state'] ?? '');
                return $state === $targetState && (int) ($row['available_at'] ?? 0) <= $now;
            });
            uasort($candidates, static function (array $left, array $right): int {
                return ((int) ($left['available_at'] ?? 0) <=> (int) ($right['available_at'] ?? 0))
                    ?: strcmp((string) ($left['job_key'] ?? ''), (string) ($right['job_key'] ?? ''));
            });
            $row = reset($candidates);
            return is_array($row) ? [(object) $row] : [];
        }

        if (str_contains($sql, 'claim_token = %s') && str_contains($sql, 'claimed_generation')) {
            $token = (string) ($args[0] ?? '');
            $claimed = [];
            $sources = [];
            $sourceBatchBytes = 0;
            foreach ($this->queue as $jobKey => $row) {
                if (
                    (string) ($row['claim_token'] ?? '') !== $token
                    || (int) ($row['claimed_generation'] ?? 0) !== (int) ($row['generation'] ?? 0)
                ) {
                    continue;
                }
                $claimed[$jobKey] = $row;
                $source = (string) ($row['kind'] ?? '') === 'post'
                    ? $this->v4_post_row((int) ($row['post_id'] ?? 0))
                    : null;
                $sourceExists = is_object($source) && isset($GLOBALS['wp_fts_test_posts'][(int) ($row['post_id'] ?? 0)]);
                if (!$sourceExists && is_object($source) && (int) ($source->ID ?? 0) > 0) {
                    foreach ($this->postRows as $candidate) {
                        if (is_object($candidate) && (int) ($candidate->ID ?? 0) === (int) $source->ID) {
                            $sourceExists = true;
                            break;
                        }
                    }
                }
                if (!$sourceExists) {
                    $source = null;
                }
                $sources[$jobKey] = $source;
                if (is_object($source)) {
                    $sourceBatchBytes += strlen((string) ($source->post_title ?? ''))
                        + strlen((string) ($source->post_content ?? ''))
                        + strlen((string) ($source->post_excerpt ?? ''));
                }
            }
            $snapshotLimit = 0;
            $limitStart = strpos($sql, '), 0) <= ');
            if ($limitStart !== false) {
                $limitStart += strlen('), 0) <= ');
                $limitEnd = strpos($sql, ') AS snapshot_complete', $limitStart);
                if ($limitEnd !== false) {
                    $snapshotLimit = max(0, (int) trim(substr($sql, $limitStart, $limitEnd - $limitStart)));
                }
            }
            $snapshotComplete = $sourceBatchBytes <= $snapshotLimit;
            $claimedPostIds = [];
            foreach ($claimed as $row) {
                if ((string) ($row['kind'] ?? '') === 'post' && (int) ($row['post_id'] ?? 0) > 0) {
                    $claimedPostIds[(int) $row['post_id']] = true;
                }
            }
            $claimedPostIds = array_keys($claimedPostIds);
            sort($claimedPostIds, SORT_NUMERIC);
            $remainingOldPostings = WP_FTS_Storage_Mysql::MAX_BATCH_POSTINGS + 1;
            $oldPostingCounts = [];
            foreach ($claimedPostIds as $postId) {
                if (array_key_exists($postId, $this->replacementFrontierPostingCounts)) {
                    $postingCount = max(0, (int) $this->replacementFrontierPostingCounts[$postId]);
                } else {
                    $postingCount = 0;
                    foreach ($this->postings as $postings) {
                        $postingCount += isset($postings[$postId]) ? 1 : 0;
                    }
                }
                $oldPostingCounts[$postId] = min($postingCount, $remainingOldPostings);
                $remainingOldPostings -= $oldPostingCounts[$postId];
                if ($remainingOldPostings === 0) {
                    break;
                }
            }
            $rows = [];
            foreach ($claimed as $jobKey => $row) {
                $source = $sources[$jobKey] ?? null;
                $sourceExists = is_object($source);
                $sourceBytes = $sourceExists
                    ? strlen((string) ($source->post_title ?? ''))
                        + strlen((string) ($source->post_content ?? ''))
                        + strlen((string) ($source->post_excerpt ?? ''))
                    : 0;
                $rows[] = (object) ($row + [
                    'source_exists' => $sourceExists ? 1 : 0,
                    'source_bytes' => $sourceBytes,
                    'canonical_bytes' => $sourceExists ? $this->v4_canonical_post_bytes($source) : 0,
                    'source_snapshot_complete' => $snapshotComplete ? 1 : 0,
                    'source_id' => $sourceExists ? (int) ($source->ID ?? 0) : null,
                    'source_post_title' => $sourceExists && $snapshotComplete ? (string) ($source->post_title ?? '') : '',
                    'source_post_content' => $sourceExists && $snapshotComplete ? (string) ($source->post_content ?? '') : '',
                    'source_post_excerpt' => $sourceExists && $snapshotComplete ? (string) ($source->post_excerpt ?? '') : '',
                    'source_post_type' => $sourceExists ? (string) ($source->post_type ?? '') : null,
                    'source_post_status' => $sourceExists ? (string) ($source->post_status ?? '') : null,
                    'source_post_date_gmt' => $sourceExists ? (string) ($source->post_date_gmt ?? '') : null,
                    'source_post_password' => $sourceExists ? (string) ($source->post_password ?? '') : null,
                    'source_existing_hash' => $sourceExists
                        ? ($this->docs[(int) ($source->ID ?? 0)]['content_hash'] ?? null)
                        : null,
                    'old_posting_count' => max(0, (int) ($oldPostingCounts[(int) ($row['post_id'] ?? 0)] ?? 0)),
                ]);
            }
            usort($rows, static function (object $left, object $right): int {
                return strcmp((string) ($right->kind ?? ''), (string) ($left->kind ?? ''))
                    ?: ((int) ($left->post_id ?? 0) <=> (int) ($right->post_id ?? 0))
                    ?: strcmp((string) ($left->job_key ?? ''), (string) ($right->job_key ?? ''));
            });
            return $rows;
        }

        if (str_contains($sql, "WHERE kind = 'scope'") && str_contains($sql, 'bounded_scope_candidates')) {
            $now = $args === [] ? 0 : max(array_map('intval', $args));
            $keys = $this->claimable_v4_queue_keys(
                'scope',
                1,
                $now,
                !str_contains($sql, 'wp_fts:fences-require-free-guard')
            );
            return $keys === [] ? [] : [(object) $this->queue[$keys[0]]];
        }

        if (str_contains($sql, "WHERE kind = 'scope'") && str_contains($sql, "state IN ('guarded','fenced','ready','retry','leased')")) {
            $now = max(0, (int) ($args[0] ?? 0));
            $keys = $this->claimable_v4_queue_keys('scope', 1, $now);
            return $keys === [] ? [] : [(object) $this->queue[$keys[0]]];
        }

        return [];
    }

    /**
     * @param array<int,mixed> $args
     * @return object[]|null
     */
    private function get_v4_storage_results(string $sql, array $args): ?array
    {
        $this->ensure_term_identity_maps();

        if (
            str_starts_with($sql, 'SELECT p.ID,')
            && str_contains($sql, 'requested.source_budget')
            && str_contains($sql, 'requested ON requested.post_id = p.ID')
        ) {
            $rows = [];
            for ($offset = 0; $offset + 2 < count($args); $offset += 3) {
                $postId = (int) $args[$offset];
                $sourceBudget = max(0, (int) $args[$offset + 1]);
                $canonicalBudget = max(0, (int) $args[$offset + 2]);
                $post = $GLOBALS['wp_fts_test_posts'][$postId] ?? null;
                if (!is_object($post)) {
                    foreach ($this->postRows as $candidate) {
                        if (is_object($candidate) && (int) ($candidate->ID ?? 0) === $postId) {
                            $post = $candidate;
                            break;
                        }
                    }
                }
                if (!is_object($post)) {
                    continue;
                }
                $sourceBytes = strlen((string) ($post->post_title ?? ''))
                    + strlen((string) ($post->post_content ?? ''))
                    + strlen((string) ($post->post_excerpt ?? ''));
                $row = clone $post;
                if ($sourceBytes > $sourceBudget) {
                    $row->post_title = '';
                    $row->post_content = '';
                    $row->post_excerpt = '';
                }
                $row->fts_source_changed = $sourceBytes > $sourceBudget ? 1 : 0;
                $canonicalBytes = $this->v4_canonical_post_bytes($post);
                $row->fts_canonical_changed = $canonicalBytes > $canonicalBudget ? 1 : 0;
                $row->fts_post_source_bytes = $sourceBytes;
                $row->fts_canonical_post_bytes = $canonicalBytes;
                $row->fts_existing_hash = $this->docs[$postId]['content_hash'] ?? null;
                $rows[] = $row;
            }
            usort($rows, static fn(object $left, object $right): int => (int) $left->ID <=> (int) $right->ID);
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT p.*, d.content_hash AS fts_existing_hash')) {
            $rows = [];
            foreach (array_map('intval', $args) as $postId) {
                $post = $GLOBALS['wp_fts_test_posts'][$postId] ?? null;
                if (!is_object($post)) {
                    foreach ($this->postRows as $candidate) {
                        if (is_object($candidate) && (int) ($candidate->ID ?? 0) === $postId) {
                            $post = $candidate;
                            break;
                        }
                    }
                }
                if (!is_object($post)) {
                    continue;
                }
                $row = clone $post;
                $row->fts_existing_hash = $this->docs[$postId]['content_hash'] ?? null;
                $rows[] = $row;
            }
            usort($rows, static fn(object $left, object $right): int => (int) $left->ID <=> (int) $right->ID);
            return $rows;
        }

        if (str_starts_with($sql, '/* wp_fts:plan */')) {
            $requestedEnd = strpos($sql, ") requested_terms\nLEFT JOIN");
            $requestedSql = $requestedEnd === false ? $sql : substr($sql, 0, $requestedEnd);
            $identityCount = substr_count($requestedSql, 'SELECT UNHEX(%s) AS lang');
            $capabilityReady = $this->v4_search_snapshot_ready($sql, $args, false);
            $reconciliationScopeActive = false;
            foreach ($this->queue as $work) {
                if ((string) ($work['kind'] ?? '') === 'scope') {
                    $reconciliationScopeActive = true;
                    break;
                }
            }
            $rows = [];
            for ($identityOffset = 0; $identityOffset < $identityCount; $identityOffset++) {
                $argOffset = $identityOffset * 2;
                $lang = hex2bin((string) ($args[$argOffset] ?? ''));
                $term = hex2bin((string) ($args[$argOffset + 1] ?? ''));
                $lang = is_string($lang) ? $lang : '';
                $term = is_string($term) ? $term : '';
                $key = WP_FTS_TermNamespace::namespace_term($lang, $term);
                $row = array_key_exists($key, $this->ftsTerms)
                    ? $this->v4_term_row($key, 'exact')
                    : (object) [
                        'row_kind' => 'exact',
                        'term_id' => null,
                        'lang' => $lang,
                        'kind' => 0,
                        'term' => $term,
                        'doc_freq' => null,
                    ];
                $row->surface_available = 0;
                $row->surface_doc_freq = 0;
                $row->search_epoch = $this->searchEpoch;
                $row->search_epoch_incarnation = $this->searchEpochIncarnation;
                $row->capability_ready = $capabilityReady ? 1 : 0;
                $row->reconciliation_scope_active = $reconciliationScopeActive ? 1 : 0;
                $rows[] = $row;
            }
            if (str_contains($sql, "'surface_available' AS row_kind")) {
                $rangeOffset = $this->v4_surface_range_argument_offset($sql);
                $prefixKeys = $rangeOffset === null
                    ? []
                    : $this->v4_surface_keys_from_hex_args(array_slice($args, $rangeOffset, 3));
                $surfaceDocFreq = 0;
                foreach ($prefixKeys as $prefixKey) {
                    $surfaceDocFreq += max(0, (int) ($this->ftsTerms[$prefixKey]['doc_freq'] ?? 0));
                }
                $rows[] = (object) [
                    'row_kind' => 'surface_available',
                    'term_id' => 0,
                    'lang' => '',
                    'kind' => 0,
                    'term' => '',
                    'doc_freq' => 0,
                    'surface_available' => $prefixKeys === [] ? 0 : 1,
                    'surface_doc_freq' => $surfaceDocFreq,
                    'search_epoch' => $this->searchEpoch,
                    'search_epoch_incarnation' => $this->searchEpochIncarnation,
                    'capability_ready' => $capabilityReady ? 1 : 0,
                    'reconciliation_scope_active' => $reconciliationScopeActive ? 1 : 0,
                ];
            }
            if ($rows === [] && str_contains($sql, "'control' AS row_kind")) {
                $rows[] = (object) [
                    'row_kind' => 'control',
                    'term_id' => 0,
                    'lang' => '',
                    'kind' => 0,
                    'term' => '',
                    'doc_freq' => 0,
                    'surface_available' => 0,
                    'surface_doc_freq' => 0,
                    'search_epoch' => $this->searchEpoch,
                    'search_epoch_incarnation' => $this->searchEpochIncarnation,
                    'capability_ready' => $capabilityReady ? 1 : 0,
                    'reconciliation_scope_active' => $reconciliationScopeActive ? 1 : 0,
                ];
            }
            return $rows;
        }

        if (str_starts_with($sql, '/* wp_fts:replacement-frontier */')) {
            $postIds = array_values(array_unique(array_filter(
                array_map('intval', $args),
                static fn(int $postId): bool => $postId > 0
            )));
            sort($postIds, SORT_NUMERIC);
            $remaining = WP_FTS_Storage_Mysql::MAX_BATCH_POSTINGS + 1;
            $rows = [];
            foreach ($postIds as $postId) {
                if (array_key_exists($postId, $this->replacementFrontierPostingCounts)) {
                    $postingCount = max(0, (int) $this->replacementFrontierPostingCounts[$postId]);
                } else {
                    $postingCount = 0;
                    foreach ($this->postings as $postings) {
                        $postingCount += isset($postings[$postId]) ? 1 : 0;
                    }
                }
                $postingCount = min($postingCount, $remaining);
                if ($postingCount > 0) {
                    $rows[] = (object) [
                        'post_id' => $postId,
                        'posting_count' => $postingCount,
                    ];
                    $remaining -= $postingCount;
                }
                if ($remaining === 0) {
                    break;
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term_id, post_id, impact FROM wp_fts_postings')) {
            $wanted = array_fill_keys(array_map('intval', $args), true);
            $rows = [];
            foreach ($this->postings as $key => $postings) {
                $termId = $this->ensure_term_id($key);
                if (!isset($wanted[$termId])) {
                    continue;
                }
                foreach ($postings as $postId => $impact) {
                    $rows[] = (object) ['term_id' => $termId, 'post_id' => (int) $postId, 'impact' => (int) $impact];
                }
            }
            usort($rows, static fn(object $a, object $b): int => (int) $a->term_id <=> (int) $b->term_id ?: (int) $a->post_id <=> (int) $b->post_id);
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT post_id, content_hash FROM wp_fts_documents')) {
            $rows = [];
            foreach (array_map('intval', $args) as $postId) {
                if (isset($this->docs[$postId])) {
                    $rows[] = (object) ['post_id' => $postId, 'content_hash' => $this->docs[$postId]['content_hash'] ?? null];
                }
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT d.post_id, d.primary_lang,')) {
            $paged = str_contains($sql, 'ORDER BY d.post_id');
            $limit = $paged ? max(1, (int) ($args[count($args) - 1] ?? 1)) : count($args);
            $cursor = $paged && count($args) > 1 ? max(0, (int) $args[0]) : 0;
            $descending = str_contains($sql, 'ORDER BY d.post_id DESC');
            $postIds = $paged
                ? array_map('intval', array_keys($this->docs))
                : array_values(array_unique(array_filter(array_map('intval', $args), static fn(int $id): bool => $id > 0)));
            if ($paged) {
                $postIds = array_values(array_filter(
                    $postIds,
                    static fn(int $postId): bool => $cursor === 0
                        || ($descending ? $postId < $cursor : $postId > $cursor)
                ));
            }
            $descending ? rsort($postIds, SORT_NUMERIC) : sort($postIds, SORT_NUMERIC);
            $rows = [];
            foreach (array_slice($postIds, 0, $limit) as $postId) {
                if (!isset($this->docs[$postId])) {
                    continue;
                }
                $post = $this->v4_post_row($postId);
                $rows[] = (object) [
                    'post_id' => $postId,
                    'primary_lang' => (string) ($this->docs[$postId]['primary_lang'] ?? 'und'),
                    'snippet_text' => (string) ($this->docs[$postId]['snippet_text'] ?? ''),
                    'post_title' => (string) ($post->post_title ?? ''),
                    'post_excerpt' => (string) ($post->post_excerpt ?? ''),
                    'post_type' => (string) ($post->post_type ?? ''),
                    'post_status' => (string) ($post->post_status ?? ''),
                    'post_date_gmt' => (string) ($post->post_date_gmt ?? ''),
                ];
            }
            return $rows;
        }

        if ($sql === 'SELECT lang, term FROM wp_fts_terms ORDER BY lang, term') {
            $rows = [];
            $keys = array_keys($this->ftsTerms);
            sort($keys, SORT_STRING);
            foreach ($keys as $key) {
                $split = WP_FTS_TermNamespace::split_term($key);
                $rows[] = (object) ['lang' => (string) ($split['lang'] ?? 'und'), 'term' => (string) ($split['term'] ?? $key)];
            }
            return $rows;
        }

        if (str_starts_with($sql, 'SELECT term FROM wp_fts_terms WHERE lang = UNHEX(%s)')) {
            $limit = max(0, (int) array_pop($args));
            $keys = $this->v4_prefix_keys_from_hex_args($args);
            return array_map(
                static function (string $key): object {
                    $split = WP_FTS_TermNamespace::split_term($key);
                    return (object) ['term' => (string) ($split['term'] ?? $key)];
                },
                array_slice($keys, 0, $limit)
            );
        }

        if (str_starts_with($sql, 'SELECT t.lang, t.term FROM wp_fts_postings')) {
            $postId = max(0, (int) ($args[0] ?? 0));
            $keys = [];
            foreach ($this->postings as $key => $postings) {
                [$kind] = $this->v4_decode_storage_term_key((string) $key);
                if ($kind === 0 && isset($postings[$postId])) {
                    $keys[] = $key;
                }
            }
            sort($keys, SORT_STRING);
            return array_map(static function (string $key): object {
                $split = WP_FTS_TermNamespace::split_term($key);
                return (object) ['lang' => (string) ($split['lang'] ?? 'und'), 'term' => (string) ($split['term'] ?? $key)];
            }, $keys);
        }

        if (
            str_starts_with($sql, 'SELECT ranked.post_id, ranked.lang, ranked.term')
            || str_starts_with($sql, 'SELECT bounded.post_id, bounded.lang, bounded.term')
        ) {
            if (str_starts_with($sql, 'SELECT bounded.')) {
                $postIds = [];
                $limits = [];
                for ($offset = 0; $offset + 1 < count($args); $offset += 2) {
                    $postIds[] = (int) $args[$offset];
                    $limits[] = (int) $args[$offset + 1];
                }
                $limit = max(1, $limits[0] ?? 1);
            } else {
                $limit = max(1, (int) array_pop($args));
                $postIds = array_map('intval', $args);
            }
            $rows = [];
            foreach ($postIds as $postId) {
                $keys = [];
                foreach ($this->postings as $key => $postings) {
                    [$kind] = $this->v4_decode_storage_term_key((string) $key);
                    if ($kind === 0 && isset($postings[$postId])) {
                        $keys[] = $key;
                    }
                }
                sort($keys, SORT_STRING);
                foreach (array_slice($keys, 0, $limit) as $key) {
                    $split = WP_FTS_TermNamespace::split_term($key);
                    $rows[] = (object) [
                        'post_id' => $postId,
                        'lang' => (string) ($split['lang'] ?? 'und'),
                        'term' => (string) ($split['term'] ?? $key),
                    ];
                }
            }
            return $rows;
        }

        return null;
    }

    /** @param array<int,mixed> $args @return string[] */
    private function v4_prefix_keys_from_hex_args(array $args): array
    {
        $decoded = [];
        foreach ($args as $value) {
            $binary = hex2bin((string) $value);
            $decoded[] = is_string($binary) ? $binary : '';
        }
        $lang = (string) ($decoded[0] ?? '');
        $lower = (string) ($decoded[1] ?? '');
        $upper = $decoded[2] ?? null;
        $keys = [];
        foreach (array_keys($this->ftsTerms) as $key) {
            [$kind, $canonicalKey] = $this->v4_decode_storage_term_key($key);
            if ($kind !== 0) {
                continue;
            }
            $split = WP_FTS_TermNamespace::split_term($canonicalKey);
            $keyLang = (string) ($split['lang'] ?? 'und');
            $term = (string) ($split['term'] ?? $canonicalKey);
            if ($keyLang !== $lang || strcmp($term, $lower) < 0 || ($upper !== null && strcmp($term, $upper) >= 0)) {
                continue;
            }
            $keys[] = $key;
        }
        usort($keys, static function (string $a, string $b): int {
            $left = WP_FTS_TermNamespace::split_term($a);
            $right = WP_FTS_TermNamespace::split_term($b);
            return strcmp((string) ($left['term'] ?? $a), (string) ($right['term'] ?? $b));
        });
        return $keys;
    }

    /** Locate the binary `(lang, lower, upper)` range arguments in generated SQL. */
    private function v4_surface_range_argument_offset(string $sql): ?int
    {
        $rangeAt = strpos($sql, 'WHERE pt.lang = UNHEX(%s) AND pt.kind = 1 AND pt.term >= UNHEX(%s)');
        if ($rangeAt === false) {
            return null;
        }

        $beforeRange = substr($sql, 0, $rangeAt);
        return substr_count($beforeRange, '%s') + substr_count($beforeRange, '%d');
    }

    /** @param array<int,mixed> $args @return string[] */
    private function v4_surface_keys_from_hex_args(array $args): array
    {
        $decoded = [];
        foreach ($args as $value) {
            $binary = hex2bin((string) $value);
            $decoded[] = is_string($binary) ? $binary : '';
        }
        $lang = (string) ($decoded[0] ?? '');
        $lower = (string) ($decoded[1] ?? '');
        $upper = array_key_exists(2, $decoded) ? (string) $decoded[2] : null;
        $keys = [];
        foreach (array_keys($this->ftsTerms) as $key) {
            [$kind, $canonicalKey] = $this->v4_decode_storage_term_key($key);
            if ($kind !== 1) {
                continue;
            }
            $split = WP_FTS_TermNamespace::split_term($canonicalKey);
            $keyLang = (string) ($split['lang'] ?? 'und');
            $term = (string) ($split['term'] ?? $canonicalKey);
            if ($keyLang !== $lang || strcmp($term, $lower) < 0 || ($upper !== null && strcmp($term, $upper) >= 0)) {
                continue;
            }
            $keys[] = $key;
        }
        usort($keys, function (string $left, string $right): int {
            [, $leftKey] = $this->v4_decode_storage_term_key($left);
            [, $rightKey] = $this->v4_decode_storage_term_key($right);
            $leftTerm = WP_FTS_TermNamespace::split_term($leftKey)['term'] ?? $leftKey;
            $rightTerm = WP_FTS_TermNamespace::split_term($rightKey)['term'] ?? $rightKey;
            return strcmp((string) $leftTerm, (string) $rightTerm);
        });

        return $keys;
    }

    /** Evaluate the exact option/epoch/scope sentinel bound into search SQL. */
    private function v4_search_snapshot_ready(string $sql, array $args, bool $requireEpoch): bool
    {
        $schemaOffset = array_search(WP_FTS_Plugin::SCHEMA_VERSION_OPTION, $args, true);
        $desiredOffset = array_search(WP_FTS_Plugin::READINESS_INCARNATION_OPTION, $args, true);
        $publishedOffset = array_search(WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION, $args, true);
        if (
            $schemaOffset === false
            || $desiredOffset === false
            || $publishedOffset === false
            || (string) ($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? '')
                !== (string) ($args[$schemaOffset + 1] ?? '')
            || (string) ($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION] ?? '')
                !== (string) ($args[$desiredOffset + 1] ?? '')
            || serialize($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION] ?? '')
                !== (string) ($args[$publishedOffset + 1] ?? '')
        ) {
            return false;
        }

        foreach ($this->queue as $work) {
            if ((string) ($work['kind'] ?? '') === 'scope') {
                return false;
            }
        }
        if (!$requireEpoch || !str_contains($sql, 'epoch_control')) {
            return true;
        }

        foreach ($args as $offset => $value) {
            if ((string) $value !== WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY) {
                continue;
            }
            if (
                (int) ($args[$offset + 1] ?? 0) === $this->searchEpoch
                && hash_equals($this->searchEpochIncarnation, (string) ($args[$offset + 2] ?? ''))
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Evaluate the generated relational ranking statement against the fake
     * tables. The SQL itself remains under test; this adapter only supplies the
     * rows that MySQL would return to the WordPress integration fixtures.
     *
     * @param array<int,mixed> $args
     * @return object[]
     */
    private function get_v4_rank_results(string $sql, array $args): array
    {
        $snapshotReady = $this->v4_search_snapshot_ready($sql, $args, true);
        if (!$snapshotReady) {
            return [(object) [
                'doc_id' => null,
                'score' => null,
                'post_date_gmt' => null,
                'snapshot_ready' => 0,
            ]];
        }
        $termGroups = [];
        foreach (explode("\n", $sql) as $line) {
            $selectOffset = strpos($line, 'SELECT ');
            if ($selectOffset === false) {
                continue;
            }
            $termRow = sscanf(substr($line, $selectOffset), 'SELECT %d AS term_id, %d AS group_id, %d AS weight');
            if (!is_array($termRow) || count($termRow) !== 3) {
                continue;
            }
            [$termId, $groupId, $weight] = array_map('intval', $termRow);
            if ($termId <= 0 || $weight <= 0) {
                continue;
            }
            $termGroups[$groupId][$termId] = max($termGroups[$groupId][$termId] ?? 0, $weight);
        }

        $prefixKeys = [];
        $prefixArgOffset = $this->v4_surface_range_argument_offset($sql);
        if ($prefixArgOffset !== null) {
            $prefixKeys = $this->v4_surface_keys_from_hex_args(
                array_slice($args, $prefixArgOffset, 3)
            );
        }
        $prefixGroup = $termGroups === [] ? 0 : max(array_map('intval', array_keys($termGroups)));
        foreach (explode("\n", $sql) as $line) {
            $parsed = sscanf(trim($line), 'SELECT ppo.post_id, %d AS group_id,');
            if (is_array($parsed) && isset($parsed[0])) {
                $prefixGroup = max(0, (int) $parsed[0]);
                break;
            }
        }

        $scores = [];
        foreach ($termGroups as $groupId => $terms) {
            foreach ($terms as $termId => $weight) {
                $key = $this->termKeysById[$termId] ?? null;
                if ($key === null) {
                    continue;
                }
                foreach ($this->postings[$key] ?? [] as $postId => $impact) {
                    $scores[(int) $postId][(int) $groupId] = max(
                        $scores[(int) $postId][(int) $groupId] ?? 0,
                        (int) $impact * (int) $weight
                    );
                }
            }
        }
        foreach ($prefixKeys as $key) {
            $docFreq = max(1, (int) ($this->ftsTerms[$key]['doc_freq'] ?? count($this->postings[$key] ?? [])));
            $weight = max(1, intdiv(1000000, $docFreq) * 600);
            foreach ($this->postings[$key] ?? [] as $postId => $impact) {
                $scores[(int) $postId][$prefixGroup] = max(
                    $scores[(int) $postId][$prefixGroup] ?? 0,
                    (int) $impact * $weight
                );
            }
        }

        $requiredGroups = null;
        $marker = 'HAVING COUNT(*) = ';
        $position = strpos($sql, $marker);
        if ($position !== false) {
            $requiredGroups = max(1, (int) substr($sql, $position + strlen($marker)));
        }
        $visibilityAlias = str_contains($sql, 'wp_f.post_status IN (')
            ? 'wp_f'
            : (str_contains($sql, 'wp_exact_anchor.post_status IN (')
                ? 'wp_exact_anchor'
                : (str_contains($sql, 'wp_prefix_anchor_identity.post_status IN (')
                    ? 'wp_prefix_anchor_identity'
                    : 'wp_f'));
        $visibilityAt = strpos($sql, $visibilityAlias . '.post_status IN (');
        $beforeVisibility = $visibilityAt === false ? '' : substr($sql, 0, $visibilityAt);
        $offset = substr_count($beforeVisibility, '%s') + substr_count($beforeVisibility, '%d');
        $statuses = $this->prepared_in_args($sql, $visibilityAlias . '.post_status', '%s', $args, $offset);
        if ($statuses === []) {
            $statuses = ['publish'];
        }
        $types = $this->prepared_in_args($sql, $visibilityAlias . '.post_type', '%s', $args, $offset);
        $dateAfter = str_contains($sql, $visibilityAlias . '.post_date_gmt >= %s') ? (string) ($args[$offset++] ?? '') : null;
        $dateBefore = str_contains($sql, $visibilityAlias . '.post_date_gmt <= %s') ? (string) ($args[$offset++] ?? '') : null;
        $cursor = null;
        if (str_contains($sql, 'AND (scored.score')) {
            $cursor = [
                'score' => (int) ($args[$offset] ?? 0),
                'date' => (string) ($args[$offset + 2] ?? ''),
                'post_id' => (int) ($args[$offset + 5] ?? 0),
            ];
            $offset += 6;
        }
        $limit = max(0, (int) ($args[count($args) - 1] ?? 0));
        $ascending = str_contains($sql, 'ORDER BY scored.score ASC');
        $scopeDirty = false;
        $dirtyPosts = [];
        foreach ($this->queue as $row) {
            if (
                (string) ($row['kind'] ?? '') === 'scope'
                && in_array(
                    (string) ($row['scope_coverage'] ?? ''),
                    [WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS, WP_FTS_Index_Queue::SCOPE_COVERAGE_GLOBAL],
                    true
                )
            ) {
                $scopeDirty = true;
            } elseif (
                (string) ($row['kind'] ?? '') === 'scope'
                && (string) ($row['scope_coverage'] ?? '') === WP_FTS_Index_Queue::SCOPE_COVERAGE_TARGETED
                && (string) ($row['scope_subject_type'] ?? '') === 'term_taxonomy'
            ) {
                $subjectId = max(0, (int) ($row['scope_subject_id'] ?? 0));
                $objectIds = $GLOBALS['wp_fts_test_term_taxonomy_object_ids'][$subjectId] ?? null;
                if (!is_array($objectIds) && count($GLOBALS['wp_fts_test_term_object_ids'] ?? []) === 1) {
                    $objectIds = reset($GLOBALS['wp_fts_test_term_object_ids']);
                }
                foreach (is_array($objectIds) ? $objectIds : [] as $postId) {
                    $dirtyPosts[(int) $postId] = true;
                }
            } elseif ((string) ($row['kind'] ?? '') === 'post') {
                $dirtyPosts[(int) ($row['post_id'] ?? 0)] = true;
            }
        }

        $rows = [];
        if (!$scopeDirty) {
            foreach ($scores as $postId => $byGroup) {
                if ($requiredGroups !== null && count($byGroup) !== $requiredGroups) {
                    continue;
                }
                if (!isset($this->docs[$postId]) || isset($dirtyPosts[$postId])) {
                    continue;
                }
                $post = $this->v4_post_row($postId);
                $status = (string) ($post->post_status ?? 'draft');
                $type = (string) ($post->post_type ?? 'post');
                $date = (string) ($post->post_date_gmt ?? '1970-01-01 00:00:00');
                if (
                    (string) ($post->post_password ?? '') !== ''
                    || !in_array($status, array_map('strval', $statuses), true)
                    || ($types !== [] && !in_array($type, array_map('strval', $types), true))
                    || ($dateAfter !== null && strcmp($date, $dateAfter) < 0)
                    || ($dateBefore !== null && strcmp($date, $dateBefore) > 0)
                ) {
                    continue;
                }
                $score = array_sum($byGroup);
                if ($score <= 0) {
                    continue;
                }
                $score = $this->v4_recency_score($score, $date, $sql);
                if ($cursor !== null) {
                    $comparison = $score <=> $cursor['score']
                        ?: strcmp($date, $cursor['date'])
                        ?: ($postId <=> $cursor['post_id']);
                    if ((!$ascending && $comparison >= 0) || ($ascending && $comparison <= 0)) {
                        continue;
                    }
                }
                $rankedRow = [
                    'doc_id' => $postId,
                    'score' => $score,
                    'snapshot_ready' => 1,
                    'post_type' => $type,
                    'post_status' => $status,
                    'post_date_gmt' => $date,
                    'post_title' => (string) ($post->post_title ?? ''),
                    'post_excerpt' => (string) ($post->post_excerpt ?? ''),
                    'primary_lang' => (string) ($this->docs[$postId]['primary_lang'] ?? 'und'),
                    'snippet_text' => (string) ($this->docs[$postId]['snippet_text'] ?? ''),
                ];
                if (str_contains($sql, 'AS canonical_post_bytes')) {
                    $rankedRow['canonical_post_bytes'] = $this->v4_canonical_post_bytes($post);
                }
                $rows[] = (object) $rankedRow;
            }
        }
        usort($rows, static function (object $left, object $right) use ($ascending): int {
            $comparison = ((int) $left->score <=> (int) $right->score)
                ?: strcmp((string) $left->post_date_gmt, (string) $right->post_date_gmt)
                ?: ((int) $left->doc_id <=> (int) $right->doc_id);
            return $ascending ? $comparison : -$comparison;
        });
        $rows = $limit > 0 ? array_slice($rows, 0, $limit) : [];
        return $rows !== [] ? $rows : [(object) [
            'doc_id' => null,
            'score' => null,
            'post_date_gmt' => null,
            'snapshot_ready' => 1,
        ]];
    }

    /** Measures the canonical WordPress columns loaded for one fixture post. */
    private function v4_canonical_post_bytes(object $post): int
    {
        $bytes = 0;
        foreach (WP_FTS_Index_Queue::CANONICAL_POST_COLUMNS as $column) {
            $value = $post->{$column} ?? null;
            if ($value !== null) {
                $bytes += strlen((string) $value);
            }
        }
        return $bytes;
    }

    /** Evaluates the production recency expression in the relational-v4 fake. */
    private function v4_recency_score(int $score, string $date, string $sql): int
    {
        $marker = 'ranked.score * (1000000 + ';
        $start = strpos($sql, $marker);
        if ($start === false) {
            return $score;
        }
        $tail = substr($sql, $start + strlen($marker));
        $strength = max(0, (int) $tail);
        $separator = ' * ';
        $halfLifeStart = strpos($tail, $separator);
        if ($halfLifeStart === false) {
            return $score;
        }
        $halfLife = max(1, (int) substr($tail, $halfLifeStart + strlen($separator)));
        $dateMarker = "strftime('%s', '";
        $nowStart = strpos($sql, $dateMarker);
        $now = time();
        if ($nowStart !== false) {
            $nowStart += strlen($dateMarker);
            $nowEnd = strpos($sql, "')", $nowStart);
            $parsed = $nowEnd === false ? false : strtotime(substr($sql, $nowStart, $nowEnd - $nowStart) . ' UTC');
            if ($parsed !== false) {
                $now = $parsed;
            }
        } else {
            $mysqlMarker = "post_date_gmt, '";
            $nowStart = strpos($sql, $mysqlMarker);
            if ($nowStart !== false) {
                $nowStart += strlen($mysqlMarker);
                $nowEnd = strpos($sql, "'", $nowStart);
                $parsed = $nowEnd === false ? false : strtotime(substr($sql, $nowStart, $nowEnd - $nowStart) . ' UTC');
                if ($parsed !== false) {
                    $now = $parsed;
                }
            }
        }
        $postTime = strtotime($date . ' UTC');
        $age = $postTime === false ? 0 : max(0, $now - $postTime);
        return (int) round($score * (1000000 + $strength * $halfLife / ($halfLife + $age)) / 1000000);
    }

    /** Emulates single-row wpdb reads against the in-memory relational model. */
    public function get_row(mixed $statement): ?object
    {
        [$sql, $args] = $this->statement_parts($statement);
        $this->record_read_query($sql);
        $this->last_error = '';
        if (str_starts_with($sql, 'SELECT post_id, primary_lang, content_hash FROM wp_fts_documents')) {
            $postId = (int) ($args[0] ?? 0);
            return isset($this->docs[$postId]) ? (object) $this->docs[$postId] : null;
        }

        if (str_starts_with($sql, 'SELECT COUNT(*) AS doc_count FROM wp_fts_documents')) {
            $lang = str_contains($sql, 'WHERE primary_lang = %s') ? (string) ($args[0] ?? '') : null;
            $count = 0;
            foreach ($this->docs as $doc) {
                if ($lang !== null && (string) ($doc['primary_lang'] ?? $doc['lang'] ?? '') !== $lang) {
                    continue;
                }
                $count++;
            }
            return (object) ['doc_count' => $count];
        }

        if (str_starts_with($sql, 'SELECT doc_id, lang, doc_len, content_hash, is_deleted FROM wp_fts_docs')) {
            $docId = (int) $args[0];
            if (!isset($this->docs[$docId])) {
                return null;
            }

            return (object) array_merge(['doc_id' => $docId], $this->docs[$docId]);
        }

        return null;
    }

    /**
     * @return array<int,int|string>
     */
    public function get_col(mixed $statement): array
    {
        [$sql, $args] = $this->statement_parts($statement);
        $this->record_read_query($sql);
        $this->last_error = '';
        if (str_starts_with($sql, 'SELECT object_id') && str_contains($sql, 'FROM wp_term_relationships')) {
            $termTaxonomyId = max(0, (int) ($args[0] ?? 0));
            $cursor = max(0, (int) ($args[1] ?? 0));
            $limit = max(1, (int) ($args[2] ?? 1));
            $ids = [];
            $objectIds = $GLOBALS['wp_fts_test_term_taxonomy_object_ids'][$termTaxonomyId] ?? null;
            if (!is_array($objectIds) && count($GLOBALS['wp_fts_test_term_object_ids'] ?? []) === 1) {
                $objectIds = reset($GLOBALS['wp_fts_test_term_object_ids']);
            }
            foreach (is_array($objectIds) ? $objectIds : [] as $postId) {
                $postId = (int) $postId;
                if ($postId > $cursor) {
                    $ids[$postId] = true;
                }
            }
            $ids = array_map('intval', array_keys($ids));
            sort($ids, SORT_NUMERIC);

            return array_slice($ids, 0, $limit);
        }

        if (
            str_starts_with($sql, "SELECT p.ID\nFROM wp_posts p\nWHERE p.ID > %d")
            && str_contains($sql, 'p.post_status IN (')
            && str_contains($sql, 'p.post_type IN (')
        ) {
            $cursor = max(0, (int) ($args[0] ?? 0));
            $offset = 1;
            $statuses = array_map('strval', $this->prepared_in_args($sql, 'p.post_status', '%s', $args, $offset));
            $types = array_map('strval', $this->prepared_in_args($sql, 'p.post_type', '%s', $args, $offset));
            $limit = max(1, (int) ($args[$offset] ?? $args[count($args) - 1] ?? 1));
            $posts = [];
            foreach ($this->postRows as $row) {
                if (is_object($row) && isset($row->ID)) {
                    $posts[(int) $row->ID] = $row;
                }
            }
            foreach ($GLOBALS['wp_fts_test_posts'] ?? [] as $postId => $row) {
                if (is_object($row)) {
                    $posts[(int) $postId] = $row;
                }
            }
            $ids = [];
            foreach ($posts as $postId => $post) {
                if (
                    $postId > $cursor
                    && in_array((string) ($post->post_status ?? 'publish'), $statuses, true)
                    && in_array((string) ($post->post_type ?? 'post'), $types, true)
                ) {
                    $ids[] = $postId;
                }
            }
            sort($ids, SORT_NUMERIC);

            return array_slice($ids, 0, $limit);
        }

        if (str_starts_with($sql, 'SELECT candidates.post_id')) {
            $cursor = max(0, (int) ($args[0] ?? 0));
            $limit = max(1, (int) ($args[count($args) - 1] ?? 1));
            $statusNames = ['publish', 'draft', 'pending', 'future', 'private', 'trash', 'inherit', 'auto-draft'];
            $allowedStatuses = [];
            $allowedTypes = [];
            foreach ($args as $value) {
                if (!is_string($value)) {
                    continue;
                }
                if (in_array($value, $statusNames, true)) {
                    $allowedStatuses[$value] = true;
                } elseif (isset($GLOBALS['wp_fts_test_post_types'][$value])) {
                    $allowedTypes[$value] = true;
                }
            }
            $posts = [];
            foreach ($this->postRows as $row) {
                if (is_object($row) && isset($row->ID)) {
                    $posts[(int) $row->ID] = $row;
                }
            }
            foreach ($GLOBALS['wp_fts_test_posts'] as $postId => $row) {
                if (is_object($row)) {
                    $posts[(int) $postId] = $row;
                }
            }
            $ids = [];
            foreach ($posts as $postId => $post) {
                $postStatus = (string) ($post->post_status ?? '');
                $postType = (string) ($post->post_type ?? '');
                if (
                    $postId <= $cursor
                    || (string) ($post->post_password ?? '') !== ''
                    || !isset($allowedTypes[$postType])
                    || !isset($allowedStatuses[$postStatus])
                ) {
                    continue;
                }
                $ids[$postId] = true;
            }
            foreach (array_keys($this->docs) as $postId) {
                $postId = (int) $postId;
                if ($postId > $cursor) {
                    $ids[$postId] = true;
                }
            }
            $ids = array_map('intval', array_keys($ids));
            sort($ids, SORT_NUMERIC);
            return array_slice($ids, 0, $limit);
        }

        if (str_starts_with($sql, 'SELECT DISTINCT term_id FROM wp_fts_postings')) {
            $ids = array_fill_keys(array_map('intval', $args), true);
            $termIds = [];
            foreach ($this->postings as $key => $postings) {
                foreach ($postings as $postId => $_impact) {
                    if (isset($ids[(int) $postId])) {
                        $termIds[$this->ensure_term_id($key)] = true;
                        break;
                    }
                }
            }
            $termIds = array_map('intval', array_keys($termIds));
            sort($termIds, SORT_NUMERIC);
            return $termIds;
        }

        if (str_starts_with($sql, 'SELECT post_id FROM wp_fts_documents')) {
            $ids = array_map('intval', array_keys($this->docs));
            sort($ids, SORT_NUMERIC);
            return $ids;
        }

        if (str_starts_with($sql, 'SELECT p.ID FROM wp_posts p JOIN wp_fts_documents d')) {
            $offset = 0;
            $docIds = $this->prepared_in_args($sql, 'p.ID', '%d', $args, $offset);
            $types = $this->prepared_in_args($sql, 'p.post_type', '%s', $args, $offset);
            $statuses = $this->prepared_in_args($sql, 'p.post_status', '%s', $args, $offset);
            $dateAfter = str_contains($sql, 'p.post_date_gmt >= %s') ? (string) ($args[$offset++] ?? '') : null;
            $dateBefore = str_contains($sql, 'p.post_date_gmt <= %s') ? (string) ($args[$offset++] ?? '') : null;
            $result = [];
            foreach (array_map('intval', $docIds) as $postId) {
                if (!isset($this->docs[$postId])) {
                    continue;
                }
                $post = $this->v4_post_row($postId);
                $type = (string) ($post->post_type ?? 'post');
                $status = (string) ($post->post_status ?? 'draft');
                $date = (string) ($post->post_date_gmt ?? '1970-01-01 00:00:00');
                if (
                    ($types !== [] && !in_array($type, array_map('strval', $types), true))
                    || ($statuses !== [] && !in_array($status, array_map('strval', $statuses), true))
                    || ($dateAfter !== null && strcmp($date, $dateAfter) < 0)
                    || ($dateBefore !== null && strcmp($date, $dateBefore) > 0)
                ) {
                    continue;
                }
                $result[] = $postId;
            }
            sort($result, SORT_NUMERIC);
            return $result;
        }

        if (str_starts_with($sql, 'SELECT blog_id FROM `wp_blogs` WHERE blog_id > %d')) {
            $afterSiteId = max(0, (int) ($args[0] ?? 0));
            $limit = max(0, (int) ($args[count($args) - 1] ?? 0));
            $sites = array_values(array_filter(
                array_map('intval', is_array($GLOBALS['wp_fts_test_sites'] ?? null) ? $GLOBALS['wp_fts_test_sites'] : []),
                static fn(int $siteId): bool => $siteId > $afterSiteId
            ));
            sort($sites, SORT_NUMERIC);

            return $limit > 0 ? array_slice($sites, 0, $limit) : $sites;
        }

        if (str_starts_with($sql, 'SELECT term FROM wp_fts_terms')) {
            return array_keys($this->ftsTerms);
        }

        if (str_starts_with($sql, 'SELECT doc_id FROM wp_fts_docs WHERE is_deleted = 1')) {
            return array_keys(array_filter(
                $this->docs,
                static fn(array $doc): bool => $doc['is_deleted'] === 1
            ));
        }

        if (str_starts_with($sql, 'SELECT doc_id FROM wp_fts_docs')) {
            $includeDeleted = !str_contains($sql, 'WHERE is_deleted = 0');
            return array_keys(array_filter(
                $this->docs,
                static fn(array $doc): bool => $includeDeleted || $doc['is_deleted'] === 0
            ));
        }

        return [];
    }

    /** Restores the expected relational-v4 columns and indexes for one fake table. */
    private function restore_schema_contract(string $table): void
    {
        foreach (['fts_terms', 'fts_postings', 'fts_documents', 'fts_work'] as $suffix) {
            if (!str_ends_with($table, $suffix)) {
                continue;
            }

            [$columns, $indexes] = match ($suffix) {
                'fts_terms' => [['term_id', 'lang', 'kind', 'term', 'doc_freq'], ['PRIMARY' => ['term_id'], 'term_identity' => ['lang', 'kind', 'term'], 'empty_terms' => ['doc_freq']]],
                'fts_postings' => [['term_id', 'post_id', 'impact'], ['PRIMARY' => ['term_id', 'post_id'], 'post_term_impact' => ['post_id', 'term_id', 'impact']]],
                'fts_documents' => [['post_id', 'primary_lang', 'content_hash', 'snippet_text', 'indexed_at'], ['PRIMARY' => ['post_id']]],
                'fts_work' => [['job_key', 'kind', 'post_id', 'generation', 'state', 'available_at', 'attempts', 'claim_token', 'claimed_generation', 'claim_expires_at', 'cursor_post_id', 'scope_coverage', 'scope_incarnation', 'scope_subject_type', 'scope_subject_id', 'payload', 'last_error_code', 'last_error_at'], ['PRIMARY' => ['job_key'], 'ready' => ['kind', 'state', 'available_at', 'post_id', 'job_key'], 'recoverable' => ['kind', 'state', 'claim_expires_at', 'available_at', 'post_id', 'job_key'], 'claim_token' => ['claim_token', 'post_id'], 'kind_job' => ['kind', 'job_key'], 'scope_subject' => ['kind', 'scope_coverage', 'scope_subject_type', 'scope_subject_id'], 'dirty' => ['post_id', 'kind']]],
            };
            $this->schemaColumns[$table] = $columns;
            $this->schemaEngines[$table] = 'InnoDB';
            unset($this->schemaColumnDefinitions[$table]);
            $this->schemaIndexes[$table] = $indexes;
            unset($this->schemaIndexSubParts[$table], $this->schemaInvisibleIndexes[$table]);
            $this->schemaUniqueIndexes[$table] = match ($suffix) {
                'fts_terms' => ['PRIMARY' => true, 'term_identity' => true],
                default => ['PRIMARY' => true],
            };
            return;
        }
    }

    /** @return array{Field:string,Type:string,Null:string,Extra:string} */
    private function schema_column_definition(string $table, string $column): array
    {
        $types = match (true) {
            str_ends_with($table, 'fts_terms') => [
                'term_id' => 'bigint(20) unsigned',
                'lang' => 'varbinary(32)',
                'kind' => 'tinyint(3) unsigned',
                'term' => 'varbinary(255)',
                'doc_freq' => 'int(10) unsigned',
            ],
            str_ends_with($table, 'fts_postings') => [
                'term_id' => 'bigint(20) unsigned',
                'post_id' => 'bigint(20) unsigned',
                'impact' => 'smallint(5) unsigned',
            ],
            str_ends_with($table, 'fts_documents') => [
                'post_id' => 'bigint(20) unsigned',
                'primary_lang' => 'varbinary(32)',
                'content_hash' => 'varbinary(64)',
                'snippet_text' => 'mediumtext',
                'indexed_at' => 'bigint(20) unsigned',
            ],
            str_ends_with($table, 'fts_work') => [
                'job_key' => 'varbinary(191)',
                'kind' => 'varchar(16)',
                'post_id' => 'bigint(20) unsigned',
                'generation' => 'bigint(20) unsigned',
                'state' => 'varchar(12)',
                'available_at' => 'bigint(20) unsigned',
                'attempts' => 'int(10) unsigned',
                'claim_token' => 'varchar(64)',
                'claimed_generation' => 'bigint(20) unsigned',
                'claim_expires_at' => 'bigint(20) unsigned',
                'cursor_post_id' => 'bigint(20) unsigned',
                'scope_coverage' => 'varchar(12)',
                'scope_incarnation' => 'varbinary(32)',
                'scope_subject_type' => 'varchar(24)',
                'scope_subject_id' => 'bigint(20) unsigned',
                'payload' => 'longtext',
                'last_error_code' => 'varchar(64)',
                'last_error_at' => 'bigint(20) unsigned',
            ],
            default => [],
        };
        $nullable = in_array($column, ['content_hash', 'snippet_text', 'payload'], true);
        $definition = [
            'Field' => $column,
            'Type' => $types[$column] ?? 'text',
            'Null' => $nullable ? 'YES' : 'NO',
            'Extra' => $column === 'term_id' && str_ends_with($table, 'fts_terms') ? 'auto_increment' : '',
        ];

        return array_replace($definition, $this->schemaColumnDefinitions[$table][$column] ?? []);
    }

    /**
     * @return array{0:string,1:array<int,mixed>}
     */
    private function statement_parts(mixed $statement): array
    {
        if ($statement instanceof WP_FTS_Test_Prepared_SQL) {
            return [$statement->sql, $statement->args];
        }

        return [(string) $statement, []];
    }

    /** Records one simulated read statement and notifies its observer. */
    private function record_read_query(string $sql): void
    {
        $this->num_queries++;
        if (is_callable($this->readQueryObserver)) {
            ($this->readQueryObserver)($sql);
        }
        if (!$this->recordReadQueries) {
            return;
        }

        $this->queries[] = [$sql, 0.0005, 'WP_FTS_Test_WPDB'];
    }

    /**
     * @param array<int,mixed> $args
     * @return array<int,mixed>
     */
    private function prepared_in_args(string $sql, string $column, string $placeholder, array $args, int &$offset): array
    {
        if (preg_match('/' . preg_quote($column, '/') . ' IN \(([^)]*)\)/', $sql, $matches) !== 1) {
            return [];
        }

        $count = substr_count($matches[1], $placeholder);
        $values = array_slice($args, $offset, $count);
        $offset += $count;

        return $values;
    }

    /**
     * Read MySQL binary literals from a generated SQL statement.
     *
     * @return string[]
     */
    private function binary_term_literals(string $sql): array
    {
        $values = [];
        $offset = 0;
        while (($start = strpos($sql, "X'", $offset)) !== false) {
            $end = strpos($sql, "'", $start + 2);
            if ($end === false) {
                break;
            }

            $hex = substr($sql, $start + 2, $end - $start - 2);
            if ($hex !== '' && strlen($hex) % 2 === 0 && strspn($hex, '0123456789abcdefABCDEF') === strlen($hex)) {
                $value = hex2bin($hex);
                if ($value !== false) {
                    $values[] = $value;
                }
            }
            $offset = $end + 1;
        }

        return $values;
    }
}

/**
 * Replace the fake durable queue with the requested post ids.
 *
 * @param int[] $post_ids
 */
function wp_fts_test_seed_queue(WP_FTS_Test_WPDB $wpdb, array $post_ids, ?int $now = null): void
{
    $queue = new WP_FTS_Index_Queue($wpdb);
    $queue->clear();
    $queue->enqueue_many($post_ids, $now);
    $wpdb->queries = [];
    $wpdb->prepared = [];
    $wpdb->last_error = '';
}

/** Seed one durable corpus reconciliation without enumerating its posts. */
function wp_fts_test_seed_scope(WP_FTS_Test_WPDB $wpdb, string $scope_key = 'test-corpus'): void
{
    $health = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
    $profileHash = is_array($health) && is_string($health['index_profile_hash'] ?? null)
        ? $health['index_profile_hash']
        : '';
    if (preg_match('/^[a-f0-9]{40}$/D', $profileHash) !== 1) {
        $profileHash = wp_fts_test_default_index_profile_hash();
    }
    (new WP_FTS_Index_Queue($wpdb))->enqueue_scope(
        $scope_key,
        [
            'reason' => 'test_corpus',
            'profile_hash' => $profileHash,
        ],
        null,
        WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
        '',
        0,
        (string) ($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION]
            ?? '0123456789abcdef0123456789abcdef')
    );
    $wpdb->queries = [];
    $wpdb->prepared = [];
    $wpdb->last_error = '';
}

/**
 * @return int[]
 */
function wp_fts_test_queue_ids(WP_FTS_Test_WPDB $wpdb): array
{
    $ids = [];
    foreach ($wpdb->queue as $row) {
        if ((string) ($row['kind'] ?? 'post') === 'post' && (int) ($row['post_id'] ?? 0) > 0) {
            $ids[] = (int) $row['post_id'];
        }
    }
    sort($ids, SORT_NUMERIC);

    return $ids;
}

final class WP_FTS_Test_SQLite_Driver
{
}

final class WP_FTS_Test_Language_Aware_Analyzer
{
    /** @var array<int,array<string,mixed>> */
    public array $contentOptions = [];

    /** @var array<int,array<string,mixed>> */
    public array $queryOccurrenceOptions = [];

    /** @var array<int,array<string,mixed>> */
    public array $queryOptions = [];

    /**
     * @return array<int,array{term:string,weight:float,lang:string}>
     */
    public function analyze_content(string $html, array $options = []): array
    {
        $this->contentOptions[] = $options;
        $documentLang = $this->language_from_options($options, ['document_lang']);
        $occurrences = [];

        if (str_contains($html, 'zamek')) {
            $occurrences[] = ['term' => 'zamek', 'weight' => 1.0, 'lang' => $documentLang];
        }
        if (str_contains($html, 'castle')) {
            $occurrences[] = ['term' => 'castle', 'weight' => 1.0, 'lang' => 'en'];
        }

        return $occurrences;
    }

    /**
     * @return array<int,array{term:string,lang:string}>
     */
    public function analyze_query_occurrences(string $query, array $options = []): array
    {
        $this->queryOccurrenceOptions[] = $options;

        return $this->query_occurrences($query, $this->language_from_options($options, ['query_lang']));
    }

    /**
     * @return array<int,string|array{term:string,lang:string}>
     */
    public function analyze_query(string $query, array $options = []): array
    {
        $this->queryOptions[] = $options;
        $occurrences = $this->query_occurrences($query, $this->language_from_options($options, ['query_lang']));

        return array_map(static fn(array $occurrence): string => $occurrence['term'], $occurrences);
    }

    /**
     * @param array<int,string> $keys
     */
    private function language_from_options(array $options, array $keys): string
    {
        foreach ($keys as $key) {
            if (isset($options[$key]) && is_string($options[$key]) && trim($options[$key]) !== '') {
                return WP_FTS_TermNamespace::canonicalize_lang($options[$key]);
            }
        }

        return 'en';
    }

    /**
     * @return array<int,array{term:string,lang:string}>
     */
    private function query_occurrences(string $query, string $lang): array
    {
        if (!str_contains($query, 'zamek')) {
            return [];
        }

        return $lang === 'en' ? [] : [['term' => 'zamek', 'lang' => $lang]];
    }
}

final class WP_FTS_Test_Oversized_Term_Analyzer
{
    public function __construct(
        private string $normalTerm,
        private string $oversizedTerm,
        private string $exactLimitTerm,
    ) {
    }

    public function index_signature(): string
    {
        return 'wp-fts-test-oversized-term-analyzer-v1';
    }

    /**
     * @return array<int,array{term:string,weight:float,lang:string}>
     */
    public function analyze_content(string $html, array $options = []): array
    {
        return $this->occurrences_for_text($html, $options);
    }

    /**
     * @return array<int,array{term:string,weight:float,lang:string}>
     */
    public function analyze_plain_content(string $text, array $options = []): array
    {
        return $this->occurrences_for_text($text, $options);
    }

    /**
     * @return array<int,array{term:string,lang:string}>
     */
    public function analyze_query_occurrences(string $query, array $options = []): array
    {
        return array_map(
            static fn(array $occurrence): array => [
                'term' => $occurrence['term'],
                'lang' => $occurrence['lang'],
            ],
            $this->occurrences_for_text($query, $options)
        );
    }

    /**
     * @return string[]|array<int,array{term:string,lang:string}>
     */
    public function analyze_query(string $query, array $options = []): array
    {
        $occurrences = $this->analyze_query_occurrences($query, $options);
        return array_map(static fn(array $occurrence): string => $occurrence['term'], $occurrences);
    }

    /**
     * @return array<int,array{term:string,weight:float,lang:string}>
     */
    private function occurrences_for_text(string $text, array $options): array
    {
        $lang = WP_FTS_TermNamespace::language_from_options(
            $options,
            'en',
            ['query_lang', 'document_lang', '_default_query_lang', '_default_document_lang']
        ) ?? 'en';

        $occurrences = [];
        if (str_contains($text, 'normal-token')) {
            $occurrences[] = ['term' => $this->normalTerm, 'weight' => 1.0, 'lang' => $lang];
        }
        if (str_contains($text, 'oversized-token')) {
            $occurrences[] = ['term' => $this->oversizedTerm, 'weight' => 1.0, 'lang' => $lang];
        }
        if (str_contains($text, 'exact-limit-token')) {
            $occurrences[] = ['term' => $this->exactLimitTerm, 'weight' => 1.0, 'lang' => $lang];
        }

        return $occurrences;
    }
}

