/** Computes and caches the accepted profile hash used by default fixtures. */
function wp_fts_test_default_index_profile_hash(): string
{
    static $hash = null;
    if (is_string($hash)) {
        return $hash;
    }

    $profileMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'current_index_profile');
    $profileMethod->setAccessible(true);
    $profile = $profileMethod->invoke(null);
    $hash = is_array($profile) && is_string($profile['hash'] ?? null)
        ? $profile['hash']
        : '';
    if (preg_match('/^[a-f0-9]{40}$/', $hash) !== 1) {
        throw new RuntimeException('Could not establish the default accepted FTS index profile for tests.');
    }

    return $hash;
}

