/** Installs blog-switching fakes on test runs that do not already provide them. */
function wp_fts_test_install_multisite_switch_functions(): void
{
    if (!function_exists('switch_to_blog')) {
        /** Switches the fixture’s option and table context to another site. */
        function switch_to_blog(int $blog_id): bool
        {
            global $wpdb;

            $failIds = $GLOBALS['wp_fts_test_switch_to_blog_fail_ids'] ?? [];
            if (
                !empty($GLOBALS['wp_fts_test_switch_to_blog_returns_false'])
                || (is_array($failIds) && in_array($blog_id, $failIds, true))
            ) {
                return false;
            }

            $current = (int) ($GLOBALS['wp_fts_test_current_blog_id'] ?? 1);
            $GLOBALS['wp_fts_test_switch_log'][] = $blog_id;
            $GLOBALS['wp_fts_test_blog_stack'][] = $current;
            $GLOBALS['wp_fts_test_current_blog_id'] = $blog_id;
            if (isset($wpdb) && is_object($wpdb) && method_exists($wpdb, 'get_blog_prefix')) {
                $wpdb->prefix = $wpdb->get_blog_prefix($blog_id);
                $wpdb->posts = $wpdb->prefix . 'posts';
                $wpdb->term_relationships = $wpdb->prefix . 'term_relationships';
                foreach (['posts', 'term_relationships'] as $suffix) {
                    $source = $wpdb->base_prefix . $suffix;
                    $target = $wpdb->prefix . $suffix;
                    foreach ([
                        'schemaColumns',
                        'schemaColumnDefinitions',
                        'schemaIndexes',
                        'schemaUniqueIndexes',
                        'schemaIndexSubParts',
                        'schemaInvisibleIndexes',
                    ] as $property) {
                        if (
                            isset($wpdb->{$property})
                            && is_array($wpdb->{$property})
                            && !array_key_exists($target, $wpdb->{$property})
                            && array_key_exists($source, $wpdb->{$property})
                        ) {
                            $wpdb->{$property}[$target] = $wpdb->{$property}[$source];
                        }
                    }
                    if (
                        isset($wpdb->schemaEngines)
                        && is_array($wpdb->schemaEngines)
                        && !array_key_exists($target, $wpdb->schemaEngines)
                        && array_key_exists($source, $wpdb->schemaEngines)
                    ) {
                        $wpdb->schemaEngines[$target] = $wpdb->schemaEngines[$source];
                    }
                }
            }

            return true;
        }
    }

    if (!function_exists('restore_current_blog')) {
        /** Restores the fixture’s previous option and table context. */
        function restore_current_blog(): bool
        {
            global $wpdb;

            $previous = array_pop($GLOBALS['wp_fts_test_blog_stack']);
            if (!is_int($previous)) {
                $previous = 1;
            }
            $GLOBALS['wp_fts_test_restore_log'][] = $previous;
            $GLOBALS['wp_fts_test_current_blog_id'] = $previous;
            if (isset($wpdb) && is_object($wpdb) && method_exists($wpdb, 'get_blog_prefix')) {
                $wpdb->prefix = $wpdb->get_blog_prefix($previous);
                $wpdb->posts = $wpdb->prefix . 'posts';
                $wpdb->term_relationships = $wpdb->prefix . 'term_relationships';
            }

            return true;
        }
    }

    if (!function_exists('get_current_blog_id')) {
        function get_current_blog_id(): int
        {
            return (int) ($GLOBALS['wp_fts_test_current_blog_id'] ?? 1);
        }
    }
}

