        $store =& wp_fts_test_option_store();
        $existed = array_key_exists($name, $store);
        unset($store[$name]);
        $GLOBALS['wp_fts_test_deleted_options'][] = [
            'blog_id' => wp_fts_test_current_option_blog_id(),
            'name' => $name,
            'existed' => $existed,
        ];
        $afterDelete = $GLOBALS['wp_fts_test_after_delete_option'] ?? null;
        if (is_callable($afterDelete)) {
            $afterDelete($name, $existed);
        }

        return $existed;
    }
}

