    }
}

if (!function_exists('_get_cron_array')) {
    /** @return array<int,array<string,array<string,array{schedule:false,args:array<int,mixed>}>>> */
    function _get_cron_array(): array
    {
        $GLOBALS['wp_fts_test_cron_array_reads']++;
        $crons = [];
        foreach ($GLOBALS['wp_fts_test_scheduled'] as $event) {
            if (!is_array($event)) {
                continue;
            }
            $timestamp = max(1, (int) ($event['timestamp'] ?? 0));
            $hook = is_string($event['hook'] ?? null) ? $event['hook'] : '';
            $args = is_array($event['args'] ?? null) ? array_values($event['args']) : [];
            if ($hook === '') {
                continue;
            }
            $crons[$timestamp][$hook][md5(serialize($args))] = [
                'schedule' => false,
                'args' => $args,
            ];
        }
        uksort($crons, 'strnatcasecmp');

        return $crons;
    }
}

if (!function_exists('_set_cron_array')) {
    /** Persists the fake cron array when the configured write boundary allows it. */
    function _set_cron_array(array $crons, bool $wp_error = false): bool
    {
        $GLOBALS['wp_fts_test_cron_write_count']++;
        $GLOBALS['wp_fts_test_cron_write_calls'][] = $crons;
        if (empty($GLOBALS['wp_fts_test_set_cron_array_succeeds'])) {
            return false;
        }

        $scheduled = [];
        uksort($crons, 'strnatcasecmp');
        foreach ($crons as $timestamp => $hooks) {
            if (!is_array($hooks)) {
                continue;
            }
            foreach ($hooks as $hook => $events) {
                if (!is_string($hook) || !is_array($events)) {
                    continue;
                }
                foreach ($events as $event) {
                    if (!is_array($event)) {
                        continue;
                    }
                    $args = is_array($event['args'] ?? null) ? array_values($event['args']) : [];
                    $key = $args === [] ? $hook : $hook . '|' . serialize($args);
                    if (!isset($scheduled[$key])) {
                        $scheduled[$key] = [
                            'timestamp' => (int) $timestamp,
                            'hook' => $hook,
                            'args' => $args,
                        ];
                    }
                }
            }
        }
        $GLOBALS['wp_fts_test_scheduled'] = $scheduled;

        return true;
    }
}

if (!function_exists('wp_schedule_single_event')) {
    /** Adds one event through the fake cron read-modify-write boundary. */
    function wp_schedule_single_event(int $timestamp, string $hook, array $args = []): bool
    {
        $GLOBALS['wp_fts_test_schedule_calls'][] = [
            'timestamp' => $timestamp,
            'hook' => $hook,
            'args' => $args,
        ];
        if (empty($GLOBALS['wp_fts_test_schedule_succeeds'])) {
            return false;
        }
        $crons = _get_cron_array();
        $crons[$timestamp][$hook][md5(serialize($args))] = [
            'schedule' => false,
            'args' => $args,
        ];
        uksort($crons, 'strnatcasecmp');

        return _set_cron_array($crons, true);
    }
}

if (!function_exists('wp_clear_scheduled_hook')) {
    /** Removes all fake cron events registered for one hook. */
    function wp_clear_scheduled_hook(string $hook): int
    {
        $GLOBALS['wp_fts_test_cleared_hooks'][] = $hook;
        $crons = _get_cron_array();
        $removed = 0;
        foreach ($crons as $timestamp => &$hooks) {
            if (!is_array($hooks) || !isset($hooks[$hook])) {
                continue;
            }
            $removed += is_array($hooks[$hook]) ? count($hooks[$hook]) : 0;
            unset($hooks[$hook]);
            if ($hooks === []) {
                unset($crons[$timestamp]);
            }
        }
        unset($hooks);
        if ($removed > 0) {
            _set_cron_array($crons, true);
        }

        return $removed;
    }
}

