        throw new WP_FTS_TestFailure("Could not parse admin route: {$url}");
    }

    $params = [];
    parse_str((string) ($parts['query'] ?? ''), $params);

    return [
        'path' => (string) ($parts['path'] ?? ''),
        'params' => $params,
    ];
}

