test_case('health manual batch records failures without exposing raw details', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $oldGet = $_GET;
    $oldPost = $_POST;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
    $rejected = wp_fts_test_backfill_post(731, 'post', 'publish', 'Health Failure');
    $rejected->post_content = str_repeat('x', WP_FTS_Analysis_Limits::MAX_SOURCE_BYTES + 1);
    $fake->postRows = [
        $rejected,
        wp_fts_test_backfill_post(732, 'post', 'publish', 'Health Continued'),
    ];
    wp_fts_test_seed_queue($fake, [731, 732]);

    try {
        $fake->queries = [];
        $_GET = ['page' => WP_FTS_Plugin::ADMIN_PAGE_SLUG];
        $_POST = [
            'wp_fts_health_action' => 'index_next_batch',
            'wp_fts_health_nonce' => wp_create_nonce('wp_fts_health_admin_action'),
        ];
        $html = wp_fts_test_capture_admin_settings_tab(null);
        $firstStatementCount = count($fake->queries);
        $diagnostics = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['latest_batch_diagnostics'] ?? [];
        $queueAfterRejection = $fake->queue;
        $docsAfterRejection = $fake->docs;
        $successorRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            100,
            static fn(): bool => count(array_filter(
                $fake->queue,
                static fn(array $row): bool => in_array($row['kind'] ?? '', ['post', 'scope'], true)
            )) === 0
        );
    } finally {
        $_GET = $oldGet;
        $_POST = $oldPost;
        $wpdb = $oldWpdb;
    }

    assert_contains('notice-warning', $html, 'manual health failure should render a warning notice');
    assert_contains('Indexed 0 items. 1 item failed and was recorded; indexing continued where possible.', $html, 'manual health failure notice should report the isolated rejection phase without claiming deferred work');
    assert_contains('<th scope="row">Last indexing failure</th><td>1 item failed in the latest batch; (untitled) (ID 731)', $html, 'health dashboard should render a concise failure row without reloading rejected source content');
    assert_contains('2 MiB document-source limit', $html, 'health dashboard should show the bounded rejection context');
    assert_true(!str_contains($html, 'INSERT INTO wp_fts_docs'), 'health dashboard should not expose raw SQL in failure output');
    assert_true(!str_contains($html, 'SELECT * FROM'), 'health dashboard should not expose stack SQL in failure output');
    assert_true(!str_contains($html, '#0'), 'health dashboard should not expose stack traces in failure output');
    assert_true(!str_contains($html, 'batchindexneedle 731'), 'health dashboard should not expose raw post body content in failure output');
    assert_true($firstStatementCount <= 20, 'the isolated health rejection phase must stay inside the complete 20-statement ceiling');
    assert_true(!isset($docsAfterRejection[731]), 'the isolated rejection phase must not publish the poison document');
    assert_true(!isset($docsAfterRejection[732]), 'the isolated rejection phase must not publish its deferred valid suffix');
    assert_same([732], array_map('intval', array_keys(array_filter(
        $queueAfterRejection,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'post'
    ))), 'the isolated rejection phase should acknowledge only the poison generation');
    assert_same('ready', $queueAfterRejection[732]['state'] ?? null, 'the valid suffix should remain immediately and durably claimable');
    assert_same('failed', $diagnostics['status'] ?? null, 'manual health diagnostics should report the isolated zero-publication rejection phase as failed');
    assert_same(0, $diagnostics['indexed'] ?? null, 'manual health diagnostics must not count the deferred suffix as indexed in the rejection phase');
    assert_same(1, $diagnostics['failures'] ?? null, 'manual health failure diagnostics should record bounded failure count');
    assert_same(731, $diagnostics['last_failed_post_id'] ?? null, 'manual health failure diagnostics should record failed post id');
    assert_same('', $diagnostics['last_failed_post_title'] ?? null, 'manual health failure diagnostics should not reload oversized rejected source content');
    assert_same('WP_FTS_Analysis_Limit_Exceeded', $diagnostics['error_class'] ?? null, 'manual health failure diagnostics should record the original bounded rejection');
    assert_contains('2 MiB document-source limit', (string) ($diagnostics['error_message'] ?? ''), 'manual health failure diagnostics should retain the safe rejection reason');
    $diagnosticJson = json_encode($diagnostics, JSON_THROW_ON_ERROR);
    assert_true(!str_contains($diagnosticJson, 'INSERT INTO wp_fts_docs'), 'manual health failure diagnostics should not store raw SQL');
    assert_true(!str_contains($diagnosticJson, 'SELECT * FROM'), 'manual health failure diagnostics should not store stack SQL');
    assert_true(!str_contains($diagnosticJson, '#0'), 'manual health failure diagnostics should not store stack traces');
    assert_true(!str_contains($diagnosticJson, 'batchindexneedle 731'), 'manual health failure diagnostics should not store raw post body content');
    assert_true(($diagnostics['stop_reason'] ?? '') !== 'stale_writer_lease_recovered', 'a fresh health fixture must not consume a stale-takeover control phase');
    $successorSummaries = array_column($successorRuns, 'summary');
    assert_same([], array_values(array_filter(
        $successorSummaries,
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'the fresh health successor must not consume a stale-takeover control phase');
    assert_true(max(array_column($successorRuns, 'statement_count')) <= 20, 'every health successor phase must stay inside the complete 20-statement ceiling');
    assert_true(!isset($fake->docs[731]), 'the permanently rejected health item should leave no derived row');
    assert_true(isset($fake->docs[732]), 'a bounded successor should index the valid suffix after the isolated rejection phase');
    assert_same([], wp_fts_test_queue_ids($fake), 'the bounded health successor should acknowledge the exact valid suffix');
});

