test_case('admin language support details cache analyzer pack statuses per request', function (): void {
    wp_fts_test_reset_wordpress_fakes();
    $filterCalls = 0;
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::ANALYZER_OPTIONS_FILTER] = static function (array $options) use (&$filterCalls): array {
        $filterCalls++;

        return $options;
    };

    WP_FTS_Plugin::reset_request_caches();
    $supportDetails = new ReflectionMethod(WP_FTS_Plugin::class, 'language_support_details');
    $supportDetails->setAccessible(true);

    for ($i = 0; $i < 6; $i++) {
        $support = $supportDetails->invoke(null, 'en-US', true);
        assert_true(is_array($support), 'language support details should return a support payload');
    }
    assert_same(2, $filterCalls, 'sandbox language support details should reuse runtime and sandbox analyzer pack statuses within one request');

    $supportDetails->invoke(null, 'en-US', false);
    assert_same(2, $filterCalls, 'runtime-only language support details should reuse cached runtime analyzer pack statuses');

    WP_FTS_Plugin::reset_request_caches();
    $supportDetails->invoke(null, 'en-US', false);
    assert_same(3, $filterCalls, 'reset request caches should allow analyzer status inspection to run again for a new request');
});

test_case('runtime analyzer is constructed once per request and invalidated by option changes', function (): void {
    wp_fts_test_reset_wordpress_fakes();
    $filterCalls = 0;
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::ANALYZER_OPTIONS_FILTER] = static function (array $options) use (&$filterCalls): array {
        $filterCalls++;

        return $options;
    };

    $first = WP_FTS_Plugin::runtime_analyzer();
    $second = WP_FTS_Plugin::runtime_analyzer();
    assert_true($first === $second, 'indexing, drift detection, and search should share one validated analyzer object within a request');
    assert_same(1, $filterCalls, 'reusing the runtime analyzer must not reconstruct or revalidate its pack configuration');

    WP_FTS_Plugin::set_runtime_lemma_pack_option(
        'pl',
        WP_FTS_AnalyzerPackValidator::default_polish_fixture_manifest()
    );
    $afterOptionChange = WP_FTS_Plugin::runtime_analyzer();
    assert_true($afterOptionChange !== $first, 'persisting analyzer options should invalidate the request cache before later work');
    assert_same(3, $filterCalls, 'option preflight and the first analyzer read after mutation should each validate the effective filtered configuration once');
    assert_true($afterOptionChange === WP_FTS_Plugin::runtime_analyzer(), 'the replacement analyzer should remain shared for the rest of the request');
    assert_same(3, $filterCalls, 'reusing the replacement analyzer should perform no additional pack-option reads');
});

test_case('runtime analyzer cache follows same-request multisite switches and restoration', function (): void {
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_install_multisite_switch_functions();
    $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
    $GLOBALS['wp_fts_test_site_options'] = [
        1 => [
            WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION => [
                'lemma_packs_by_lang' => [
                    'pl' => WP_FTS_AnalyzerPackValidator::default_polish_fixture_manifest(),
                ],
            ],
        ],
        2 => [
            WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION => [
                'lemma_packs_by_lang' => [
                    'pl' => false,
                ],
            ],
        ],
    ];
    $constructedForBlogs = [];
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::ANALYZER_OPTIONS_FILTER] = static function (array $options) use (&$constructedForBlogs): array {
        $constructedForBlogs[] = get_current_blog_id();

        return $options;
    };

    try {
        $siteOne = WP_FTS_Plugin::runtime_analyzer();
        assert_same(['zamek'], $siteOne->analyze_query('zamkach', ['query_lang' => 'pl']), 'site one should use its configured fixture lemma pack');

        assert_same(true, switch_to_blog(2), 'the fixture should switch to the second site');
        WP_FTS_Plugin::handle_blog_switch(2, 1, 'switch');
        $siteTwo = WP_FTS_Plugin::runtime_analyzer();
        assert_same(['zamk'], $siteTwo->analyze_query('zamkach', ['query_lang' => 'pl']), 'site two should use its disabled-pack fallback instead of site one cache state');

        assert_same(true, restore_current_blog(), 'the fixture should restore the original site');
        WP_FTS_Plugin::handle_blog_switch(1, 2, 'restore');
        $restoredSiteOne = WP_FTS_Plugin::runtime_analyzer();
        assert_same(['zamek'], $restoredSiteOne->analyze_query('zamkach', ['query_lang' => 'pl']), 'restoring site one should restore its own analyzer behavior');
    } finally {
        wp_fts_test_reset_wordpress_fakes();
    }

    assert_true($siteOne !== $siteTwo && $siteTwo !== $restoredSiteOne, 'each blog context should receive a newly validated site-scoped analyzer object');
    assert_same($siteOne->index_signature(), $restoredSiteOne->index_signature(), 'restoring a blog should reproduce its deterministic analyzer signature');
    assert_true($siteOne->index_signature() !== $siteTwo->index_signature(), 'different per-site analyzer options must produce distinct signatures');
    assert_same([1, 2, 1], $constructedForBlogs, 'one analyzer should be constructed in each switched or restored blog context');
});

