        assert_same(403, $forged['payload']['data']['status'] ?? null, 'detail AJAX bad nonce response should use HTTP-forbidden status metadata');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('admin detail ID parsing rejects oversized scalar and array inputs before expansion', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $method = new ReflectionMethod(WP_FTS_Plugin::class, 'request_id_list_value');

    try {
        $oversizedScalar = str_repeat('1,', 1025);
        assert_true(strlen($oversizedScalar) > 2048, 'oversized scalar fixture should exceed the 2 KiB pre-split ceiling');
        assert_same([], $method->invoke(null, ['ids' => $oversizedScalar], 'ids', 50), 'oversized scalar IDs should be rejected before preg_split');

        $twentyByteScalar = '1' . str_repeat('0', 19);
        assert_same(20, strlen($twentyByteScalar), '20-byte scalar fixture should exercise the documented item boundary');
        assert_same([], $method->invoke(null, ['ids' => $twentyByteScalar], 'ids', 50), 'a structurally bounded scalar above PHP_INT_MAX should be rejected rather than saturating');

        $twentyOneByteScalar = '1' . str_repeat('0', 20);
        assert_same(21, strlen($twentyOneByteScalar), '21-byte scalar fixture should exceed the item boundary by one byte');
        assert_same([], $method->invoke(null, ['ids' => $twentyOneByteScalar], 'ids', 50), 'a scalar item above 20 bytes should reject the complete request');

        $maxInteger = (string) PHP_INT_MAX;
        assert_same([PHP_INT_MAX], $method->invoke(null, ['ids' => $maxInteger], 'ids', 50), 'the exact runtime integer boundary should remain accepted');
        $sameLengthOverflow = str_repeat('9', strlen($maxInteger));
        assert_same([], $method->invoke(null, ['ids' => $sameLengthOverflow], 'ids', 50), 'same-length decimal overflow should be rejected before integer conversion');

        $mixedScalar = '1,' . $twentyOneByteScalar . ',2';
        assert_same([], $method->invoke(null, ['ids' => $mixedScalar], 'ids', 50), 'one oversized scalar token should reject the whole CSV rather than partially accepting neighbors');

        $oversizedArray = array_map('strval', range(1, 51));
        assert_same([], $method->invoke(null, ['ids' => $oversizedArray], 'ids', 50), 'oversized ID arrays should be rejected before item scanning');

        $oversizedItemArray = array_fill(0, 50, '1');
        $oversizedItemArray[49] = str_repeat('9', 21);
        assert_same([], $method->invoke(null, ['ids' => $oversizedItemArray], 'ids', 50), 'an array item above 20 bytes should reject the complete request');

        $boundaryArray = array_map('strval', range(1, 50));
        assert_same(range(1, 50), $method->invoke(null, ['ids' => $boundaryArray], 'ids', 50), 'the exact 50-ID page boundary should remain accepted');

        $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
        $fake->queries = [];
        $fake->prepared = [];
        $response = wp_fts_test_capture_sandbox_details_ajax([
            'wp_fts_sandbox_details_nonce' => wp_create_nonce('wp_fts_sandbox_result_details'),
            'wp_fts_sandbox_post_ids' => $mixedScalar,
            'wp_fts_sandbox_query' => 'boundedneedle',
            'wp_fts_sandbox_lang' => 'en',
            'wp_fts_sandbox_search' => '1',
        ]);
        assert_same(false, $response['payload']['success'] ?? null, 'an oversized mixed CSV should fail the authenticated detail request');
        assert_same(400, $response['payload']['data']['status'] ?? null, 'an oversized mixed CSV should fail before search as a bad request');
        assert_same([], $fake->prepared, 'an oversized mixed CSV should prepare zero downstream search statements');
        assert_same([], $fake->queries, 'an oversized mixed CSV should execute zero downstream search statements');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('admin sandbox detail ajax returns sanitized page snippets without posting inspection', function (): void {
