        is_array($settings['field_boosts'] ?? null) ? $settings['field_boosts'] : [],
        [
            'title' => 7.0,
            'content' => 1.25,
        ]
    );
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = $settings;
    wp_fts_test_mark_search_takeover_ready();

    try {
        $requestedPost = (object) [
            'ID' => 916,
            'post_title' => 'titleneedle Operator <script>UnsafeTitle</script>',
            'post_content' => '<p>bodyneedle safe body text.</p><script>UNSAFE_HIDDEN_BODY_MARKER</script><img src=x onerror="alert(1)">',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-06-12 00:00:00',
        ];
        $unrequestedPost = (object) [
            'ID' => 917,
            'post_title' => 'Unrequested Sandbox Match',
            'post_content' => '<p>titleneedle bodyneedle also matches.</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-06-12 00:00:00',
        ];
        foreach ([$requestedPost, $unrequestedPost] as $post) {
            $GLOBALS['wp_fts_test_posts'][(int) $post->ID] = $post;
            $fake->postRows[] = $post;
            update_post_meta((int) $post->ID, WP_FTS_Plugin::LANGUAGE_META_KEY, 'en');
            wp_fts_test_index_saved_post((int) $post->ID, $post, true);
        }

        $request = [
            'wp_fts_sandbox_details_nonce' => wp_create_nonce('wp_fts_sandbox_result_details'),
            'wp_fts_sandbox_post_ids' => '916,999999',
            'wp_fts_sandbox_query' => 'titleneedle bodyneedle',
            'wp_fts_sandbox_lang' => 'en',
            'wp_fts_sandbox_search' => '1',
            'wp_fts_sandbox_mode' => 'OR',
            'wp_fts_sandbox_limit' => '10',
            'wp_fts_sandbox_snippet_length' => '180',
            'wp_fts_sandbox_highlight' => '1',
            'wp_fts_sandbox_prefix_matching' => '0',
            'wp_fts_sandbox_language_fallback' => '0',
            'wp_fts_sandbox_post_type' => ['post'],
            'wp_fts_sandbox_post_status' => ['publish'],
        ];

        $fake->prepared = [];
        $detail = wp_fts_test_capture_sandbox_details_ajax($request);
        assert_same(true, $detail['payload']['success'] ?? null, 'detail AJAX should authorize and return a success payload');
        $rows = $detail['payload']['data']['rows'] ?? [];
        assert_true(isset($rows['916']), 'detail AJAX should return the requested visible result row');
        assert_true(!isset($rows['917']), 'detail AJAX should omit visible results that were not requested');
        assert_true(!isset($rows['999999']), 'detail AJAX should omit requested IDs that are not in the current result set');
        assert_true(!array_key_exists('indexed_terms', $rows['916']), 'detail rows should not expose stored postings');
        assert_true(!array_key_exists('match_explanation', $rows['916']), 'detail rows should not restore a per-result explanation path');
        $encodedRow = json_encode($rows['916'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        assert_true(is_string($encodedRow), 'bounded detail rows should be JSON encodable');
        assert_true(!str_contains($encodedRow, '<script'), 'detail JSON should not expose script markup from indexed content');
        assert_true(!str_contains($encodedRow, 'onerror'), 'detail JSON should not expose unsafe attributes from indexed content');
        assert_true(!str_contains($encodedRow, 'UNSAFE_HIDDEN_BODY_MARKER'), 'detail JSON should not expose hidden unsafe post body text');
        assert_same(1, wp_fts_test_prepared_sql_count($fake, '/* wp_fts:plan */'), 'detail AJAX should use one dictionary planning statement');
        assert_same(1, wp_fts_test_prepared_sql_count($fake, '/* wp_fts:rank */'), 'detail AJAX should use one relational ranking statement');
        assert_same(1, wp_fts_test_prepared_sql_count($fake, '/* wp_fts:hydrate */'), 'detail AJAX should use one page hydration statement');
        assert_same(0, wp_fts_test_prepared_sql_count($fake, 'SELECT bounded.post_id, bounded.lang, bounded.term'), 'detail AJAX should not inspect postings per result');
    } finally {
        $_GET = $oldGet;
        $_POST = $oldPost;
        $wpdb = $oldWpdb;
    }
});

test_case('admin sandbox indexed post list uses bounded storage cursor pages', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $oldGet = $_GET;
    $oldPost = $_POST;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;

    $renderIndexed = static function (array $get = []): string {
        $_POST = [];
        $_GET = array_merge(['page' => WP_FTS_Plugin::ADMIN_PAGE_SLUG], $get);

        return wp_fts_test_capture_admin_settings_tab('indexed-content');
    };

    try {
        for ($i = 1; $i <= 12; $i++) {
            $post_id = 2000 + $i;
            $post = (object) [
                'ID' => $post_id,
                'post_title' => 'Custom Indexed ' . $i,
                'post_content' => '<p>custom indexed page ' . $i . ' alpha content</p>',
                'post_excerpt' => '',
                'post_status' => 'publish',
                'post_type' => 'post',
                'post_date_gmt' => '2026-06-12 00:00:00',
            ];
            $GLOBALS['wp_fts_test_posts'][$post_id] = $post;
            $fake->postRows[] = $post;
            wp_fts_test_index_saved_post($post_id, $post, true);
        }

        wp_fts_test_capture_admin_sandbox();

        $fake->prepared = [];
        $pageOneHtml = $renderIndexed(['wp_fts_sandbox_posts_page' => '1']);
        assert_same(0, wp_fts_test_prepared_sql_count($fake, 'SELECT term FROM wp_fts_postings WHERE doc_id = %d'), 'default indexed-post page should not hydrate stored terms for visible rows');
        assert_contains('Showing one bounded page of indexed posts. Exact totals are intentionally not calculated.', $pageOneHtml, 'indexed-post diagnostics should avoid an exhaustive count query');
        assert_contains('<td>Custom Indexed 1</td>', $pageOneHtml, 'first indexed-post page should list the first custom row');
        assert_contains('<td>Custom Indexed 10</td>', $pageOneHtml, 'first indexed-post page should include custom rows up to the page limit');
        assert_true(!str_contains($pageOneHtml, 'Custom Indexed 11'), 'first indexed-post page should not leak the cursor successor page');
        assert_contains('wp_fts_sandbox_posts_cursor=2010', $pageOneHtml, 'first indexed-post page should link forward from its last visible ID');
        assert_contains('wp_fts_sandbox_posts_cursor_direction=after', $pageOneHtml, 'forward indexed-post navigation should carry an explicit cursor direction');
        assert_true(!str_contains($pageOneHtml, '>Previous</a>'), 'first cursor page should have no predecessor link');

        $fake->prepared = [];
        $pageTwoHtml = $renderIndexed([
            'wp_fts_sandbox_posts_page' => '2',
            'wp_fts_sandbox_posts_cursor' => '2010',
            'wp_fts_sandbox_posts_cursor_direction' => 'after',
        ]);
        assert_contains('Previous', $pageTwoHtml, 'sandbox indexed-post table should link back to the first page');
        assert_true(!str_contains($pageTwoHtml, 'Next'), 'last indexed-post page should not link beyond the available storage rows');
        assert_contains('Custom Indexed 11', $pageTwoHtml, 'second indexed-post page should include the eleventh custom storage row');
        assert_contains('Custom Indexed 12', $pageTwoHtml, 'second indexed-post page should include the twelfth custom storage row');
        assert_true(!str_contains($pageTwoHtml, '<td>Custom Indexed 1</td>'), 'second indexed-post page should not leak first-page rows');
        assert_true(!str_contains($pageTwoHtml, 'Create or refresh demo posts'), 'paginated sandbox page should still hide manual demo refresh controls');
        assert_true(!str_contains($pageTwoHtml, 'Build demo index'), 'paginated sandbox page should still hide manual demo index controls');
        $fake->prepared = [];
        $pageOneDebugHtml = $renderIndexed(['wp_fts_sandbox_posts_page' => '1', 'wp_fts_sandbox_show_indexed_terms' => '1']);
        assert_same(1, wp_fts_test_prepared_sql_count($fake, 'SELECT bounded.post_id, bounded.lang, bounded.term'), 'explicit indexed-term debug mode should hydrate the visible page in one set-oriented statement');
        assert_same(0, wp_fts_test_prepared_sql_count($fake, 'SELECT term FROM wp_fts_postings WHERE doc_id = %d'), 'explicit indexed-term debug mode should not issue one query per visible result');
        assert_contains('Hide indexed terms', $pageOneDebugHtml, 'explicit indexed-term debug mode should render the hide control');
    } finally {
        $_GET = $oldGet;
        $_POST = $oldPost;
        $wpdb = $oldWpdb;
    }
});

test_case('activation repairs schema stores version and surfaces database failures', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    foreach (['wp_fts_terms', 'wp_fts_postings', 'wp_fts_documents', 'wp_fts_work'] as $table) {
        unset($fake->schemaColumns[$table], $fake->schemaIndexes[$table], $fake->schemaUniqueIndexes[$table]);
    }
    $fake->queueTableExists = false;
    $fake->options = 'wp_options';
    $fake->mysqlMatchedNoopUpdatesReturnZero = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_backfill_posts($fake, 30);

    try {
        WP_FTS_Plugin::activate();
        assert_true($fake->mysqlMatchedNoopUpdateCount > 0, 'fresh activation should exercise MySQL zero-row semantics for an idempotent health CAS');
        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'activation should store schema version option');
        assert_same(4, count(array_filter($fake->queries, static fn(string $sql): bool => str_starts_with($sql, 'CREATE TABLE'))), 'activation should create or repair the four-table relational schema');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'activation should schedule the queue processor');
        assert_same([], $fake->docs, 'activation should not immediately backfill existing content');
        assert_same([], $fake->ftsTerms, 'activation should not write FTS terms for existing content');

        WP_FTS_Plugin::maybe_schedule_schema_repair();
        assert_same(4, count(array_filter($fake->queries, static fn(string $sql): bool => str_starts_with($sql, 'CREATE TABLE'))), 'current schema version should avoid redundant runtime repair');

        WP_FTS_Plugin::create_or_repair_schema();
        assert_same(4, count(array_filter($fake->queries, static fn(string $sql): bool => str_starts_with($sql, 'CREATE TABLE'))), 'explicit repair should avoid redundant DDL when the physical schema is already valid');
    } finally {
        $wpdb = $oldWpdb;
    }

    $failing = new WP_FTS_Test_WPDB();
    foreach (['wp_fts_terms', 'wp_fts_postings', 'wp_fts_documents', 'wp_fts_work'] as $table) {
        unset($failing->schemaColumns[$table], $failing->schemaIndexes[$table], $failing->schemaUniqueIndexes[$table]);
    }
    $failing->queueTableExists = false;
    $failing->failQueryPrefix = 'CREATE TABLE';
    $wpdb = $failing;
    wp_fts_test_reset_wordpress_fakes();
    $thrown = false;
    try {
        WP_FTS_Plugin::activate();
    } catch (RuntimeException $e) {
        $thrown = true;
        assert_contains('create relational FTS tables', $e->getMessage(), 'activation failure should name the failed schema operation');
    } finally {
        $wpdb = $oldWpdb;
    }
    assert_true($thrown, 'activation should throw on schema write failure');
});

test_case('physical schema verification repairs current-version table column and index gaps', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    wp_fts_test_mark_search_takeover_ready();
    try {
        unset($fake->schemaColumns['wp_fts_documents'], $fake->schemaIndexes['wp_fts_documents']);
        $damaged = WP_FTS_Plugin::storage(false)->verify_schema();
        assert_same(false, $damaged['valid'] ?? null, 'the explicit maintenance verifier should detect a missing relational table');
        assert_same(['wp_fts_documents'], $damaged['missing_tables'] ?? null, 'physical status should identify the missing table');

        WP_FTS_Plugin::create_or_repair_schema();
        assert_true(isset($fake->schemaColumns['wp_fts_documents']), 'dedicated schema maintenance should restore the missing table contract');

        $fake->schemaColumns['wp_fts_documents'] = array_values(array_diff($fake->schemaColumns['wp_fts_documents'], ['content_hash']));
        unset($fake->schemaIndexes['wp_fts_documents']['PRIMARY']);
        $physical = WP_FTS_Plugin::storage(false)->verify_schema();
        assert_same(['wp_fts_documents.content_hash'], $physical['missing_columns'] ?? null, 'verification should identify a missing required column');
        assert_same(['wp_fts_documents.PRIMARY(post_id)'], $physical['missing_indexes'] ?? null, 'verification should identify a missing required primary key');

        WP_FTS_Plugin::create_or_repair_schema();
        assert_same(true, WP_FTS_Plugin::storage(false)->verify_schema()['valid'] ?? null, 'dedicated maintenance should restore missing columns and indexes');

        $fake->schemaColumns['wp_fts_documents'][] = 'doc_len';
        $physical = WP_FTS_Plugin::storage(false)->verify_schema();
        assert_same(['wp_fts_documents.doc_len'], $physical['unexpected_columns'] ?? null, 'verification should reject the removed production document-length column');

        WP_FTS_Plugin::create_or_repair_schema();
        assert_true(!in_array('doc_len', $fake->schemaColumns['wp_fts_documents'] ?? [], true), 'dedicated maintenance should replace an incompatible document-length projection');
        assert_same(true, WP_FTS_Plugin::storage(false)->verify_schema()['valid'] ?? null, 'schema should be valid after removing the forbidden document-length column');

        $fake->schemaColumnDefinitions['wp_fts_terms']['term'] = ['Type' => 'varchar(255)'];
        $physical = WP_FTS_Plugin::storage(false)->verify_schema();
        assert_same(['wp_fts_terms.term'], $physical['invalid_columns'] ?? null, 'verification should reject a collation-sensitive text term identity in place of VARBINARY');

        WP_FTS_Plugin::create_or_repair_schema();
        assert_same(true, WP_FTS_Plugin::storage(false)->verify_schema()['valid'] ?? null, 'dedicated maintenance should rebuild a type-incompatible dictionary');
    } finally {
        $wpdb = $oldWpdb;
    }
});

