test_case('search takeover waits for a complete initial corpus and usable physical schema', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    unset(
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION],
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]
    );
    $fake->postRows = [
        wp_fts_test_backfill_post(41, 'post', 'publish', 'Initial Readiness One'),
        wp_fts_test_backfill_post(42, 'post', 'publish', 'Initial Readiness Two'),
    ];
    foreach ($fake->postRows as $post) {
        $GLOBALS['wp_fts_test_posts'][(int) $post->ID] = $post;
    }

    try {
        WP_FTS_Plugin::activate();
        $globalScopeKey = (string) (new ReflectionClass(WP_FTS_Plugin::class))->getConstant('GLOBAL_RECONCILIATION_SCOPE_KEY');
        $activationScopes = array_values(array_filter($fake->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'));
        assert_same(1, count($activationScopes), 'activation should install exactly one corpus reconciliation generation');
        assert_same('scope:' . hash('sha256', $globalScopeKey), $activationScopes[0]['job_key'] ?? null, 'activation should use the one canonical corpus scope identity');
        $pending = WP_FTS_Plugin::search_takeover_status();
        $statusScopes = array_values(array_filter($fake->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'));
        assert_same(1, count($statusScopes), 'the first takeover drift check must coalesce with activation instead of enqueueing a second corpus scan');
        assert_same(false, $pending['ready'] ?? null, 'activation should not make a partial index eligible for search takeover');
        assert_same('initial_index_pending', $pending['reason'] ?? null, 'activation should expose the initial corpus as pending');
        assert_same(false, $pending['physical_schema_checked'] ?? null, 'pending readiness should avoid a physical probe on each search request');

        $query = new WP_FTS_Test_Query(['s' => 'batchindexneedle', 'posts_per_page' => 10, 'post_type' => 'post']);
        assert_same([], WP_FTS_Plugin::replace_frontend_search_posts(null, $query), 'an FTS-owned search must fail closed while the initial index is pending instead of falling through to an unbounded LIKE query');
        $GLOBALS['wp_fts_test_is_admin'] = true;
        $GLOBALS['pagenow'] = 'edit.php';
        $adminQuery = new WP_FTS_Test_Query([
            's' => 'batchindexneedle',
            'posts_per_page' => 10,
            'post_type' => 'post',
            'post_status' => 'publish',
        ]);
        assert_same([], WP_FTS_Plugin::replace_admin_post_search_posts(null, $adminQuery), 'an FTS-owned wp-admin search must fail closed while the initial index is pending instead of falling through to an unbounded LIKE query');
        $GLOBALS['wp_fts_test_is_admin'] = false;
        unset($GLOBALS['pagenow']);

        $scope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        assert_same(0, $scope['indexed'] ?? null, 'the first bounded readiness pass should expand only one scope page');
        assert_same(2, $scope['backfill_scanned'] ?? null, 'one scope pass should inspect no more than its requested bound');
        assert_same(2, $scope['backfill_queued'] ?? null, 'one scope pass should queue exactly its bounded source page');

        $firstPostDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same(1, $firstPostDrain['indexed'] ?? null, 'the first post-only successor should process one bounded direct generation');
        assert_same(false, $firstPostDrain['scope_completed'] ?? null, 'the first direct generation should leave the exhausted scope ready');
        assert_same(true, $firstPostDrain['has_more'] ?? null, 'the first post drain should report both the deferred scope and remaining post generation');
        $partial = WP_FTS_Plugin::search_takeover_status();
        assert_same(false, $partial['ready'] ?? null, 'a partially indexed corpus must remain ineligible for takeover');

        $scopeCompletion = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same(0, $scopeCompletion['indexed'] ?? null, 'the reserved scope turn should not consume the remaining post generation');
        assert_same(true, $scopeCompletion['scope_completed'] ?? null, 'the reserved scope turn should durably acknowledge the exhausted corpus scope');
        assert_same(true, $scopeCompletion['has_more'] ?? null, 'scope completion should report the direct generation returned for its next turn');
        assert_same(false, WP_FTS_Plugin::search_takeover_status()['ready'] ?? null, 'scope completion alone must not make a partially indexed corpus eligible for takeover');

        $finalPostDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $afterFinalWrite = WP_FTS_Plugin::search_takeover_status();
        assert_same(1, $finalPostDrain['indexed'] ?? null, 'the next bounded readiness batch should index the final post');
        assert_same(false, $finalPostDrain['scope_completed'] ?? null, 'document work should not repeat the already acknowledged corpus scope');
        assert_same(true, $finalPostDrain['has_more'] ?? null, 'a full direct claim should conservatively report possible remaining work without an extra count query');
        assert_same(false, $afterFinalWrite['ready'] ?? null, 'ordinary document workers must not publish readiness without the dedicated maintenance verifier');

        $empty = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same(0, $empty['indexed'] ?? null, 'the completing empty pass should prove no corpus work remains without rewriting a document');
        assert_same(false, $empty['has_more'] ?? null, 'the completing empty pass should prove no corpus work remains');
        assert_same(false, $empty['scope_completed'] ?? null, 'the empty follow-up pass should not invent another scope acknowledgement');
        assert_same(0, count($fake->queue), 'the completing readiness pass should leave no unresolved work generations');
        assert_same(false, WP_FTS_Plugin::search_takeover_status()['ready'] ?? null, 'an empty ordinary batch still must not bypass physical maintenance verification');

        WP_FTS_Plugin::run_scheduled_schema_repair();
        $ready = WP_FTS_Plugin::search_takeover_status();
        assert_same('ready', $ready['reason'] ?? null, 'the completing readiness pass should publish the ready reason');
        assert_same(true, $ready['ready'] ?? null, 'maintenance should permit takeover only after proving a complete corpus and usable physical tables');
        assert_same('ready', $ready['initial_index_status'] ?? null, 'completion should persist explicit initial readiness state');
        assert_same(false, $ready['physical_schema_checked'] ?? null, 'ready takeover should not run physical schema probes on visitor requests');
        assert_same(false, $ready['physical_schema_usable'] ?? null, 'logical readiness should leave physical verification to maintenance and fail-closed query handling');

        $readyQuery = new WP_FTS_Test_Query(['s' => 'batchindexneedle', 'posts_per_page' => 10, 'post_type' => 'post']);
        $readyPosts = WP_FTS_Plugin::replace_frontend_search_posts(null, $readyQuery);
        assert_same([42, 41], array_map(static fn(object $post): int => (int) $post->ID, $readyPosts), 'FTS should take over only after readiness completes and use the stable descending-ID tie-break');

        $fake->failReadQueryPrefix = '/* wp_fts:plan */';
        WP_FTS_Plugin::reset_request_caches();
        $logicallyReady = WP_FTS_Plugin::search_takeover_status();
        $queueBeforeRuntimeFailure = $fake->queue;
        $corpusSchedulesBeforeRuntimeFailure = count(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::CRON_HOOK
        ));
        assert_same(true, $logicallyReady['ready'] ?? null, 'visitor readiness should remain option-only until a real search detects storage failure');
        $unusableQuery = new WP_FTS_Test_Query(['s' => 'batchindexneedle', 'posts_per_page' => 10, 'post_type' => 'post']);
        assert_same([], WP_FTS_Plugin::replace_frontend_search_posts(null, $unusableQuery), 'physical index failure should fail closed without handing the same query to core LIKE search');
        WP_FTS_Plugin::reset_request_caches();
        $unusable = WP_FTS_Plugin::search_takeover_status();
        assert_same(false, $unusable['ready'] ?? null, 'a failed search should mark the index unhealthy before the next takeover decision');
        assert_same('index_reconciling_or_unhealthy', $unusable['reason'] ?? null, 'a transient storage read should fail closed without discarding corpus readiness provenance');
        assert_same('ready', $unusable['initial_index_status'] ?? null, 'a transient read failure must not turn a verified corpus into pending rebuild work');
        assert_same($queueBeforeRuntimeFailure, $fake->queue, 'a transient read failure must not enqueue a corpus reconciliation');
        assert_same($corpusSchedulesBeforeRuntimeFailure, count(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::CRON_HOOK
        )), 'a transient read failure must not schedule the corpus worker');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]), 'a transient read failure should schedule only bounded maintenance verification');

        $fake->failReadQueryPrefix = null;
        WP_FTS_Plugin::run_scheduled_schema_repair();
        $afterVerification = WP_FTS_Plugin::search_takeover_status();
        assert_same(true, $afterVerification['ready'] ?? null, 'successful bounded schema/profile/work verification should clear only the transient search latch');
        assert_same('ready', $afterVerification['initial_index_status'] ?? null, 'maintenance should preserve the already verified corpus readiness');
        assert_same($queueBeforeRuntimeFailure, $fake->queue, 'successful transient verification should not manufacture corpus work');
        $afterVerificationQuery = new WP_FTS_Test_Query(['s' => 'batchindexneedle', 'posts_per_page' => 10, 'post_type' => 'post']);
        assert_same([42, 41], array_map(static fn(object $post): int => (int) $post->ID, WP_FTS_Plugin::replace_frontend_search_posts(null, $afterVerificationQuery)), 'verified transient recovery should resume FTS without rebuilding the corpus');
    } finally {
        $GLOBALS['wp_fts_test_is_admin'] = false;
        unset($GLOBALS['pagenow']);
        $wpdb = $oldWpdb;
    }
});

test_case('actual search recovers a missing capability after the finalizer crash window', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->options = 'wp_options';
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $expectedIncarnation = (string) $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION];
    $expectedProfile = wp_fts_test_default_index_profile_hash();
    // Model a process dying after the health CAS and before the final
    // capability write. The consumed one-shot event is deliberately absent.
    unset(
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION],
        $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]
    );
    WP_FTS_Plugin::reset_request_caches();

    try {
        $readOnly = WP_FTS_Plugin::search_takeover_status(false);
        $scheduledAfterReadOnly = $GLOBALS['wp_fts_test_scheduled'];
        $actual = WP_FTS_Plugin::search_takeover_status(true);
        $scheduledAfterSearch = $GLOBALS['wp_fts_test_scheduled'];
        WP_FTS_Plugin::run_scheduled_schema_repair();
        WP_FTS_Plugin::reset_request_caches();
        $recovered = WP_FTS_Plugin::search_takeover_status(false);
        $capability = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION] ?? null;
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(false, $readOnly['ready'] ?? null, 'missing publication must fail closed even when diagnostic health says ready');
    assert_same('search_ready_capability_missing', $readOnly['reason'] ?? null, 'read-only status should identify the missing final capability');
    assert_true(!isset($scheduledAfterReadOnly[WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]), 'read-only status must not create maintenance work');
    assert_same(false, $actual['ready'] ?? null, 'the recovering search must remain unavailable until maintenance republishes readiness');
    assert_true(isset($scheduledAfterSearch[WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]), 'an actual search should restore the consumed one-shot finalizer event');
    assert_same(true, $recovered['ready'] ?? null, 'the bounded maintenance verifier should recover takeover without another corpus sweep');
    assert_same([], wp_fts_test_queue_ids($fake), 'capability recovery must not manufacture document reconciliation work');
    assert_same([
        'incarnation' => $expectedIncarnation,
        'profile_hash' => $expectedProfile,
    ], $capability, 'an absent option row should be atomically recreated with the exact combined capability');
    $capabilityAdds = array_values(array_filter(
        $GLOBALS['wp_fts_test_added_options'],
        static fn(array $event): bool => ($event['name'] ?? '') === WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION
    ));
    assert_same(1, count($capabilityAdds), 'missing-row recovery should use one insert-if-absent publication');
    assert_same('yes', $capabilityAdds[0]['autoload'] ?? null, 'the tiny search-ready capability must join WordPress alloptions on cold requests');
});

/**
 * Run bounded manual phases until a fixture-specific durable terminal proof.
 *
 * @return array<int,array{summary:array<string,mixed>,statement_count:int}>
 */
function wp_fts_test_drain_manual_index_phases(
    object $wpdb,
    int $batchSize,
    callable $terminal,
    int $maxPhases = 8
): array {
    $runs = [];
    for ($phase = 0; $phase < $maxPhases; $phase++) {
        $before = is_array($wpdb->queries ?? null) ? count($wpdb->queries) : 0;
        $summary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => $batchSize]);
        $after = is_array($wpdb->queries ?? null) ? count($wpdb->queries) : $before;
        $runs[] = [
            'summary' => $summary,
            'statement_count' => max(0, $after - $before),
        ];
        if ($terminal()) {
            return $runs;
        }
    }

    throw new WP_FTS_TestFailure("Manual indexing did not reach its durable terminal condition within {$maxPhases} bounded phases.");
}

test_case('rejected initial content stays gated until maintenance', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $rejected = wp_fts_test_backfill_post(52, 'post', 'publish', 'Initial Failure');
    $rejected->post_content = str_repeat('x', WP_FTS_Analysis_Limits::MAX_SOURCE_BYTES + 1);
    $fake->postRows = [
        wp_fts_test_backfill_post(51, 'post', 'publish', 'Initial Good'),
        $rejected,
    ];

    try {
        WP_FTS_Plugin::activate();
        $runs = wp_fts_test_drain_manual_index_phases(
            $fake,
            2,
            static fn(): bool => count(array_filter(
                $fake->queue,
                static fn(array $row): bool => in_array($row['kind'] ?? '', ['post', 'scope'], true)
            )) === 0
        );
        $summaries = array_column($runs, 'summary');
        $scope = $summaries[0] ?? [];
        assert_same(2, $scope['backfill_queued'] ?? null, 'initial reconciliation should enqueue one bounded scope page');
        $failureRuns = array_values(array_filter(
            $summaries,
            static fn(array $summary): bool => (int) ($summary['last_batch_failures'] ?? 0) === 1
        ));
        $batch = $failureRuns[0] ?? [];
        assert_same(false, $batch['scope_completed'] ?? null, 'the initial document batch should leave the exhausted scope ready');
        assert_same(true, $batch['has_more'] ?? null, 'the initial document batch should request its scope-only successor');
        $scopeCompletionRuns = array_values(array_filter(
            $summaries,
            static fn(array $summary): bool => !empty($summary['scope_completed'])
        ));
        $scopeCompletion = $scopeCompletionRuns[0] ?? [];
        assert_same(true, $scopeCompletion['scope_completed'] ?? null, 'initial reconciliation should require a following scope-only empty keyset proof');
        assert_same(0, $scopeCompletion['indexed'] ?? null, 'the initial scope proof should not repeat either analyzed source');
        assert_same([], array_values(array_filter(
            $summaries,
            static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
        )), 'a fresh activation fixture must never consume a stale-takeover control phase');
        assert_true(max(array_column($runs, 'statement_count')) <= 20, 'every initial-index phase must stay inside the complete 20-statement ceiling');
        $status = WP_FTS_Plugin::search_takeover_status();
        assert_same(1, $batch['last_batch_failures'] ?? null, 'initial indexing should report a permanently rejected bounded source');
        assert_same(1, count($fake->docs), 'a poison source should not prevent a later bounded phase from indexing the valid document');
        assert_same(false, $status['ready'] ?? null, 'ordinary workers must not publish readiness after a partial corpus batch');
        assert_same('pending', $status['initial_index_status'] ?? null, 'the dedicated maintenance verifier should remain the only readiness publisher');

    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('explicit schema repair returns saved readiness to pending', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_mark_search_takeover_ready();
    assert_same(true, WP_FTS_Plugin::search_takeover_status()['ready'] ?? null, 'the pre-repair readiness cache should describe the intact schema');
    unset($fake->schemaColumns['wp_fts_documents'], $fake->schemaIndexes['wp_fts_documents']);

    try {
        assert_same('damaged', WP_FTS_Plugin::schema_status()['status'] ?? null, 'a missing table should make a previously ready schema damaged');

        WP_FTS_Plugin::repair_schema();
        $status = WP_FTS_Plugin::search_takeover_status();

        assert_same('current', $status['schema_status'] ?? null, 'runtime schema repair should restore the physical table contract');
        assert_same(false, $status['ready'] ?? null, 'runtime schema repair should not trust readiness recorded for the damaged index');
        assert_same('pending', $status['initial_index_status'] ?? null, 'runtime schema repair should require corpus verification before takeover resumes');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'runtime schema repair should schedule the pending corpus verification');
    } finally {
        $wpdb = $oldWpdb;
    }
});

