    }

    assert_same(null, $failure, 'the wp_initialize_site hook must not fail canonical site creation when optional FTS provisioning cannot switch');
    assert_same([], $fake->queries, 'new-site provisioning should not touch storage when switch_to_blog declines the switch');
    assert_same([], $GLOBALS['wp_fts_test_restore_log'], 'failed new-site switch should not restore an unmade switch');
    assert_true(!isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'failed new-site switch should not schedule queue work');
});

test_case('network activation chains bounded schema batches for existing subsites', function (): void {
    global $wpdb;
    wp_fts_test_install_multisite_switch_functions();

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_is_multisite'] = true;
    $GLOBALS['wp_fts_test_sites'] = range(1, 12);
    $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
    $GLOBALS['wp_fts_test_site_options'] = array_fill_keys(range(1, 12), [
        WP_FTS_Plugin::UNINSTALL_FENCE_OPTION => WP_FTS_Plugin::UNINSTALL_FENCE_VALUE,
    ]);
    $fake->docs[41] = [
        'lang' => 'en',
        'doc_len' => 2,
        'content_hash' => 'retained-before-network-reactivation',
        'is_deleted' => 0,
    ];

    try {
        WP_FTS_Plugin::activate(true);
        $schemaCalls = array_values(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK
        ));
        $networkActivationToken = (string) ($schemaCalls[0]['args'][1] ?? '');
        assert_true(strlen($networkActivationToken) === 32, 'network activation should persist one bounded capability for its schema chain');
        assert_same([[0, $networkActivationToken]], array_column($schemaCalls, 'args'), 'network activation should schedule only the first authorized bounded schema batch');
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][1][WP_FTS_Plugin::UNINSTALL_FENCE_OPTION]), 'network activation should clear the current site fence inside its activation lease');
        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_site_options'][1][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'network activation should provision the current site immediately');
        assert_same('pending', $GLOBALS['wp_fts_test_site_options'][1][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] ?? null, 'network activation should queue bounded corpus reconciliation on the current site');
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), 'network activation request should not synchronously mutate a subsite');
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::INDEX_HEALTH_OPTION]), 'network activation request should leave subsite reconciliation to the bounded schema job');

        WP_FTS_Plugin::handle_scheduled_site_schema(0, $networkActivationToken);
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), 'a schema callback that discovers the current site should not also provision a subsite');

        WP_FTS_Plugin::handle_scheduled_site_schema(1, $networkActivationToken);
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::UNINSTALL_FENCE_OPTION]), 'authorized network provisioning should clear the target site fence inside its lease');
        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'one bounded schema job should provision its target subsite');
        assert_same('pending', $GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] ?? null, 'one bounded schema job should queue corpus reconciliation for its target subsite');
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][3][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), 'one schema callback must not cross its one-site bound');
        assert_contains('CREATE TABLE wp_2_fts_documents', implode("\n", $fake->queries), 'subsite schema job should use the target site table prefix');

        $GLOBALS['wp_fts_test_sites'] = array_values(array_filter(
            $GLOBALS['wp_fts_test_sites'],
            static fn(int $siteId): bool => $siteId !== 2
        ));
        foreach (range(2, 12) as $afterSiteId) {
            WP_FTS_Plugin::handle_scheduled_site_schema($afterSiteId, $networkActivationToken);
        }
        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_site_options'][11][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'deleting an earlier site between batches should not skip the next site id');
        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_site_options'][12][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'the successor batch should finish the remaining sites');
        assert_same(11, count($GLOBALS['wp_fts_test_switch_log']), 'the chain should switch once for every non-current site');
        assert_same(array_fill(0, 11, 1), $GLOBALS['wp_fts_test_restore_log'], 'every subsite repair should restore the original site');
        foreach (range(1, 12) as $siteId) {
            assert_true(!isset($GLOBALS['wp_fts_test_site_options'][$siteId][WP_FTS_Plugin::UNINSTALL_FENCE_OPTION]), "network reactivation should clear the uninstall fence on site {$siteId}");
        }
        $schemaCalls = array_values(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK
        ));
        assert_same(array_map(
            static fn(int $cursor): array => [$cursor, $networkActivationToken],
            range(0, 12)
        ), array_column($schemaCalls, 'args'), 'each non-empty one-site page should schedule exactly one keyset successor');
        $siteQueries = array_values(array_filter(
            $fake->prepared,
            static fn(array $query): bool => str_starts_with($query['sql'] ?? '', 'SELECT blog_id FROM `wp_blogs`')
        ));
        assert_same(array_fill(0, 13, 1), array_map(
            static fn(array $query): int => (int) ($query['args'][count($query['args']) - 1] ?? 0),
            $siteQueries
        ), 'each schema callback should query at most one site with a stable keyset cursor');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('preloaded network activation job cannot cross a later multisite uninstall fence', function (): void {
    global $wpdb;
    wp_fts_test_install_multisite_switch_functions();

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_is_multisite'] = true;
    $GLOBALS['wp_fts_test_sites'] = [1, 2];
    $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
    $GLOBALS['wp_fts_test_site_options'] = array_fill_keys([1, 2], [
        WP_FTS_Plugin::UNINSTALL_FENCE_OPTION => WP_FTS_Plugin::UNINSTALL_FENCE_VALUE,
    ]);

    try {
        WP_FTS_Plugin::activate(true);
        $schemaCalls = array_values(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK
        ));
        $staleToken = (string) ($schemaCalls[0]['args'][1] ?? '');
        assert_true(strlen($staleToken) === 32, 'fixture should preload one authorized network schema event');

        $networkTokenDeletes = 0;
        $GLOBALS['wp_fts_test_after_delete_site_option'] = static function (string $name) use (&$networkTokenDeletes, $staleToken): void {
            if ($name !== 'wp_fts_network_activation_token') {
                return;
            }
            $networkTokenDeletes++;
            if ($networkTokenDeletes === 1) {
                // Deterministically model an activation request that began
                // before uninstall's early revocation and publishes late.
                $GLOBALS['wp_fts_test_network_options'][$name] = $staleToken;
            }
        };

        WP_FTS_Plugin::uninstall();
        $optionsAfterUninstall = $GLOBALS['wp_fts_test_site_options'];
        foreach ([1, 2] as $siteId) {
            wp_fts_test_assert_uninstall_fence($optionsAfterUninstall[$siteId] ?? [], "network stale-event site {$siteId}");
        }
        assert_same(2, $networkTokenDeletes, 'completed uninstall should revoke the network token both before discovery and after every site boundary');
        assert_true(!isset($GLOBALS['wp_fts_test_network_options']['wp_fts_network_activation_token']), 'uninstall should revoke the preloaded network activation capability before site cleanup');

        $fake->queries = [];
        $fake->prepared = [];
        $GLOBALS['wp_fts_test_switch_log'] = [];
        $GLOBALS['wp_fts_test_restore_log'] = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];
        $GLOBALS['wp_fts_test_schedule_calls'] = [];
        $GLOBALS['wp_fts_test_scheduled'] = [];
        $GLOBALS['wp_fts_test_get_sites_calls'] = [];

        WP_FTS_Plugin::handle_scheduled_site_schema(0, $staleToken);

        assert_same([], $GLOBALS['wp_fts_test_switch_log'], 'revoked network job should not switch to or inspect any site');
        assert_same([], $GLOBALS['wp_fts_test_get_sites_calls'], 'revoked network job should not enumerate any site');
        assert_same([], $fake->queries, 'revoked network job should execute zero SQL');
        assert_same([], $fake->prepared, 'revoked network job should prepare zero SQL');
        assert_same([], $GLOBALS['wp_fts_test_added_options'], 'revoked network job should add no lock or lifecycle option');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'revoked network job should update no lifecycle option');
        assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'revoked network job should delete no lifecycle option');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'revoked network job should schedule no successor');
        assert_same($optionsAfterUninstall, $GLOBALS['wp_fts_test_site_options'], 'revoked network job should leave every uninstall fence unchanged');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('network lifecycle lease orders cross-site activation behind uninstall', function (): void {
    global $wpdb;
    wp_fts_test_install_multisite_switch_functions();

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_is_multisite'] = true;
    $GLOBALS['wp_fts_test_sites'] = [1, 2];
    $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();
    $GLOBALS['wp_fts_test_site_options'] = [
        1 => wp_fts_test_uninstall_seeded_options($operationalOptions, 1),
        2 => wp_fts_test_uninstall_seeded_options($operationalOptions, 2),
    ];
    $lateActivationError = null;
    $lateActivationQueryCount = null;
    $lateActivationQueries = [];
    $lateActivationPrepared = [];
    $lateActivationEffects = [];

    try {
        $GLOBALS['wp_fts_test_before_delete_option'] = static function () use (
            $fake,
            &$lateActivationError,
            &$lateActivationQueryCount,
            &$lateActivationQueries,
            &$lateActivationPrepared,
            &$lateActivationEffects
        ): void {
            $before = count($fake->queries);
            $preparedBefore = count($fake->prepared);
            $scheduledBefore = count($GLOBALS['wp_fts_test_schedule_calls']);
            $networkOptionsBefore = $GLOBALS['wp_fts_test_network_options'];
            $lifecycleProperty = (new ReflectionClass(WP_FTS_Plugin::class))
                ->getProperty('active_network_lifecycle_lock');
            $uninstallOwner = $lifecycleProperty->getValue();
            // Model another PHP request: it shares only the durable option row,
            // not uninstall's request-local ownership capability.
            $lifecycleProperty->setValue(null, null);
            switch_to_blog(2);
            try {
                WP_FTS_Plugin::activate(true);
            } catch (Throwable $error) {
                $lateActivationError = $error;
            } finally {
                restore_current_blog();
                $lifecycleProperty->setValue(null, $uninstallOwner);
            }
            $lateActivationQueryCount = count($fake->queries) - $before;
            $lateActivationQueries = array_map(
                static fn(mixed $query): string => is_array($query)
                    ? (string) ($query[0] ?? '')
                    : (string) $query,
                array_slice($fake->queries, $before)
            );
            $lateActivationPrepared = array_slice($fake->prepared, $preparedBefore);
            $lateActivationEffects = [
                'scheduled' => count($GLOBALS['wp_fts_test_schedule_calls']) - $scheduledBefore,
                'network_options_changed' => $networkOptionsBefore !== $GLOBALS['wp_fts_test_network_options'],
            ];
        };

        WP_FTS_Plugin::uninstall();
        $optionsAfter = $GLOBALS['wp_fts_test_site_options'];
        $networkOptionsAfter = $GLOBALS['wp_fts_test_network_options'];
        $lifecycleRowsAfter = $GLOBALS['wp_fts_test_network_lifecycle_rows'];
        $schemaSchedules = array_values(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK
        ));
    } finally {
        unset($GLOBALS['wp_fts_test_before_delete_option']);
        $wpdb = $oldWpdb;
    }

    assert_true($lateActivationError instanceof RuntimeException, 'activation on another site must fail before crossing an active network uninstall');
    assert_same(2, $lateActivationQueryCount, 'an independent contender should use one atomic insert attempt and one indexed owner read');
    assert_same(
        [
            'INSERT IGNORE INTO wp_options (option_name,option_value,autoload) VALUES (%s,%s,%s)',
            'SELECT option_value FROM wp_options WHERE option_name = %s LIMIT 1',
        ],
        $lateActivationQueries,
        'the independent contender must use only the atomic insert and primary option-name lookup'
    );
    assert_same(
        ['wp_fts_network_lifecycle_lock', 'wp_fts_network_lifecycle_lock'],
        array_map(
            static fn(array $prepared): string => (string) ($prepared['args'][0] ?? ''),
            $lateActivationPrepared
        ),
        'both independent-request statements must address only the durable lifecycle row'
    );
    assert_same(['scheduled' => 0, 'network_options_changed' => false], $lateActivationEffects, 'rejected activation must publish no token or schedule side effect');
    assert_same([], $schemaSchedules, 'rejected activation must not publish a network schema chain');
    assert_true(!isset($networkOptionsAfter['wp_fts_network_activation_token']), 'completed uninstall must leave no resurrected network activation token');
    assert_same([], $lifecycleRowsAfter, 'successful uninstall should exact-delete its network lifecycle lease');
    foreach ([1, 2] as $siteId) {
        wp_fts_test_assert_uninstall_fence($optionsAfter[$siteId] ?? [], "cross-site lifecycle site {$siteId}");
        assert_true(!isset($optionsAfter[$siteId][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), "cross-site lifecycle site {$siteId} must remain uninstalled");
    }
});

test_case('expired network lifecycle owner is replaced by one bounded activation', function (): void {
    global $wpdb;
    wp_fts_test_install_multisite_switch_functions();

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_is_multisite'] = true;
    $GLOBALS['wp_fts_test_sites'] = [1];
    $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
    $GLOBALS['wp_fts_test_site_options'][1] = [
        WP_FTS_Plugin::UNINSTALL_FENCE_OPTION => WP_FTS_Plugin::UNINSTALL_FENCE_VALUE,
    ];
    $GLOBALS['wp_fts_test_network_lifecycle_rows']['wp_fts_network_lifecycle_lock'] = maybe_serialize([
        'token' => str_repeat('e', 32),
        'mode' => 'crashed-uninstall',
        'started_at' => time() - 600,
        'heartbeat_at' => time() - 600,
        'expires_at' => time() - 1,
        'renewals' => 0,
    ]);

    try {
        WP_FTS_Plugin::activate(false);
        $schemaVersion = $GLOBALS['wp_fts_test_site_options'][1][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null;
        $lifecycleRowsAfter = $GLOBALS['wp_fts_test_network_lifecycle_rows'];
        $lifecycleSql = array_values(array_filter(
            $fake->queries,
            static fn(string $sql): bool => str_contains($sql, 'wp_options')
                && str_contains($sql, 'option_')
        ));
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $schemaVersion, 'an expired network owner must not strand explicit activation');
    assert_same([], $lifecycleRowsAfter, 'replacement activation should release its exact successor lease');
    assert_true(count($lifecycleSql) <= 7, 'expired-owner replacement must remain a bounded handful of indexed option-row statements');
});

test_case('failed network schema provisioning retries the same bounded keyset page', function (): void {
    global $wpdb;
    wp_fts_test_install_multisite_switch_functions();

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_is_multisite'] = true;
    $GLOBALS['wp_fts_test_sites'] = [1, 2, 3];
    $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
    $GLOBALS['wp_fts_test_site_options'] = array_fill_keys([1, 2, 3], []);
    $fake->failQueryPrefix = 'CREATE TABLE wp_2_fts_terms';

    try {
        $failure = null;
        try {
            WP_FTS_Plugin::handle_scheduled_site_schema(1);
        } catch (RuntimeException $caught) {
            $failure = $caught;
        }

        assert_true($failure instanceof RuntimeException, 'one failed site should fail the bounded schema job visibly');
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), 'the failed site must remain unacknowledged');
        assert_true(!isset($GLOBALS['wp_fts_test_site_options'][3][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), 'a failed one-site event must not touch its successor');
        $schemaCalls = array_values(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK
        ));
        assert_same([[1]], array_column($schemaCalls, 'args'), 'a failed one-site event must retry the original cursor instead of advancing past the failed site');

        $fake->failQueryPrefix = null;
        unset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK]);
        $GLOBALS['wp_fts_test_schedule_calls'] = [];
        WP_FTS_Plugin::handle_scheduled_site_schema(1);

        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'replaying the same event should provision the formerly failed site');
        $retryCalls = array_values(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::SCHEMA_SITE_CRON_HOOK
        ));
        assert_same([[2]], array_column($retryCalls, 'args'), 'only a successful replay may advance to the one-site high-water mark');
        assert_same(1, get_current_blog_id(), 'failed and replayed schema work should always restore the original site');
    } finally {
        $wpdb = $oldWpdb;
    }
});

