test_case('v6 component hashes and plugin profiles share one index behavior signature', function (): void {
    $componentConstant = (new ReflectionClass(WP_FTS_Indexer::class))
        ->getReflectionConstant('INDEX_SIGNATURE_VERSION');
    $pluginConstant = (new ReflectionClass(WP_FTS_Plugin::class))
        ->getReflectionConstant('INDEX_PROFILE_INDEXER_SIGNATURE');

    assert_true($componentConstant instanceof ReflectionClassConstant, 'the component index signature must remain an explicit content-hash input');
    assert_true($pluginConstant instanceof ReflectionClassConstant, 'the plugin index signature must remain an explicit accepted-profile input');
    assert_same('wp-fts-indexer-v6', $componentConstant->getValue(), 'v6 surface-indexed documents must not reuse the prior relational content-hash signature');
    assert_same($componentConstant->getValue(), $pluginConstant->getValue(), 'component content hashes and plugin profile drift must advance in lockstep');
});

test_case('runtime index profile drift enqueues one durable reconciliation scope before acceptance', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $wpdb = new WP_FTS_Test_WPDB();
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = [
        'initial_index_status' => 'pending',
        'index_profile_hash' => '',
        'accepted_index_profile_hash' => '',
    ];

    try {
        WP_FTS_Plugin::detect_index_profile_drift();
        $initial = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
        $initialHash = (string) ($initial['index_profile_hash'] ?? '');
        assert_true(preg_match('/^[a-f0-9]{40}$/', $initialHash) === 1, 'a fresh empty index should bind its corpus scope to the initial runtime profile');
        assert_same('', $initial['accepted_index_profile_hash'] ?? '', 'a pending corpus must not accept its profile before maintenance publication');

        $initial['accepted_index_profile_hash'] = str_repeat('0', 40);
        $initial['index_profile_hash'] = str_repeat('0', 40);
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = $initial;

        WP_FTS_Plugin::detect_index_profile_drift();
        $drifted = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
        assert_same('reconciling', $drifted['status'] ?? null, 'a runtime profile different from the accepted index should enter durable reconciliation');
        assert_same('pending', $drifted['initial_index_status'] ?? null, 'profile reconciliation should make search takeover unavailable immediately');
        assert_same(1, count(array_filter($wpdb->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope')), 'runtime drift should coalesce into one durable scope generation');
        assert_same(str_repeat('0', 40), $drifted['accepted_index_profile_hash'] ?? null, 'drift detection must not accept the new profile before reindexing');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'runtime drift should schedule the durable reconciliation worker');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('first search takeover detects analyzer drift without polling ordinary pages', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $profileMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'current_index_profile');
    $profileMethod->setAccessible(true);
    $baseline = $profileMethod->invoke(null);
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = [
        'status' => 'ready',
        'initial_index_status' => 'ready',
        'initial_index_started_at' => '2026-07-17 00:00:00',
        'initial_index_completed_at' => '2026-07-17 00:01:00',
        'index_profile_hash' => $baseline['hash'],
        'accepted_index_profile_hash' => $baseline['hash'],
    ];
    WP_FTS_Plugin::reset_request_caches();
    $filterCalls = 0;
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::ANALYZER_OPTIONS_FILTER] = static function (array $options) use (&$filterCalls): array {
        $filterCalls++;
        $options['lemma_packs_by_lang']['pl'] = WP_FTS_AnalyzerPackValidator::default_polish_fixture_manifest();

        return $options;
    };

    try {
        $first = WP_FTS_Plugin::search_takeover_status();
        $second = WP_FTS_Plugin::search_takeover_status();
        $health = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
        $scopeRows = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ));
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(false, $first['ready'] ?? null, 'the first real search boundary should fail closed on analyzer drift');
    assert_same('initial_index_pending', $first['reason'] ?? null, 'demand-driven drift detection should enter the normal reconciliation readiness state');
    assert_same($first, $second, 'later readiness reads in the request should reuse the fail-closed takeover result');
    assert_same(1, $filterCalls, 'search drift detection and the cached takeover result should construct one analyzer total');
    assert_same(1, count($scopeRows), 'the first search should enqueue one coalesced global profile reconciliation');
    assert_same($baseline['hash'], $health['accepted_index_profile_hash'] ?? null, 'search-time detection must not accept the changed profile before its sweep');
});

test_case('configured custom-field selection is part of the accepted index profile', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(731, 'post', 'publish', 'Custom field profile host');
    $post->custom_fields = ['subtitle' => 'ProfileSelectedMetadataSignal'];
    $fake->postRows = [$post];
    $GLOBALS['wp_fts_test_posts'][731] = $post;
    $profileMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'current_index_profile');
    $profileMethod->setAccessible(true);

    try {
        $oldProfile = $profileMethod->invoke(null);
        wp_fts_test_replace_post(
            wp_fts_test_unleased_storage(),
            $post,
            ['lang' => 'en', 'custom_fields' => []],
            WP_FTS_Plugin::runtime_analyzer()
        );
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = [
            'status' => 'ready',
            'initial_index_status' => 'ready',
            'initial_index_started_at' => '2026-07-17 00:00:00',
            'initial_index_completed_at' => '2026-07-17 00:01:00',
            'reconciliation_scope_completed_at' => '2026-07-17 00:01:00',
            'reconciliation_scope_completed_incarnation' => '0123456789abcdef0123456789abcdef',
            'reconciliation_scope_completed_profile_hash' => $oldProfile['hash'],
            'index_profile_hash' => $oldProfile['hash'],
            'accepted_index_profile_hash' => $oldProfile['hash'],
        ];
        WP_FTS_Plugin::reset_request_caches();
        assert_same([], WP_FTS_Plugin::search('ProfileSelectedMetadataSignal', ['limit' => 10]), 'setup should exclude the not-yet-configured custom field');

        $GLOBALS['wp_fts_test_options'][WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION] = ['subtitle'];
        $newProfile = $profileMethod->invoke(null);
        WP_FTS_Plugin::detect_index_profile_drift();
        $drifted = WP_FTS_Plugin::search_health();
        $scopeRows = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ));

        for ($pass = 0; $pass < 6 && $fake->queue !== []; $pass++) {
            WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        }
        WP_FTS_Plugin::run_scheduled_schema_repair();
        $accepted = WP_FTS_Plugin::search_health();
        $results = WP_FTS_Plugin::search('ProfileSelectedMetadataSignal', ['limit' => 10]);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_true(($oldProfile['hash'] ?? '') !== ($newProfile['hash'] ?? ''), 'changing configured custom-field keys should change the deterministic index profile');
    assert_same('pending', $drifted['initial_index_status'] ?? null, 'custom-field profile drift should disable takeover before stale content can be served');
    assert_same(1, count($scopeRows), 'custom-field profile drift should enqueue one global index-profile scope');
    assert_same('index_profile_changed', json_decode((string) ($scopeRows[0]['payload'] ?? ''), true)['reason'] ?? null, 'the custom-field sweep should use the durable index-profile scope');
    assert_same($newProfile['hash'] ?? null, $accepted['accepted_index_profile_hash'] ?? null, 'maintenance should accept the new custom-field profile only after the corpus sweep drains');
    assert_same([731], array_column($results, 'doc_id'), 'the completed profile sweep should make newly selected metadata searchable');
});

test_case('operator status ranking tuning remains read only', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $fake->postRows = [
        wp_fts_test_backfill_post(721, 'post', 'publish', 'Ranking Status Indexed'),
        wp_fts_test_backfill_post(722, 'post', 'publish', 'Ranking Status Queued'),
    ];
    $fake->docs[721] = [
        'lang' => 'en',
        'doc_len' => 3,
        'content_hash' => 'ranking-status-hash',
        'is_deleted' => 0,
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    wp_fts_test_seed_queue($fake, [722]);
    $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK] = [
        'timestamp' => time() + 120,
        'hook' => WP_FTS_Plugin::CRON_HOOK,
    ];
    $optionsBefore = $GLOBALS['wp_fts_test_options'];
    $scheduledBefore = $GLOBALS['wp_fts_test_scheduled'];
    $postRowsBefore = $fake->postRows;
    $docsBefore = $fake->docs;

    try {
        $status = WP_FTS_Plugin::operator_status();
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_true(is_array($status['ranking_tuning'] ?? null), 'read-only status should still expose ranking tuning block');
    assert_same([WP_FTS_Plugin::CRON_HOOK], $GLOBALS['wp_fts_test_next_scheduled_calls'], 'ranking tuning status should only inspect the existing cron schedule through operator status');
    assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'ranking tuning status should not schedule queue processors');
    assert_same([], $GLOBALS['wp_fts_test_cleared_hooks'], 'ranking tuning status should not clear scheduled queue processors');
    assert_same([], $GLOBALS['wp_fts_test_added_options'], 'ranking tuning status should not add plugin options');
    assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'ranking tuning status should not update plugin options');
    assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'ranking tuning status should not delete plugin options');
    assert_same($optionsBefore, $GLOBALS['wp_fts_test_options'], 'ranking tuning status should leave settings, queue, and health options unchanged');
    assert_same($scheduledBefore, $GLOBALS['wp_fts_test_scheduled'], 'ranking tuning status should leave scheduled cron state unchanged');
    assert_same($postRowsBefore, $fake->postRows, 'ranking tuning status should not mutate source post rows');
    assert_same($docsBefore, $fake->docs, 'ranking tuning status should not index or mutate documents');
    assert_same([], $fake->ftsTerms, 'ranking tuning status should not write FTS terms');
    assert_same([], $fake->queries, 'ranking tuning status should not run schema repair or storage writes');
    assert_same([722], wp_fts_test_queue_ids($fake), 'ranking tuning status should not drain queued content');
});

test_case('wp-cli status reports lifecycle state without mutating index data', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $now = time();
    $fake->postRows = [
        wp_fts_test_backfill_post(701, 'post', 'publish', 'CLI Status Indexed'),
        wp_fts_test_backfill_post(702, 'post', 'publish', 'CLI Status Queued'),
    ];
    $fake->docs[701] = [
        'lang' => 'en',
        'doc_len' => 3,
        'content_hash' => 'status-hash',
        'is_deleted' => 0,
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        [
            'replace_frontend_search' => false,
            'replace_admin_post_search' => true,
            'search_provider_compatibility' => 'respect_existing',
        ]
    );
    $GLOBALS['wp_fts_test_options']['active_plugins'] = [
        'jetpack/jetpack.php',
        'searchwp/index.php',
        'private-search-provider/secret-basename.php',
    ];
    $GLOBALS['wp_fts_test_options']['jetpack_active_modules'] = [
        'search',
        'raw-provider-payload-must-not-render',
    ];
    wp_fts_test_seed_queue($fake, [702]);
    $scheduledAt = $now + 120;
    $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK] = [
        'timestamp' => $scheduledAt,
        'hook' => WP_FTS_Plugin::CRON_HOOK,
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = [
        'token' => 'do-not-expose',
        'mode' => 'manual',
        'started_at' => $now - 10,
        'expires_at' => $now + 290,
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = [
        'last_batch_indexed' => 4,
        'last_batch_queue_processed' => 1,
        'last_batch_backfill_processed' => 3,
        'has_more' => false,
        'last_indexed_post_id' => 701,
        'last_indexed_post_title' => 'CLI Status Indexed',
        'last_indexed_at' => '2026-06-19 10:00:00',
        'last_skipped_locked' => false,
        'last_stopped_by_budget' => false,
        'last_mode' => 'manual',
        'last_run_at' => '2026-06-19 10:01:00',
        'last_batch_failures' => 2,
        'last_failed_post_id' => 703,
        'last_failed_post_title' => 'CLI <b>Status</b> Failed',
        'last_failed_at' => '2026-06-19 10:02:00',
        'last_error' => "RuntimeException: Failed to put FTS document: SELECT * FROM wp_users\n#0 stack trace",
        'accepted_index_profile_hash' => str_repeat('b', 40),
        'latest_batch_diagnostics' => [
            'schema' => 'wp-fts-index-batch-diagnostics-v1',
            'trigger' => 'manual',
            'source' => 'wp-cli',
            'status' => 'partial_failure',
            'started_at' => '2026-06-19 10:00:00',
            'finished_at' => '2026-06-19 10:01:00',
            'elapsed_ms' => 12.5,
            'batch_limit' => 5,
            'indexed' => 4,
            'queue_processed' => 1,
            'backfill_processed' => 3,
            'queue_before' => 2,
            'queue_after' => 1,
            'backfill_scanned' => 4,
            'backfill_queued' => 3,
            'failures' => 2,
            'error_class' => 'RuntimeException',
            'error_message' => "Failed to put FTS document: SELECT * FROM wp_users\n#0 stack trace",
            'last_failed_post_id' => 703,
            'last_failed_post_title' => 'CLI <b>Status</b> Failed',
            'last_failed_at' => '2026-06-19 10:02:00',
            'reschedule_decision' => 'not_applicable_manual',
            'stop_reason' => 'batch_cap',
            'lock_at_start' => ['state' => 'none', 'active' => false, 'mode' => '', 'started_at' => '', 'expires_at' => ''],
            'lock_at_end' => ['state' => 'none', 'active' => false, 'mode' => '', 'started_at' => '', 'expires_at' => ''],
            'schema_status' => 'current',
            'schema_version' => WP_FTS_Plugin::SCHEMA_VERSION,
            'expected_schema_version' => WP_FTS_Plugin::SCHEMA_VERSION,
            'storage_backend' => 'mysql',
        ],
    ];
    $optionsBeforeStatus = $GLOBALS['wp_fts_test_options'];
    $postRowsBeforeStatus = $fake->postRows;
    $docsBeforeStatus = $fake->docs;

    try {
        $command = new WP_FTS_WPCLI_Command();
        $human = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->status([], []);
        });
        $fake->recordReadQueries = true;
        $fake->queries = [];
        $fake->prepared = [];
        $raw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->status([], ['format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_contains("field\tvalue", $human, 'default status output should be a human-readable field list');
    assert_contains("pending_queue_count\t1", $human, 'default status output should include queue count');
    assert_contains("last_batch_failures\t2", $human, 'default status output should include failure count');
    assert_contains("reconciliation_active\tyes", $human, 'default status output should include derived reconciliation state');
    assert_same('current', $payload['schema_status'] ?? null, 'status JSON should report current schema status');
    assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $payload['schema_version'] ?? null, 'status JSON should report stored schema version');
    assert_same('mysql', $payload['storage_backend'] ?? null, 'status JSON should report storage backend');
    assert_true(is_string($payload['index_profile_hash'] ?? null) && preg_match('/^[a-f0-9]{40}$/', $payload['index_profile_hash']) === 1, 'status JSON should expose the current index profile hash');
    assert_same(str_repeat('b', 40), $payload['accepted_index_profile_hash'] ?? null, 'status JSON should expose the last accepted index profile hash');
    assert_same(true, $payload['reconciliation_active'] ?? null, 'status JSON should derive active reconciliation from lifecycle and durable work');
    assert_same(true, $payload['profile_reconciliation_pending'] ?? null, 'status JSON should expose the current-versus-accepted profile mismatch');
    assert_same(1, $payload['pending_queue_count'] ?? null, 'status JSON should report pending queue count');
    assert_same(1, $payload['pending_post_work_count'] ?? null, 'status JSON should report durable post generations');
    assert_same(0, $payload['pending_scope_work_count'] ?? null, 'status JSON should report the absence of scope work');
    assert_same(0, $payload['reconciliation_cursor_post_id'] ?? null, 'status JSON should report the durable scope cursor only');
    $schedule = $payload['queue_processor_schedule'] ?? null;
    assert_true(is_array($schedule), 'status JSON should expose queue processor schedule as a bounded object');
    assert_same(WP_FTS_Plugin::CRON_HOOK, $schedule['hook'] ?? null, 'status JSON should expose the queue processor cron hook');
    assert_same(true, $schedule['scheduled'] ?? null, 'status JSON should report the scheduled queue processor event');
    assert_same('scheduled', $schedule['status'] ?? null, 'status JSON should classify an existing event as scheduled');
    assert_same(gmdate('Y-m-d\TH:i:s\Z', $scheduledAt), $schedule['next_run_at'] ?? null, 'status JSON should expose the next queue run as a bounded UTC timestamp');
    assert_true(is_int($schedule['next_run_delay_seconds'] ?? null), 'status JSON should expose a numeric next-run delay when scheduled');
    assert_true(($schedule['next_run_delay_seconds'] ?? -1) >= 0 && ($schedule['next_run_delay_seconds'] ?? 999) <= 120, 'status JSON should bound next-run delay to a nonnegative value');
    assert_same(true, $schedule['pending_work'] ?? null, 'status JSON should keep pending-work context with schedule state');
    $runner = $payload['cron_runner'] ?? null;
    assert_true(is_array($runner), 'status JSON should expose cron runner diagnostics as a bounded object');
    assert_same('traffic_triggered', $runner['status'] ?? null, 'status JSON should report traffic-triggered cron when DISABLE_WP_CRON is not set');
    assert_same(false, $runner['wp_cron_disabled'] ?? null, 'status JSON should expose the DISABLE_WP_CRON state');
    assert_same(false, $runner['alternate_wp_cron'] ?? null, 'status JSON should expose the ALTERNATE_WP_CRON state');
    assert_same(true, $runner['pending_work'] ?? null, 'cron runner diagnostics should reuse pending-work context');
    assert_contains('traffic-triggered', (string) ($runner['advice'] ?? ''), 'cron runner advice should explain traffic-triggered cron mode');
    $ranking = $payload['ranking_tuning'] ?? null;
    assert_true(is_array($ranking), 'status JSON should preserve the nested ranking tuning block');
    assert_same('wp-fts-ranking-tuning-v1', $ranking['schema'] ?? null, 'status JSON ranking tuning should expose schema');
    assert_same('OR', $ranking['match_mode'] ?? null, 'status JSON ranking tuning should expose effective match mode');
    assert_same('respect_existing', $ranking['search_provider_compatibility'] ?? null, 'status JSON ranking tuning should expose provider compatibility mode');
    assert_same(false, $ranking['frontend_replacement_enabled'] ?? null, 'status JSON ranking tuning should expose frontend replacement state');
    assert_same(true, $ranking['admin_posts_replacement_enabled'] ?? null, 'status JSON ranking tuning should expose admin Posts replacement state');
    assert_same(true, $ranking['reconciliation_active'] ?? null, 'status JSON ranking tuning should expose durable reconciliation state');
    assert_same(true, $ranking['profile_reconciliation_pending'] ?? null, 'status JSON ranking tuning should expose profile reconciliation state');
    assert_contains('Durable index reconciliation is active', (string) ($ranking['advice'] ?? ''), 'status JSON ranking tuning should expose reconciliation advice');
    $compatibility = $payload['search_provider_compatibility'] ?? null;
    assert_true(is_array($compatibility), 'status JSON should expose search provider compatibility as a bounded object');
    assert_same('respect_existing', $compatibility['mode'] ?? null, 'status JSON should expose the effective provider compatibility mode');
    assert_same('Keep provider-integrated searches on WordPress', $compatibility['mode_label'] ?? null, 'status JSON should expose the human provider compatibility label');
    assert_same('respect_existing_provider', $compatibility['mode_debug_value'] ?? null, 'status JSON should expose the debug provider compatibility value');
    assert_same('disabled', $compatibility['public_site_replacement'] ?? null, 'status JSON should expose public-site replacement state');
    assert_same(false, $compatibility['public_site_replacement_enabled'] ?? null, 'status JSON should expose public-site replacement boolean');
    assert_same('enabled', $compatibility['admin_posts_replacement'] ?? null, 'status JSON should expose admin Posts replacement state');
    assert_same(true, $compatibility['admin_posts_replacement_enabled'] ?? null, 'status JSON should expose admin Posts replacement boolean');
    assert_same(2, $compatibility['known_provider_count'] ?? null, 'status JSON should expose detected known-provider count');
    assert_same(['Jetpack Search / Jetpack', 'SearchWP'], $compatibility['known_provider_names'] ?? null, 'status JSON should expose bounded known-provider family names');
    assert_same('Jetpack Search / Jetpack, SearchWP', $compatibility['known_provider_summary'] ?? null, 'status JSON should expose a known-provider summary without basenames');
    assert_contains('Keep provider-integrated searches on WordPress is appropriate', (string) ($compatibility['recommendation'] ?? ''), 'status JSON should expose mode-specific provider recommendation');
    assert_contains('not an end-to-end integration certification', (string) ($compatibility['detection_note'] ?? ''), 'status JSON should expose the advisory-only detection boundary');
    assert_contains('Jetpack Search / Jetpack, SearchWP', (string) ($compatibility['advisory'] ?? ''), 'status JSON should expose concise provider advisory text');
    $compatibilityJson = json_encode($compatibility, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
    assert_true(!str_contains($compatibilityJson, 'searchwp/index.php'), 'provider compatibility JSON should not expose raw plugin basenames');
    assert_true(!str_contains($compatibilityJson, 'secret-basename.php'), 'provider compatibility JSON should not expose unknown active plugin basenames');
    assert_true(!str_contains($compatibilityJson, 'raw-provider-payload-must-not-render'), 'provider compatibility JSON should not expose arbitrary provider option payloads');
    assert_same('active', $payload['lock_state'] ?? null, 'status JSON should report lock state without exposing the token');
    assert_same(true, $payload['lock_active'] ?? null, 'status JSON should report active lock boolean');
    assert_true(is_int($payload['lock_age_seconds'] ?? null), 'status JSON should expose bounded lock age');
    assert_true(($payload['lock_age_seconds'] ?? -1) >= 0 && ($payload['lock_age_seconds'] ?? 999) <= 30, 'status JSON should bound active lock age near the fixture age');
    assert_true(is_int($payload['lock_expires_in_seconds'] ?? null), 'status JSON should expose seconds until active lock expiry');
    assert_true(($payload['lock_expires_in_seconds'] ?? -1) >= 260 && ($payload['lock_expires_in_seconds'] ?? 999) <= 300, 'status JSON should bound active lock expiry timing near the fixture expiry');
    assert_same(null, $payload['lock_expired_seconds'] ?? null, 'status JSON should not report expired seconds for active locks');
    assert_contains('Another index writer is running', (string) ($payload['lock_advice'] ?? ''), 'status JSON should expose active lock advice');
    $lock = $payload['lock'] ?? null;
    assert_true(is_array($lock), 'status JSON should expose nested sanitized lock diagnostics');
    assert_same('active', $lock['state'] ?? null, 'nested lock diagnostics should include active state');
    assert_same('manual', $lock['mode'] ?? null, 'nested lock diagnostics should include sanitized lock mode');
    assert_true(is_int($lock['age_seconds'] ?? null), 'nested lock diagnostics should include bounded age');
    assert_true(is_int($lock['expires_in_seconds'] ?? null), 'nested lock diagnostics should include bounded active expiry timing');
    assert_true(!str_contains(json_encode($lock, JSON_THROW_ON_ERROR), 'do-not-expose'), 'nested lock diagnostics should not expose the token');
    assert_true(!array_key_exists('token', $payload), 'status JSON should not expose lock token');
    assert_same(true, $payload['has_more'] ?? null, 'status JSON should include has-more state from queued work');
    assert_same('manual', $payload['last_mode'] ?? null, 'status JSON should report last run mode');
    assert_same('2026-06-19 10:01:00', $payload['last_run_at'] ?? null, 'status JSON should report last run time');
    assert_same(4, $payload['last_batch_indexed'] ?? null, 'status JSON should report the last indexed batch count');
    assert_same(1, $payload['last_batch_queue_processed'] ?? null, 'status JSON should report last batch queue count');
    assert_same(3, $payload['last_batch_backfill_processed'] ?? null, 'status JSON should report last batch backfill count');
    assert_same(2, $payload['last_batch_failures'] ?? null, 'status JSON should report bounded failure count');
    assert_same('CLI Status Failed (ID 703)', $payload['last_failed_post'] ?? null, 'status JSON should report the last failed post label');
    assert_same(703, $payload['last_failed_post_id'] ?? null, 'status JSON should report the last failed post id');
    assert_same('CLI Status Failed', $payload['last_failed_post_title'] ?? null, 'status JSON should sanitize the last failed post title');
    assert_same('2026-06-19 10:02:00', $payload['last_failed_at'] ?? null, 'status JSON should report the last failure time');
    assert_contains('SELECT statement', (string) ($payload['last_error'] ?? ''), 'status JSON should retain a concise redacted failure error');
    assert_true(!str_contains((string) ($payload['last_error'] ?? ''), 'SELECT * FROM'), 'status JSON should not expose raw SQL in failure errors');
    assert_true(!str_contains((string) ($payload['last_error'] ?? ''), '#0'), 'status JSON should not expose stack traces in failure errors');
    assert_same('CLI Status Indexed (ID 701)', $payload['last_indexed_post'] ?? null, 'status JSON should report last indexed post label');
    assert_same(false, $payload['counts_exact'] ?? null, 'normal status JSON should label corpus totals as intentionally unscanned');
    assert_same(null, $payload['eligible_count'] ?? null, 'normal status JSON must not scan the eligible corpus');
    assert_same(null, $payload['indexed_count'] ?? null, 'normal status JSON must not count the entire index');
    assert_same(null, $payload['remaining_count'] ?? null, 'normal status JSON must not compute an exhaustive difference');
    assert_same('stored', $payload['schema_verification'] ?? null, 'normal status JSON should trust stored schema readiness');
    $statusSql = array_map(
        static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
        $fake->queries
    );
    $statusQueries = implode("\n", $statusSql);
    assert_same(1, count($fake->queries), 'normal current-schema status should issue one bounded durable-work statement');
    assert_true(!str_contains($statusQueries, 'SHOW TABLES'), 'normal status must not probe physical schema');
    assert_true(!str_contains($statusQueries, 'COUNT(DISTINCT'), 'normal status must not scan WordPress content for totals');
    $diagnostics = $payload['latest_batch_diagnostics'] ?? null;
    assert_true(is_array($diagnostics), 'status JSON should expose latest batch diagnostics as a bounded object');
    assert_same('manual', $diagnostics['trigger'] ?? null, 'status diagnostics should include latest batch trigger');
    assert_same('wp-cli', $diagnostics['source'] ?? null, 'status diagnostics should include latest batch source');
    assert_same('partial_failure', $diagnostics['status'] ?? null, 'status diagnostics should include latest batch status');
    assert_same(5, $diagnostics['batch_limit'] ?? null, 'status diagnostics should include batch limit');
    assert_same(4, $diagnostics['indexed'] ?? null, 'status diagnostics should include indexed count');
    assert_same(2, $diagnostics['queue_before'] ?? null, 'status diagnostics should include queue before count');
    assert_same(1, $diagnostics['queue_after'] ?? null, 'status diagnostics should include queue after count');
    assert_same(4, $diagnostics['backfill_scanned'] ?? null, 'status diagnostics should include backfill scanned count');
    assert_same(3, $diagnostics['backfill_queued'] ?? null, 'status diagnostics should include backfill selected count');
    assert_contains('SELECT statement', (string) ($diagnostics['error_message'] ?? ''), 'status diagnostics should retain redacted error context');
    assert_true(!str_contains(json_encode($diagnostics, JSON_THROW_ON_ERROR), 'SELECT * FROM'), 'status diagnostics should not expose raw SQL');
    assert_contains("queue_processor_schedule\t", $human, 'default status output should include queue processor schedule');
    assert_contains("cron_runner\t", $human, 'default status output should include cron runner diagnostics');
    assert_contains("search_provider_compatibility\t", $human, 'default status output should preserve the nested provider compatibility row');
    assert_contains("search_provider_compatibility_mode\trespect_existing", $human, 'default status output should expose provider compatibility mode');
    assert_contains("search_provider_compatibility_label\tKeep provider-integrated searches on WordPress", $human, 'default status output should expose provider compatibility label');
    assert_contains("search_provider_compatibility_public_site_replacement\tdisabled", $human, 'default status output should expose public-site replacement state');
    assert_contains("search_provider_compatibility_admin_posts_replacement\tenabled", $human, 'default status output should expose admin Posts replacement state');
    assert_contains("search_provider_compatibility_known_provider_count\t2", $human, 'default status output should expose known-provider count');
    assert_contains("search_provider_compatibility_known_provider_names\tJetpack Search / Jetpack, SearchWP", $human, 'default status output should expose bounded known-provider names');
    assert_contains("search_provider_compatibility_recommendation\tKeep provider-integrated searches on WordPress is appropriate", $human, 'default status output should expose provider compatibility recommendation');
    assert_true(!str_contains($human, 'searchwp/index.php'), 'default status output should not expose raw plugin basenames');
    assert_true(!str_contains($human, 'secret-basename.php'), 'default status output should not expose unknown active plugin basenames');
    assert_true(!str_contains($human, 'raw-provider-payload-must-not-render'), 'default status output should not expose arbitrary provider option payloads');
    assert_contains("lock_age_seconds\t", $human, 'default status output should include lock age');
    assert_contains("lock_advice\tAnother index writer is running", $human, 'default status output should include lock advice');
    assert_contains("lock\t", $human, 'default status output should include nested sanitized lock diagnostics');
    assert_same([WP_FTS_Plugin::CRON_HOOK, WP_FTS_Plugin::CRON_HOOK], $GLOBALS['wp_fts_test_next_scheduled_calls'], 'status should inspect the cron schedule without mutating it');
    assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'status should not schedule queue processors while rendering status');
    assert_same([], $GLOBALS['wp_fts_test_cleared_hooks'], 'status should not clear queue processor events while rendering status');
    assert_same([], $GLOBALS['wp_fts_test_added_options'], 'status should not add options while rendering provider compatibility status');
    assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'status should not update options while rendering provider compatibility status');
    assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'status should not delete options while rendering provider compatibility status');
    assert_same($optionsBeforeStatus, $GLOBALS['wp_fts_test_options'], 'status should leave settings, provider signals, queue, health, and lock options unchanged');
    assert_same($postRowsBeforeStatus, $fake->postRows, 'status should not mutate source post rows');
    assert_same($docsBeforeStatus, $fake->docs, 'status should not mutate index document rows');
    assert_same([], array_values(array_filter(
        $statusSql,
        static fn(string $sql): bool => !str_starts_with(ltrim($sql), 'SELECT ')
    )), 'status should not run schema repair or storage writes');
    assert_same([702], wp_fts_test_queue_ids($fake), 'status should leave queue state unchanged');
    assert_same('do-not-expose', $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]['token'] ?? null, 'status should leave lock state unchanged');
    assert_same(1, count($fake->docs), 'status should not index additional content');
});

test_case('operator status reports unsupported language pack fallback without mutating state', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_locale'] = 'qaa';
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION] = [
        'lemma_packs_by_lang' => [
            'qaa' => '/tmp/private/status-secret-manifest.json',
        ],
    ];
    $optionsBefore = $GLOBALS['wp_fts_test_options'];
    $docsBefore = $fake->docs;

    try {
        $status = WP_FTS_Plugin::operator_status();
    } finally {
        $wpdb = $oldWpdb;
    }

    $languagePack = $status['language_pack_status'] ?? null;
    assert_true(is_array($languagePack), 'operator status should expose language pack status as a bounded object');
    assert_same('qaa', $languagePack['site_language'] ?? null, 'language pack status should expose the current site language');
    assert_same('QAA (qaa)', $languagePack['site_language_label'] ?? null, 'language pack status should expose a human site-language label');
    assert_same('fallback', $languagePack['runtime_support_status'] ?? null, 'unsupported site language should report fallback runtime support');
    assert_same('Conservative fallback', $languagePack['runtime_support_label'] ?? null, 'unsupported site language should report the existing fallback support label');
    assert_contains('No active analyzer pack covers this language', (string) ($languagePack['runtime_support_reason'] ?? ''), 'unsupported site language should explain why fallback is used');
    assert_same('', $languagePack['matched_runtime_language'] ?? null, 'unsupported site language should not invent a matched runtime language');
    foreach (['language_fallback_enabled', 'fallback_languages', 'fallback_language_labels', 'fallback_summary'] as $legacyKey) {
        assert_true(!array_key_exists($legacyKey, $languagePack), "language pack status should not expose removed {$legacyKey} state");
    }
    assert_true(is_array($languagePack['unsupported_language_summaries'] ?? null), 'language pack status should include bounded fallback/license summaries');
    assert_true(count($languagePack['unsupported_language_summaries']) <= 8, 'language pack fallback/license summaries should stay bounded');
    assert_contains('Urdu (ur)', json_encode($languagePack['unsupported_language_summaries'], JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR), 'bounded language pack summaries should retain license-blocked language guidance');
    assert_contains('Configure an external pack, or accept conservative fallback', (string) ($languagePack['recommendation'] ?? ''), 'unsupported site language should guide operators without promising nonexistent controls');
    assert_true(!str_contains((string) ($languagePack['recommendation'] ?? ''), 'Enable the bundled pack'), 'unsupported site language should not promise a bundled-pack control');
    $encoded = json_encode($languagePack, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
    assert_true(!str_contains($encoded, '/tmp/private'), 'language pack status should not expose manifest paths');
    assert_true(!str_contains($encoded, 'status-secret-manifest'), 'language pack status should not expose unsafe path basenames from invalid options');
    assert_same($optionsBefore, $GLOBALS['wp_fts_test_options'], 'language pack status should not mutate analyzer pack options');
    assert_same($docsBefore, $fake->docs, 'language pack status should not index content');
    assert_same([], $fake->ftsTerms, 'language pack status should not write terms');
    assert_same([], $fake->queries, 'language pack status should not run schema repair or storage writes');
});

test_case('wp-cli status reports language pack base locale coverage through active runtime pack', function (): void {
    global $wpdb;

    if (!WP_FTS_AnalyzerPackValidator::gzip_available()) {
        assert_true(true, 'gzip is unavailable, so indexed runtime English pack status is skipped.');
        return;
    }

    $packDir = temp_directory_path('status_en_base_pack');

    try {
        $manifest = write_synthetic_full_analyzer_pack($packDir, 3, 1, 'en', 'en-synthetic-status-pack', true);
        $oldWpdb = $wpdb ?? null;
        $fake = new WP_FTS_Test_WPDB();
        $wpdb = $fake;
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_locale'] = 'en_US';
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION] = [
            'lemma_packs_by_lang' => [
                'en' => $manifest,
            ],
        ];
        $optionsBefore = $GLOBALS['wp_fts_test_options'];

        try {
            $command = new WP_FTS_WPCLI_Command();
            $human = wp_fts_test_capture_cli(static function () use ($command): void {
                $command->status([], []);
            });
            $raw = wp_fts_test_capture_cli(static function () use ($command): void {
                $command->status([], ['format' => 'json']);
            });
            $payload = wp_fts_test_decode_cli_json_object($raw);
        } finally {
            $wpdb = $oldWpdb;
        }

        $languagePack = $payload['language_pack_status'] ?? null;
        assert_true(is_array($languagePack), 'status JSON should preserve the nested language pack status block');
        assert_same('en-US', $languagePack['site_language'] ?? null, 'language pack status should expose canonical locale language');
        assert_same('English (en-US)', $languagePack['site_language_label'] ?? null, 'language pack status should expose locale label');
        assert_same('full', $languagePack['runtime_support_status'] ?? null, 'en-US should report full support through the active base English pack');
        assert_same('Full morphology', $languagePack['runtime_support_label'] ?? null, 'en-US should preserve the runtime support label');
        assert_same('en', $languagePack['matched_runtime_language'] ?? null, 'en-US should report the matched base runtime language');
        assert_same('English (en)', $languagePack['matched_runtime_language_label'] ?? null, 'en-US should report the matched base runtime language label');
        assert_contains('English morphology is available through the active base-language analyzer pack English (en)', (string) ($languagePack['runtime_support_reason'] ?? ''), 'en-US should explain base-language analyzer coverage');
        assert_true(!array_key_exists('fallback_summary', $languagePack), 'language pack status should not retain a compatibility fanout summary');
        assert_true(($languagePack['active_runtime_pack_count'] ?? 0) >= 1, 'language pack status should count active runtime packs');
        assert_true(is_array($languagePack['active_runtime_packs'] ?? null), 'language pack status should expose bounded active runtime pack summaries');
        assert_true(count($languagePack['active_runtime_packs']) <= 8, 'active runtime pack summaries should be bounded');
        assert_contains('en-synthetic-status-pack', json_encode($languagePack['active_runtime_packs'], JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR), 'active runtime pack summaries should expose safe pack ids');
        assert_true(is_bool($languagePack['gzip_available'] ?? null), 'language pack status should expose gzip availability as a boolean');
        assert_true(in_array($languagePack['gzip_status'] ?? null, ['available', 'missing'], true), 'language pack status should expose concise gzip status');
        assert_contains('Read-only advisory status', (string) ($languagePack['status_note'] ?? ''), 'language pack status should make read-only scope explicit');
        assert_contains("language_pack_status\t", $human, 'default status output should preserve the nested language pack row');
        assert_contains("language_pack_site_language\tEnglish (en-US)", $human, 'default status output should expose flattened site language');
        assert_contains("language_pack_runtime_support\tFull morphology via English (en)", $human, 'default status output should expose flattened runtime support');
        assert_true(!str_contains($human, "language_pack_fallback_languages\t"), 'default status output should not expose removed language fanout state');
        assert_contains("language_pack_active_runtime_pack_count\t", $human, 'default status output should expose active runtime pack count');
        assert_contains("language_pack_active_runtime_languages\t", $human, 'default status output should expose active runtime language summaries');
        assert_contains("language_pack_gzip_status\t", $human, 'default status output should expose gzip/runtime status');
        assert_contains("language_pack_recommendation\t", $human, 'default status output should expose language-pack recommendation');
        $encodedPayload = json_encode($languagePack, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
        assert_true(!str_contains($encodedPayload, $packDir), 'language pack status should not expose local pack directories');
        assert_true(!str_contains($encodedPayload, $manifest), 'language pack status should not expose manifest paths');
        assert_true(!str_contains($human, $packDir), 'default status output should not expose local pack directories');
        assert_same($optionsBefore, $GLOBALS['wp_fts_test_options'], 'wp-cli status should not mutate analyzer pack options while rendering language-pack status');
        assert_same([], $fake->docs, 'wp-cli status should not create index documents while rendering language-pack status');
        assert_same([], $fake->ftsTerms, 'wp-cli status should not write terms while rendering language-pack status');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'wp-cli status should not schedule work while rendering language-pack status');
    } finally {
        remove_directory_tree($packDir);
        wp_fts_test_reset_wordpress_fakes();
    }
});

test_case('wp-cli status reports expired lock diagnostics without exposing token data', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $now = time();
    $lockStarted = $now - 3600;
    $lockExpires = $now - 60;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = [
        'token' => 'expired-status-token-must-not-render',
        'mode' => 'wp-cli-reindex',
        'started_at' => $lockStarted,
        'expires_at' => $lockExpires,
    ];

    try {
        $command = new WP_FTS_WPCLI_Command();
        $human = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->status([], []);
        });
        $raw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->status([], ['format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same('expired', $payload['lock_state'] ?? null, 'status JSON should report expired lock state');
    assert_same(false, $payload['lock_active'] ?? null, 'status JSON should report expired locks as inactive for writer coordination');
    assert_same('wp-cli-reindex', $payload['lock_mode'] ?? null, 'status JSON should expose sanitized expired lock mode');
    assert_same(gmdate('Y-m-d H:i:s', $lockStarted), $payload['lock_started_at'] ?? null, 'status JSON should expose bounded expired lock start time');
    assert_same(gmdate('Y-m-d H:i:s', $lockExpires), $payload['lock_expires_at'] ?? null, 'status JSON should expose bounded expired lock expiry time');
    assert_true(is_int($payload['lock_age_seconds'] ?? null), 'status JSON should expose bounded expired lock age');
    assert_true(($payload['lock_age_seconds'] ?? -1) >= 3600 && ($payload['lock_age_seconds'] ?? 99999) <= 3610, 'status JSON expired lock age should stay near the fixture age');
    assert_same(null, $payload['lock_expires_in_seconds'] ?? null, 'status JSON should not report active expiry seconds for expired locks');
    assert_true(is_int($payload['lock_expired_seconds'] ?? null), 'status JSON should expose bounded seconds since expiry');
    assert_true(($payload['lock_expired_seconds'] ?? -1) >= 60 && ($payload['lock_expired_seconds'] ?? 99999) <= 70, 'status JSON expired lock timing should stay near the fixture expiry');
    assert_contains('next indexing writer will replace it automatically', (string) ($payload['lock_advice'] ?? ''), 'status JSON should expose expired lock recovery advice');
    assert_contains('Recurring expired locks indicate interrupted or fatal indexing jobs.', (string) ($payload['lock_advice'] ?? ''), 'status JSON should expose recurring expired-lock guidance');
    $lock = $payload['lock'] ?? null;
    assert_true(is_array($lock), 'status JSON should include nested expired lock diagnostics');
    assert_same('expired', $lock['state'] ?? null, 'nested lock diagnostics should include expired state');
    assert_same(false, $lock['active'] ?? null, 'nested lock diagnostics should keep expired lock inactive');
    assert_same('wp-cli-reindex', $lock['mode'] ?? null, 'nested lock diagnostics should include sanitized expired mode');
    assert_true(is_int($lock['age_seconds'] ?? null), 'nested lock diagnostics should include bounded expired age');
    assert_true(is_int($lock['expired_seconds'] ?? null), 'nested lock diagnostics should include bounded expired timing');
    assert_true(!str_contains(json_encode($payload, JSON_THROW_ON_ERROR), 'expired-status-token-must-not-render'), 'status JSON should not expose expired lock token anywhere');
    assert_true(!str_contains($human, 'expired-status-token-must-not-render'), 'default status output should not expose expired lock token');
    assert_contains("lock_state\texpired", $human, 'default status output should expose expired lock state');
    assert_contains("lock_expired_seconds\t", $human, 'default status output should expose expired lock timing');
    assert_contains('next indexing writer will replace it automatically', $human, 'default status output should include expired lock advice');
    assert_same('expired-status-token-must-not-render', $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]['token'] ?? null, 'status should leave expired lock payload unchanged');
    assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'status should not clean expired locks while rendering diagnostics');
});

test_case('status and health report missing queue processor schedule with pending work without mutating state', function (): void {
