        'started_at' => time(),
        'expires_at' => time() + 300,
    ];
    $GLOBALS['wp_fts_test_posts'][792] = (object) [
        'ID' => 792,
        'post_title' => "Queued Schedule Secret SELECT * FROM wp_users\n#0 stack trace",
        'post_content' => 'Queued Schedule Hidden Content',
        'post_status' => 'publish',
        'post_type' => 'post',
    ];

    try {
