    $fake->prepared = [];

    try {
        $raw = wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->repair([], ['format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(true, $payload['skipped_locked'] ?? null, 'CLI repair JSON should explicitly report a safe lock skip');
    assert_same(true, $payload['lock_active'] ?? null, 'CLI repair JSON should expose the sanitized active-lock state');
    assert_contains('no schema repair was performed', (string) ($payload['message'] ?? ''), 'CLI repair should not claim success under contention');
    assert_same(0, count($fake->queries), 'contended CLI repair should execute zero SQL statements');
    assert_same(0, count($fake->prepared), 'contended CLI repair should prepare zero SQL statements');
    assert_same('cli-repair-foreign-writer', $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]['token'] ?? null, 'contended CLI repair should not replace the foreign lease');
});

test_case_with_pdo_sqlite_fixture('wp-cli asynchronous reindex queues while direct writers skip safely under an active lock', function (): void {
    $fake = new WP_FTS_V4_Regression_SQLite_WPDB();
    wp_fts_v4_regression_create_schema($fake);
    wp_fts_v4_regression_add_source_post($fake, 901, '<p>locked reindex</p>', 'Locked Reindex');
    wp_fts_v4_regression_add_post($fake, 902, '2026-07-01 00:00:00');
    wp_fts_v4_regression_add_post($fake, 903, '2026-07-01 00:00:00');
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_posts'][902] = (object) [
        'ID' => 902,
        'post_type' => 'post',
        'post_status' => 'publish',
        'post_password' => '',
        'post_title' => 'Eligible canonical post',
        'post_content' => '',
        'post_excerpt' => '',
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = [
        'token' => 'active-writer-token',
        'mode' => 'cron',
        'started_at' => time(),
        'expires_at' => time() + 300,
    ];

    [$reindexResult, $health] = wp_fts_quality_with_wpdb($fake, static function (): array {
        $command = new WP_FTS_WPCLI_Command();
        $raw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->reindex([], [
                'lang' => 'en',
                'limit' => '1',
                'format' => 'json',
            ]);
        });
        $command->delete([902], []);
        $command->optimize([], []);

        return [wp_fts_test_decode_cli_json_object($raw), WP_FTS_Plugin::search_health()];
    });

    assert_same([], WP_CLI::$successMessages, 'locked writers should not report successful writes');
    assert_same('queued', $reindexResult['status'] ?? null, 'asynchronous reindex should durably accept its scope without claiming the writer lease');
    assert_same(true, $reindexResult['has_more'] ?? null, 'asynchronous reindex should report that background work remains');
    assert_same(2, count(WP_CLI::$warningMessages), 'canonical delete rejection and locked optimize should each warn');
    assert_contains('Document 902 belongs to an eligible canonical WordPress post and was not removed.', WP_CLI::$warningMessages[0], 'delete should reject an index-only mutation that canonical reconciliation would immediately reverse');
    assert_contains('Skipped FTS optimize: another index writer is already running.', WP_CLI::$warningMessages[1], 'locked optimize should explain the active writer lock');
    assert_same(0, (int) $fake->get_var('SELECT COUNT(*) FROM wp_fts_documents WHERE post_id=901'), 'scope enqueue should not publish the selected source post');
    assert_same(1, (int) $fake->get_var('SELECT COUNT(*) FROM wp_fts_documents WHERE post_id=902'), 'locked delete should retain the indexed document');
    assert_same(1, (int) $fake->get_var('SELECT COUNT(*) FROM wp_fts_documents WHERE post_id=903'), 'locked optimize should retain existing documents');
    assert_same([], array_map('intval', $fake->get_col("SELECT post_id FROM wp_fts_work WHERE kind = 'post' ORDER BY post_id")), 'reindex should not materialize post rows before a later worker claims its scope');
    assert_same(1, (int) $fake->get_var("SELECT COUNT(*) FROM wp_fts_work WHERE kind = 'scope'"), 'reindex should leave one durable filtered scope ready for a later worker');
    assert_same('ready', (string) $fake->get_var("SELECT state FROM wp_fts_work WHERE kind = 'scope'"), 'scope enqueue should not acknowledge or claim the filtered scope');
    assert_same(1, count($GLOBALS['wp_fts_test_schedule_calls']), 'scope enqueue should schedule one later worker despite current lease contention');
    assert_same('active-writer-token', $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]['token'] ?? null, 'locked writers should leave the active lease untouched');
    assert_same(true, $health['last_skipped_locked'] ?? null, 'locked writer health should record a lease skip');
    assert_same(0, $health['last_batch_indexed'] ?? null, 'locked writer health should record no indexed writes');
    $diagnostics = $health['latest_batch_diagnostics'] ?? [];
    assert_same('wp-cli-optimize', $diagnostics['source'] ?? null, 'latest diagnostics should identify the skipped optimize command');
    assert_same('skipped_locked', $diagnostics['status'] ?? null, 'locked writer diagnostics should report skipped status');
    assert_same(true, $diagnostics['lock_prevented_work'] ?? null, 'locked writer diagnostics should record that the lease prevented work');
    assert_same('lock_active', $diagnostics['stop_reason'] ?? null, 'locked writer diagnostics should record lease stop reason');
    assert_same('active', $diagnostics['lock_at_start']['state'] ?? null, 'locked writer diagnostics should include active start lease state');
    assert_same('cron', $diagnostics['lock_at_start']['mode'] ?? null, 'locked writer diagnostics should include safe holder mode');
    assert_true(!str_contains(json_encode($diagnostics, JSON_THROW_ON_ERROR), 'active-writer-token'), 'locked writer diagnostics should not expose lease tokens');
});

test_case('wp-cli delete routes a missing canonical post through exact durable reconciliation', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    try {
        $storage = wp_fts_test_unleased_storage();
        wp_fts_test_replace_empty_document($storage, 904, 'en', 'orphan-904');
        $fake->queries = [];
        $fake->prepared = [];

        (new WP_FTS_WPCLI_Command())->delete([904], []);

        assert_same(['Queued document 904 for canonical FTS reconciliation.'], WP_CLI::$successMessages, 'missing canonical content should be queued rather than mutated directly');
        assert_same([], WP_CLI::$warningMessages, 'missing canonical content should be a valid reconciliation request');
        assert_true(isset($fake->docs[904]), 'the CLI command should not write the derived index outside the shared worker lease');
        assert_same([904], wp_fts_test_queue_ids($fake), 'delete should create exactly one coalesced durable post generation');
        assert_same(1, count(array_filter(
            $fake->queries,
            static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work') && str_contains($sql, "'post'")
        )), 'delete should use one queue UPSERT');
        assert_same(0, count(array_filter(
            $fake->queries,
            static fn(string $sql): bool => str_starts_with($sql, 'DELETE FROM wp_fts_documents')
        )), 'delete should issue no direct derived-document mutation');

        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_true(!isset($fake->docs[904]), 'the shared writer should physically remove the orphaned derived document');
        assert_same([], wp_fts_test_queue_ids($fake), 'the exact missing-post generation should acknowledge after deletion');
    } finally {
        $wpdb = $oldWpdb;
    }
});

