test_case('MySQL reset revalidates mutation ownership at both atomic publication boundaries', function (): void {
    $fake = new WP_FTS_Test_WPDB();
    $guardCalls = 0;
    $guardCallsAtRename = null;
    $guardCallsAtFinalDrop = null;
    $dropStatements = 0;
    $fake->queryObserver = static function (string $sql) use (
        &$guardCalls,
        &$guardCallsAtRename,
        &$guardCallsAtFinalDrop,
        &$dropStatements
    ): void {
        if (str_starts_with($sql, 'RENAME TABLE ')) {
            $guardCallsAtRename = $guardCalls;
        }
        if (str_starts_with($sql, 'DROP TABLE IF EXISTS ') && ++$dropStatements === 2) {
            $guardCallsAtFinalDrop = $guardCalls;
        }
    };
    $storage = new WP_FTS_Storage_Mysql(
        $fake,
        null,
        static function () use (&$guardCalls): void {
            $guardCalls++;
        }
    );

    $storage->reset_index();

    assert_same(3, $guardCalls, 'MySQL reset should check ownership at entry, immediately before atomic rename, and immediately before retired cleanup');
    assert_same(2, $guardCallsAtRename, 'atomic RENAME should observe a fresh second ownership check');
    assert_same(3, $guardCallsAtFinalDrop, 'retired-table DROP should observe a fresh third ownership check');
});

test_case('wp-cli reset-index clears FTS data and operational state while preserving posts and settings', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $snapshot = wp_fts_test_seed_reset_index_state($fake);
    $epochBeforeReset = $fake->searchEpoch;
    $settingsBefore = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION];
    $analyzerBefore = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION];

    try {
        $command = new WP_FTS_WPCLI_Command();
        $raw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->reset_index([], ['yes' => true, 'format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
        $resetDatabaseStatements = count($fake->queries) + $fake->num_queries;
        $resetScheduleCalls = $GLOBALS['wp_fts_test_schedule_calls'];
        $statusRaw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->status([], ['format' => 'json']);
        });
        $status = wp_fts_test_decode_cli_json_object($statusRaw);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same('reset', $payload['status'] ?? null, 'confirmed reset-index should report reset status');
    assert_same(true, $payload['reset'] ?? null, 'confirmed reset-index should report a performed reset');
    assert_same('mysql_atomic_table_swap', $payload['reset_strategy'] ?? null, 'confirmed MySQL reset should report its constant-cost publication strategy');
    assert_same(true, $payload['reconciliation_queued'] ?? null, 'confirmed reset should report its automatic complete-corpus reconciliation');
    assert_contains('queued one complete background reconciliation scope', $payload['message'] ?? '', 'confirmed reset should tell operators that background rebuilding is already queued');
    assert_same(false, $payload['counts_exact'] ?? null, 'confirmed reset should not scan large tables merely to report cosmetic row counts');
    assert_same('current', $payload['schema_status'] ?? null, 'confirmed reset-index should keep schema current');
    assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $payload['schema_version'] ?? null, 'confirmed reset-index should preserve schema version');
    assert_same(null, $payload['postings_deleted'] ?? null, 'constant-cost reset should report posting counts as unknown');
    assert_same(null, $payload['terms_deleted'] ?? null, 'constant-cost reset should report term counts as unknown');
    assert_same(null, $payload['docs_deleted'] ?? null, 'constant-cost reset should report document counts as unknown');
    assert_same(null, $payload['doc_lengths_deleted'] ?? null, 'the removed v4 document-length table count should remain unknown rather than claim a scan');
    assert_same(null, $payload['doc_metadata_deleted'] ?? null, 'the removed v4 metadata table count should remain unknown rather than claim a scan');
    assert_same(null, $payload['collection_metadata_deleted'] ?? null, 'the removed v4 collection-statistics count should remain unknown rather than claim a scan');
    assert_same(null, $payload['pending_queue_cleared'] ?? null, 'constant-cost reset should not count the durable queue before replacing it');
    assert_same(1, $payload['last_batch_failures_cleared'] ?? null, 'confirmed reset-index should report cleared failure count');
    assert_same(0, $payload['wordpress_posts_deleted'] ?? null, 'confirmed reset-index should report that no posts were deleted');
    assert_same(true, $payload['settings_preserved'] ?? null, 'confirmed reset-index should report settings preservation');
    assert_same(true, $payload['analyzer_options_preserved'] ?? null, 'confirmed reset-index should report analyzer option preservation');

    assert_same([], $fake->ftsTerms, 'confirmed reset-index should clear terms');
    assert_same([], $fake->postings, 'confirmed reset-index should clear postings');
    assert_same([], $fake->docs, 'confirmed reset-index should clear docs and tombstones');
    assert_same([], $fake->docLengths, 'confirmed reset-index should clear doc lengths');
    assert_same([], $fake->docMeta, 'confirmed reset-index should clear doc metadata');
    assert_same([], $fake->meta, 'confirmed reset-index should clear collection metadata');
    assert_same($snapshot['postRows'], $fake->postRows, 'confirmed reset-index should not delete or trash WordPress posts');
    assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'confirmed reset-index should preserve schema option');
    assert_same($settingsBefore, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] ?? null, 'confirmed reset-index should preserve plugin settings');
    assert_same($analyzerBefore, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION] ?? null, 'confirmed reset-index should preserve analyzer options');
    assert_same([], wp_fts_test_queue_ids($fake), 'confirmed reset-index should clear old per-post work rather than carry stale generations forward');
    assert_same(1, count(array_filter(
        $fake->queue,
        static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
    )), 'confirmed reset-index should create exactly one complete reconciliation scope');
    assert_same(1, count($resetScheduleCalls), 'confirmed reset-index should schedule exactly one bounded queue processor event');
    assert_same(WP_FTS_Plugin::CRON_HOOK, $resetScheduleCalls[0]['hook'] ?? null, 'confirmed reset-index should schedule the shared queue processor');

    $resetSql = implode("\n", array_map(
        static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
        $fake->queries
    ));
    assert_same(9, count($fake->queries), 'plugin reset should add one scope UPSERT to the storage reset\'s eight constant writes');
    assert_same(10, $resetDatabaseStatements, 'plugin reset should execute one epoch read, eight constant storage writes, and one scope UPSERT');
    assert_same(1, count(array_filter(
        $fake->queries,
        static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work') && str_contains($sql, "'scope'")
    )), 'plugin reset should add exactly one durable scope UPSERT after successful publication');
    assert_same(4, substr_count($resetSql, 'CREATE TABLE '), 'reset should create one empty LIKE table for each physical relation');
    assert_same(1, substr_count($resetSql, 'RENAME TABLE '), 'reset should publish all four empty relations in one atomic rename');
    assert_same(2, substr_count($resetSql, 'DROP TABLE IF EXISTS '), 'reset should clean stale and retired generations with two metadata statements');
    assert_same(0, substr_count($resetSql, 'DELETE FROM '), 'reset must contain no corpus-sized row DELETE');
    assert_same(0, substr_count($resetSql, 'COUNT('), 'reset must contain no cosmetic table or queue count');
    assert_true(!str_contains($resetSql, 'wp_posts'), 'reset should not run SQL against canonical WordPress posts');
    $identifiers = [];
    $identifierOffset = 0;
    while (($identifierStart = strpos($resetSql, '`', $identifierOffset)) !== false) {
        $identifierEnd = strpos($resetSql, '`', $identifierStart + 1);
        if ($identifierEnd === false) {
            break;
        }
        $identifiers[] = substr($resetSql, $identifierStart + 1, $identifierEnd - $identifierStart - 1);
        $identifierOffset = $identifierEnd + 1;
    }
    foreach ($identifiers as $identifier) {
        assert_true(strlen($identifier) <= 64, "reset temporary identifier must fit MySQL's 64-byte table-name limit: {$identifier}");
    }
    assert_same($epochBeforeReset + 2, $fake->searchEpoch, 'reset publication and its dirty reconciliation scope should each invalidate existing cursors');
    assert_same(
        'pending',
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] ?? null,
        'reset should leave search takeover pending until a complete reconciliation scope finishes'
    );

    assert_same('current', $status['schema_status'] ?? null, 'status after reset should keep schema current');
    assert_same(false, $status['counts_exact'] ?? null, 'normal status after reset should keep exhaustive counts disabled');
    assert_same(null, $status['indexed_count'] ?? null, 'normal status after reset should not count the entire index');
    assert_same(1, $status['pending_queue_count'] ?? null, 'status after reset should report the one automatic reconciliation scope');
    assert_same(true, $status['reconciliation_active'] ?? null, 'status after reset should report automatic reconciliation as active');
    assert_same(false, $status['profile_reconciliation_pending'] ?? null, 'reset should initialize current and accepted profiles from one source');
    assert_same(1, $status['pending_scope_work_count'] ?? null, 'status after reset should report exactly one durable scope row');
    assert_same(0, $status['reconciliation_cursor_post_id'] ?? null, 'status after reset should report no durable scope cursor');
    assert_same(0, $status['last_batch_failures'] ?? null, 'status after reset should clear batch failures');
    assert_same(0, $status['last_failed_post_id'] ?? null, 'status after reset should clear failed post id');
    assert_same('', $status['last_failed_post_title'] ?? null, 'status after reset should clear failed post title');
    assert_same('', $status['last_error'] ?? null, 'status after reset should clear failure error');
    assert_same(false, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['search_runtime_failure_latched'] ?? null, 'reset should clear the generic runtime latch in the new generation');
    assert_same(false, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['foreground_owner_guard_blocked'] ?? null, 'reset should clear the operator-authorized owner-guard latch in the new generation');
    $diagnostics = $status['latest_batch_diagnostics'] ?? [];
    assert_same('wp-cli-reset-index', $diagnostics['source'] ?? null, 'status after reset should identify reset as the latest writer');
    assert_same('success', $diagnostics['status'] ?? null, 'status after reset should report successful reset diagnostics');
    assert_true(!str_contains(json_encode($payload, JSON_THROW_ON_ERROR), 'SELECT '), 'reset-index JSON should not include raw SQL');
    assert_true(!str_contains(json_encode($payload, JSON_THROW_ON_ERROR), 'Indexed reset fixture'), 'reset-index JSON should not include post content or titles');
    assert_same([], WP_CLI::$warningMessages, 'confirmed reset-index should not warn');
});

test_case('wp-cli reset-index keeps takeover pending across post-publication cleanup failure and deterministic retry', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_reset_index_state($fake);
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] = 'ready';
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_completed_at'] = '2026-06-18 01:06:00';

    $pendingBeforeFirstDdl = null;
    $fake->queryObserver = static function (string $sql) use (&$pendingBeforeFirstDdl): void {
        if ($pendingBeforeFirstDdl !== null || !str_starts_with($sql, 'DROP TABLE IF EXISTS ')) {
            return;
        }
        $pendingBeforeFirstDdl = ($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] ?? null) === 'pending';
    };
    $fake->failQueryNeedle = 'DROP TABLE IF EXISTS ';
    $fake->failQueryNeedleOccurrence = 2;

    $failure = null;
    try {
        try {
            (new WP_FTS_WPCLI_Command())->reset_index([], ['yes' => true, 'format' => 'json']);
        } catch (Throwable $error) {
            $failure = $error;
        }

        assert_true($failure instanceof RuntimeException, 'a failed retired-generation DROP should fail reset rather than report success');
        assert_same(true, $pendingBeforeFirstDdl, 'reset must disable takeover before its first DDL statement');
        assert_same(
            'pending',
            $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] ?? null,
            'a cleanup failure after atomic publication must leave takeover pending'
        );
        assert_same([], $fake->ftsTerms, 'the atomic rename should already have published an empty dictionary before retired cleanup fails');
        assert_same([], $fake->postings, 'the atomic rename should already have published empty postings before retired cleanup fails');
        assert_same([], $fake->docs, 'the atomic rename should already have published empty documents before retired cleanup fails');
        assert_same([], wp_fts_test_queue_ids($fake), 'the atomic rename should already have published work containing only epoch metadata');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'failed retired cleanup must not schedule or advertise reconciliation success');
        assert_same([], WP_CLI::$successMessages, 'failed retired cleanup must not emit a success message');
        assert_true(!isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]), 'a failed reset should release only its own writer lease');

        $failedSql = implode("\n", $fake->queries);
        assert_same(1, substr_count($failedSql, 'RENAME TABLE '), 'cleanup failure should occur after exactly one atomic publication');
        assert_same(0, substr_count($failedSql, 'DELETE FROM '), 'failed reset must not fall back to corpus-sized deletion');
        assert_same(0, substr_count($failedSql, 'COUNT('), 'failed reset must not scan tables for cosmetic counts');
        $leftoverGenerationTables = array_values(array_filter(
            array_keys($fake->schemaColumns),
            static fn(string $table): bool => str_contains($table, '_rn_') || str_contains($table, '_ro_')
        ));
        assert_same(4, count($leftoverGenerationTables), 'failed final cleanup should leave exactly the four retired tables for deterministic retry cleanup');
        foreach ($leftoverGenerationTables as $table) {
            assert_true(str_contains($table, '_ro_'), 'only retired, never staging, tables should remain after publication');
        }

        $epochAfterPublishedFailure = $fake->searchEpoch;
        $fake->queries = [];
        $fake->prepared = [];
        $fake->queryObserver = null;
        $fake->failQueryNeedle = null;
        $fake->failQueryNeedleOccurrence = 0;
        $fake->failQueryNeedleMatches = 0;

        $raw = wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->reset_index([], ['yes' => true, 'format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);

        assert_same('reset', $payload['status'] ?? null, 'retry should clean fixed generation names and complete reset');
        assert_same(true, $payload['reconciliation_queued'] ?? null, 'successful retry should queue the non-forgettable complete reconciliation');
        assert_same($epochAfterPublishedFailure + 2, $fake->searchEpoch, 'retry publication and its dirty reconciliation scope should advance the cursor epoch monotonically');
        assert_same(
            [],
            array_values(array_filter(
                array_keys($fake->schemaColumns),
                static fn(string $table): bool => str_contains($table, '_rn_') || str_contains($table, '_ro_')
            )),
            'successful retry should remove every stale staging and retired generation'
        );
        assert_same(
            'pending',
            $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['initial_index_status'] ?? null,
            'successful retry should still require a complete corpus reconciliation before takeover'
        );
        $retrySql = implode("\n", $fake->queries);
        assert_same(9, count($fake->queries), 'retry should retain eight storage writes plus one complete-scope UPSERT');
        assert_same(1, count(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        )), 'successful retry should leave exactly one automatic reconciliation scope');
        assert_same(1, count($GLOBALS['wp_fts_test_schedule_calls']), 'successful retry should schedule exactly one worker event');
        assert_same(0, substr_count($retrySql, 'DELETE FROM '), 'retry must not fall back to row deletion');
        assert_same(0, substr_count($retrySql, 'COUNT('), 'retry must not add table scans');
    } finally {
        $wpdb = $oldWpdb;
    }
});

