test_case('automatic reset reconciliation completes the only path back to search takeover', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_reset_index_state($fake);
    // An empty canonical corpus reaches the completion boundary in one worker
    // pass; populated sites use the identical scope over bounded keyset pages.
    $fake->postRows = [];

    try {
        $raw = wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->reset_index([], ['yes' => true, 'format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
        $summary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
        $finalizerScheduled = isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]);
        $afterScope = WP_FTS_Plugin::search_health();
        WP_FTS_Plugin::run_scheduled_schema_repair();
        $ready = WP_FTS_Plugin::search_health();

        assert_same(true, $payload['reconciliation_queued'] ?? null, 'reset should publish exactly one durable readiness path');
        assert_same(true, $summary['scope_completed'] ?? null, 'the automatic reset scope should acknowledge after complete canonical discovery');
        assert_same(true, $summary['scope_completed_global'] ?? null, 'the automatic reset scope must be classified as complete-corpus work');
        assert_true(($afterScope['reconciliation_scope_completed_at'] ?? '') !== '', 'global scope completion should persist the readiness proof');
        assert_same('pending', $afterScope['initial_index_status'] ?? null, 'worker completion alone should not bypass physical-schema verification');
        assert_same(true, $finalizerScheduled, 'completed reset reconciliation should schedule its dedicated readiness finalizer');
        assert_same('ready', $ready['initial_index_status'] ?? null, 'maintenance should promote takeover after the exact global scope and schema proof');
        assert_same(0, $ready['pending_queue_count'] ?? null, 'ready takeover should have no residual reset work');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('wp-cli process-batch runs one bounded direct-work batch without implicit corpus scanning', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    wp_fts_test_seed_backfill_posts($fake, 4, 101);
    $GLOBALS['wp_fts_test_posts'][81] = wp_fts_test_backfill_post(81, 'post', 'publish', 'CLI Queued Post');
    wp_fts_test_seed_queue($fake, [81, 101, 102]);

    try {
        $command = new WP_FTS_WPCLI_Command();
        $raw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->process_batch([], [
                'batch_size' => 2,
                'format' => 'json',
            ]);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
        $health = WP_FTS_Plugin::search_health();
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same('manual', $payload['mode'] ?? null, 'process-batch should use the manual batch path');
    assert_same(2, $payload['batch_size'] ?? null, 'process-batch should report the requested bounded batch size');
    assert_same(2, $payload['indexed'] ?? null, 'process-batch should process only one bounded batch');
    assert_same(2, $payload['queue_processed'] ?? null, 'process-batch should report only directly claimed work');
    assert_same(0, $payload['backfill_processed'] ?? null, 'process-batch should not perform an implicit corpus scan');
    assert_same(false, $payload['skipped_locked'] ?? null, 'process-batch should report no lock skip when it runs');
    assert_same(false, $payload['stopped_by_budget'] ?? null, 'process-batch should report no budget stop when budget remains');
    assert_same(true, $payload['has_more'] ?? null, 'process-batch should report remaining work after a partial batch');
    assert_same(1, $payload['pending_queue_count'] ?? null, 'process-batch should report the unclaimed direct generation');
    assert_same(2, count($fake->docs), 'process-batch should not drain all available content');
    assert_true(isset($fake->docs[81]), 'process-batch should index the queued post first');
    assert_true(isset($fake->docs[101]), 'process-batch should use remaining capacity for the next direct generation');
    assert_true(!isset($fake->docs[102]), 'process-batch should leave later direct work for another invocation');
    $diagnostics = $health['latest_batch_diagnostics'] ?? [];
    assert_same([], $diagnostics, 'an ordinary successful batch should not add a global health-option write');
    $healthWrites = array_values(array_filter(
        $GLOBALS['wp_fts_test_updated_options'],
        static fn(array $entry): bool => ($entry['name'] ?? null) === WP_FTS_Plugin::INDEX_HEALTH_OPTION
    ));
    assert_same([], $healthWrites, 'the CLI result should report bounded progress without persistent per-batch telemetry');
});

