test_case('manual queue batch records one failed post and continues without retrying it', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    foreach ([81 => 'Queue Good Before', 82 => 'Queue Bad', 83 => 'Queue Good After'] as $postId => $title) {
        $GLOBALS['wp_fts_test_posts'][$postId] = wp_fts_test_backfill_post($postId, 'post', 'publish', $title);
    }
    wp_fts_test_seed_queue($fake, [81, 82, 83]);
    $badAttempts = 0;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post) use (&$badAttempts): array {
        if ((int) ($post->ID ?? 0) === 82) {
            $badAttempts++;
            throw new RuntimeException("simulated analysis failure SELECT * FROM wp_users\n#0 stack secret=must-not-render");
        }

        return $fields;
    };

    try {
        $fake->queries = [];
        $result = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        $firstStatementCount = count($fake->queries);
        $health = WP_FTS_Plugin::search_health();
        $queueAfterFailure = $fake->queue;
        $docsAfterFailure = $fake->docs;
        $successorRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            3,
            static fn(): bool => isset($fake->docs[81], $fake->docs[83])
                && wp_fts_test_queue_ids($fake) === [82]
        );
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_same(0, $result['indexed'], 'the retryable failure phase must not publish successful replacements');
    assert_same(0, $result['queue_processed'], 'the retryable failure phase must not acknowledge deferred valid generations');
    assert_same(1, $result['retryable_failures'] ?? null, 'the retryable failure phase should settle exactly its failed generation');
    assert_same(2, $result['deferred'] ?? null, 'both valid generations should be released for a bounded successor');
    assert_same('failure_phase', $result['stop_reason'] ?? null, 'a mixed retryable batch should stop after its isolated failure settlement');
    assert_same(1, $result['last_batch_failures'], 'queue failure batch should report one failed item');
    assert_same(82, $result['last_failed_post_id'], 'queue failure summary should record the failed queued post id');
    assert_same('Queue Bad', $result['last_failed_post_title'], 'queue failure summary should record the failed queued post title');
    assert_contains('SELECT statement', (string) $result['last_error'], 'queue failure summary should redact SQL text');
    assert_true(!str_contains((string) $result['last_error'], 'SELECT * FROM'), 'queue failure summary should not expose raw SQL');
    assert_true(!str_contains((string) $result['last_error'], '#0'), 'queue failure summary should not expose stack traces');
    assert_same(1, $badAttempts, 'failed queued post should be analyzed once in the batch');
    assert_true($firstStatementCount <= 20, 'the isolated queue failure phase must stay inside the complete 20-statement ceiling');
    assert_same([81, 82, 83], array_map('intval', array_keys(array_filter(
        $queueAfterFailure,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'post'
    ))), 'the failure phase should preserve the failed generation and both valid suffix generations');
    assert_same('ready', $queueAfterFailure[81]['state'] ?? null, 'the valid prefix should be immediately claimable by a successor');
    assert_same('retry', $queueAfterFailure[82]['state'] ?? null, 'the failed queued post should enter durable retry backoff');
    assert_true((int) ($queueAfterFailure[82]['available_at'] ?? 0) > time(), 'the failed queued post should receive a future retry availability');
    assert_same('ready', $queueAfterFailure[83]['state'] ?? null, 'the valid suffix should be immediately claimable by a successor');
    assert_same([], $docsAfterFailure, 'the isolated failure phase should publish no replacement documents');
    assert_true(!isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]), 'queue failure batch should release the index lock');
    assert_same([], array_values(array_filter(
        [$result, ...array_column($successorRuns, 'summary')],
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'a fresh queue failure fixture must never consume a stale-takeover control phase');
    assert_true(max([$firstStatementCount, ...array_column($successorRuns, 'statement_count')]) <= 20, 'every queue failure and successor phase must stay inside the complete 20-statement ceiling');
    assert_same([82], wp_fts_test_queue_ids($fake), 'the valid successor should leave only the backed-off failed generation queued');
    assert_true(isset($fake->docs[81]), 'a bounded successor should index the valid item before the failure');
    assert_true(!isset($fake->docs[82]), 'queue failure batch should not mark the failed post indexed');
    assert_true(isset($fake->docs[83]), 'a bounded successor should index the valid item after the failure');
    assert_same('retry', $fake->queue[82]['state'] ?? null, 'the valid successor must not retry or disturb the failed generation');
    assert_same(1, $badAttempts, 'bounded successor phases must not hot-loop the backed-off failure');
    assert_same(1, $health['last_batch_failures'], 'queue failure should persist bounded health failure state');
    assert_same(82, $health['last_failed_post_id'], 'queue failure health should record failed post id');
});

test_case('manual direct-work failure records backoff and explicit retry later resolves it', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $fake->postRows = [
        wp_fts_test_backfill_post(101, 'post', 'publish', 'Backfill Bad'),
        wp_fts_test_backfill_post(102, 'post', 'publish', 'Backfill Good One'),
        wp_fts_test_backfill_post(103, 'post', 'publish', 'Backfill Good Two'),
    ];
    foreach ($fake->postRows as $post) {
        $GLOBALS['wp_fts_test_posts'][(int) $post->ID] = $post;
    }
    wp_fts_test_seed_queue($fake, [101, 102, 103]);
    $failBad = true;
    $badAttempts = 0;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post) use (&$failBad, &$badAttempts): array {
        if ($failBad && (int) ($post->ID ?? 0) === 101) {
            $badAttempts++;
            throw new RuntimeException("simulated analysis failure DELETE FROM wp_users\n#0 stack secret=must-not-render");
        }

        return $fields;
    };

    try {
        $fake->queries = [];
        $failed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        $failedStatementCount = count($fake->queries);
        $failedHealth = WP_FTS_Plugin::search_health();
        $docsAfterFailure = $fake->docs;
        $queueAfterFailure = $fake->queue;
        $lockAfterFailure = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? null;
        $suffixRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            3,
            static fn(): bool => isset($fake->docs[102], $fake->docs[103])
                && wp_fts_test_queue_ids($fake) === [101]
        );
        $failBad = false;
        WP_FTS_Plugin::retry_failed_item_recovery(101, 1);
        $recoveryRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            1,
            static fn(): bool => wp_fts_test_queue_ids($fake) === [] && isset($fake->docs[101])
        );
        $cleanRuns = array_values(array_filter(
            array_column($recoveryRuns, 'summary'),
            static fn(array $summary): bool => (int) ($summary['indexed'] ?? 0) === 1
        ));
        $clean = $cleanRuns[0] ?? [];
        $cleanHealth = WP_FTS_Plugin::search_health();
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_same(0, $failed['indexed'], 'the retryable direct-work failure phase must not publish successful replacements');
    assert_same(0, $failed['queue_processed'], 'the retryable direct-work failure phase must not acknowledge deferred valid generations');
    assert_same(0, $failed['backfill_processed'], 'direct-work processing should not scan an implicit corpus');
    assert_same(1, $failed['retryable_failures'] ?? null, 'the retryable direct-work phase should settle exactly its failed generation');
    assert_same(2, $failed['deferred'] ?? null, 'the two valid direct generations should be released for a bounded successor');
    assert_same('failure_phase', $failed['stop_reason'] ?? null, 'mixed direct work should stop after its isolated failure settlement');
    assert_same(1, $failed['last_batch_failures'], 'direct-work failure batch should report one failed row');
    assert_same(true, $failed['has_more'], 'direct-work failure batch should report more work because the failed post remains in backoff');
    assert_same(101, $failed['last_failed_post_id'], 'direct-work failure summary should record failed post id');
    assert_same('Backfill Bad', $failed['last_failed_post_title'], 'direct-work failure summary should record failed post title');
    assert_contains('DELETE statement', (string) $failed['last_error'], 'direct-work failure summary should redact SQL text');
    assert_same([], $docsAfterFailure, 'the isolated direct-work failure phase should publish no replacement document');
    assert_same([101, 102, 103], array_map('intval', array_keys(array_filter(
        $queueAfterFailure,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'post'
    ))), 'the direct-work failure phase should preserve all three durable generations');
    assert_same('retry', $queueAfterFailure[101]['state'] ?? null, 'the failed direct generation should enter durable backoff');
    assert_true((int) ($queueAfterFailure[101]['available_at'] ?? 0) > time(), 'the failed direct generation should receive a future retry availability');
    assert_same('ready', $queueAfterFailure[102]['state'] ?? null, 'the first valid suffix generation should remain immediately claimable');
    assert_same('ready', $queueAfterFailure[103]['state'] ?? null, 'the second valid suffix generation should remain immediately claimable');
    assert_same(null, $lockAfterFailure, 'direct-work failure batch should release the index lock');
    assert_same(1, $badAttempts, 'failed direct row should be analyzed once in the failed batch');
    assert_same(1, $failedHealth['last_batch_failures'], 'direct-work failure should persist bounded health failure state');
    assert_true(isset($fake->docs[102], $fake->docs[103]), 'bounded successor work should index both valid direct generations');

    assert_same(1, $clean['indexed'], 'explicitly retried clean batch should index the previously failed row');
    assert_true(isset($fake->docs[101]), 'explicit retry should recover the previously failed row');
    assert_same([], wp_fts_test_queue_ids($fake), 'the explicit recovery should leave no unresolved direct generation');
    $allRuns = [
        ['summary' => $failed, 'statement_count' => $failedStatementCount],
        ...$suffixRuns,
        ...$recoveryRuns,
    ];
    assert_same([], array_values(array_filter(
        array_column($allRuns, 'summary'),
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'a fresh direct-work recovery fixture must never consume a stale-takeover control phase');
    assert_true(max(array_column($allRuns, 'statement_count')) <= 20, 'every failed, suffix, and explicit-recovery phase must stay inside the complete 20-statement ceiling');
    assert_same(0, $cleanHealth['last_batch_failures'], 'later clean batch should clear stale failure count');
    assert_same(0, $cleanHealth['last_failed_post_id'], 'later clean batch should clear stale failed post id');
    assert_same('', $cleanHealth['last_error'], 'later clean batch should clear stale error details');
});

test_case('bulk failed-item retry uses one set-oriented queue UPSERT and one schedule', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $records = [];
    for ($offset = 1; $offset <= 20; $offset++) {
        $records[] = [
            'post_id' => 3000 + $offset,
            'title' => 'Bulk retry ' . $offset,
            'status' => 'backoff',
            'failure_count' => 1,
            'attempt_count' => 1,
            'last_failed_at' => sprintf('2026-07-17 10:%02d:00', $offset),
            'next_retry_at' => '2026-07-18 10:00:00',
        ];
    }
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['failure_history'] = $records;
    $GLOBALS['wp_fts_test_schedule_calls'] = [];
    $GLOBALS['wp_fts_test_scheduled'] = [];
    $fake->queries = [];
    $fake->prepared = [];

    try {
        $result = WP_FTS_Plugin::retry_failed_item_recovery(0, 20);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(20, $result['matched_count'] ?? null, 'bulk retry should select the complete bounded 20-record recovery page');
    assert_same(20, $result['queued_count'] ?? null, 'bulk retry should queue every selected recovery record');
    $retryStatements = array_values(array_filter(
        $fake->prepared,
        static fn(array $entry): bool => str_starts_with($entry['sql'] ?? '', 'INSERT INTO wp_fts_work')
            && str_contains($entry['sql'] ?? '', "'operator_retry'")
    ));
    assert_same(1, count($retryStatements), 'bulk retry should prepare one set-oriented queue UPSERT');
    assert_same(20, substr_count($retryStatements[0]['sql'] ?? '', "(%s, 'post', %d"), 'the one UPSERT should contain exactly the 20 selected post rows');
    $queueScheduleCalls = array_values(array_filter(
        $GLOBALS['wp_fts_test_schedule_calls'],
        static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::CRON_HOOK
    ));
    assert_same(1, count($queueScheduleCalls), 'bulk retry should schedule the queue processor once, not once per record');
    assert_same(range(3001, 3020), wp_fts_test_queue_ids($fake), 'bulk retry should retain exact durable post identities');
});

test_case('failed item recovery history is bounded sanitized and durable across batches', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post): array {
        $postId = (int) ($post->ID ?? 0);
        if ($postId >= 1000 && $postId < 1025) {
            throw new RuntimeException("history failure {$postId} SELECT * FROM wp_users WHERE user_pass = 'secret'\n#0 trace token=must-not-render");
        }

        return $fields;
    };

    try {
        for ($i = 0; $i < 25; $i++) {
            $postId = 1000 + $i;
            $GLOBALS['wp_fts_test_posts'][$postId] = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Recovery <b>Failure</b> ' . $i);
            wp_fts_test_seed_queue($fake, [$postId]);

            WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1, 'source' => 'history-test']);
        }

        $history = WP_FTS_Plugin::failure_recovery_status(25);
        $encoded = json_encode($history, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);

        $goodPost = wp_fts_test_backfill_post(2000, 'post', 'publish', 'Recovery Clean Batch');
        $GLOBALS['wp_fts_test_posts'][2000] = $goodPost;
        wp_fts_test_seed_queue($fake, [2000]);
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1, 'source' => 'history-clean']);
        $afterClean = WP_FTS_Plugin::failure_recovery_status(25);
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_same('wp-fts-failure-recovery-v1', $history['schema'] ?? null, 'failure recovery should expose a stable schema');
    assert_true(($history['total_count'] ?? 0) > 0 && ($history['total_count'] ?? 0) <= 20, 'failure recovery history should be bounded by item count and byte size');
    assert_true(count($history['recent_items'] ?? []) > 0 && count($history['recent_items'] ?? []) <= ($history['total_count'] ?? 0), 'failure recovery status should clamp requested limits to the bounded history size and byte budget');
    assert_same(1024, $history['recent_items'][0]['post_id'] ?? null, 'failure recovery should keep newest failures first');
    assert_true(!in_array(1000, array_column($history['recent_items'] ?? [], 'post_id'), true), 'failure recovery should discard oldest records past the bound');
    assert_same('backoff', $history['recent_items'][0]['status'] ?? null, 'first failures should enter bounded backoff');
    assert_same(1, $history['recent_items'][0]['failure_count'] ?? null, 'failure recovery should count item failures');
    assert_same(1, $history['recent_items'][0]['attempt_count'] ?? null, 'failure recovery should count item attempts');
    assert_true(strlen($encoded) <= ($history['bytes_limit'] ?? 0), 'failure recovery JSON should remain byte bounded');
    assert_true(!str_contains($encoded, 'SELECT * FROM'), 'failure recovery should not store raw SQL');
    assert_true(!str_contains($encoded, '#0'), 'failure recovery should not store stack traces');
    assert_true(!str_contains($encoded, 'must-not-render'), 'failure recovery should redact secret-looking values');
    assert_true(!str_contains($encoded, '<b>'), 'failure recovery should sanitize titles');
    assert_same($history['total_count'] ?? null, $afterClean['total_count'] ?? null, 'clean later batches should not erase unrelated durable failure history');
    assert_true(isset($fake->docs[2000]), 'clean durability check should still index unrelated queued work');
});

test_case('repeated transient failures stay in capped backoff and do not starve unrelated work', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    foreach ([
        2101 => 'Repeated Bad',
        2102 => 'Unrelated Good One',
        2103 => 'Unrelated Good Two',
    ] as $postId => $title) {
        $GLOBALS['wp_fts_test_posts'][$postId] = wp_fts_test_backfill_post($postId, 'post', 'publish', $title);
    }
    $badAttempts = 0;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (
        array $fields,
        object $post
    ) use (&$badAttempts): array {
        if ((int) ($post->ID ?? 0) === 2101) {
            $badAttempts++;
            throw new RuntimeException("repeated failure SELECT * FROM wp_users secret=must-not-render\n#0 stack");
        }

        return $fields;
    };

    try {
        wp_fts_test_seed_queue($fake, [2101]);
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        WP_FTS_Plugin::retry_failed_item_recovery(2101, 1);
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        WP_FTS_Plugin::retry_failed_item_recovery(2101, 1);
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);

        $backoff = WP_FTS_Plugin::failure_recovery_status(10, 2101);
        (new WP_FTS_Index_Queue($fake))->enqueue_many([2102, 2103]);
        $afterBackoff = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $idleBackoff = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $health = WP_FTS_Plugin::search_health();
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_same(3, $badAttempts, 'explicit retry setup should attempt the transiently bad item exactly three times');
    assert_same(1, $backoff['backoff_count'] ?? null, 'third repeated transient failure should remain in automatic backoff');
    assert_same(0, $backoff['rejected_count'] ?? null, 'transient failure should never become a terminal rejection');
    assert_same(true, $backoff['automatic_retry'] ?? null, 'failure status should state that the durable retry is automatic');
    assert_same(WP_FTS_Index_Queue::MAX_BACKOFF_SECONDS, $backoff['max_backoff_seconds'] ?? null, 'failure status should expose the capped queue backoff');
    assert_same('backoff', $backoff['recent_items'][0]['status'] ?? null, 'repeated transient item should be visible in backoff state');
    assert_same(3, $backoff['recent_items'][0]['failure_count'] ?? null, 'repeated transient item should keep its full failure count');
    assert_true((int) ($backoff['recent_items'][0]['retry_after_seconds'] ?? 0) > 0, 'repeated transient item should publish a future retry time');
    assert_same(2, $afterBackoff['indexed'] ?? null, 'automatic processing should use the whole batch for unrelated ready work');
    assert_same(2, $afterBackoff['queue_processed'] ?? null, 'unrelated durable generations should use the available batch capacity');
    assert_same(0, $idleBackoff['indexed'] ?? null, 'an immediate follow-up should not claim a future retry');
    assert_same(3, $badAttempts, 'future retry should not form a hot loop across immediate worker calls');
    assert_same('retry', $fake->queue[2101]['state'] ?? null, 'transient item should remain durably queued');
    assert_true((int) ($fake->queue[2101]['available_at'] ?? 0) > time(), 'transient item should retain a future queue availability');
    assert_true(!isset($fake->docs[2101]), 'failed transient item should not be marked indexed');
    assert_true(isset($fake->docs[2102], $fake->docs[2103]), 'unrelated items should be indexed while the bad item waits');
    assert_same(true, $health['has_more'] ?? null, 'future retry should remain visible as pending automatic work');
});

test_case('worker removes permanently rejected stale rows but preserves transient failures for retry', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $permanentId = 2151;
    $transientId = 2152;
    $posts = [
        $permanentId => wp_fts_test_backfill_post($permanentId, 'post', 'publish', 'Permanent analysis boundary'),
        $transientId => wp_fts_test_backfill_post($transientId, 'post', 'publish', 'Transient extraction failure'),
    ];
    $posts[$permanentId]->post_content = '<p>permanentstalesignal stable baseline</p>';
    $posts[$transientId]->post_content = '<p>transientstalesignal stable baseline</p>';
    foreach ($posts as $postId => $post) {
        $GLOBALS['wp_fts_test_posts'][$postId] = $post;
    }
    $transientAttempts = 0;

    try {
        $analyzer = WP_FTS_Plugin::runtime_analyzer();
        $storage = wp_fts_test_unleased_storage();
        foreach ($posts as $post) {
            wp_fts_test_replace_post($storage, $post, ['lang' => 'en'], $analyzer);
        }
        $permanentBefore = $fake->docs[$permanentId] ?? null;
        $transientBefore = $fake->docs[$transientId] ?? null;
        $permanentAnalysis = $analyzer->analyze_plain_content('permanentstalesignal', ['document_lang' => 'en']);
        $transientAnalysis = $analyzer->analyze_plain_content('transientstalesignal', ['document_lang' => 'en']);
        $permanentTerm = WP_FTS_TermNamespace::namespace_term(
            (string) ($permanentAnalysis[0]['lang'] ?? 'en'),
            (string) ($permanentAnalysis[0]['term'] ?? '')
        );
        $transientTerm = WP_FTS_TermNamespace::namespace_term(
            (string) ($transientAnalysis[0]['lang'] ?? 'en'),
            (string) ($transientAnalysis[0]['term'] ?? '')
        );
        assert_true(isset($fake->postings[$permanentTerm][$permanentId]), 'permanent rejection setup should retain one searchable stale posting');
        assert_true(isset($fake->postings[$transientTerm][$transientId]), 'transient failure setup should retain one searchable stale posting');

        $distinctTerms = [];
        for ($index = 0; $index <= WP_FTS_Analysis_Limits::MAX_DOCUMENT_DISTINCT_TERMS; $index++) {
            $distinctTerms[] = 'uniqueterm' . str_pad((string) $index, 4, '0', STR_PAD_LEFT);
        }
        $posts[$permanentId]->post_content = '<p>' . implode(' ', $distinctTerms) . '</p>';
        $posts[$transientId]->post_content = '<p>transient replacement content</p>';
        $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (
            array $fields,
            object $post
        ) use ($transientId, &$transientAttempts): array {
            if ((int) ($post->ID ?? 0) === $transientId) {
                $transientAttempts++;
                throw new RuntimeException('temporary extractor dependency unavailable');
            }

            return $fields;
        };
        wp_fts_test_seed_queue($fake, [$permanentId, $transientId]);

        $fake->queries = [];
        $result = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $failureStatementCount = count($fake->queries);
        $queueAfterFailure = $fake->queue;
        $docsAfterFailure = $fake->docs;
        $postingsAfterFailure = $fake->postings;
        $rejectionRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            2,
            static fn(): bool => !isset($fake->docs[$permanentId])
                && wp_fts_test_queue_ids($fake) === [$transientId]
        );
        $rejectionSummaries = array_values(array_filter(
            array_column($rejectionRuns, 'summary'),
            static fn(array $summary): bool => (int) ($summary['permanently_rejected'] ?? 0) === 1
        ));
        $rejection = $rejectionSummaries[0] ?? [];
        $permanentRecovery = WP_FTS_Plugin::failure_recovery_status(10, $permanentId);
        $transientRecovery = WP_FTS_Plugin::failure_recovery_status(10, $transientId);
        $beforeImmediateRetry = count($fake->queries);
        $immediateRetry = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $immediateRetryStatementCount = count($fake->queries) - $beforeImmediateRetry;
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_true(is_array($permanentBefore), 'permanent rejection setup should create a derived document row');
    assert_true(is_array($transientBefore), 'transient failure setup should create a derived document row');
    assert_same(0, $result['indexed'] ?? null, 'the retryable failure phase must report no indexed documents');
    assert_same(0, $result['committed'] ?? null, 'the retryable failure phase must not acknowledge the deferred permanent rejection');
    assert_same(0, $result['queue_processed'] ?? null, 'the retryable failure phase must not consume the deferred permanent generation');
    assert_same(0, $result['permanently_rejected'] ?? null, 'the deferred permanent rejection must not be reported before its delete-only phase commits');
    assert_same(1, $result['retryable_failures'] ?? null, 'transient extraction failure should have its own retryable outcome bucket');
    assert_same(1, $result['deferred'] ?? null, 'the permanent generation should be released for its independent delete-only phase');
    assert_same(1, $result['last_batch_failures'] ?? null, 'the isolated retryable phase should retain only its settled failure diagnostic');
    assert_same('failure_phase', $result['stop_reason'] ?? null, 'mixed failures should stop after the retryable settlement phase');
    assert_same([$permanentId, $transientId], array_map('intval', array_keys(array_filter(
        $queueAfterFailure,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'post'
    ))), 'the retryable phase should preserve both durable generations');
    assert_same('ready', $queueAfterFailure[$permanentId]['state'] ?? null, 'the permanent generation should remain immediately claimable for delete-only settlement');
    assert_same('retry', $queueAfterFailure[$transientId]['state'] ?? null, 'the transient generation should enter durable retry backoff');
    assert_same($permanentBefore, $docsAfterFailure[$permanentId] ?? null, 'the retryable phase must not delete the deferred permanent stale row');
    assert_true(isset($postingsAfterFailure[$permanentTerm][$permanentId]), 'the retryable phase must not delete the deferred permanent stale posting');
    assert_same($transientBefore, $docsAfterFailure[$transientId] ?? null, 'the retryable phase must preserve the transient stale row exactly');
    assert_true(isset($postingsAfterFailure[$transientTerm][$transientId]), 'the retryable phase must preserve the transient stale posting');

    assert_same(0, $rejection['indexed'] ?? null, 'the delete-only rejection phase should index no replacement document');
    assert_same(1, $rejection['committed'] ?? null, 'the rejection phase should commit its stale-row deletion and queue acknowledgement');
    assert_same(1, $rejection['queue_processed'] ?? null, 'the rejection phase should consume its exact owned queue generation');
    assert_same(1, $rejection['permanently_rejected'] ?? null, 'permanent analysis boundary should have its own truthful outcome bucket');
    assert_same(0, $rejection['retryable_failures'] ?? null, 'the delete-only rejection phase must not retry the backed-off transient generation');
    assert_true(!isset($fake->docs[$permanentId]), 'permanent analysis rejection should remove the stale derived document');
    assert_true(!isset($fake->postings[$permanentTerm][$permanentId]), 'permanent analysis rejection should remove every stale posting');
    assert_same($transientBefore, $fake->docs[$transientId] ?? null, 'transient exception should preserve the last known derived document exactly');
    assert_true(isset($fake->postings[$transientTerm][$transientId]), 'transient exception should preserve the last known posting until retry succeeds');
    assert_same([$transientId], wp_fts_test_queue_ids($fake), 'only the transient generation should remain durably queued');
    assert_same('retry', $fake->queue[$transientId]['state'] ?? null, 'transient generation should enter retry state');
    assert_same(1, $fake->queue[$transientId]['attempts'] ?? null, 'transient generation should increment its attempt count once');
    assert_true((int) ($fake->queue[$transientId]['available_at'] ?? 0) > time(), 'transient generation should use a future retry time');
    assert_same(1, $permanentRecovery['rejected_count'] ?? null, 'permanent boundary should be visible as rejected recovery state');
    assert_same('rejected', $permanentRecovery['recent_items'][0]['status'] ?? null, 'permanent boundary should not be presented as automatically retryable');
    assert_same(true, $permanentRecovery['permanent_rejections_require_content_change'] ?? null, 'recovery status should require canonical change before permanent retry');
    assert_same(1, $transientRecovery['backoff_count'] ?? null, 'transient exception should be visible in automatic backoff');
    assert_same('backoff', $transientRecovery['recent_items'][0]['status'] ?? null, 'transient exception should not be mislabeled as permanent rejection');
    assert_same(0, $immediateRetry['indexed'] ?? null, 'immediate worker pass should not reclaim the backed-off generation');
    assert_same(1, $transientAttempts, 'transient exception should not form a hot retry loop');
    $allRuns = [
        ['summary' => $result, 'statement_count' => $failureStatementCount],
        ...$rejectionRuns,
        ['summary' => $immediateRetry, 'statement_count' => $immediateRetryStatementCount],
    ];
    assert_same([], array_values(array_filter(
        array_column($allRuns, 'summary'),
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'a fresh mixed-failure fixture must never consume a stale-takeover control phase');
    assert_true(max(array_column($allRuns, 'statement_count')) <= 20, 'every retryable, rejection, and blocked-retry phase must stay inside the complete 20-statement ceiling');
});

if (!class_exists('WP_FTS_Test_Malicious_Serialized_Meta', false)) {
    class WP_FTS_Test_Malicious_Serialized_Meta
    {
        public static int $wakeups = 0;
        public static int $unserializes = 0;
        public static int $destructs = 0;
        public static int $magicReads = 0;

        /** Records any forbidden object wakeup during hostile metadata decoding. */
        public function __wakeup(): void
        {
            self::$wakeups++;
        }

        /** Records any forbidden object unserialization during hostile metadata decoding. */
        public function __unserialize(array $data): void
        {
            self::$unserializes++;
        }

        /** Records destruction of an object that hostile metadata must never instantiate. */
        public function __destruct()
        {
            self::$destructs++;
        }

        /** Records a forbidden magic read on hostile serialized metadata. */
        public function __get(string $name): mixed
        {
            self::$magicReads++;

            return 'MagicReadMustNotRun';
        }
    }
}

test_case('worker disables serialized objects and rejects deep or wide metadata without retaining graphs', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_options'][WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION] = ['structured_meta'];
    wp_fts_test_mark_search_takeover_ready();

    $class = WP_FTS_Test_Malicious_Serialized_Meta::class;
    $maliciousSignal = 'MaliciousMetaSignal';
    $malicious = 'O:' . strlen($class) . ':"' . $class . '":1:{s:5:"value";s:'
        . strlen($maliciousSignal) . ':"' . $maliciousSignal . '";}';
    $deepValue = 'DeepMetaSignal';
    for ($depth = 0; $depth < 20; $depth++) {
        $deepValue = [$deepValue];
    }
    $wideValue = array_fill(0, 2050, 'WideMetaSignal');
    $safeValue = ['outer' => ['inner' => 'SafeNestedMetaSignal']];
    $metaByPost = [
        2161 => $malicious,
        2162 => serialize($deepValue),
        2163 => serialize($wideValue),
        2164 => serialize($safeValue),
    ];
    foreach ($metaByPost as $postId => $metaValue) {
        $post = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Structured metadata ' . $postId);
        $GLOBALS['wp_fts_test_posts'][$postId] = $post;
        $GLOBALS['wp_fts_test_post_meta'][$postId]['structured_meta'] = [$metaValue];
    }
    WP_FTS_Test_Malicious_Serialized_Meta::$wakeups = 0;
    WP_FTS_Test_Malicious_Serialized_Meta::$unserializes = 0;
    WP_FTS_Test_Malicious_Serialized_Meta::$destructs = 0;
    WP_FTS_Test_Malicious_Serialized_Meta::$magicReads = 0;
    wp_fts_test_seed_queue($fake, array_keys($metaByPost));

    try {
        $fake->queries = [];
        $result = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 4]);
        $rejectionStatementCount = count($fake->queries);
        $queueAfterRejection = $fake->queue;
        $docsAfterRejection = $fake->docs;
        $successorRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            4,
            static fn(): bool => wp_fts_test_queue_ids($fake) === []
        );
        $safeResults = WP_FTS_Plugin::search('SafeNestedMetaSignal', ['limit' => 10]);
        $maliciousResults = WP_FTS_Plugin::search($maliciousSignal, ['limit' => 10]);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(0, WP_FTS_Test_Malicious_Serialized_Meta::$wakeups, 'class-disabled metadata decoding must not execute __wakeup');
    assert_same(0, WP_FTS_Test_Malicious_Serialized_Meta::$unserializes, 'class-disabled metadata decoding must not execute __unserialize');
    assert_same(0, WP_FTS_Test_Malicious_Serialized_Meta::$destructs, 'class-disabled metadata decoding must not construct an application object whose destructor can run');
    assert_same(0, WP_FTS_Test_Malicious_Serialized_Meta::$magicReads, 'bounded flattening must not invoke object magic access');
    assert_same(0, $result['indexed'] ?? null, 'the delete-only rejection phase must not publish valid replacement documents');
    assert_same(2, $result['committed'] ?? null, 'the rejection phase should acknowledge exactly the two deterministic poison generations');
    assert_same(2, $result['permanently_rejected'] ?? null, 'deep and wide graphs should be terminal bounded-analysis rejections');
    assert_same(0, $result['retryable_failures'] ?? null, 'deterministic graph limits should not enter retry backoff');
    assert_same(2, $result['deferred'] ?? null, 'both valid metadata generations should be released for a bounded successor');
    assert_same([2161, 2164], array_map('intval', array_keys(array_filter(
        $queueAfterRejection,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'post'
    ))), 'the rejection phase should retain exactly the two valid metadata generations');
    assert_same('ready', $queueAfterRejection[2161]['state'] ?? null, 'the object-skipping generation should remain immediately claimable');
    assert_same('ready', $queueAfterRejection[2164]['state'] ?? null, 'the safe nested generation should remain immediately claimable');
    assert_same([], $docsAfterRejection, 'the delete-only rejection phase should publish no valid derived row');
    $allRuns = [
        ['summary' => $result, 'statement_count' => $rejectionStatementCount],
        ...$successorRuns,
    ];
    $allSummaries = array_column($allRuns, 'summary');
    assert_same(2, array_sum(array_map(static fn(array $summary): int => (int) ($summary['indexed'] ?? 0), $allSummaries)), 'the complete bounded sequence should index both valid metadata documents exactly once');
    assert_same(4, array_sum(array_map(static fn(array $summary): int => (int) ($summary['committed'] ?? 0), $allSummaries)), 'the complete bounded sequence should resolve all four owned generations exactly once');
    assert_same(2, array_sum(array_map(static fn(array $summary): int => (int) ($summary['permanently_rejected'] ?? 0), $allSummaries)), 'the complete bounded sequence should report exactly two permanent rejections');
    assert_same([], array_values(array_filter(
        $allSummaries,
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'a fresh structured-metadata fixture must never consume a stale-takeover control phase');
    assert_true(max(array_column($allRuns, 'statement_count')) <= 20, 'every rejection and valid-metadata successor phase must stay inside the complete 20-statement ceiling');
    assert_same([], wp_fts_test_queue_ids($fake), 'bounded metadata outcomes should acknowledge every deterministic generation');
    assert_same([2164], array_column($safeResults, 'doc_id'), 'safe nested scalar metadata should remain searchable after immediate flattening');
    assert_same([], $maliciousResults, 'properties from a disabled serialized object must never enter searchable text');
    assert_true(isset($fake->docs[2161], $fake->docs[2164]), 'safe documents should retain derived rows');
    assert_true(!isset($fake->docs[2162], $fake->docs[2163]), 'deep and wide metadata should leave no stale derived rows');
});

test_case('changed worker defers bounded dictionary cleanup to the queue-empty pass', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->options = 'wp_options';
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(2171, 'post', 'publish', 'Cleanup follow-up document');
    $GLOBALS['wp_fts_test_posts'][2171] = $post;
    for ($index = 0; $index < 7; $index++) {
        $fake->ftsTerms['empty-follow-up-' . $index] = ['doc_freq' => 0];
    }
    wp_fts_test_seed_queue($fake, [2171]);

    try {
        $fake->queries = [];
        $changed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $changedQueries = $fake->queries;
        $fake->queries = [];
        $cleanup = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $cleanupQueries = $fake->queries;
        $activeToken = new ReflectionProperty(WP_FTS_Plugin::class, 'active_index_writer_token');
        $activeToken->setAccessible(true);
        $activeTokenAfter = $activeToken->getValue();
    } finally {
        $wpdb = $oldWpdb;
    }

    $ackQueryIndex = array_search(true, array_map(
        static fn(string $sql): bool => str_contains($sql, '/* wp_fts:atomic-worker-ack */'),
        $changedQueries
    ), true);
    $leaseDeleteIndex = array_search(true, array_map(
        static fn(string $sql): bool => str_starts_with($sql, 'DELETE FROM wp_options WHERE option_name = %s AND option_value = %s'),
        $changedQueries
    ), true);

    assert_same(1, $changed['indexed'] ?? null, 'changed pass should index its claimed document');
    assert_same(false, $changed['cleanup_pending'] ?? null, 'the changed pass should not report cleanup debt it deliberately did not probe');
    assert_same(true, $changed['has_more'] ?? null, 'an exactly full one-row manual claim should retain its conservative queue-boundary signal');
    assert_same(0, $changed['empty_terms_cleaned'] ?? null, 'the changed pass should spend no extra dictionary-cleanup statement');
    assert_same(0, count(array_filter($changedQueries, static fn(string $sql): bool => str_contains($sql, 'bounded_empty_terms'))), 'a changed pass should execute no opportunistic dictionary cleanup');
    assert_same(7, $cleanup['empty_terms_cleaned'] ?? null, 'the immediate queue-empty pass should remove the complete sub-limit debt page');
    assert_same(1, count(array_filter($cleanupQueries, static fn(string $sql): bool => str_contains($sql, 'bounded_empty_terms'))), 'the queue-empty pass should pay exactly one bounded cleanup statement');
    assert_same([], array_values(array_filter(array_keys($fake->ftsTerms), static fn(string $term): bool => str_starts_with($term, 'empty-follow-up-'))), 'sub-limit cleanup should remove every seeded zero-frequency term');
    assert_same(1, count(array_filter($changedQueries, static fn(string $sql): bool => str_contains($sql, '/* wp_fts:atomic-worker-ack */'))), 'successful MySQL worker should acknowledge the exact claimed generation once');
    assert_same(1, count(array_filter($changedQueries, static fn(string $sql): bool => str_starts_with($sql, 'DELETE FROM wp_options WHERE option_name = %s AND option_value = %s'))), 'successful MySQL worker should retire the exact writer option once after publication');
    assert_true(is_int($leaseDeleteIndex) && is_int($ackQueryIndex) && $ackQueryIndex < $leaseDeleteIndex, 'the exact option lease must remain owned until after the transactional work acknowledgement');
    assert_same([], wp_fts_test_queue_ids($fake), 'atomic acknowledgement should remove the exact successful generation');
    assert_true(!isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]), 'atomic acknowledgement should remove the exact writer option row');
    assert_same(null, $activeTokenAfter, 'atomic acknowledgement should clear request-local writer ownership');
});

test_case('queue-empty cleanup failure never reopens an acknowledged document generation', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->options = 'wp_options';
    $wpdb = $fake;
