    $GLOBALS['wp_fts_test_posts'][2173] = $post;
    $fake->ftsTerms['cleanup-failure-debt'] = ['doc_freq' => 0];
    wp_fts_test_seed_queue($fake, [2173]);
    WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
    $fake->failQueryNeedle = 'bounded_empty_terms';
    $fake->failQueryNeedleOccurrence = 1;
    $error = null;

    try {
        $fake->queries = [];
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
