    assert_true(!isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]), 'outer failure cleanup should release the exact writer lease');
    assert_same(null, $activeTokenAfter, 'outer failure cleanup should clear request-local writer ownership');
});

test_case('analyzer construction failure uses durable systemic cron backoff', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_posts'][2181] = wp_fts_test_backfill_post(2181, 'post', 'publish', 'Analyzer outage document');
    wp_fts_test_seed_queue($fake, [2181]);
    $analyzerAttempts = 0;
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::ANALYZER_OPTIONS_FILTER]
        = static function (array $options) use (&$analyzerAttempts): array {
            $analyzerAttempts++;
            throw new RuntimeException('simulated shared analyzer dependency outage');
        };
    WP_FTS_Plugin::reset_request_caches();
    $startedAt = time();
    $firstError = null;

    try {
        WP_FTS_Plugin::process_scheduled_indexing();
    } catch (Throwable $error) {
        $firstError = $error;
    }
    $firstHealth = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
    $secondError = null;
    try {
        WP_FTS_Plugin::process_scheduled_indexing();
    } catch (Throwable $error) {
        $secondError = $error;
    } finally {
        $finishedAt = time();
        $wpdb = $oldWpdb;
    }

    $queueRow = $fake->queue[2181] ?? null;
    $scheduledAt = (int) ($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]['timestamp'] ?? 0);
    $queueSchedules = array_values(array_filter(
        $GLOBALS['wp_fts_test_schedule_calls'],
        static fn(array $call): bool => ($call['hook'] ?? '') === WP_FTS_Plugin::CRON_HOOK
    ));
    $diagnostics = is_array($firstHealth['latest_batch_diagnostics'] ?? null)
        ? $firstHealth['latest_batch_diagnostics']
        : [];
    assert_true($firstError instanceof Throwable, 'shared analyzer outage should remain visible to the cron caller');
    assert_same(null, $secondError, 'immediate repeated cron invocation should find the failed claim in durable backoff instead of rebuilding the analyzer');
    assert_same(1, $analyzerAttempts, 'durable backoff should prevent an immediate second analyzer construction attempt');
    assert_true(is_array($queueRow), 'analyzer outage must retain the claimed generation');
    assert_same('retry', $queueRow['state'] ?? null, 'analyzer outage should use the queue retry state rather than immediate release');
    assert_true((int) ($queueRow['available_at'] ?? 0) >= $startedAt + WP_FTS_Index_Queue::BASE_BACKOFF_SECONDS, 'analyzer retry row should carry the full 300-second base backoff');
    assert_same(1, count($queueSchedules), 'repeated cron calls should retain one systemic queue watchdog');
    assert_true($scheduledAt >= $startedAt + WP_FTS_Index_Queue::BASE_BACKOFF_SECONDS, 'analyzer outage watchdog must not use the one-second path');
    assert_true($scheduledAt <= $finishedAt + WP_FTS_Index_Queue::BASE_BACKOFF_SECONDS, 'analyzer outage watchdog should target the exact bounded retry window');
    assert_same('analyzer_unavailable', $diagnostics['stop_reason'] ?? null, 'persisted manual/cron diagnostics should identify the systemic analyzer dependency');
    assert_same('scheduled_at_availability', $diagnostics['reschedule_decision'] ?? null, 'diagnostics should describe the delayed retry rather than an immediate continuation');
});

test_case('schema mismatch keeps queue processing on the 300-second systemic path', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
