test_case('full empty-term cleanup page reschedules once and the sub-limit tail terminates', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $fake->recordReadQueries = true;
    $total = WP_FTS_Storage_Mysql::MAX_EMPTY_TERM_CLEANUP + 1;
    for ($index = 0; $index < $total; $index++) {
        $fake->ftsTerms['empty-page-' . str_pad((string) $index, 4, '0', STR_PAD_LEFT)] = ['doc_freq' => 0];
    }

    try {
        $fake->queries = [];
        $full = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $fullQueries = $fake->queries;
        $fake->queries = [];
        $tail = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $tailQueries = $fake->queries;
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(WP_FTS_Storage_Mysql::MAX_EMPTY_TERM_CLEANUP, $full['empty_terms_cleaned'] ?? null, 'one pass should never delete beyond the indexed cleanup page');
    assert_same(true, $full['cleanup_pending'] ?? null, 'a full page should conservatively request one immediate continuation');
    assert_same(true, $full['has_more'] ?? null, 'a full cleanup page should keep the bounded worker scheduled');
    assert_same(0, count(array_filter($fullQueries, static function (mixed $query): bool {
        $sql = is_array($query) ? (string) ($query[0] ?? '') : (string) $query;
        return str_contains($sql, 'bounded_next_available');
    })), 'full cleanup page should not add a future-work timing query');
    assert_same(1, $tail['empty_terms_cleaned'] ?? null, 'the next pass should remove only the remaining cleanup tail');
    assert_same(false, $tail['cleanup_pending'] ?? null, 'a sub-limit tail should prove cleanup completion');
    assert_same(false, $tail['has_more'] ?? null, 'completed cleanup with no queue work should stop rescheduling');
    assert_same(1, count(array_filter($tailQueries, static function (mixed $query): bool {
        $sql = is_array($query) ? (string) ($query[0] ?? '') : (string) $query;
        return str_contains($sql, 'bounded_next_available');
    })), 'completed cleanup should consult future queue availability exactly once');
    assert_same([], $fake->ftsTerms, 'two bounded passes should remove the 1,001-term churn fixture');
});

test_case('wp-cli failed item recovery controls emit stable json and only mutate intended metadata or queue state', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_posts'][3101] = wp_fts_test_backfill_post(3101, 'post', 'publish', 'CLI Failed Recovery');
    wp_fts_test_seed_queue($fake, [3101]);
    $analysisAttempts = 0;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post) use (&$analysisAttempts): array {
        if ((int) ($post->ID ?? 0) === 3101) {
            $analysisAttempts++;
            throw new RuntimeException("cli failure DELETE FROM wp_users token=must-not-render\n#0 stack");
        }

        return $fields;
    };

    try {
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $command = new WP_FTS_WPCLI_Command();

        $listRaw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->failed_items([], ['format' => 'json']);
        });
        $list = wp_fts_test_decode_cli_json_object($listRaw);
        $listJson = json_encode($list, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);

        $retryRaw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->retry_failed_item([3101], ['format' => 'json']);
        });
        $retry = wp_fts_test_decode_cli_json_object($retryRaw);
        $docsAfterRetry = $fake->docs;
        $attemptsAfterRetry = $analysisAttempts;
        $queueAfterRetry = wp_fts_test_queue_ids($fake);

        $clearRaw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->clear_failed_item([3101], ['format' => 'json']);
        });
        $clear = wp_fts_test_decode_cli_json_object($clearRaw);
        $afterClear = WP_FTS_Plugin::failure_recovery_status();
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_same('wp-fts-failure-recovery-v1', $list['schema'] ?? null, 'failed-items JSON should expose stable schema');
    assert_same(1, $list['total_count'] ?? null, 'failed-items JSON should expose record count');
    assert_same(3101, $list['recent_items'][0]['post_id'] ?? null, 'failed-items JSON should expose the failed post id');
    assert_true(!str_contains($listJson, 'DELETE FROM'), 'failed-items JSON should not expose raw SQL');
    assert_true(!str_contains($listJson, '#0'), 'failed-items JSON should not expose stack traces');
    assert_true(!str_contains($listJson, 'must-not-render'), 'failed-items JSON should redact secret-looking values');

    assert_same('retry', $retry['action'] ?? null, 'retry JSON should identify the action');
    assert_same('retryable', $retry['status'] ?? null, 'retry JSON should report retryable status');
    assert_same(1, $retry['matched_count'] ?? null, 'retry JSON should report the selected record');
    assert_same(1, $retry['queued_count'] ?? null, 'retry should enqueue the selected failed item');
    assert_same([3101], $queueAfterRetry, 'retry should only change queue state by adding the selected post');
    assert_same([], $docsAfterRetry, 'retry should not index content directly');
    assert_same(1, $attemptsAfterRetry, 'retry should not attempt indexing in the retry command');

    assert_same('clear', $clear['action'] ?? null, 'clear JSON should identify the action');
    assert_same('cleared', $clear['status'] ?? null, 'clear JSON should report cleared status');
    assert_same(1, $clear['matched_count'] ?? null, 'clear JSON should report the selected record');
    assert_same(0, $afterClear['total_count'] ?? null, 'clear should remove failed-item recovery metadata');
    assert_same([3101], wp_fts_test_queue_ids($fake), 'clear should not remove existing queued retry state');
    assert_same([], $fake->docs, 'clear should not delete or create indexed rows');
});

test_case('failure recovery status and health rendering are read only and redacted', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = [
        'failure_history' => [
            [
                'post_id' => 4101,
                'title' => 'Health <b>Failure</b>',
                'status' => 'retryable',
                'failure_count' => 3,
                'attempt_count' => 3,
                'first_failed_at' => '2026-06-20 10:00:00',
                'last_failed_at' => '2026-06-20 10:10:00',
                'mode' => 'cron',
                'source' => 'cron',
                'error_class' => 'RuntimeException',
                'error_message' => "SELECT * FROM wp_users\n#0 stack token=must-not-render",
                'error_summary' => "RuntimeException: SELECT * FROM wp_users\n#0 stack token=must-not-render",
            ],
        ],
    ];
    $optionsBefore = $GLOBALS['wp_fts_test_options'];

    try {
        $status = WP_FTS_Plugin::operator_status();
        $html = wp_fts_test_capture_admin_settings_tab('health');
        $encodedStatus = json_encode($status['failure_recovery'] ?? [], JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
    } finally {
        $wpdb = $oldWpdb;
    }

    $recovery = is_array($status['failure_recovery'] ?? null) ? $status['failure_recovery'] : [];
    assert_same('wp-fts-failure-recovery-v1', $recovery['schema'] ?? null, 'operator status should expose failure recovery schema');
    assert_same(1, $recovery['total_count'] ?? null, 'operator status should expose failure recovery count');
    assert_same(1, $recovery['retryable_count'] ?? null, 'operator status should count retryable records');
    assert_same(0, $recovery['rejected_count'] ?? null, 'transient failures should not be mislabeled as permanent rejection');
    assert_same(true, $recovery['automatic_retry'] ?? null, 'operator status should report that transient work retries automatically');
    assert_same(WP_FTS_Index_Queue::MAX_BACKOFF_SECONDS, $recovery['max_backoff_seconds'] ?? null, 'operator status should expose the durable queue backoff ceiling');
    assert_same('Health Failure (ID 4101)', $recovery['recent_items'][0]['label'] ?? null, 'operator status should expose bounded sanitized item labels');
    assert_same('retryable', $recovery['recent_items'][0]['status'] ?? null, 'retryable records should retain their automatic-retry status');
    assert_contains('Failed items are retryable', (string) ($recovery['advice'] ?? ''), 'operator status should expose automatic recovery advice');
    assert_contains('<h3>Failure recovery</h3>', $html, 'Health tab should render failure recovery visibility');
    assert_contains('<th scope="row">Failed item history</th><td>1 tracked (1 retryable, 0 waiting, 0 rejected)</td>', $html, 'Health tab should render failure recovery counts');
    assert_contains('Health Failure (ID 4101) [retryable]', $html, 'Health tab should render normalized recent failed item labels');
    assert_true(!str_contains($encodedStatus . $html, 'SELECT * FROM'), 'failure recovery status and health should not expose raw SQL');
    assert_true(!str_contains($encodedStatus . $html, '#0'), 'failure recovery status and health should not expose stack traces');
    assert_true(!str_contains($encodedStatus . $html, 'must-not-render'), 'failure recovery status and health should redact secret-looking values');
    assert_same([], $GLOBALS['wp_fts_test_added_options'], 'read-only failure recovery status should not add options');
    assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'read-only failure recovery status should not update options');
    assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'read-only failure recovery status should not delete options');
    assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'read-only failure recovery status should not schedule queue work');
    assert_same([], $fake->docs, 'read-only failure recovery status should not index content');
    assert_same([], $fake->queries, 'read-only failure recovery status should not write index storage');
    assert_same($optionsBefore, $GLOBALS['wp_fts_test_options'], 'read-only failure recovery status should leave stored options unchanged');
});

test_case('scheduled indexing cron expands only one bounded scope page and reschedules remaining work', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_backfill_posts($fake, 25);

    try {
        WP_FTS_Plugin::activate();
        unset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]);

        $result = WP_FTS_Plugin::process_scheduled_indexing();
        assert_same(0, $result['indexed'], 'a scope pass should not mix corpus discovery with document indexing');
        assert_same(0, $result['backfill_processed'], 'scope expansion should only enqueue durable direct work');
        assert_same(20, $result['backfill_scanned'], 'cron should keyset-scan at most the default 20-item scope page');
        assert_same(20, $result['backfill_queued'], 'cron should enqueue exactly the bounded source page');
        assert_same(0, count($fake->docs), 'scope expansion should not index source content in the same run');
        assert_true((bool) $result['has_more'], 'cron should report that more eligible content remains');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'cron should schedule another run when scope or direct work remains');
        $health = WP_FTS_Plugin::search_health();
        assert_same([], $health['latest_batch_diagnostics'] ?? [], 'ordinary scope progress should not rewrite global health diagnostics');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('scheduled indexing cron reschedules when direct work exceeds the bounded batch', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_backfill_posts($fake, 25);
    for ($post_id = 1; $post_id <= 20; $post_id++) {
        $GLOBALS['wp_fts_test_posts'][$post_id] = wp_fts_test_backfill_post($post_id);
    }
    wp_fts_test_seed_queue($fake, range(1, 25));

    try {
        $result = WP_FTS_Plugin::process_scheduled_indexing();
        assert_same(20, $result['indexed'], 'cron should spend the default batch on queued work first');
        assert_same(20, $result['queue_processed'], 'cron should drain the queued work that filled the batch');
        assert_same(0, $result['backfill_processed'], 'direct work should not trigger an implicit corpus scan');
        assert_same(range(21, 25), wp_fts_test_queue_ids($fake), 'one bounded batch should leave later direct generations queued');
        assert_same(20, count($fake->docs), 'queued indexing should consume exactly the default batch');
        assert_true(!isset($fake->docs[21]), 'later direct work should be left for a follow-up run');
        assert_true((bool) $result['has_more'], 'cron should report direct work beyond the batch cap');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'cron should reschedule while direct work remains');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('future retry watchdog sleeps without polling and new ready work brings it forward', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    foreach ([31, 32, 33] as $postId) {
        $GLOBALS['wp_fts_test_posts'][$postId] = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Watchdog ' . $postId);
    }
    $queue = new WP_FTS_Index_Queue($fake);
    $queue->enqueue(31);
    $claim = $queue->claim_batch(1)[0] ?? null;
    assert_true(is_array($claim), 'watchdog fixture should own the retry generation');
    $retry = $queue->fail($claim);
    $retryAt = (int) ($retry['available_at'] ?? 0);

    try {
        $waiting = WP_FTS_Plugin::process_scheduled_indexing();
        assert_same(0, $waiting['indexed'] ?? null, 'cron should not reclaim a future retry early');
        assert_same(true, $waiting['has_more'] ?? null, 'the future retry should remain visible as pending work');
        assert_same('scheduled_at_availability', $waiting['reschedule_decision'] ?? null, 'future-only work should schedule once rather than enter a prompt polling loop');
        assert_same($retryAt, $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]['timestamp'] ?? null, 'the watchdog should sleep until the exact retry boundary');

        $cronWritesBeforeBringForward = $GLOBALS['wp_fts_test_cron_write_count'];
        $accepted = WP_FTS_Plugin::invalidate_post_content_dependencies(32);
        $broughtForward = (int) ($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]['timestamp'] ?? 0);
        assert_same(1, $accepted, 'new canonical work should durably enqueue while a retry watchdog sleeps');
        assert_true($broughtForward < $retryAt, 'new immediately ready work must replace the far-future watchdog');
        assert_true($broughtForward >= time() + 59 && $broughtForward <= time() + 61, 'ordinary foreground work should retain its bounded sixty-second schedule');
        assert_same([], $GLOBALS['wp_fts_test_cleared_hooks'], 'bringing work forward must not clear the valid singleton before replacing it');
        assert_same(
            $cronWritesBeforeBringForward + 1,
            $GLOBALS['wp_fts_test_cron_write_count'],
            'bringing work forward must replace the singleton in one cron-option write'
        );

        $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK] = [
            'timestamp' => $retryAt,
            'hook' => WP_FTS_Plugin::CRON_HOOK,
            'args' => [],
        ];
        $GLOBALS['wp_fts_test_set_cron_array_succeeds'] = false;
        $cronWritesBeforeFailedReplacement = $GLOBALS['wp_fts_test_cron_write_count'];
        $accepted = WP_FTS_Plugin::invalidate_post_content_dependencies(33);
        assert_same(1, $accepted, 'new work must remain durable when a cron singleton replacement fails');
        assert_same(
            $retryAt,
            $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]['timestamp'] ?? null,
            'a failed one-write replacement must retain the valid later watchdog'
        );
        assert_same(
            $cronWritesBeforeFailedReplacement + 1,
            $GLOBALS['wp_fts_test_cron_write_count'],
            'a failed singleton replacement must make only one cron-option write attempt'
        );
        assert_same([], $GLOBALS['wp_fts_test_cleared_hooks'], 'a failed replacement must never clear the retained watchdog');
    } finally {
        $GLOBALS['wp_fts_test_set_cron_array_succeeds'] = true;
        $wpdb = $oldWpdb;
    }
});

