test_case('save status and delete hooks defer tombstones behind the writer lease', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    foreach ([801, 802, 803] as $postId) {
        $fake->docs[$postId] = [
            'lang' => 'en',
            'doc_len' => 1,
            'content_hash' => 'hook-lock-' . $postId,
            'is_deleted' => 0,
        ];
    }
    $activeLock = [
        'token' => 'other-hook-writer',
        'mode' => 'wp-cli-reindex',
        'started_at' => time(),
        'expires_at' => time() + 300,
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $activeLock;
    $preFlushQueueIds = [];
    $preFlushScopes = [];

    try {
        WP_FTS_Plugin::handle_post_save(801, (object) [
            'ID' => 801,
            'post_type' => 'post',
            'post_status' => 'trash',
            'post_password' => '',
        ]);
        WP_FTS_Plugin::handle_post_save(802, (object) [
            'ID' => 802,
            'post_type' => 'post',
            'post_status' => 'trash',
            'post_password' => '',
        ]);
        WP_FTS_Plugin::handle_post_delete(803);
        $preFlushQueueIds = wp_fts_test_queue_ids($fake);
        $preFlushScopes = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(0, $fake->docs[801]['is_deleted'], 'save hook should not tombstone while another writer owns the lease');
    assert_same(0, $fake->docs[802]['is_deleted'], 'status hook should not tombstone while another writer owns the lease');
    assert_same(0, $fake->docs[803]['is_deleted'], 'delete hook should not tombstone while another writer owns the lease');
    assert_same([801], $preFlushQueueIds, 'the first lifecycle should remain directly queued while later targets share one request fence');
    assert_same(1, count($preFlushScopes), 'the second distinct lifecycle should install one request-global fence');
    assert_same('guarded', $preFlushScopes[0]['state'] ?? null, 'the request-global row should stay fail closed until shutdown');
    assert_same([801, 802, 803], wp_fts_test_queue_ids($fake), 'shutdown should hand every exact lifecycle target to the coordinated writer');
    assert_same([], array_values(array_filter(
        $fake->queue,
        static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
    )), 'the exact post handoff should remove its temporary request-global fence');
    assert_same($activeLock, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? null, 'lifecycle hooks should leave the active writer capability untouched');
    assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'deferred lifecycle tombstones should schedule the queue processor');
});

test_case('foreground mutations persist exact post rows with bounded write complexity', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $countWorkWrites = static fn(WP_FTS_Test_WPDB $fake): int => count(array_filter(
        $fake->queries,
        static fn(string $query): bool => str_contains($query, 'wp_fts_work')
            && (str_starts_with($query, 'INSERT ') || str_starts_with($query, 'DELETE ') || str_starts_with($query, 'UPDATE '))
    ));

    try {
        $single = new WP_FTS_Test_WPDB();
        $wpdb = $single;
        wp_fts_test_reset_wordpress_fakes();
        WP_FTS_Plugin::handle_post_save(901, (object) ['ID' => 901]);
        assert_same(1, $countWorkWrites($single), 'one foreground mutation should become durable with exactly one FTS write');
        assert_same([901], wp_fts_test_queue_ids($single), 'one foreground mutation should use one direct durable generation');

        $bulk = new WP_FTS_Test_WPDB();
        $wpdb = $bulk;
        wp_fts_test_reset_wordpress_fakes();
        assert_same(2, WP_FTS_Plugin::invalidate_post_content_dependencies([911, 912]), 'one bulk call should accept both distinct ids');
        assert_same(1, $countWorkWrites($bulk), 'one bounded bulk call should persist all ids in one set-oriented UPSERT');
        assert_same([911, 912], wp_fts_test_queue_ids($bulk), 'the bounded bulk call should expose both exact durable generations before returning');
        assert_same([], array_values(array_filter(
            $bulk->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        )), 'direct bulk invalidation must not create a corpus scope or suppress unrelated search');

        $sequential = new WP_FTS_Test_WPDB();
        $wpdb = $sequential;
        wp_fts_test_reset_wordpress_fakes();
        WP_FTS_Plugin::handle_post_save(921, (object) ['ID' => 921]);
        WP_FTS_Plugin::handle_post_save(922, (object) ['ID' => 922]);
        assert_same(2, $countWorkWrites($sequential), 'the second distinct hook should replace per-post fan-out with one global fence');
        assert_same([921], wp_fts_test_queue_ids($sequential), 'the global fence should remain closed until request shutdown hands off the retained ids');
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        assert_same(4, $countWorkWrites($sequential), 'two or more sequential hooks should use one direct write, one global fence, one bounded post handoff, and one sentinel delete');
        assert_same([921, 922], wp_fts_test_queue_ids($sequential), 'shutdown should atomically expose both exact desired generations');
        assert_same([], array_values(array_filter(
            $sequential->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        )), 'an exact post handoff should delete its request-global visibility fence');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('one thousand taxonomy bulk requests coalesce to one corpus scan', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
