    $directScopesProperty = (new ReflectionClass(WP_FTS_Plugin::class))
        ->getProperty('foreground_direct_scope_keys');

    try {
        for ($request = 0; $request < 1000; $request++) {
            WP_FTS_Plugin::reset_request_caches();
            $before = count($fake->queries);
            $firstTerm = 100000 + ($request * 2);
            $secondTerm = $firstTerm + 1;
            WP_FTS_Plugin::handle_taxonomy_term_pre_edit(
                $firstTerm,
                'category',
                ['term_taxonomy_id' => $firstTerm + 1000000]
            );
            WP_FTS_Plugin::handle_taxonomy_term_edit(
                $firstTerm,
                $firstTerm + 1000000,
                'category'
            );
            WP_FTS_Plugin::handle_taxonomy_term_pre_edit(
                $secondTerm,
                'category',
                ['term_taxonomy_id' => $secondTerm + 1000000]
            );
            WP_FTS_Plugin::handle_taxonomy_term_edit(
                $secondTerm,
                $secondTerm + 1000000,
                'category'
            );
            $maxDirectScopes = max(
                $maxDirectScopes,
                count((array) $directScopesProperty->getValue())
            );
            WP_FTS_Plugin::flush_foreground_bulk_mutations();

            $requestQueries = array_map(
                static fn(mixed $query): string => is_array($query)
                    ? (string) ($query[0] ?? '')
                    : (string) $query,
                array_slice($fake->queries, $before)
            );
            $workWrites = array_values(array_filter($requestQueries, static fn(string $sql): bool =>
                str_contains($sql, 'wp_fts_work')
                && (
                    str_starts_with($sql, 'INSERT ')
                    || str_starts_with($sql, 'UPDATE ')
                    || str_starts_with($sql, 'DELETE ')
                )
            ));
            $maxWorkWrites = max($maxWorkWrites, count($workWrites));
            foreach ($workWrites as $sql) {
                $maxStatementBytes = max($maxStatementBytes, strlen($sql));
            }
        }

        $scopes = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        $globalScopeKey = (string) (new ReflectionClass(WP_FTS_Plugin::class))
            ->getConstant('GLOBAL_RECONCILIATION_SCOPE_KEY');
        $beforeWorker = count($fake->queries);
        $completed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
        $workerQueries = array_map(
            static fn(mixed $query): string => is_array($query)
                ? (string) ($query[0] ?? '')
                : (string) $query,
            array_slice($fake->queries, $beforeWorker)
        );
        $corpusPages = array_values(array_filter(
            $workerQueries,
            static fn(string $sql): bool => str_starts_with($sql, '/* wp_fts:corpus-scope-page */')
        ));
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(1, count($scopes), '1,000 request-unique sentinels must leave O(1) durable scope debt');
    assert_same('scope:' . hash('sha256', $globalScopeKey), $scopes[0]['job_key'] ?? null, 'all bulk requests must converge on the canonical corpus identity');
    assert_same(1000, $scopes[0]['generation'] ?? null, 'the canonical row should coalesce every request as one latest desired generation');
    assert_same(WP_FTS_Index_Queue::MAX_FOREGROUND_DIRECT_SCOPES, $maxDirectScopes, 'bulk mode must structurally cap direct scope ownership at one');
    assert_true($maxWorkWrites <= 6, 'each taxonomy bulk request must use no more than six indexed queue writes');
    assert_true($maxStatementBytes < 1048576, 'every foreground queue statement must stay below one MiB');
    assert_same(1, count($corpusPages), 'the coalesced frontier must require exactly one eventual corpus keyset scan');
    assert_same(true, $completed['scope_completed'] ?? null, 'the single empty-corpus page should acknowledge the canonical generation');
    assert_same([], array_values(array_filter(
        $fake->queue,
        static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
    )), 'one completed corpus pass must leave no random or targeted scope residue');
});

test_case('abandoned global sentinels recover into one canonical corpus scan', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $queue = new WP_FTS_Index_Queue($fake);
    $now = time();
    $maxRecoveryWorkQueries = 0;

    try {
        for ($sentinel = 0; $sentinel < 64; $sentinel++) {
            $queue->fence_scope(
                'abandoned-foreground-bulk:' . $sentinel,
                'guard:' . substr(hash('sha256', 'abandoned-token:' . $sentinel), 0, 32),
                ['reason' => 'foreground_bulk_mutation'],
                $now - 1,
                WP_FTS_Index_Queue::SCOPE_COVERAGE_GLOBAL
            );
        }
        $fake->queries = [];
        for ($pass = 0; $pass < 64; $pass++) {
            $before = count($fake->queries);
            WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
            $queries = array_map(
                static fn(mixed $query): string => is_array($query)
                    ? (string) ($query[0] ?? '')
                    : (string) $query,
                array_slice($fake->queries, $before)
            );
            $maxRecoveryWorkQueries = max($maxRecoveryWorkQueries, count(array_filter(
                $queries,
                static fn(string $sql): bool => str_contains($sql, 'wp_fts_work')
            )));
        }
        $scopesBeforeScan = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        $beforeScan = count($fake->queries);
        $completed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
        $scanQueries = array_map(
            static fn(mixed $query): string => is_array($query)
                ? (string) ($query[0] ?? '')
                : (string) $query,
            array_slice($fake->queries, $beforeScan)
        );
        $corpusPages = array_values(array_filter(
            $scanQueries,
            static fn(string $sql): bool => str_starts_with($sql, '/* wp_fts:corpus-scope-page */')
        ));
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(1, count($scopesBeforeScan), '64 crashed requests must coalesce to one canonical scope before source expansion');
    assert_same(WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS, $scopesBeforeScan[0]['scope_coverage'] ?? null, 'recovery must replace visibility sentinels with corpus authority');
    assert_same(64, $scopesBeforeScan[0]['generation'] ?? null, 'every abandoned boundary should advance the one latest desired generation');
    assert_true($maxRecoveryWorkQueries <= 4, 'each abandoned-sentinel recovery must use at most claim, confirmation, canonical UPSERT, and exact delete');
    assert_same(1, count($corpusPages), 'all abandoned sentinels must require one eventual corpus page, not one scan each');
    assert_same(true, $completed['scope_completed'] ?? null, 'the one canonical recovery generation should acknowledge normally');
});

test_case('abandoned global recovery preserves a newer guarded canonical payload', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $queue = new WP_FTS_Index_Queue($fake);
    $profile = wp_fts_test_default_index_profile_hash();
    $incarnation = str_repeat('a', 32);
    $canonicalToken = 'guard:' . str_repeat('b', 32);
    $canonicalScopeKey = (string) (new ReflectionClass(WP_FTS_Plugin::class))
        ->getConstant('GLOBAL_RECONCILIATION_SCOPE_KEY');
    $canonicalJobKey = 'scope:' . hash('sha256', $canonicalScopeKey);
    $now = time();

    try {
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION] = $incarnation;
        $health = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
        $health['initial_index_status'] = 'pending';
        $health['status'] = 'reconciling';
        $health['index_profile_hash'] = $profile;
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = $health;

        $queue->fence_scope(
            $canonicalScopeKey,
            $canonicalToken,
            ['reason' => 'newer_canonical_request', 'profile_hash' => $profile],
            $now + 300,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
            '',
            0,
            $incarnation
        );
        $queue->fence_scope(
            'abandoned-global-before-canonical',
            'guard:' . str_repeat('c', 32),
            ['reason' => 'abandoned_foreground_request'],
            $now - 1,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_GLOBAL
        );

        $recovery = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
        $canonical = $fake->queue[$canonicalJobKey] ?? [];
        $scopes = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(true, $recovery['global_visibility_fence_completed'] ?? null, 'the abandoned request sentinel should exact-delete after canonical debt exists');
    assert_same(1, count($scopes), 'recovery must leave only the canonical corpus identity');
    assert_same($canonicalJobKey, $scopes[0]['job_key'] ?? null, 'recovery must not create a second corpus identity');
    assert_same(2, $canonical['generation'] ?? null, 'the abandoned request should advance the newer canonical desired generation');
    assert_same('guarded', $canonical['state'] ?? null, 'recovery must not release the newer request boundary');
    assert_same($canonicalToken, $canonical['claim_token'] ?? null, 'recovery must preserve the newer request ownership token');
    assert_same($incarnation, $canonical['scope_incarnation'] ?? null, 'recovery must preserve the newer readiness authority');
    assert_same(
        'newer_canonical_request',
        json_decode((string) ($canonical['payload'] ?? ''), true)['reason'] ?? null,
        'recovery must preserve the newer canonical payload rather than overwrite it with abandonment metadata'
    );
});

test_case('taxonomy post hooks retain an unresolved pre-hook corpus identity', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(88001, 'category');
        $before = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        WP_FTS_Plugin::handle_taxonomy_term_edit(88001, 188001, 'category');
        $after = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        $globalScopeKey = (string) (new ReflectionClass(WP_FTS_Plugin::class))
            ->getConstant('GLOBAL_RECONCILIATION_SCOPE_KEY');
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(1, count($before), 'an unresolved pre-hook should install one fail-closed scope');
    assert_same(1, count($after), 'the resolved post-hook must not create a second targeted or random scope');
    assert_same('scope:' . hash('sha256', $globalScopeKey), $after[0]['job_key'] ?? null, 'the post-hook must reuse the canonical pre-hook identity');
    assert_same(WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS, $after[0]['scope_coverage'] ?? null, 'post-hook resolution cannot narrow authority that began corpus-wide');
    assert_same('ready', $after[0]['state'] ?? null, 'the matching post-hook should release the canonical generation immediately');
});

test_case('stale global post promotion cannot rotate past a newer corpus generation', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $globalScopeKey = (string) (new ReflectionClass(WP_FTS_Plugin::class))
        ->getConstant('GLOBAL_RECONCILIATION_SCOPE_KEY');
    $jobKey = 'scope:' . hash('sha256', $globalScopeKey);
    $profile = wp_fts_test_default_index_profile_hash();
    $incarnationB = str_repeat('b', 32);

    try {
        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(88002, 'category');
        $generationA = $fake->queue[$jobKey] ?? [];

        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION] = $incarnationB;
        $health = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
        $health['initial_index_status'] = 'pending';
        $health['status'] = 'reconciling';
        $health['index_profile_hash'] = $profile;
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = $health;
        (new WP_FTS_Index_Queue($fake))->enqueue_scope(
            $globalScopeKey,
            ['reason' => 'concurrent_generation_b', 'profile_hash' => $profile],
            null,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
            '',
            0,
            $incarnationB
        );
        $generationB = $fake->queue[$jobKey] ?? [];

        WP_FTS_Plugin::handle_taxonomy_term_edit(88002, 188002, 'category');
        $afterStalePost = $fake->queue[$jobKey] ?? [];
        $healthIncarnation = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION] ?? '';
        $completed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(1, $generationA['generation'] ?? null, 'request A should own the first fenced corpus generation');
    assert_same(2, $generationB['generation'] ?? null, 'concurrent request B should advance the one canonical row');
    assert_same($incarnationB, $generationB['scope_incarnation'] ?? null, 'request B should bind its durable generation to health B');
    assert_same($incarnationB, $healthIncarnation, 'request A post-hook must not rotate health from B to an unbacked incarnation C');
    assert_same($incarnationB, $afterStalePost['scope_incarnation'] ?? null, 'stale A promotion must preserve B scope authority');
    assert_same('concurrent_generation_b', json_decode((string) ($afterStalePost['payload'] ?? ''), true)['reason'] ?? null, 'stale A promotion must preserve B payload intent');
    assert_same('ready', $afterStalePost['state'] ?? null, 'stale A may release the coalesced successor without replacing its authority');
    assert_same(true, $completed['scope_completed'] ?? null, 'the one B-bound canonical generation should drain successfully');
});

test_case('stale bulk handoff preserves a newer fenced corpus authority', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $reflection = new ReflectionClass(WP_FTS_Plugin::class);
    $globalScopeKey = (string) $reflection->getConstant('GLOBAL_RECONCILIATION_SCOPE_KEY');
    $jobKey = 'scope:' . hash('sha256', $globalScopeKey);
    $identity = 'scope:' . hash('sha256', $globalScopeKey);
    $profile = wp_fts_test_default_index_profile_hash();
    $incarnationB = str_repeat('c', 32);
    $tokenB = str_repeat('d', 32);
    $boundaryKeyB = 'taxonomy:category:88005';

    try {
        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(88003, 'category', ['term_taxonomy_id' => 188003]);
        WP_FTS_Plugin::handle_taxonomy_term_edit(88003, 188003, 'category');
        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(88004, 'category', ['term_taxonomy_id' => 188004]);
        WP_FTS_Plugin::handle_taxonomy_term_edit(88004, 188004, 'category');

        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION] = $incarnationB;
        $health = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] ?? [];
        $health['initial_index_status'] = 'pending';
        $health['status'] = 'reconciling';
        $health['index_profile_hash'] = $profile;
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION] = $health;
        $queue = new WP_FTS_Index_Queue($fake);
        $queue->fence_scope(
            $globalScopeKey,
            $tokenB,
            ['reason' => 'newer_canonical_pre_b', 'profile_hash' => $profile],
            time() + 300,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
            '',
            0,
            $incarnationB
        );

        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $afterHandoffA = $fake->queue[$jobKey] ?? [];
        $scopesAfterHandoffA = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));

        $reflection->getProperty('mutation_fence_tokens')->setValue(null, [
            $identity => ['token' => $tokenB, 'depth' => 1, 'expires_at' => time() + 300],
        ]);
        $reflection->getProperty('foreground_direct_scope_keys')->setValue(null, [$identity => $globalScopeKey]);
        $reflection->getProperty('foreground_direct_scope_tokens')->setValue(null, [$identity => $tokenB]);
        $reflection->getProperty('taxonomy_term_global_pre_boundaries')->setValue(null, [$boundaryKeyB => 1]);
        WP_FTS_Plugin::handle_taxonomy_term_edit(88005, 188005, 'category');

        $afterPostB = $fake->queue[$jobKey] ?? [];
        $healthIncarnation = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::READINESS_INCARNATION_OPTION] ?? '';
        $completed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(1, count($scopesAfterHandoffA), 'A handoff should delete its random sentinel and request-owned targeted scope');
    assert_same($jobKey, $scopesAfterHandoffA[0]['job_key'] ?? null, 'only the canonical B scope may survive A handoff');
    assert_same('fenced', $afterHandoffA['state'] ?? null, 'A handoff must not release B before its post boundary');
    assert_same($tokenB, $afterHandoffA['claim_token'] ?? null, 'A handoff must preserve B fence ownership');
    assert_same($incarnationB, $afterHandoffA['scope_incarnation'] ?? null, 'A handoff must preserve health-bound B scope authority');
    assert_same('newer_canonical_pre_b', json_decode((string) ($afterHandoffA['payload'] ?? ''), true)['reason'] ?? null, 'A handoff must not overwrite B payload with stale bulk intent');
    assert_same($incarnationB, $healthIncarnation, 'B post must retain the one current health incarnation');
    assert_same($incarnationB, $afterPostB['scope_incarnation'] ?? null, 'B post must leave its successor generation bound to B');
    assert_same(true, $completed['scope_completed'] ?? null, 'the coalesced B generation should require only one successful drain');
});

test_case('SIGKILL preserves completed direct generations without a global blast radius', function (): void {
    global $wpdb;

    $originalWpdb = $wpdb ?? null;
    if (!function_exists('proc_open')) {
        mark_pending('proc_open() is unavailable, so the SIGKILL direct-durability test cannot run.');
    }

    $queueFile = tempnam(sys_get_temp_dir(), 'wp-fts-direct-queue-');
    $readyFile = tempnam(sys_get_temp_dir(), 'wp-fts-direct-ready-');
    if (!is_string($queueFile) || !is_string($readyFile)) {
        throw new WP_FTS_TestFailure('Could not allocate direct-durability subprocess fixtures.');
    }
    @unlink($queueFile);
    @unlink($readyFile);
    $descriptors = [
        0 => ['pipe', 'r'],
        1 => ['pipe', 'w'],
        2 => ['pipe', 'w'],
    ];
    $baseEnv = getenv();
    $baseEnv = is_array($baseEnv) ? $baseEnv : [];
    $process = proc_open([PHP_BINARY, __FILE__], $descriptors, $pipes, dirname(__DIR__), array_merge($baseEnv, [
        'WP_FTS_DIRECT_DURABILITY_CHILD' => '1',
        'WP_FTS_DIRECT_DURABILITY_QUEUE_FILE' => $queueFile,
        'WP_FTS_DIRECT_DURABILITY_READY_FILE' => $readyFile,
        'WP_FTS_TEST_FILTER' => '',
        'WP_FTS_MIN_CHECKS' => '1',
    ]));
    if (!is_resource($process)) {
        @unlink($queueFile);
        @unlink($readyFile);
        mark_pending('Could not start the SIGKILL direct-durability subprocess.');
    }

    fclose($pipes[0]);
    $deadline = microtime(true) + 10.0;
    while (!is_file($readyFile) && microtime(true) < $deadline) {
        usleep(10000);
    }
    $status = proc_get_status($process);
    $ready = is_file($readyFile) ? json_decode((string) file_get_contents($readyFile), true) : null;
    $preKillSnapshot = is_file($queueFile) ? json_decode((string) file_get_contents($queueFile), true) : null;

    $concurrentError = null;
    $concurrentResult = null;
    $concurrentQueue = null;
    if (is_array($preKillSnapshot) && is_array($preKillSnapshot['queue'] ?? null)) {
        $concurrentFake = new WP_FTS_Test_WPDB();
        $wpdb = $concurrentFake;
        wp_fts_test_reset_wordpress_fakes();
        $concurrentPosts = [
            901 => wp_fts_test_backfill_post(901, 'post', 'publish', 'Direct durability first'),
            902 => wp_fts_test_backfill_post(902, 'post', 'publish', 'Direct durability second'),
        ];
        $GLOBALS['wp_fts_test_posts'] = $concurrentPosts;
        $concurrentFake->postRows = array_values($concurrentPosts);
        $concurrentFake->queue = $preKillSnapshot['queue'];
        try {
            // Direct rows are not request-owned. A worker may claim and finish
            // them even while the foreground PHP process remains alive.
            $concurrentResult = WP_FTS_Plugin::process_manual_index_batch([
                'batch_size' => 2,
                'source' => 'live-direct-durability-probe',
            ]);
            $concurrentQueue = $concurrentFake->queue;
        } catch (Throwable $error) {
            $concurrentError = $error;
        } finally {
            $wpdb = $originalWpdb;
        }
    }

    $terminated = proc_terminate($process, 9);
    $stdout = (string) stream_get_contents($pipes[1]);
    $stderr = (string) stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);
    proc_close($process);

    try {
        assert_true(is_array($ready), 'the child should reach its post-enqueue point before SIGKILL' . ($stderr !== '' ? "\n{$stderr}" : '') . ($stdout !== '' ? "\n{$stdout}" : ''));
        assert_true($terminated || !($status['running'] ?? false), 'the parent should terminate the live child with signal 9');
        assert_same([901, 903], $ready['visible_before'] ?? null, 'the child fixture should start with both dirty-target and unrelated indexed results');
        assert_same([903], $ready['visible_after'] ?? null, 'direct dirty rows should hide only targeted stale content before the worker runs');
        assert_same(2, $ready['accepted'] ?? null, 'the completed bounded call should report its two unique durable ids');

        $snapshot = is_file($queueFile) ? json_decode((string) file_get_contents($queueFile), true) : null;
        assert_true(is_array($snapshot), 'SIGKILL should leave the immediately persisted durable queue snapshot');
        $queue = is_array($snapshot['queue'] ?? null) ? $snapshot['queue'] : [];
        $postRows = array_values(array_filter(
            $queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'post'
        ));
        $scopeRows = array_values(array_filter(
            $queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        $dirtyIds = array_map(static fn(array $row): int => (int) ($row['post_id'] ?? 0), $postRows);
        sort($dirtyIds, SORT_NUMERIC);
        assert_same([901, 902], $dirtyIds, 'a killed bounded request should retain exactly the ids whose enqueue call completed');
        assert_same([], $scopeRows, 'direct foreground invalidation must never substitute a corpus scope');
        assert_same(['ready'], array_values(array_unique(array_column($postRows, 'state'))), 'completed direct rows should be immediately claimable');
        assert_same([1], array_values(array_unique(array_map('intval', array_column($postRows, 'generation')))), 'one completed bulk UPSERT should create exactly one generation per id');
        assert_same(1, $snapshot['fts_write_queries'] ?? null, 'the killed bounded call should persist all exact ids in one set-oriented write');

        assert_same(null, $concurrentError, 'a concurrent worker should process direct rows while the foreground request remains alive');
        assert_same(2, $concurrentResult['queue_processed'] ?? null, 'the live-request probe should reconcile both immediately claimable rows');
        assert_same([], $concurrentQueue, 'the live-request probe should not encounter a request-owner guard');

        $fake = new WP_FTS_Test_WPDB();
        $wpdb = $fake;
        wp_fts_test_reset_wordpress_fakes();
        $posts = [
            901 => (object) [
                'ID' => 901,
                'post_title' => 'Direct durability first',
                'post_content' => '<p>DirectDurabilitySignal current first.</p>',
                'post_excerpt' => '',
                'post_status' => 'publish',
                'post_type' => 'post',
                'post_date_gmt' => '2026-07-18 00:00:00',
            ],
            902 => (object) [
                'ID' => 902,
                'post_title' => 'Direct durability second',
                'post_content' => '<p>DirectDurabilitySignal current second.</p>',
                'post_excerpt' => '',
                'post_status' => 'publish',
                'post_type' => 'post',
                'post_date_gmt' => '2026-07-18 00:00:01',
            ],
            903 => (object) [
                'ID' => 903,
                'post_title' => 'Unrelated stable result',
                'post_content' => '<p>DirectDurabilitySignal unrelated stable.</p>',
                'post_excerpt' => '',
                'post_status' => 'publish',
                'post_type' => 'post',
                'post_date_gmt' => '2026-07-17 00:00:00',
            ],
        ];
        $GLOBALS['wp_fts_test_posts'] = $posts;
        $fake->postRows = array_values($posts);
        $fake->queue = $queue;
        $analyzer = new WP_FTS_Analyzer();
        $occurrences = $analyzer->analyze_query_occurrences('DirectDurabilitySignal', ['query_lang' => 'en', '_force_query_lang' => true]);
        $term = (string) ($occurrences[0]['term'] ?? 'directdurabilitysignal');
        $key = WP_FTS_TermNamespace::namespace_term('en', $term);
        $fake->ftsTerms[$key] = ['doc_freq' => 2];
        $fake->postings[$key] = [901 => 8192, 903 => 4096];
        foreach ([901, 903] as $postId) {
            $fake->docs[$postId] = [
                'post_id' => $postId,
                'primary_lang' => 'en',
                'lang' => 'en',
                'doc_len' => 1,
                'content_hash' => 'pre-crash-' . $postId,
                'snippet_text' => 'DirectDurabilitySignal stale fixture.',
                'indexed_at' => time(),
                'is_deleted' => 0,
            ];
        }
        assert_same([903], array_column(WP_FTS_Plugin::search('DirectDurabilitySignal', ['limit' => 10]), 'doc_id'), 'restored direct rows should leave unrelated indexed content eligible');

        for ($pass = 0; $pass < 3 && $fake->queue !== []; $pass++) {
            WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2, 'source' => 'direct-durability-recovery']);
        }
        assert_same([], $fake->queue, 'bounded worker passes should completely reconcile the two surviving direct rows');
        $reconciledIds = array_column(WP_FTS_Plugin::search('DirectDurabilitySignal', ['limit' => 10]), 'doc_id');
        sort($reconciledIds, SORT_NUMERIC);
        assert_same([901, 902, 903], $reconciledIds, 'worker reconciliation should update both targets without disturbing the unrelated result');
    } finally {
        $wpdb = $originalWpdb;
        @unlink($queueFile);
        @unlink($readyFile);
    }
});

test_case('lifecycle hooks preserve queued generations for current-state reconciliation', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    foreach ([811, 812, 813] as $postId) {
        $fake->docs[$postId] = [
            'lang' => 'en',
            'doc_len' => 1,
            'content_hash' => 'hook-generation-' . $postId,
            'is_deleted' => 0,
        ];
    }
    $savedTrash = (object) [
        'ID' => 811,
        'post_type' => 'post',
        'post_status' => 'trash',
        'post_password' => '',
    ];
    $transitionedTrash = (object) [
        'ID' => 812,
        'post_type' => 'post',
        'post_status' => 'trash',
        'post_password' => '',
    ];
    $GLOBALS['wp_fts_test_posts'][811] = $savedTrash;
    $GLOBALS['wp_fts_test_posts'][812] = $transitionedTrash;
    wp_fts_test_seed_queue($fake, [811, 812, 813]);
    (new WP_FTS_Index_Queue($fake))->enqueue(811);

    try {
        WP_FTS_Plugin::handle_post_save(811, $savedTrash);
        WP_FTS_Plugin::handle_post_save(812, $transitionedTrash);
        WP_FTS_Plugin::handle_post_delete(813);

        assert_same([0, 0, 0], array_map(
            static fn(int $postId): int => (int) ($fake->docs[$postId]['is_deleted'] ?? 0),
            [811, 812, 813]
        ), 'foreground lifecycle hooks should never mutate derived documents inline');
        assert_same([811, 812, 813], wp_fts_test_queue_ids($fake), 'each lifecycle hook should preserve its newer desired generation before returning');
        assert_same(3, $fake->queue[811]['generation'] ?? null, 'the save hook should advance beyond both pre-existing generations for the same post');

        $processed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        assert_same(3, $processed['queue_processed'] ?? null, 'later queue processing should reconcile every retained lifecycle generation');
        assert_same([], wp_fts_test_queue_ids($fake), 'generation-aware acknowledgements should drain reconciled lifecycle work');
        assert_same([], array_intersect([811, 812, 813], array_map('intval', array_keys($fake->docs))), 'current-state reconciliation should physically remove every ineligible derived document');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('writer heartbeat renews the same ownership token', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $before = [];
    $after = [];

    try {
        $locked = WP_FTS_Plugin::run_index_writer_with_lock(
            'heartbeat-test',
            static function () use (&$before, &$after): int {
                $before = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? [];
                WP_FTS_Plugin::heartbeat_index_writer(true);
                $after = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? [];
                return 0;
            },
            ['record_health' => false]
        );
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(true, $locked['acquired'] ?? null, 'heartbeat test should acquire the writer lease');
    assert_true(is_string($before['token'] ?? null) && ($before['token'] ?? '') !== '', 'acquired lease should carry a private ownership token');
    assert_same($before['token'] ?? null, $after['token'] ?? null, 'heartbeat should renew rather than replace the writer token');
    assert_same(((int) ($before['renewals'] ?? 0)) + 1, $after['renewals'] ?? null, 'heartbeat should advance the lease renewal sequence');
    assert_true((int) ($after['expires_at'] ?? 0) >= (int) ($before['expires_at'] ?? 0), 'heartbeat should not shorten the writer lease');
    assert_true(!isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]), 'writer should release the renewed lease after completion');
});

test_case('writer acquisition never deletes a successor that replaces a malformed lease', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $malformedLease = 'malformed-legacy-writer-lease';
    $successorLease = [
        'token' => 'successor-after-malformed-read',
        'mode' => 'cron',
        'started_at' => time(),
        'heartbeat_at' => time(),
        'expires_at' => time() + 300,
        'renewals' => 0,
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $malformedLease;
    $writerRan = false;
    $replacementInjected = false;
    $GLOBALS['wp_fts_test_after_get_option'] = static function (string $name, mixed $observed) use ($malformedLease, $successorLease, &$replacementInjected): void {
        if (
            $name !== WP_FTS_Plugin::INDEX_LOCK_OPTION
            || $observed !== $malformedLease
            || $replacementInjected
        ) {
            return;
        }
        unset($GLOBALS['wp_fts_test_after_get_option']);
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $successorLease;
        $replacementInjected = true;
    };

    try {
        $locked = WP_FTS_Plugin::run_index_writer_with_lock(
            'malformed-lease-race',
            static function () use (&$writerRan): void {
                $writerRan = true;
            },
            [
                'batch_size' => 1,
                'record_health' => false,
                'record_skip' => false,
            ]
        );
    } finally {
        unset($GLOBALS['wp_fts_test_after_get_option']);
        $wpdb = $oldWpdb;
    }

    assert_same(true, $replacementInjected, 'the fixture should replace the malformed observed value before its exact delete');
    assert_same(false, $locked['acquired'] ?? null, 'the stale contender should lose rather than deleting and replacing its successor');
    assert_same(false, $writerRan, 'a contender that lost the malformed-value compare must run zero writer work');
    assert_same($successorLease, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? null, 'exact compare-delete must preserve the successor lease');
    assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'the stale contender must issue no unconditional option deletion');
    assert_same([], $GLOBALS['wp_fts_test_added_options'], 'the stale contender must not install a replacement lease after losing the compare');
    assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'the no-health contention path must not mutate other options');
    assert_same([], $fake->queries, 'the fallback race proof should execute zero derived-table SQL');
});

