test_case('set-oriented batch aborts without partial writes when writer ownership is replaced', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_backfill_posts($fake, 3, 821);
    foreach ($fake->postRows as $post) {
        $GLOBALS['wp_fts_test_posts'][(int) $post->ID] = $post;
    }
    wp_fts_test_seed_queue($fake, [821, 822, 823]);
    $successor = [
        'token' => 'successor-writer-token',
        'mode' => 'cron',
        'started_at' => time(),
        'expires_at' => time() + 300,
    ];
    $lost = false;
    $replacementInjected = false;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post) use ($successor, &$replacementInjected): array {
        if (!$replacementInjected && (int) ($post->ID ?? 0) === 821) {
            $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $successor;
            $replacementInjected = true;
        }

        return $fields;
    };

    try {
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
    } catch (WP_FTS_Index_Writer_Ownership_Lost) {
        $lost = true;
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_true($lost, 'batch should abort explicitly after losing its ownership token');
    assert_same([], $fake->docs, 'ownership loss during preparation should publish no partial derived batch');
    assert_same([821, 822, 823], wp_fts_test_queue_ids($fake), 'ownership loss should retain every desired generation');
    foreach ([821, 822, 823] as $postId) {
        assert_same('', $fake->queue[$postId]['claim_token'] ?? null, "ownership loss should immediately release claim {$postId}");
    }
    assert_same($successor, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? null, 'stale writer release should not delete the successor lease');
    $diagnostics = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_HEALTH_OPTION]['latest_batch_diagnostics'] ?? [];
    assert_same('ownership_lost', $diagnostics['stop_reason'] ?? null, 'lease loss should remain visible in bounded batch diagnostics');
    assert_true(!str_contains(json_encode($diagnostics, JSON_THROW_ON_ERROR), 'successor-writer-token'), 'lease-loss diagnostics should not expose ownership tokens');
});

