test_case('relational source preload failure backs off every claimed generation without a hot loop', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $preloadIds = [841, 842, 843, 844, 845];
    foreach ($preloadIds as $postId) {
        $post = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Preload failure ' . $postId);
        $post->post_content = str_repeat('x ', 900000);
        $GLOBALS['wp_fts_test_posts'][$postId] = $post;
    }
    wp_fts_test_seed_queue($fake, $preloadIds);
    $fake->failReadQueryPrefix = 'SELECT p.ID,';
    $thrown = null;
    $startedAt = time();

    try {
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 5]);
    } catch (RuntimeException $error) {
        $thrown = $error;
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_true($thrown instanceof RuntimeException, 'a source preload database failure should remain visible to the worker caller');
    assert_contains('load FTS source posts', $thrown?->getMessage() ?? '', 'the failure should identify the failed set-oriented source read');
    assert_same($preloadIds, wp_fts_test_queue_ids($fake), 'a failed source read should acknowledge none of the claimed generations');
    foreach ($preloadIds as $postId) {
        assert_same('retry', $fake->queue[$postId]['state'] ?? null, "post {$postId} should enter durable retry state");
        assert_same(1, $fake->queue[$postId]['attempts'] ?? null, "post {$postId} should record exactly one shared-read failure");
        assert_true(
            (int) ($fake->queue[$postId]['available_at'] ?? 0) >= $startedAt + WP_FTS_Index_Queue::BASE_BACKOFF_SECONDS,
            "post {$postId} should not become claimable before the base backoff"
        );
        assert_same('', $fake->queue[$postId]['claim_token'] ?? null, "post {$postId} should release its claim token");
        assert_same('content_failure', $fake->queue[$postId]['last_error_code'] ?? null, "post {$postId} should retain a bounded failure reason");
    }
    assert_same([], $fake->docs, 'a failed source read should execute no document write');
    assert_true(!in_array('START TRANSACTION', $fake->queries, true), 'a failed source read should stop before the writer transaction');
    assert_same(0, count(array_filter(
        $fake->queries,
        static fn(string $query): bool => str_starts_with($query, 'DELETE FROM wp_fts_work WHERE')
    )), 'a failed source read should not acknowledge any claimed generation');
});

