test_case('latest indexing diagnostics remain bounded after repeated batches', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    $firstJson = '';
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post): array {
        $postId = (int) ($post->ID ?? 0);
        if ($postId >= 901 && $postId <= 912) {
            $index = $postId - 901;
            throw new RuntimeException('diagnostic failure ' . $index . ' ' . str_repeat('overflow ', 80) . "SELECT * FROM wp_users\n#0 trace");
        }

        return $fields;
    };

    try {
        for ($i = 0; $i < 12; $i++) {
            $postId = 901 + $i;
            $GLOBALS['wp_fts_test_posts'][$postId] = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Bounded Diagnostic ' . $i);
            wp_fts_test_seed_queue($fake, [$postId]);

            $result = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
            $diagnostics = WP_FTS_Plugin::search_health()['latest_batch_diagnostics'] ?? [];
            $json = json_encode($diagnostics, JSON_THROW_ON_ERROR);
            if ($i === 0) {
                $firstJson = $json;
            }

            assert_same(0, $result['indexed'], 'bounded diagnostics failure fixture should not mark failed queued posts indexed');
            assert_same('failed', $diagnostics['status'] ?? null, 'all-failed batch diagnostics should record failed status');
            assert_same(1, $diagnostics['failures'] ?? null, 'bounded diagnostics should record one failure for each latest batch');
            assert_true(count($diagnostics) <= 48, 'latest diagnostics should stay fixed-size after repeated batches');
            assert_true(strlen($json) < 2048, 'latest diagnostics JSON should remain bounded after repeated batches');
            assert_true(!str_contains($json, 'SELECT * FROM'), 'latest diagnostics should not store raw SQL after repeated failures');
            assert_true(!str_contains($json, '#0'), 'latest diagnostics should not store stack traces after repeated failures');
        }

        $latestJson = json_encode(WP_FTS_Plugin::search_health()['latest_batch_diagnostics'] ?? [], JSON_THROW_ON_ERROR);
        assert_true($firstJson !== '', 'bounded diagnostics test should capture the first payload');
        assert_true(!str_contains($latestJson, 'diagnostic failure 0'), 'latest diagnostics should overwrite earlier batch details instead of accumulating history');
        assert_contains('diagnostic failure 11', $latestJson, 'latest diagnostics should retain the most recent bounded failure');
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }
});

test_case('durable corpus scope includes public pages from default settings', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $fake->postRows = [
        wp_fts_test_backfill_post(201, 'page', 'publish', 'Backfill Page'),
        wp_fts_test_backfill_post(202, 'post', 'publish', 'Backfill Post'),
        wp_fts_test_backfill_post(203, 'page', 'draft', 'Draft Page'),
    ];
    foreach ($fake->postRows as $post) {
        $GLOBALS['wp_fts_test_posts'][(int) $post->ID] = $post;
    }
    wp_fts_test_seed_scope($fake);

    try {
        $scope = WP_FTS_Plugin::process_manual_index_batch();
        assert_same(0, $scope['indexed'], 'scope discovery should not mix source scanning with document writes');
        assert_same(3, $scope['backfill_scanned'], 'default scope should select supported public and operator-visible statuses for every configured post type');
        assert_same(3, $scope['backfill_queued'], 'scope discovery should durably enqueue every eligible configured post-type row');
        $postDrain = WP_FTS_Plugin::process_manual_index_batch();
        assert_same(false, $postDrain['scope_completed'], 'the direct-post pass should leave the co-claimed scope ready for its own bounded successor');
        assert_same(3, $postDrain['indexed'], 'the second pass should drain the claimed direct batch without adding scope SQL');
        assert_same(true, $postDrain['has_more'], 'the deferred scope should request its immediate scope-only successor');
        $scopeCompletion = WP_FTS_Plugin::process_manual_index_batch();
        assert_same(true, $scopeCompletion['scope_completed'], 'a scope-only empty keyset page should acknowledge the durable scope');
        assert_same(0, $scopeCompletion['indexed'], 'the scope-only completion pass should not repeat document work');
        $result = WP_FTS_Plugin::process_manual_index_batch();
        assert_same(0, $result['indexed'], 'no redundant fourth pass should remain after alternating direct and scope work');
        assert_same([201, 202, 203], array_keys($fake->docs), 'default backfill should retain operator-searchable page statuses as well as posts');

        wp_fts_test_mark_search_takeover_ready();
        $GLOBALS['wp_fts_test_caps']['edit_others_pages'][0] = true;
        assert_same(
            [203],
            array_column(WP_FTS_Plugin::search('Draft Page', [
                'mode' => 'AND',
                'post_types' => ['page'],
                'post_statuses' => ['draft'],
            ]), 'doc_id'),
            'an authorized operator search should return the draft page that the worker retained'
        );

        $backfillSelect = null;
        foreach ($fake->prepared as $prepared) {
            if (str_starts_with($prepared['sql'], '/* wp_fts:corpus-scope-page */')) {
                $backfillSelect = $prepared;
                break;
            }
        }
        assert_true($backfillSelect !== null, 'scope discovery should use one bounded keyset query');
        assert_true(in_array('page', $backfillSelect['args'], true), 'scope query should include the default page post type');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('profile reconciliation keyset-expands and rewrites only bounded durable batches', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        wp_fts_test_seed_indexed_posts($fake, 5, 401);

        $beforeSaveDocs = $fake->docs;
        $marked = wp_fts_test_enqueue_field_boost_reconciliation();
        $settingsSaveLeftDocsUntouched = $fake->docs === $beforeSaveDocs;
        $firstScope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $firstPostDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $docsAfterFirstWrite = $fake->docs;
        $secondScope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $secondPostDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $thirdScope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $finalPostDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $scopeCompletion = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        WP_FTS_Plugin::run_scheduled_schema_repair();
        $completeHealth = WP_FTS_Plugin::search_health();
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(true, $marked['reconciliation_active'] ?? null, 'settings save should activate durable reconciliation before processing');
    assert_same(1, $marked['pending_scope_work_count'] ?? null, 'settings save should persist one scope as the reconciliation source of truth');
    assert_true($settingsSaveLeftDocsUntouched, 'settings save itself should not rewrite indexed docs');
    assert_same([2, 2, 1], [
        $firstScope['backfill_queued'] ?? null,
        $secondScope['backfill_queued'] ?? null,
        $thirdScope['backfill_queued'] ?? null,
    ], 'profile reconciliation should expand retained rows in bounded keyset pages');
    assert_same(0, $firstScope['indexed'] ?? null, 'scope expansion should not write derived documents');
    assert_same(true, $scopeCompletion['scope_completed'] ?? null, 'a scope-only empty keyset proof should acknowledge the reconciliation scope');
    assert_same(2, $firstPostDrain['indexed'], 'the first post pass should rewrite only the prior bounded claim');
    assert_same(2, $firstPostDrain['queue_processed'], 'the first post pass should acknowledge exactly two durable generations');
    assert_same(true, $firstPostDrain['has_more'] ?? null, 'the first post pass should retain an immediate scope successor');
    assert_true(($fake->docs[401]['content_hash'] ?? '') !== 'old-profile-401', 'first stale row should be rewritten under the active profile');
    assert_true(($fake->docs[402]['content_hash'] ?? '') !== 'old-profile-402', 'second stale row should be rewritten under the active profile');
    assert_same('old-profile-403', $docsAfterFirstWrite[403]['content_hash'] ?? null, 'later rows should remain untouched after the first bounded write slice');

    assert_same(0, $secondScope['indexed'], 'the second scope page should not mix expansion with document replacement');
    assert_same(2, $secondPostDrain['indexed'], 'the second post pass should consume the next bounded post slice');
    assert_same(0, $thirdScope['indexed'], 'the final scope page should only enqueue its one remaining generation');
    assert_same(1, $finalPostDrain['indexed'], 'the final post pass should consume the last durable generation');
    assert_same(0, $scopeCompletion['indexed'], 'the empty-keyset proof should not repeat the final document write');
    assert_same(false, $completeHealth['reconciliation_active'], 'maintenance should publish inactive reconciliation after durable work is empty');
    assert_same($completeHealth['index_profile_hash'], $completeHealth['accepted_index_profile_hash'], 'maintenance should accept the current profile only after physical verification');
    assert_same(0, count($fake->queue), 'clean reconciliation should leave no hidden cursor or work generation');
});

test_case('scope shrink physically removes retained rows outside configured post types', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $oldPost = $_POST;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_post_types']['product'] = (object) [
            'public' => true,
            'exclude_from_search' => false,
            'cap' => (object) [
                'edit_others_posts' => 'edit_others_products',
                'read_private_posts' => 'read_private_products',
            ],
        ];
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = ['index_post_types' => ['post', 'product']];
        wp_fts_test_seed_indexed_posts($fake, 1, 1101, 'product');
        wp_fts_test_seed_indexed_posts($fake, 1, 1102, 'post');

        $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
        $_POST = [
            'option_page' => WP_FTS_Plugin::SETTINGS_OPTION,
            'action' => 'update',
            '_wpnonce' => wp_create_nonce(WP_FTS_Plugin::SETTINGS_OPTION . '-options'),
        ];
        $settings = WP_FTS_Plugin::sanitize_settings_for_save(['index_post_types' => ['post']]);
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = $settings;

        $marked = WP_FTS_Plugin::search_health();
        $scope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $postDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $scopeCompletion = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        WP_FTS_Plugin::run_scheduled_schema_repair();
        $complete = WP_FTS_Plugin::search_health();
    } finally {
        $_POST = $oldPost;
        $wpdb = $oldWpdb;
    }

    assert_same(true, $marked['reconciliation_active'] ?? null, 'removing a configured post type should enqueue retained rows for reconciliation');
    assert_same(1, $marked['pending_scope_work_count'] ?? null, 'scope removal should use one durable reconciliation scope');
    assert_same(2, $scope['backfill_queued'] ?? null, 'scope reconciliation should enumerate both old-scope and retained current-scope rows');
    assert_same(1, $postDrain['indexed'] ?? null, 'the bounded post pass should report only the retained document as indexed');
    assert_same(1, $postDrain['deleted'] ?? null, 'the removed post type should be reported as a physical derived-row deletion');
    assert_same(2, $postDrain['committed'] ?? null, 'both retained generations should be durably resolved in the same bounded post batch');
    assert_same(true, $postDrain['has_more'] ?? null, 'the post drain should retain the deferred scope as immediate work');
    assert_same(true, $scopeCompletion['scope_completed'] ?? null, 'a following scope-only pass should acknowledge the empty keyset proof');
    assert_same(0, $scopeCompletion['indexed'] ?? null, 'scope acknowledgement should not repeat either resolved document generation');
    assert_true(!isset($fake->docs[1101]), 'a retained row from the removed post type should be physically deleted');
    assert_true(isset($fake->docs[1102]), 'a retained row still in scope should be reindexed');
    assert_same(false, $complete['reconciliation_active'] ?? null, 'maintenance should publish inactive reconciliation only after the durable table drains');
});

test_case('activation scope reconciles retained rows after inactive edits and state loss', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        wp_fts_test_seed_indexed_posts($fake, 2, 1201);
        $oldHash = $fake->docs[1201]['content_hash'] ?? '';

        $changed = wp_fts_test_backfill_post(1201, 'post', 'publish', 'Changed While Inactive');
        $changed->post_content = '<p>fresh orchard content</p>';
        $fake->postRows = [$changed];
        $GLOBALS['wp_fts_test_posts'][1201] = $changed;
        unset($GLOBALS['wp_fts_test_posts'][1202]);

        WP_FTS_Plugin::uninstall();
        WP_FTS_Plugin::activate();
        $marked = WP_FTS_Plugin::search_health();
        $scope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $postDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $scopeCompletion = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        WP_FTS_Plugin::run_scheduled_schema_repair();
        $complete = WP_FTS_Plugin::search_health();
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same('pending', $marked['initial_index_status'] ?? null, 'activation should distrust retained rows until maintenance verifies reconciliation');
    assert_same(1, $scope['backfill_queued'] ?? null, 'activation scope should enumerate the one live source after uninstall removed every derived row');
    assert_same(1, $postDrain['indexed'] ?? null, 'activation reconciliation should report only the changed live post as indexed');
    assert_same(0, $postDrain['deleted'] ?? null, 'activation reconciliation should not rediscover a derived row already removed by uninstall');
    assert_same(1, $postDrain['committed'] ?? null, 'activation reconciliation should resolve the one live source generation');
    assert_same(true, $postDrain['has_more'] ?? null, 'activation document work should retain the deferred scope successor');
    assert_same(true, $scopeCompletion['scope_completed'] ?? null, 'activation scope should require a following scope-only empty keyset proof');
    assert_same(0, $scopeCompletion['indexed'] ?? null, 'activation scope completion should not repeat the indexed live post');
    assert_true(($fake->docs[1201]['content_hash'] ?? '') !== $oldHash, 'content changed while hooks were inactive should be reindexed on activation');
    assert_same([1201], array_keys($fake->postings[WP_FTS_TermNamespace::namespace_term('en', 'orchard')] ?? []), 'activation reconciliation should replace postings for inactive content edits');
    assert_true(!isset($fake->docs[1202]), 'a missing source should remain absent after uninstall and reactivation');
    assert_same('ready', $complete['initial_index_status'] ?? null, 'maintenance should publish readiness only after all retained rows converge');
});

test_case('scope work and direct generations alternate across bounded set-oriented batches', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        wp_fts_test_seed_indexed_posts($fake, 4, 501);
        foreach ([601, 602] as $postId) {
            $GLOBALS['wp_fts_test_posts'][$postId] = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Queued Priority ' . $postId);
        }
        wp_fts_test_seed_queue($fake, [601, 602]);
        wp_fts_test_enqueue_field_boost_reconciliation();

        $postDrain = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        $scopeAfterPostDrain = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ))[0] ?? [];
        $postIdsAfterDrain = wp_fts_test_queue_ids($fake);
        $scopeAdvance = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        $scopeAfterAdvance = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ))[0] ?? [];
        $health = WP_FTS_Plugin::search_health();
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(2, $postDrain['indexed'], 'the first batch should publish only the bounded direct claims acquired alongside scope work');
    assert_same(0, $postDrain['backfill_queued'], 'the direct-post batch must not add scope expansion SQL');
    assert_same(true, $postDrain['has_more'], 'the released scope should request its immediate bounded successor');
    assert_same([], $postIdsAfterDrain, 'the direct-post batch should acknowledge its exact claims before scope expansion');
    assert_same('ready', $scopeAfterPostDrain['state'] ?? null, 'the deferred scope should become immediately claimable again');
    assert_same(0, $scopeAfterPostDrain['cursor_post_id'] ?? null, 'deferring a co-claimed scope must preserve its unadvanced cursor');
    assert_same(WP_FTS_Index_Queue::SCOPE_EXPANSION_TURN_CODE, $scopeAfterPostDrain['last_error_code'] ?? null, 'the deferred scope should reserve the next mixed collision for expansion');
    assert_same(0, $scopeAdvance['indexed'], 'the scope-only successor must not repeat direct document writes');
    assert_same(3, $scopeAdvance['backfill_queued'], 'the scope-only successor should remain bounded by the requested size');
    assert_same('', $scopeAfterAdvance['last_error_code'] ?? null, 'advancing the reserved scope turn should clear its scheduling marker');
    assert_same([501, 502, 503], wp_fts_test_queue_ids($fake), 'scope discovery should persist only the newly discovered post generations after direct claims commit');
    assert_true(isset($fake->docs[601], $fake->docs[602]), 'pre-existing direct generations should commit before the scope-only successor');
    assert_same('old-profile-501', $fake->docs[501]['content_hash'] ?? null, 'scope discovery should not rewrite retained documents');
    assert_same(true, $health['reconciliation_active'], 'reconciliation should remain active while durable scope and post work remain');
});

test_case('releasing an old scope claim preserves its superseding generation', function (): void {
    $fake = new WP_FTS_Test_WPDB();
    $queue = new WP_FTS_Index_Queue($fake);
    $scopeKey = 'release-superseded-scope';

    $queue->enqueue_scope($scopeKey, ['reason' => 'initial-generation']);
    $initial = $queue->claim_batch(0)[0] ?? null;
    assert_true(is_array($initial), 'the release-race fixture should claim its initial scope generation');
    assert_true($queue->commit_scope_page($initial, [], 77), 'the fixture should publish a nonzero cursor before the release race');
    $oldClaim = $queue->claim_batch(0)[0] ?? null;
    assert_true(is_array($oldClaim), 'the release-race fixture should reclaim the continued scope generation');

    $queue->enqueue_scope($scopeKey, ['reason' => 'superseding-generation']);
    $jobKey = (string) ($oldClaim['job_key'] ?? '');
    $newerBeforeRelease = $fake->queue[$jobKey] ?? [];
    $released = $queue->release_scope($oldClaim);
    $newerAfterRelease = $fake->queue[$jobKey] ?? [];

    assert_same(false, $released, 'an old release CAS should lose after the scope generation advances and clears its token');
    assert_same($newerBeforeRelease, $newerAfterRelease, 'the lost release CAS must not mutate any field of the superseding scope generation');
    assert_same(((int) ($oldClaim['generation'] ?? 0)) + 1, $newerAfterRelease['generation'] ?? null, 'the newer desired scope generation must remain authoritative');
    assert_same('ready', $newerAfterRelease['state'] ?? null, 'the superseding scope generation should remain immediately claimable');
    assert_same('', $newerAfterRelease['claim_token'] ?? null, 'the superseding enqueue should retain its cleared old claim token');
    assert_same(0, $newerAfterRelease['cursor_post_id'] ?? null, 'the superseding generation must retain its reset keyset cursor');
    assert_same(
        'superseding-generation',
        json_decode((string) ($newerAfterRelease['payload'] ?? ''), true)['reason'] ?? null,
        'the lost release CAS must preserve the superseding payload'
    );
});

test_case('failed reconciliation generation backs off without rewinding its completed scope', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        wp_fts_test_seed_indexed_posts($fake, 3, 701);
        wp_fts_test_enqueue_field_boost_reconciliation();
        $fake->queries = [];
        $scope = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        $scopeStatementCount = count($fake->queries);
        $scopeRowsAfterExpansion = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ));
        $docsAfterExpansion = $fake->docs;
        $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post): array {
            if ((int) ($post->ID ?? 0) === 701) {
                throw new RuntimeException("simulated reconciliation failure SELECT * FROM wp_users\n#0 stack");
            }

            return $fields;
        };

        $beforeFailure = count($fake->queries);
        $result = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 3]);
        $failureStatementCount = count($fake->queries) - $beforeFailure;
        $health = WP_FTS_Plugin::search_health();
        $queueAfterFailure = $fake->queue;
        $docsAfterFailure = $fake->docs;
        $successorRuns = wp_fts_test_drain_manual_index_phases(
            $fake,
            3,
            static fn(): bool => wp_fts_test_queue_ids($fake) === [701]
                && count(array_filter(
                    $fake->queue,
                    static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
                )) === 0
        );
        $scopeCompletionRuns = array_values(array_filter(
            array_column($successorRuns, 'summary'),
            static fn(array $summary): bool => !empty($summary['scope_completed'])
        ));
        $scopeCompletion = $scopeCompletionRuns[0] ?? [];
        $retryAt = (int) ($fake->queue[701]['available_at'] ?? 0);
        unset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]);
        $beforeBlocked = count($fake->queries);
        $blocked = WP_FTS_Plugin::process_scheduled_indexing();
        $blockedStatementCount = count($fake->queries) - $beforeBlocked;
        $blockedHealth = WP_FTS_Plugin::search_health();
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }

    assert_same(3, $scope['backfill_queued'] ?? null, 'reconciliation should first enqueue one bounded retained page');
    assert_same(1, count($scopeRowsAfterExpansion), 'the bounded scope expansion should preserve one durable exhaustion proof');
    assert_same(703, $scopeRowsAfterExpansion[0]['cursor_post_id'] ?? null, 'the bounded scope expansion should persist its exact keyset frontier');
    assert_same(false, $result['scope_completed'] ?? null, 'the bounded direct claims should leave the exhausted scope ready for a separate proof');
    assert_same(true, $result['has_more'] ?? null, 'the direct-post result should request its scope-only completion successor');
    assert_same('failure_phase', $result['stop_reason'] ?? null, 'the mixed reconciliation batch should stop after its isolated retryable settlement');
    assert_same(true, $scopeCompletion['scope_completed'] ?? null, 'the following scope-only pass should publish the empty-keyset proof');
    assert_same(0, $scopeCompletion['indexed'] ?? null, 'scope completion should not repeat successful or failed direct generations');
    assert_same(0, $result['indexed'], 'the retryable failure phase must not publish unrelated prepared generations');
    assert_same(0, $result['queue_processed'] ?? null, 'the retryable failure phase must not acknowledge unrelated prepared generations');
    assert_same(1, $result['retryable_failures'] ?? null, 'the retryable failure phase should settle exactly the poison generation');
    assert_same(2, $result['deferred'] ?? null, 'the two valid reconciliation generations should be released for bounded successors');
    assert_same(1, $result['last_batch_failures'], 'transient reconciliation failure should be recorded once');
    assert_same(701, $result['last_failed_post_id'], 'failure summary should identify the failed generation');
    assert_same($docsAfterExpansion, $docsAfterFailure, 'the isolated failure phase must not publish any successful profile rewrite');
    assert_same([701, 702, 703], array_map('intval', array_keys(array_filter(
        $queueAfterFailure,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'post'
    ))), 'the isolated failure phase should preserve all three durable document generations');
    assert_same('retry', $queueAfterFailure[701]['state'] ?? null, 'the poison reconciliation generation should enter durable backoff');
    assert_true((int) ($queueAfterFailure[701]['available_at'] ?? 0) > time(), 'the poison reconciliation generation should receive a future retry availability');
    assert_same('ready', $queueAfterFailure[702]['state'] ?? null, 'the first valid reconciliation suffix should remain immediately claimable');
    assert_same('ready', $queueAfterFailure[703]['state'] ?? null, 'the second valid reconciliation suffix should remain immediately claimable');
    $scopeRowsAfterFailure = array_values(array_filter(
        $queueAfterFailure,
        static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
    ));
    assert_same(1, count($scopeRowsAfterFailure), 'the retryable document phase should preserve the exhausted scope proof');
    assert_same(703, $scopeRowsAfterFailure[0]['cursor_post_id'] ?? null, 'the retryable document phase must not rewind the completed scope frontier');
    assert_same(2, array_sum(array_map(
        static fn(array $run): int => (int) ($run['summary']['indexed'] ?? 0),
        $successorRuns
    )), 'bounded successors should publish both valid reconciliation generations exactly once');
    assert_same([701], wp_fts_test_queue_ids($fake), 'only the transient generation should remain queued');
    assert_same('retry', $fake->queue[701]['state'] ?? null, 'the transient generation should use durable backoff');
    assert_same(0, count(array_filter($fake->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope')), 'a direct failure should not recreate or rewind the completed scope');
    assert_same('old-profile-701', $fake->docs[701]['content_hash'] ?? null, 'the backed-off poison generation should retain its previous derived profile');
    assert_true(($fake->docs[702]['content_hash'] ?? '') !== 'old-profile-702', 'the first valid successor should publish its new profile');
    assert_true(($fake->docs[703]['content_hash'] ?? '') !== 'old-profile-703', 'the second valid successor should publish its new profile');
    assert_contains('SELECT statement', (string) ($health['last_error'] ?? ''), 'failure health should redact SQL details');
    assert_same(0, $blocked['indexed'] ?? null, 'an immediate cron pass should not reclaim a future retry');
    assert_same(true, $blocked['has_more'] ?? null, 'future retry work should keep the worker scheduled');
    assert_same('scheduled_at_availability', $blocked['reschedule_decision'] ?? null, 'a deferred retry should not request a prompt polling loop');
    assert_same($retryAt, $GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]['timestamp'] ?? null, 'cron should sleep until the exact retry availability instead of polling every second');
    assert_same(true, $blockedHealth['reconciliation_active'] ?? null, 'reconciliation should remain active while retry work exists');
    $allRuns = [
        ['summary' => $scope, 'statement_count' => $scopeStatementCount],
        ['summary' => $result, 'statement_count' => $failureStatementCount],
        ...$successorRuns,
        ['summary' => $blocked, 'statement_count' => $blockedStatementCount],
    ];
    assert_same([], array_values(array_filter(
        array_column($allRuns, 'summary'),
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'a fresh reconciliation fixture must never consume a stale-takeover control phase');
    assert_true(max(array_column($allRuns, 'statement_count')) <= 20, 'every expansion, failure, successor, and blocked-retry phase must stay inside the complete 20-statement ceiling');
});

test_case('profile change during reconciliation fences and restarts the durable scope generation', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        wp_fts_test_seed_indexed_posts($fake, 3, 801);
        wp_fts_test_enqueue_field_boost_reconciliation(8.0);
        $partial = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $partialHealth = WP_FTS_Plugin::search_health();
        $scopeBefore = array_values(array_filter($fake->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'))[0] ?? [];
        wp_fts_test_enqueue_field_boost_reconciliation(9.0);
        $changedHealth = WP_FTS_Plugin::search_health();
        $scopesAfter = array_values(array_filter($fake->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'));
        $scopeAfter = $scopesAfter[0] ?? [];
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(0, $partial['indexed'], 'scope expansion should not publish a partial derived rewrite');
    assert_same(1, $partial['backfill_queued'], 'setup should keyset-expand one retained row');
    assert_same(801, $scopeBefore['cursor_post_id'] ?? null, 'setup should persist progress in the durable scope row');
    assert_same(true, $changedHealth['reconciliation_active'], 'profile change should keep reconciliation active');
    assert_same(1, count($scopesAfter), 'a repeated profile change should coalesce into the same scope key');
    assert_same(((int) ($scopeBefore['generation'] ?? 0)) + 1, $scopeAfter['generation'] ?? null, 'a repeated profile change should fence the previous scope generation');
    assert_same(0, $scopeAfter['cursor_post_id'] ?? null, 'the new desired profile should restart keyset progress');
    assert_true(($changedHealth['index_profile_hash'] ?? '') !== ($partialHealth['index_profile_hash'] ?? ''), 'profile change should move the active profile hash');
});

test_case('newer profile scope authority survives an older fenced promotion', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $queue = new WP_FTS_Index_Queue($fake);
    $scopeKey = 'index-profile';
    $tokenH1 = str_repeat('1', 32);
    $profileH1 = str_repeat('a', 40);
    $profileH2 = str_repeat('b', 40);
    $incarnationH1 = str_repeat('c', 32);
    $incarnationH2 = str_repeat('d', 32);

    try {
        $queue->fence_scope(
            $scopeKey,
            $tokenH1,
            ['reason' => 'H1-pre', 'profile_hash' => $profileH1],
            time() + 300,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
            '',
            0,
            $incarnationH1
        );
        $scopeStorageKey = array_key_first(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ));
        if ($scopeStorageKey !== null) {
            $fake->queue[$scopeStorageKey]['cursor_post_id'] = 777;
        }
        $queue->enqueue_scope(
            $scopeKey,
            ['reason' => 'H2-enqueue', 'profile_hash' => $profileH2],
            time(),
            WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
            '',
            0,
            $incarnationH2
        );
        $afterH2 = $scopeStorageKey !== null ? ($fake->queue[$scopeStorageKey] ?? []) : [];
        $queue->promote_scope(
            $scopeKey,
            $tokenH1,
            ['reason' => 'H1-post', 'profile_hash' => $profileH1],
            time(),
            WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
            '',
            0,
            $incarnationH1
        );
        $afterOldPromotion = $scopeStorageKey !== null ? ($fake->queue[$scopeStorageKey] ?? []) : [];
    } finally {
        $wpdb = $oldWpdb;
    }

    $afterH2Payload = json_decode((string) ($afterH2['payload'] ?? ''), true);
    $afterPromotionPayload = json_decode((string) ($afterOldPromotion['payload'] ?? ''), true);
    assert_same('fenced', $afterH2['state'] ?? null, 'a newer enqueue must not make the older in-flight boundary claimable');
    assert_same($tokenH1, $afterH2['claim_token'] ?? null, 'the existing boundary token should stay authoritative until its completion');
    assert_same(2, $afterH2['generation'] ?? null, 'the newer desired profile should advance the durable generation');
    assert_same(1, $afterH2['claimed_generation'] ?? null, 'the old token must remain bound to only its original generation');
    assert_same(0, $afterH2['cursor_post_id'] ?? null, 'new profile authority must restart the corpus cursor even while the old boundary is fenced');
    assert_same($profileH2, $afterH2Payload['profile_hash'] ?? null, 'the newer profile payload should win immediately');
    assert_same($incarnationH2, $afterH2['scope_incarnation'] ?? null, 'the newer readiness generation should win immediately');
    assert_same('ready', $afterOldPromotion['state'] ?? null, 'the old completion may release its own boundary after observing superseding work');
    assert_same('', $afterOldPromotion['claim_token'] ?? null, 'the released boundary should expose no stale request token');
    assert_same(2, $afterOldPromotion['generation'] ?? null, 'a stale completion should coalesce into the already newer desired generation');
    assert_same($profileH2, $afterPromotionPayload['profile_hash'] ?? null, 'the stale H1 completion must not overwrite H2 profile authority');
    assert_same($incarnationH2, $afterOldPromotion['scope_incarnation'] ?? null, 'the stale H1 completion must not overwrite H2 readiness authority');
});

test_case('health and wp-cli status report durable reconciliation progress without indexing content', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;

    try {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        wp_fts_test_seed_indexed_posts($fake, 4, 901);
        wp_fts_test_enqueue_field_boost_reconciliation();
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        $docsBeforeStatus = $fake->docs;

        $html = wp_fts_test_capture_admin_settings_tab('health');
        $command = new WP_FTS_WPCLI_Command();
        $raw = wp_fts_test_capture_cli(static function () use ($command): void {
            $command->status([], ['format' => 'json']);
        });
        $payload = wp_fts_test_decode_cli_json_object($raw);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_contains('Durable reconciliation', $html, 'health tab should expose the authoritative work model');
    assert_contains('<th scope="row">Pending scope jobs</th><td>1</td>', $html, 'health tab should report the coalesced scope generation');
    assert_contains('<th scope="row">Scope cursor</th><td>Post ID 902</td>', $html, 'health tab should report the persisted keyset cursor');
    assert_contains('<th scope="row">Pending post generations</th><td>2</td>', $html, 'health tab should report direct work discovered so far');
    assert_same(true, $payload['reconciliation_active'] ?? null, 'status JSON should derive reconciliation from durable work and readiness');
    assert_same(1, $payload['pending_scope_work_count'] ?? null, 'status JSON should report authoritative scope work');
    assert_same(2, $payload['pending_post_work_count'] ?? null, 'status JSON should report authoritative direct work');
    assert_same(902, $payload['reconciliation_cursor_post_id'] ?? null, 'status JSON should report the durable keyset cursor');
    assert_same([], $payload['latest_batch_diagnostics'] ?? [], 'ordinary scope progress should not persist per-batch telemetry');
    assert_same($docsBeforeStatus, $fake->docs, 'rendering health and status should not index more content');
});

/**
 * @return string[]
 */
function wp_fts_test_uninstall_operational_option_names(): array
{
    return [
        WP_FTS_Plugin::SCHEMA_VERSION_OPTION,
        WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION,
        WP_FTS_Plugin::SETTINGS_OPTION,
        WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION,
        WP_FTS_Plugin::INDEX_LOCK_OPTION,
        WP_FTS_Plugin::INDEX_HEALTH_OPTION,
        WP_FTS_Plugin::READINESS_INCARNATION_OPTION,
        WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION,
        WP_FTS_Plugin::ACTIVATION_REDIRECT_OPTION,
        WP_FTS_Plugin::SCOPE_INDEX_OWNERSHIP_OPTION,
    ];
}

/**
 * @param string[] $option_names
 * @return array<string,mixed>
 */
function wp_fts_test_uninstall_seeded_options(array $option_names, int $site_id): array
{
    $options = ['wp_fts_non_operational_marker' => "keep-site-{$site_id}"];
    foreach ($option_names as $option_name) {
        $options[$option_name] = "remove-site-{$site_id}-{$option_name}";
    }

    return $options;
}

/** Seed one relational document through the only production writer contract. */
function wp_fts_test_seed_uninstall_document(
    WP_FTS_Storage_Mysql $storage,
    int $postId,
    string $term,
    int $frequency = 2
): void {
    $storage->replace_prepared_documents([[
        'doc_id' => $postId,
        'primary_lang' => 'en',
        'content_hash' => hash('sha256', "uninstall:{$postId}:{$term}"),
        'term_frequencies' => [
            WP_FTS_TermNamespace::namespace_term('en', $term) => $frequency,
        ],
        'surface_frequencies' => [],
    ]]);
}

/** @param array<string,mixed> $options */
function wp_fts_test_assert_uninstall_fence(array $options, string $label): void
{
    assert_same(
        WP_FTS_Plugin::UNINSTALL_FENCE_VALUE,
        $options[WP_FTS_Plugin::UNINSTALL_FENCE_OPTION] ?? null,
        "{$label} should retain the exact scalar uninstall fence"
    );
}

/**
 * Assert the one-statement destructive uninstall boundary for a site prefix.
 *
 * @param string[] $queries
 */
function wp_fts_test_assert_uninstall_drop(array $queries, string $prefix, string $label): void
{
    assert_same(1, count($queries), "{$label} should issue one idempotent DROP statement");
    $sql = $queries[0] ?? '';
    assert_true(str_starts_with($sql, 'DROP TABLE IF EXISTS '), "{$label} should tolerate missing tables");
    $actualTables = explode(', ', substr($sql, strlen('DROP TABLE IF EXISTS ')));
    $expectedTables = array_map(
        static fn(string $table): string => "`{$table}`",
        wp_fts_test_owned_site_table_names($prefix)
    );
    assert_same($expectedTables, $actualTables, "{$label} should remove only the exact 12-table lifecycle inventory");
}

test_case('ready no-op request performs zero uninstall fence probes or plugin SQL', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    // Enable the native option-table shape so an accidental fence check is
    // observable as both one prepare and one database read.
    $fake->options = 'wp_options';
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $optionsBefore = $GLOBALS['wp_fts_test_options'];
    $fake->num_queries = 0;
    $fake->queries = [];
    $fake->prepared = [];

    try {
        WP_FTS_Plugin::maybe_schedule_schema_repair();
        WP_FTS_Plugin::maybe_schedule_initial_index_readiness();
        WP_FTS_Plugin::storage(true);
        $status = WP_FTS_Plugin::search_takeover_status();
        WP_FTS_Plugin::flush_foreground_bulk_mutations();

        assert_same(true, $status['ready'] ?? null, 'a logically ready no-op request should remain ready');
        assert_same(0, $fake->num_queries, 'ready init, readiness, storage, and empty shutdown boundaries should execute zero plugin SQL');
        assert_same([], $fake->prepared, 'ready no-op request should not even prepare the direct uninstall-fence probe');
        assert_same([], $fake->queries, 'ready no-op request should record no plugin reads or writes');
        assert_same([], $GLOBALS['wp_fts_test_get_site_option_calls'], 'ready init must not cold-read the normally absent network activation token');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'ready no-op request should schedule no maintenance work');
        assert_same([], $GLOBALS['wp_fts_test_added_options'], 'ready no-op request should add no options');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'ready no-op request should update no options');
        assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'ready no-op request should delete no options');
        assert_same($optionsBefore, $GLOBALS['wp_fts_test_options'], 'ready no-op request should preserve all logical state');
    } finally {
        $wpdb = $oldWpdb;
    }
});

