test_case('single-site deactivation retains derived data while uninstall removes all current FTS tables', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();

    try {
        WP_FTS_Plugin::activate();
        $storage = wp_fts_test_unleased_storage();
