        WP_FTS_Plugin::deactivate();
        assert_true(isset($fake->docs[31]), 'deactivation should not destroy indexed documents');
        assert_true($fake->ftsTerms !== [], 'deactivation should not destroy term rows');
        assert_true(isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]), 'deactivation should leave schema version option intact');
        assert_true(in_array(WP_FTS_Plugin::CRON_HOOK, $GLOBALS['wp_fts_test_cleared_hooks'], true), 'deactivation should clear scheduled queue work');

        $fake->queries = [];
        WP_FTS_Plugin::uninstall();
        assert_same([], $fake->docs, 'uninstall should remove derived documents');
        assert_same([], $fake->ftsTerms, 'uninstall should remove derived dictionary rows');
        assert_same([], $fake->postings, 'uninstall should remove derived postings');
        foreach ($operationalOptions as $option_name) {
            assert_true(!isset($GLOBALS['wp_fts_test_options'][$option_name]), "single-site uninstall should delete {$option_name}");
        }
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_options'], 'single-site uninstall');
        assert_same('keep-site-1', $GLOBALS['wp_fts_test_options']['wp_fts_non_operational_marker'] ?? null, 'single-site uninstall should leave unrelated options alone');
        wp_fts_test_assert_uninstall_drop($fake->queries, 'wp_', 'single-site uninstall');
        assert_same([], $GLOBALS['wp_fts_test_posts'], 'single-site uninstall should not create demo or content posts');
        assert_same([], $GLOBALS['wp_fts_test_trashed_posts'], 'single-site uninstall should not delete or trash content posts');
        assert_true(!str_contains(implode("\n", $fake->queries), 'TRUNCATE TABLE'), 'uninstall should not truncate custom tables under the documented deferred cleanup policy');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('single-site uninstall removes retired generations left by a failed reset', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_seed_reset_index_state($fake);
    $fake->failQueryNeedle = 'DROP TABLE IF EXISTS ';
    $fake->failQueryNeedleOccurrence = 2;

    try {
        $failure = null;
        try {
            (new WP_FTS_WPCLI_Command())->reset_index([], ['yes' => true, 'format' => 'json']);
        } catch (Throwable $error) {
            $failure = $error;
        }
        assert_true($failure instanceof RuntimeException, 'the fixture should fail after publishing the empty reset generation');
        $retired = array_values(array_filter(
            array_keys($fake->schemaColumns),
            static fn(string $table): bool => str_contains($table, '_ro_')
        ));
        assert_same(4, count($retired), 'failed post-publication cleanup should leave four retired plugin-owned tables');

        $fake->failQueryNeedle = null;
        $fake->failQueryNeedleOccurrence = 0;
        $fake->failQueryNeedleMatches = 0;
        $fake->queries = [];
        $fake->prepared = [];
        WP_FTS_Plugin::uninstall();

        assert_same([], array_values(array_filter(
            array_keys($fake->schemaColumns),
            static fn(string $table): bool => str_contains($table, '_rn_') || str_contains($table, '_ro_')
        )), 'uninstall should remove every deterministic reset generation without table discovery');
        wp_fts_test_assert_uninstall_drop($fake->queries, 'wp_', 'failed-reset uninstall');
        $drop = $fake->queries[0] ?? '';
        foreach ($retired as $table) {
            assert_contains($table, $drop, "failed-reset uninstall should name retired table {$table} explicitly");
        }
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('uninstall performs zero destructive work while another writer owns an active lease', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();
    $activeLease = [
        'token' => 'active-uninstall-fence',
        'mode' => 'cron',
        'started_at' => time() - 5,
        'heartbeat_at' => time() - 5,
        'expires_at' => time() + 295,
        'renewals' => 0,
    ];

    try {
        $storage = wp_fts_test_unleased_storage();
        wp_fts_test_seed_uninstall_document($storage, 32, 'guarded');
        $GLOBALS['wp_fts_test_options'] = wp_fts_test_uninstall_seeded_options($operationalOptions, 1);
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $activeLease;
        $optionsBefore = $GLOBALS['wp_fts_test_options'];
        $fake->queries = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];

        $message = '';
        try {
            WP_FTS_Plugin::uninstall();
        } catch (RuntimeException $error) {
            $message = $error->getMessage();
        }

        assert_contains('another index writer owns the active lease', $message, 'active writer contention should fail uninstall with explicit retry guidance');
        assert_same([], $fake->queries, 'active writer contention must issue zero DROP or other SQL statements');
        assert_same([], $GLOBALS['wp_fts_test_added_options'], 'active writer contention must not add or replace options');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'active writer contention must not update health or lease options');
        assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'active writer contention must delete zero options');
        assert_same([], $GLOBALS['wp_fts_test_cleared_hooks'], 'active writer contention must not cancel the owner or its successor schedules');
        assert_same($optionsBefore, $GLOBALS['wp_fts_test_options'], 'active writer contention must preserve every operational option and the exact owner lease');
        assert_true(isset($fake->docs[32]), 'active writer contention must preserve indexed documents');
        assert_true($fake->ftsTerms !== [], 'active writer contention must preserve dictionary rows');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('uninstall takes over an expired writer lease before one bounded DROP', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();
    $expiredLease = [
        'token' => 'expired-uninstall-fence',
        'mode' => 'schema-repair',
        'started_at' => time() - 600,
        'heartbeat_at' => time() - 600,
        'expires_at' => time() - 300,
        'renewals' => 0,
    ];

    try {
        $storage = wp_fts_test_unleased_storage();
        wp_fts_test_seed_uninstall_document($storage, 33, 'expired');
        $GLOBALS['wp_fts_test_options'] = wp_fts_test_uninstall_seeded_options($operationalOptions, 1);
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $expiredLease;
        $fake->queries = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];

        WP_FTS_Plugin::uninstall();

        wp_fts_test_assert_uninstall_drop($fake->queries, 'wp_', 'expired-lease uninstall');
        assert_same([], $fake->docs, 'expired-lease takeover should remove indexed documents');
        assert_same([], $fake->ftsTerms, 'expired-lease takeover should remove dictionary rows');
        foreach ($operationalOptions as $optionName) {
            assert_true(!isset($GLOBALS['wp_fts_test_options'][$optionName]), "expired-lease uninstall should delete {$optionName}");
        }
        assert_same('keep-site-1', $GLOBALS['wp_fts_test_options']['wp_fts_non_operational_marker'] ?? null, 'expired-lease uninstall should preserve unrelated options');
        assert_same(2, count($GLOBALS['wp_fts_test_added_options']), 'expired-lease takeover should install one replacement lease and one durable uninstall fence');
        $replacement = $GLOBALS['wp_fts_test_added_options'][0] ?? [];
        assert_same(WP_FTS_Plugin::INDEX_LOCK_OPTION, $replacement['name'] ?? null, 'expired-lease takeover should replace the shared writer lease option');
        assert_same('uninstall', $replacement['value']['mode'] ?? null, 'expired-lease takeover should identify the destructive writer');
        assert_true(($replacement['value']['token'] ?? null) !== $expiredLease['token'], 'expired-lease takeover should use a fresh capability token');
        assert_same('no', $replacement['autoload'] ?? null, 'the uninstall writer lease must remain non-autoloaded');
        assert_same(WP_FTS_Plugin::UNINSTALL_FENCE_OPTION, $GLOBALS['wp_fts_test_added_options'][1]['name'] ?? null, 'uninstall should persist its lifecycle fence before dropping tables');
        assert_same(WP_FTS_Plugin::UNINSTALL_FENCE_VALUE, $GLOBALS['wp_fts_test_added_options'][1]['value'] ?? null, 'uninstall fence should use the exact public scalar value');
        assert_same('no', $GLOBALS['wp_fts_test_added_options'][1]['autoload'] ?? null, 'uninstall fence should remain non-autoloaded');
        $leaseDeletes = array_values(array_filter(
            $GLOBALS['wp_fts_test_deleted_options'],
            static fn(array $event): bool => ($event['name'] ?? null) === WP_FTS_Plugin::INDEX_LOCK_OPTION
        ));
        assert_same(2, count($leaseDeletes), 'expired takeover and guarded release should each address the lease exactly once');
        assert_same([true, true], array_column($leaseDeletes, 'existed'), 'lease deletion order should prove exact takeover and release without a stale post-release delete');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('uninstall keeps the lease through destructive cleanup and final option deletion', function (): void {
    global $wpdb;

