        $fake->queries = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];
        $GLOBALS['wp_fts_test_before_delete_option'] = static function (string $optionName) use ($fake, &$boundary): void {
            $successorRan = false;
            $dropQueries = array_values(array_filter(
                $fake->queries,
                static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS ')
            ));
            $leaseAtBoundary = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? null;
            $successor = WP_FTS_Plugin::run_index_writer_with_lock(
                'uninstall-successor-probe',
                static function () use (&$successorRan): void {
                    $successorRan = true;
                },
                [
                    'batch_size' => 1,
                    'record_health' => false,
                    'record_skip' => false,
                ]
            );
            $boundary = [
                'option_name' => $optionName,
                'drop_count' => count($dropQueries),
                'tables_gone' => $fake->docs === [] && $fake->ftsTerms === [],
                'lease_mode' => is_array($leaseAtBoundary) ? ($leaseAtBoundary['mode'] ?? null) : null,
                'successor_acquired' => !empty($successor['acquired']),
                'successor_ran' => $successorRan,
            ];
        };

        WP_FTS_Plugin::uninstall();

        assert_same(WP_FTS_Plugin::SCHEMA_VERSION_OPTION, $boundary['option_name'] ?? null, 'the injected boundary should run immediately before the first operational option deletion');
        assert_same(1, $boundary['drop_count'] ?? null, 'the injected boundary should run after the one destructive table statement');
        assert_same(true, $boundary['tables_gone'] ?? null, 'the injected boundary should observe completed table cleanup');
        assert_same('uninstall', $boundary['lease_mode'] ?? null, 'the uninstall lease should still fence the option-deletion boundary');
        assert_same(false, $boundary['successor_acquired'] ?? null, 'a successor writer must not acquire between table cleanup and option deletion');
        assert_same(false, $boundary['successor_ran'] ?? null, 'a contended successor callback must execute zero mutations');
        wp_fts_test_assert_uninstall_drop($fake->queries, 'wp_', 'fenced-boundary uninstall');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'the outer uninstall and contended successor must not recreate health or other plugin options');
        foreach ($operationalOptions as $optionName) {
            assert_true(!isset($GLOBALS['wp_fts_test_options'][$optionName]), "fenced-boundary uninstall should leave {$optionName} absent");
        }
        assert_same('keep-site-1', $GLOBALS['wp_fts_test_options']['wp_fts_non_operational_marker'] ?? null, 'fenced-boundary uninstall should preserve unrelated options');
        assert_same(2, count($GLOBALS['wp_fts_test_added_options']), 'fenced-boundary uninstall should add only its writer lease and lifecycle fence');
        assert_same('uninstall', $GLOBALS['wp_fts_test_added_options'][0]['value']['mode'] ?? null, 'the only added option should be the uninstall lease');
        assert_same(WP_FTS_Plugin::UNINSTALL_FENCE_OPTION, $GLOBALS['wp_fts_test_added_options'][1]['name'] ?? null, 'the second added option should be the retained uninstall fence');
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_options'], 'fenced-boundary uninstall');
        $leaseDeletes = array_values(array_filter(
            $GLOBALS['wp_fts_test_deleted_options'],
            static fn(array $event): bool => ($event['name'] ?? null) === WP_FTS_Plugin::INDEX_LOCK_OPTION
        ));
        assert_same([true], array_column($leaseDeletes, 'existed'), 'the helper should release the exact owned lease without a stale post-release delete');
    } finally {
        unset($GLOBALS['wp_fts_test_before_delete_option']);
        $wpdb = $oldWpdb;
    }
});

test_case('uninstall exact release never deletes a successor lease', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();
    $successorLease = [
        'token' => 'successor-after-uninstall-release',
        'mode' => 'cron',
        'started_at' => time(),
        'heartbeat_at' => time(),
        'expires_at' => time() + 300,
        'renewals' => 0,
    ];
    $successorInstalled = false;

    try {
        $GLOBALS['wp_fts_test_options'] = wp_fts_test_uninstall_seeded_options($operationalOptions, 1);
        unset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]);
        $fake->queries = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];
        $GLOBALS['wp_fts_test_after_delete_option'] = static function (string $optionName, bool $existed) use ($successorLease, &$successorInstalled): void {
            if ($optionName !== WP_FTS_Plugin::INDEX_LOCK_OPTION || !$existed) {
                return;
            }
            unset($GLOBALS['wp_fts_test_after_delete_option']);
            $successorInstalled = add_option(WP_FTS_Plugin::INDEX_LOCK_OPTION, $successorLease, '', 'no');
        };

        WP_FTS_Plugin::uninstall();

        assert_same(true, $successorInstalled, 'the interleaving fixture should acquire a successor lease immediately after exact uninstall release');
        assert_same($successorLease, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] ?? null, 'uninstall must not issue a stale delete that erases the successor lease');
        foreach ($operationalOptions as $optionName) {
            if ($optionName === WP_FTS_Plugin::INDEX_LOCK_OPTION) {
                continue;
            }
            assert_true(!isset($GLOBALS['wp_fts_test_options'][$optionName]), "successor interleaving should not recreate removed {$optionName}");
        }
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'successor interleaving should not recreate health or other plugin state');
        wp_fts_test_assert_uninstall_drop($fake->queries, 'wp_', 'successor-interleaved uninstall');
        $leaseDeletes = array_values(array_filter(
            $GLOBALS['wp_fts_test_deleted_options'],
            static fn(array $event): bool => ($event['name'] ?? null) === WP_FTS_Plugin::INDEX_LOCK_OPTION
        ));
        assert_same([true], array_column($leaseDeletes, 'existed'), 'uninstall should perform only its token-checked release and no post-release lease delete');
        assert_same(
            [WP_FTS_Plugin::INDEX_LOCK_OPTION, WP_FTS_Plugin::UNINSTALL_FENCE_OPTION, WP_FTS_Plugin::INDEX_LOCK_OPTION],
            array_column($GLOBALS['wp_fts_test_added_options'], 'name'),
            'fixture should observe the uninstall owner, retained fence, then its synthetic successor'
        );
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_options'], 'successor-interleaved uninstall');
    } finally {
        unset($GLOBALS['wp_fts_test_after_delete_option']);
        $wpdb = $oldWpdb;
    }
});

test_case('foreground DML before uninstall is destroyed and same-request callbacks stay inert after DROP', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_save(990, (object) ['ID' => 990], true, null);
        assert_true(isset($fake->queue[990]), 'the pre-uninstall foreground DML fixture should create one durable work row');

        WP_FTS_Plugin::uninstall();
        $allQueries = array_map(
            static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
            $fake->queries
        );
        $upsertIndex = array_search(true, array_map(
            static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'),
            $allQueries
        ), true);
        $dropIndex = array_search(true, array_map(
            static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS '),
            $allQueries
        ), true);
        assert_true(is_int($upsertIndex) && is_int($dropIndex) && $upsertIndex < $dropIndex, 'work DML that wins the metadata-lock race should precede the destructive DROP');
        assert_same([], $fake->queue, 'the later DROP must destroy work DML that completed before uninstall');

        $fake->queries = [];
        $fake->prepared = [];
        WP_FTS_Plugin::handle_post_pre_update(991, []);
        WP_FTS_Plugin::handle_post_save(991, (object) ['ID' => 991], true, null);
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        assert_same([], $fake->queries, 'same-request callbacks after DROP should execute zero SQL');
        assert_same([], $fake->prepared, 'same-request callbacks after DROP should prepare zero SQL');
        assert_same([], $fake->queue, 'same-request callbacks after DROP must not recreate the work table or rows');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('a preloaded request that loses DML to DROP cannot recreate post-uninstall state', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->options = 'wp_options';
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        WP_FTS_Plugin::uninstall();
        $blockedPrefixes = new ReflectionProperty(WP_FTS_Plugin::class, 'foreground_queue_blocked_prefixes');
        $blocked = $blockedPrefixes->getValue();
        unset($blocked['wp_']);
        $blockedPrefixes->setValue(null, $blocked);
        WP_FTS_Plugin::reset_request_caches();

        // Model a second request that preloaded the current schema option before
        // uninstall committed, then lost its work-table DML to DROP.
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
        $fake->failQueryPrefix = 'INSERT INTO wp_fts_work';
        $fake->queries = [];
        $fake->prepared = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];
        $GLOBALS['wp_fts_test_schedule_calls'] = [];

        WP_FTS_Plugin::handle_post_save(992, (object) ['ID' => 992], true, null);
        unset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION]);

        $queries = array_map(
            static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
            $fake->queries
        );
        assert_same(1, count(array_filter($queries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'the preloaded request should attempt its work DML exactly once');
        assert_same(1, count(array_filter($queries, static fn(string $sql): bool => str_starts_with($sql, 'SELECT option_value FROM wp_options WHERE option_name = %s'))), 'only the failed-DML path should pay one indexed uninstall-fence probe');
        assert_same(0, count(array_filter($queries, static fn(string $sql): bool => str_starts_with($sql, 'CREATE TABLE'))), 'a DML-after-DROP loser must never recreate schema');
        assert_same([], $fake->queue, 'a DML-after-DROP loser must leave no work row');
        assert_same([], $GLOBALS['wp_fts_test_added_options'], 'a DML-after-DROP loser must add no operational option');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'a DML-after-DROP loser must update no health or readiness option');
        assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'a DML-after-DROP loser must delete no lifecycle option');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'a DML-after-DROP loser must schedule no repair or queue event');
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_options'], 'DML-after-DROP loser');
    } finally {
        $fake->failQueryPrefix = null;
        $wpdb = $oldWpdb;
    }
});

test_case('preloaded schema repair and foreground hooks remain inert behind the uninstall fence', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();

    try {
        $GLOBALS['wp_fts_test_options'] = wp_fts_test_uninstall_seeded_options($operationalOptions, 1);
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = 0;
        $preloadedRepair = static function (): void {
            WP_FTS_Plugin::run_scheduled_schema_repair();
        };
        WP_FTS_Plugin::maybe_schedule_schema_repair();
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]), 'preloaded repair fixture should begin with a scheduled schema event');

        WP_FTS_Plugin::uninstall();
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_options'], 'preloaded repair fixture uninstall');
        $optionsAfterUninstall = $GLOBALS['wp_fts_test_options'];
        $fake->queries = [];
        $fake->prepared = [];
        $GLOBALS['wp_fts_test_added_options'] = [];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];
        $GLOBALS['wp_fts_test_schedule_calls'] = [];
        $GLOBALS['wp_fts_test_scheduled'] = [];

        $preloadedRepair();
        WP_FTS_Plugin::maybe_schedule_schema_repair();
        WP_FTS_Plugin::storage(true);
        WP_FTS_Plugin::handle_post_save(991, (object) ['ID' => 991]);
        $writerRan = false;
        $writer = WP_FTS_Plugin::run_index_writer_with_lock(
            'schema-repair',
            static function () use (&$writerRan): void {
                $writerRan = true;
                WP_FTS_Plugin::storage(false)->create_tables();
            },
            ['record_health' => false, 'record_skip' => false]
        );
        $upgradeError = '';
        try {
            WP_FTS_Plugin::create_or_repair_schema();
        } catch (RuntimeException $error) {
            $upgradeError = $error->getMessage();
        }
        $directCreateBlocked = false;
        try {
            WP_FTS_Plugin::storage(false)->create_tables();
        } catch (WP_FTS_Index_Writer_Ownership_Lost) {
            $directCreateBlocked = true;
        }
        $schedule = WP_FTS_Plugin::schedule_queue_processor_for_operator();

        assert_same(false, $writerRan, 'a preloaded repair callback should never run after uninstall');
        assert_same(false, $writer['acquired'] ?? null, 'a non-activation writer should not acquire through the uninstall fence');
        assert_contains('blocked by the durable uninstall fence', $upgradeError, 'direct schema repair should fail with explicit activation guidance');
        assert_same(true, $directCreateBlocked, 'a storage object should reject direct schema creation without an owned activation lease');
        assert_same('uninstall_fenced', $schedule['status'] ?? null, 'operator scheduling should explicitly refuse the post-uninstall state');
        assert_same([], $fake->queries, 'preloaded repair, lazy storage, and foreground hooks should execute zero SQL after uninstall');
        assert_same([], $fake->prepared, 'preloaded repair should prepare zero SQL after uninstall');
        assert_same([], $GLOBALS['wp_fts_test_added_options'], 'preloaded repair should add no lock, health, or queue options');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'preloaded repair should update no health or lifecycle options');
        assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'preloaded repair should delete no lifecycle options');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'preloaded repair should schedule no schema or queue events');
        assert_same($optionsAfterUninstall, $GLOBALS['wp_fts_test_options'], 'the retained fence and unrelated option should remain the complete post-uninstall option state');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('single-site uninstall is idempotent and explicit activation alone recreates schema', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();

    try {
        $GLOBALS['wp_fts_test_options'] = wp_fts_test_uninstall_seeded_options($operationalOptions, 1);
        unset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]);
        $GLOBALS['wp_fts_test_added_options'] = [];
        $fake->queries = [];

        WP_FTS_Plugin::uninstall();
        WP_FTS_Plugin::uninstall();

        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_options'], 'idempotent single-site uninstall');
        $drops = array_values(array_filter($fake->queries, static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS ')));
        assert_same(2, count($drops), 'each idempotent uninstall retry should issue one bounded DROP statement');
        $fenceAdds = array_values(array_filter(
            $GLOBALS['wp_fts_test_added_options'],
            static fn(array $event): bool => ($event['name'] ?? null) === WP_FTS_Plugin::UNINSTALL_FENCE_OPTION
        ));
        assert_same(1, count($fenceAdds), 'idempotent uninstall should create its retained scalar fence only once');
        foreach ($operationalOptions as $optionName) {
            assert_true(!isset($GLOBALS['wp_fts_test_options'][$optionName]), "idempotent uninstall should keep {$optionName} absent");
        }

        WP_FTS_Plugin::handle_post_save(994, (object) ['ID' => 994], true, null);
        $blockedPrefixes = new ReflectionProperty(WP_FTS_Plugin::class, 'foreground_queue_blocked_prefixes');
        $blocked = $blockedPrefixes->getValue();
        $blocked['wp_2_'] = true;
        $blockedPrefixes->setValue(null, $blocked);
        $fake->queries = [];
        $GLOBALS['wp_fts_test_schedule_calls'] = [];
        WP_FTS_Plugin::activate();
        $activationQueries = $fake->queries;
        $blockedAfterActivation = $blockedPrefixes->getValue();

        assert_true(!isset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::UNINSTALL_FENCE_OPTION]), 'explicit activation should remove the durable uninstall fence inside its writer lease');
        assert_same(WP_FTS_Plugin::SCHEMA_VERSION, $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] ?? null, 'explicit activation should restore the logical schema version');
        assert_same(4, count(array_filter($activationQueries, static fn(string $sql): bool => str_starts_with($sql, 'CREATE TABLE'))), 'explicit activation should recreate exactly four current FTS tables');
        assert_same(1, count(array_filter($fake->queue, static fn(array $row): bool => ($row['kind'] ?? '') === 'scope')), 'explicit activation should restore one durable corpus reconciliation scope');
        assert_true(!isset($blockedAfterActivation['wp_']), 'explicit activation should restore foreground capability for only its current site prefix');
        assert_same(true, $blockedAfterActivation['wp_2_'] ?? null, 'explicit activation must not clear a sibling site uninstall capability');
        assert_same(1, count(array_filter(
            $GLOBALS['wp_fts_test_schedule_calls'],
            static fn(array $event): bool => ($event['hook'] ?? null) === WP_FTS_Plugin::CRON_HOOK
        )), 'explicit activation should restore one bounded queue processor event');

        $fake->queries = [];
        WP_FTS_Plugin::handle_post_save(995, (object) ['ID' => 995], true, null);
        assert_same(1, count(array_filter($fake->queries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'explicit activation should restore current-prefix foreground writes after a same-request blocked callback');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('multisite uninstall discovers 205 sites in bounded pages and remains idempotent', function (): void {
    global $wpdb;

    wp_fts_test_install_multisite_switch_functions();
    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();
    $siteIds = range(1, 205);
    $originalSiteId = 11;

    try {
        $GLOBALS['wp_fts_test_is_multisite'] = true;
        $GLOBALS['wp_fts_test_sites'] = $siteIds;
        $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
        $GLOBALS['wp_fts_test_current_blog_id'] = $originalSiteId;
        $fake->prefix = $fake->get_blog_prefix($originalSiteId);
        $fake->posts = $fake->prefix . 'posts';
        foreach ($siteIds as $siteId) {
            $GLOBALS['wp_fts_test_site_options'][$siteId] = wp_fts_test_uninstall_seeded_options($operationalOptions, $siteId);
        }
        $fake->docs[41] = [
            'lang' => 'en',
            'doc_len' => 2,
            'content_hash' => 'hash-41',
            'is_deleted' => 0,
        ];
        $fake->ftsTerms[WP_FTS_TermNamespace::namespace_term('en', 'alpha')] = ['doc_freq' => 1];

        WP_FTS_Plugin::uninstall();
        WP_FTS_Plugin::uninstall();

        $switchedPerRun = array_values(array_filter($siteIds, static fn(int $siteId): bool => $siteId !== $originalSiteId));
        assert_same(array_merge($switchedPerRun, $switchedPerRun), $GLOBALS['wp_fts_test_switch_log'], 'multisite uninstall should visit every non-current blog once per idempotent run');
        assert_same(array_fill(0, count($switchedPerRun) * 2, $originalSiteId), $GLOBALS['wp_fts_test_restore_log'], 'multisite uninstall should restore the original blog after every switch');
        assert_same($originalSiteId, get_current_blog_id(), 'multisite uninstall should leave the original blog active after cleanup');
        assert_same($fake->get_blog_prefix($originalSiteId), $fake->prefix, 'multisite uninstall should restore the original table prefix');
        foreach ($siteIds as $siteId) {
            foreach ($operationalOptions as $optionName) {
                assert_true(!isset($GLOBALS['wp_fts_test_site_options'][$siteId][$optionName]), "multisite uninstall should delete {$optionName} on site {$siteId}");
            }
            wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_site_options'][$siteId], "multisite uninstall site {$siteId}");
            assert_same("keep-site-{$siteId}", $GLOBALS['wp_fts_test_site_options'][$siteId]['wp_fts_non_operational_marker'] ?? null, "multisite uninstall should leave unrelated options on site {$siteId}");
        }
        assert_same([], $fake->docs, 'multisite uninstall should remove derived documents');
        assert_same([], $fake->ftsTerms, 'multisite uninstall should remove derived terms');

        $siteQueries = array_values(array_filter(
            $fake->prepared,
            static fn(array $query): bool => str_starts_with($query['sql'] ?? '', 'SELECT blog_id FROM `wp_blogs`')
        ));
        assert_same(6, count($siteQueries), 'two 205-site uninstall runs should use exactly three keyset discovery pages each');
        $expectedHighWaterMarks = [0, 100, 200, 0, 100, 200];
        foreach ($siteQueries as $index => $query) {
            assert_same([$expectedHighWaterMarks[$index], 100], $query['args'] ?? null, 'multisite uninstall should bind only its completed high-water mark and 100-site page limit');
            assert_contains('WHERE blog_id > %d ORDER BY blog_id ASC LIMIT %d', $query['sql'] ?? '', 'multisite uninstall discovery should use stable site-ID keyset order');
            assert_true(!str_contains($query['sql'] ?? '', 'OFFSET'), 'multisite uninstall must never use a mutable row offset');
        }
        assert_same([], $GLOBALS['wp_fts_test_get_sites_calls'], 'multisite uninstall should not use mutable WP_Site_Query offset pages');

        $dropQueries = array_values(array_filter($fake->queries, static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS ')));
        assert_same(410, count($dropQueries), 'two 205-site uninstall runs should issue exactly one DROP statement per site and no per-table statements');
        foreach ($dropQueries as $sql) {
            assert_same(12, substr_count($sql, ', ') + 1, 'each site DROP should cover four current and eight reset-generation table names');
        }
        assert_same([], $GLOBALS['wp_fts_test_posts'], 'multisite uninstall should not create content posts');
        assert_same([], $GLOBALS['wp_fts_test_trashed_posts'], 'multisite uninstall should not delete or trash canonical content posts');
        assert_true(!str_contains(implode("\n", $fake->queries), 'TRUNCATE TABLE'), 'multisite uninstall should not run a separate table scan or truncate');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('multisite uninstall keyset pages do not skip a boundary site after concurrent deletion', function (): void {
    global $wpdb;

    wp_fts_test_install_multisite_switch_functions();
    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
