            }
            $siteReadCount++;
            if ($siteReadCount === 2) {
                // Deleting an already-consumed row shifts every later OFFSET
                // page left. A keyset page after blog 100 must still start at 101.
                $GLOBALS['wp_fts_test_sites'] = array_values(array_filter(
                    $GLOBALS['wp_fts_test_sites'],
                    static fn(int $siteId): bool => $siteId !== 50
                ));
            }
        };

        WP_FTS_Plugin::uninstall();

        assert_same(3, $siteReadCount, '201 sites should require exactly 100, 100, and 1-row discovery pages');
        assert_same(range(2, 201), $GLOBALS['wp_fts_test_switch_log'], 'deleting blog 50 between pages must not skip boundary blog 101 or any later survivor');
        foreach ($operationalOptions as $optionName) {
            assert_true(!isset($GLOBALS['wp_fts_test_site_options'][101][$optionName]), "boundary blog 101 should delete {$optionName}");
        }
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_site_options'][101], 'boundary blog 101');
        $siteQueries = array_values(array_filter(
            $fake->prepared,
            static fn(array $query): bool => str_starts_with($query['sql'] ?? '', 'SELECT blog_id FROM `wp_blogs`')
        ));
        assert_same([[0, 100], [100, 100], [200, 100]], array_column($siteQueries, 'args'), 'concurrent deletion must not change the monotonic site-ID high-water marks');
        assert_same([], $GLOBALS['wp_fts_test_get_sites_calls'], 'concurrent deletion coverage must exercise direct keyset discovery, not the offset fake');
        assert_same(201, count(array_filter(
            $fake->queries,
            static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS ')
        )), 'worst-case traversal should retain one bounded DROP statement per visited site');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('multisite uninstall fences a concurrent site repair while independently cleaning sibling sites', function (): void {
    global $wpdb;

    wp_fts_test_install_multisite_switch_functions();
    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();
    $activeRepairLease = [
        'token' => 'active-schema-repair-fence',
        'mode' => 'schema-repair',
        'started_at' => time() - 10,
        'heartbeat_at' => time() - 10,
        'expires_at' => time() + 290,
        'renewals' => 0,
    ];

    try {
        $GLOBALS['wp_fts_test_is_multisite'] = true;
        $GLOBALS['wp_fts_test_sites'] = [1, 2, 3];
        $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
        $GLOBALS['wp_fts_test_current_blog_id'] = 1;
        $fake->prefix = $fake->get_blog_prefix(1);
        $fake->posts = $fake->prefix . 'posts';
        foreach ([1, 2, 3] as $siteId) {
            $GLOBALS['wp_fts_test_site_options'][$siteId] = wp_fts_test_uninstall_seeded_options($operationalOptions, $siteId);
        }
        $GLOBALS['wp_fts_test_site_options'][2][WP_FTS_Plugin::INDEX_LOCK_OPTION] = $activeRepairLease;
        $contendedOptionsBefore = $GLOBALS['wp_fts_test_site_options'][2];
        $fake->queries = [];
        $GLOBALS['wp_fts_test_deleted_options'] = [];

        $message = '';
        try {
            WP_FTS_Plugin::uninstall();
        } catch (RuntimeException $error) {
            $message = $error->getMessage();
        }

        assert_contains('1 multisite blog(s)', $message, 'multisite uninstall should aggregate rather than hide one contended blog');
        assert_contains('first failed blog ID: 2', $message, 'multisite uninstall should identify the first blog that must be retried');
        assert_same([2, 3], $GLOBALS['wp_fts_test_switch_log'], 'multisite uninstall should continue from a contended blog to its next sibling');
        assert_same([1, 1], $GLOBALS['wp_fts_test_restore_log'], 'multisite uninstall should restore the original blog after both switches');
        assert_same(1, get_current_blog_id(), 'multisite contention should leave the original blog active');
        assert_same($contendedOptionsBefore, $GLOBALS['wp_fts_test_site_options'][2], 'the contended site should preserve every option and exact repair lease');
        $siteTwoDeletes = array_values(array_filter(
            $GLOBALS['wp_fts_test_deleted_options'],
            static fn(array $event): bool => ($event['blog_id'] ?? null) === 2
        ));
        assert_same([], $siteTwoDeletes, 'the contended site should delete zero options');
        foreach ([1, 3] as $siteId) {
            foreach ($operationalOptions as $optionName) {
                assert_true(!isset($GLOBALS['wp_fts_test_site_options'][$siteId][$optionName]), "multisite uninstall should still delete {$optionName} on sibling site {$siteId}");
            }
            wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_site_options'][$siteId], "multisite sibling {$siteId}");
            assert_same("keep-site-{$siteId}", $GLOBALS['wp_fts_test_site_options'][$siteId]['wp_fts_non_operational_marker'] ?? null, "multisite uninstall should preserve unrelated data on sibling site {$siteId}");
        }
        $dropQueries = array_values(array_filter(
            $fake->queries,
            static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS ')
        ));
        $lifecycleQueries = array_values(array_filter(
            $fake->queries,
            static fn(string $sql): bool => !str_starts_with($sql, 'DROP TABLE IF EXISTS ')
        ));
        assert_same(2, count($dropQueries), 'multisite contention should issue one DROP for each uncontended sibling and none for the active repair site');
        wp_fts_test_assert_uninstall_drop([$dropQueries[0]], 'wp_', 'original multisite sibling');
        wp_fts_test_assert_uninstall_drop([$dropQueries[1]], 'wp_3_', 'later multisite sibling');
        assert_same(5, count($lifecycleQueries), 'three site boundaries must add exactly one network lease insert, three heartbeats, and one exact release');
        assert_same(1, count(array_filter(
            $lifecycleQueries,
            static fn(string $sql): bool => str_starts_with($sql, 'INSERT IGNORE INTO wp_options ')
        )), 'multisite uninstall should acquire its network lease in one unique-row insert');
        assert_same(3, count(array_filter(
            $lifecycleQueries,
            static fn(string $sql): bool => str_starts_with($sql, 'UPDATE wp_options SET option_value = %s WHERE option_name = %s AND option_value = %s')
        )), 'multisite uninstall should heartbeat exactly once before each site boundary, including the contended site');
        assert_same(1, count(array_filter(
            $lifecycleQueries,
            static fn(string $sql): bool => str_starts_with($sql, 'DELETE FROM wp_options WHERE option_name = %s AND option_value = %s')
        )), 'multisite uninstall should exact-delete its network lease once after all sites');
        assert_same(5, count(array_filter(
            $fake->prepared,
            static fn(array $prepared): bool => in_array('wp_fts_network_lifecycle_lock', $prepared['args'] ?? [], true)
        )), 'every non-destructive lifecycle statement must be bound to the singleton network lease row');
        assert_same(7, count($fake->queries), 'the contended three-site lifecycle must remain bounded at five lease statements plus two DROPs');
        assert_true(!str_contains(implode("\n", $fake->queries), 'wp_2_fts_'), 'the contended repair site must issue zero destructive table statements');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('multisite uninstall falls back to current-site cleanup when site enumeration is empty', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $operationalOptions = wp_fts_test_uninstall_operational_option_names();

    try {
        $GLOBALS['wp_fts_test_is_multisite'] = true;
        $GLOBALS['wp_fts_test_sites'] = [];
        $GLOBALS['wp_fts_test_use_blog_option_store'] = true;
        $GLOBALS['wp_fts_test_current_blog_id'] = 7;
        $fake->prefix = $fake->get_blog_prefix(7);
        $fake->posts = $fake->prefix . 'posts';
        $GLOBALS['wp_fts_test_site_options'][7] = wp_fts_test_uninstall_seeded_options($operationalOptions, 7);
        $fake->docs[71] = ['primary_lang' => 'en', 'content_hash' => 'hash-71'];

        WP_FTS_Plugin::uninstall();

        assert_same([], $GLOBALS['wp_fts_test_switch_log'], 'empty multisite enumeration should not switch blogs');
        assert_same([], $GLOBALS['wp_fts_test_restore_log'], 'empty multisite enumeration should not restore an unmade switch');
        assert_same(7, (int) ($GLOBALS['wp_fts_test_current_blog_id'] ?? 0), 'empty multisite enumeration should keep the current blog active');
        foreach ($operationalOptions as $option_name) {
            assert_true(!isset($GLOBALS['wp_fts_test_site_options'][7][$option_name]), "empty multisite enumeration fallback should delete {$option_name}");
        }
        wp_fts_test_assert_uninstall_fence($GLOBALS['wp_fts_test_site_options'][7], 'empty multisite enumeration fallback');
        assert_same('keep-site-7', $GLOBALS['wp_fts_test_site_options'][7]['wp_fts_non_operational_marker'] ?? null, 'empty multisite enumeration fallback should leave unrelated options alone');
        $dropQueries = array_values(array_filter(
            $fake->queries,
            static fn(string $sql): bool => str_starts_with($sql, 'DROP TABLE IF EXISTS ')
        ));
        $lifecycleQueries = array_values(array_filter(
            $fake->queries,
            static fn(string $sql): bool => !str_starts_with($sql, 'DROP TABLE IF EXISTS ')
        ));
        wp_fts_test_assert_uninstall_drop($dropQueries, 'wp_7_', 'empty multisite enumeration fallback');
        assert_same(4, count($lifecycleQueries), 'current-site fallback must use one lease insert, two exact heartbeats, and one exact release');
        assert_same(1, count(array_filter(
            $lifecycleQueries,
            static fn(string $sql): bool => str_starts_with($sql, 'INSERT IGNORE INTO wp_options ')
        )), 'current-site fallback should acquire the unique network lease once');
        assert_same(2, count(array_filter(
            $lifecycleQueries,
            static fn(string $sql): bool => str_starts_with($sql, 'UPDATE wp_options SET option_value = %s WHERE option_name = %s AND option_value = %s')
        )), 'current-site fallback should renew at its two destructive boundaries');
        assert_same(1, count(array_filter(
            $lifecycleQueries,
            static fn(string $sql): bool => str_starts_with($sql, 'DELETE FROM wp_options WHERE option_name = %s AND option_value = %s')
        )), 'current-site fallback should exact-delete its network lease once');
        assert_same(4, count(array_filter(
            $fake->prepared,
            static fn(array $prepared): bool => in_array('wp_fts_network_lifecycle_lock', $prepared['args'] ?? [], true)
        )), 'every fallback lifecycle statement must be bound to the singleton network lease row');
        assert_same(5, count($fake->queries), 'empty enumeration fallback must stay bounded at four lease statements plus one DROP');
        assert_same([], $fake->docs, 'empty enumeration fallback should still remove current-site derived documents');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('taxonomy and selected metadata mutations coalesce dependent post reindexing', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $posts = [
        201 => (object) [
            'ID' => 201,
            'post_title' => 'First dependency host',
            'post_content' => '<p>dependency body one</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-07-01 00:00:00',
            'terms' => ['category' => ['FormerTaxonomySignal']],
            'custom_fields' => ['subtitle' => 'FormerMetadataSignal'],
        ],
        202 => (object) [
            'ID' => 202,
            'post_title' => 'Second dependency host',
            'post_content' => '<p>dependency body two</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-07-01 00:00:00',
            'terms' => ['category' => ['FormerTaxonomySignal']],
            'custom_fields' => ['subtitle' => 'StableMetadataSignal'],
        ],
    ];
    $GLOBALS['wp_fts_test_posts'] = $posts;
    $fake->postRows = array_values($posts);
    $GLOBALS['wp_fts_test_options']['wp_fts_index_custom_fields'] = ['subtitle'];
    wp_fts_test_mark_search_takeover_ready();
    $pendingWorkRows = static fn(): array => array_values(array_filter(
        $fake->queue,
        static fn(array $row): bool => in_array((string) ($row['kind'] ?? ''), ['post', 'scope'], true)
    ));

    try {
        WP_FTS_Plugin::handle_post_save(201, $posts[201]);
        WP_FTS_Plugin::handle_post_save(202, $posts[202]);
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        assert_same([202, 201], array_column(WP_FTS_Plugin::search('FormerTaxonomySignal', ['limit' => 10]), 'doc_id'), 'initial indexing should include the shared taxonomy label with the stable descending-id tie break');
        assert_same([201], array_column(WP_FTS_Plugin::search('FormerMetadataSignal', ['limit' => 10]), 'doc_id'), 'initial indexing should include the selected metadata value');

        $posts[201]->terms = ['category' => ['CurrentTaxonomySignal']];
        $posts[202]->terms = ['category' => ['CurrentTaxonomySignal']];
        $posts[201]->custom_fields = ['subtitle' => 'CurrentMetadataSignal'];
        $GLOBALS['wp_fts_test_term_object_ids']['category:7'] = [202, 201, 202, 9999];
        $GLOBALS['wp_fts_test_updated_options'] = [];
        $GLOBALS['wp_fts_test_schedule_calls'] = [];
        $GLOBALS['wp_fts_test_scheduled'] = [];

        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(7, 'category', ['term_taxonomy_id' => 70]);
        WP_FTS_Plugin::handle_taxonomy_term_edit(7, 70, 'category', ['name' => 'CurrentTaxonomySignal']);
        assert_same(true, (new ReflectionClass(WP_FTS_Plugin::class))->getProperty('foreground_mutation_has_scope')->getValue(), 'the request tracker should remember that its first mutation target was a scope');
        WP_FTS_Plugin::handle_post_meta_pre_update(501, 201, 'subtitle', 'CurrentMetadataSignal');
        $mixedBulkState = (new ReflectionClass(WP_FTS_Plugin::class))->getProperty('foreground_bulk_mutation_scope')->getValue();
        assert_same(true, $mixedBulkState['requires_corpus'] ?? null, 'adding a post target after a scope must escalate the request-global handoff to corpus reconciliation');
        WP_FTS_Plugin::handle_post_meta_change(501, 201, 'subtitle', 'CurrentMetadataSignal');
        WP_FTS_Plugin::handle_term_relationship_pre_change(201, 70, 'category');
        WP_FTS_Plugin::handle_term_relationship_change(201, 70, 'category');
        WP_FTS_Plugin::flush_post_meta_mutations();
        WP_FTS_Plugin::flush_foreground_bulk_mutations();

        assert_same([], wp_fts_test_queue_ids($fake), 'mixed scope and post fan-out should defer exact membership to one corpus reconciliation');
        $scopeRows = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
        ));
        assert_same(1, count($scopeRows), 'canonical corpus work should subsume the request-owned targeted generation');
        $globalScopeRows = array_values(array_filter(
            $scopeRows,
            static fn(array $row): bool => (string) ($row['scope_subject_type'] ?? '') === ''
        ));
        assert_same(1, count($globalScopeRows), 'mixed fan-out should create exactly one global corpus scope');
        assert_same('ready', $globalScopeRows[0]['state'] ?? null, 'the shutdown handoff should make corpus reconciliation immediately claimable');

        $expanded = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        assert_same(2, $expanded['backfill_queued'] ?? null, 'the first bounded processor pass should expand one taxonomy-scope page without requiring inline fan-out');
        $processed = 0;
        for ($pass = 0; $pass < 6 && $pendingWorkRows() !== []; $pass++) {
            $summary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
            $processed += (int) ($summary['queue_processed'] ?? 0);
        }
        assert_true($processed >= 2, 'subsequent bounded processor passes should reindex every current taxonomy member');
        assert_same([], $pendingWorkRows(), 'bounded scope expansion should eventually drain direct work, including a vanished relationship target');
        WP_FTS_Plugin::run_scheduled_schema_repair();
        assert_same([], WP_FTS_Plugin::search('FormerTaxonomySignal', ['limit' => 10]), 'term rename processing should remove the former taxonomy label');
        assert_same([202, 201], array_column(WP_FTS_Plugin::search('CurrentTaxonomySignal', ['limit' => 10]), 'doc_id'), 'term rename processing should index the current taxonomy label with stable descending-id ties');
        assert_same([], WP_FTS_Plugin::search('FormerMetadataSignal', ['limit' => 10]), 'selected metadata processing should remove the former value');
        assert_same([201], array_column(WP_FTS_Plugin::search('CurrentMetadataSignal', ['limit' => 10]), 'doc_id'), 'selected metadata processing should index the current value');
        assert_same([], WP_FTS_Plugin::search('IgnoredMetadataSignal', ['limit' => 10]), 'unselected metadata should remain outside the index');

        $posts[201]->custom_fields = ['subtitle' => 'LatestMetadataSignal'];
        WP_FTS_Plugin::handle_post_meta_pre_update(502, 201, 'subtitle', 'LatestMetadataSignal');
        WP_FTS_Plugin::handle_post_meta_change(502, 201, 'subtitle', 'LatestMetadataSignal');
        assert_same([201], wp_fts_test_queue_ids($fake), 'one configured metadata mutation should enqueue its host post');
        WP_FTS_Plugin::flush_post_meta_mutations();
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same([], WP_FTS_Plugin::search('CurrentMetadataSignal', ['limit' => 10]), 'configured metadata invalidation should remove the previous value');
        assert_same([201], array_column(WP_FTS_Plugin::search('LatestMetadataSignal', ['limit' => 10]), 'doc_id'), 'configured metadata invalidation should index the replacement value');

        WP_FTS_Plugin::handle_term_relationship_pre_change(202, 71, 'category');
        WP_FTS_Plugin::handle_term_relationship_change(202, 71, 'category');
        assert_same([202], wp_fts_test_queue_ids($fake), 'one relationship mutation should enqueue its host post');
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        WP_FTS_Plugin::handle_taxonomy_term_pre_delete(7, 'category');
        assert_same([], wp_fts_test_queue_ids($fake), 'term pre-delete should not enumerate an unbounded relationship fan-out into direct rows');
        $deleteScopes = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
                && (string) ($row['scope_subject_type'] ?? '') === ''
        ));
        assert_same(1, count($deleteScopes), 'term pre-delete should install one global fail-closed reconciliation scope');
        assert_same('taxonomy_term_deleted', json_decode((string) ($deleteScopes[0]['payload'] ?? ''), true)['reason'] ?? null, 'the global scope should record taxonomy deletion as its bounded reason');
        $deleteScopeUnavailable = false;
        try {
            WP_FTS_Plugin::search('CurrentTaxonomySignal', ['limit' => 10]);
        } catch (WP_FTS_Search_Unavailable) {
            $deleteScopeUnavailable = true;
        }
        assert_same(true, $deleteScopeUnavailable, 'the pre-delete global scope should disable stale FTS takeover immediately');
        $posts[201]->terms = [];
        $posts[202]->terms = [];
        WP_FTS_Plugin::handle_taxonomy_term_delete(7, 70, 'category', (object) ['name' => 'FormerTaxonomySignal'], [201, 202]);
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        for ($pass = 0; $pass < 6 && $pendingWorkRows() !== []; $pass++) {
            WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        }
        assert_same([], $pendingWorkRows(), 'bounded global reconciliation should drain taxonomy deletion work without foreground fan-out');
        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK]), 'global-scope completion should automatically schedule the separate readiness verifier');
        WP_FTS_Plugin::run_scheduled_schema_repair();
        assert_same([], WP_FTS_Plugin::search('CurrentTaxonomySignal', ['limit' => 10]), 'taxonomy deletion reconciliation should remove the deleted label from every retained host');

        WP_FTS_Plugin::handle_post_meta_change(503, 201, 'unselected_key', 'IgnoredMetadataSignal');
        assert_same([], wp_fts_test_queue_ids($fake), 'unselected metadata changes should not enqueue the post');
        $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER] = static function (array $options): array {
            $options['custom_fields'] = ['runtime_selected_key'];
            return $options;
        };
        WP_FTS_Plugin::handle_post_meta_pre_update(504, 201, 'runtime_selected_key', 'RuntimeSelectedSignal');
        WP_FTS_Plugin::handle_post_meta_change(504, 201, 'runtime_selected_key', 'RuntimeSelectedSignal');
        assert_same([201], wp_fts_test_queue_ids($fake), 'runtime plugin index options should use the same metadata selection during invalidation');
        WP_FTS_Plugin::flush_post_meta_mutations();
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        unset($GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER]);
        WP_FTS_Plugin::handle_post_meta_pre_update(505, 201, WP_FTS_Plugin::LANGUAGE_META_KEY, 'pl');
        WP_FTS_Plugin::handle_post_meta_change(505, 201, WP_FTS_Plugin::LANGUAGE_META_KEY, 'pl');
        assert_same([201], wp_fts_test_queue_ids($fake), 'direct language metadata changes should also invalidate the indexed post');
        WP_FTS_Plugin::flush_post_meta_mutations();
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('normal post mutation boundaries use one UPSERT each and no uninstall option probe', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->options = 'wp_options';
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        $fake->queries = [];
        $fake->prepared = [];
        WP_FTS_Plugin::handle_post_pre_update(2199, ['post_content' => '<p>bounded pre</p>']);
        $preQueries = array_map(
            static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
            $fake->queries
        );
        $prePrepared = $fake->prepared;

        $fake->queries = [];
        $fake->prepared = [];
        WP_FTS_Plugin::handle_post_save(2199, (object) ['ID' => 2199], true, null);
        $postQueries = array_map(
            static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
            $fake->queries
        );
        $postPrepared = $fake->prepared;
    } finally {
        $wpdb = $oldWpdb;
    }

    $isWorkUpsert = static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work');
    $isUninstallProbe = static fn(string $sql): bool => str_starts_with(
        $sql,
        'SELECT option_value FROM wp_options WHERE option_name = %s'
    );
    assert_same(1, count(array_filter($preQueries, $isWorkUpsert)), 'pre-update should execute exactly one work-table UPSERT');
    assert_same(1, count(array_filter($postQueries, $isWorkUpsert)), 'post-commit should execute exactly one work-table UPSERT');
    assert_same(1, count($preQueries), 'pre-update should execute no plugin SQL beyond its work-table UPSERT');
    assert_same(1, count($postQueries), 'post-commit should execute no plugin SQL beyond its work-table UPSERT');
    assert_same(0, count(array_filter($preQueries, $isUninstallProbe)), 'pre-update must not query the uninstall option');
    assert_same(0, count(array_filter($postQueries, $isUninstallProbe)), 'post-commit must not query the uninstall option');
    assert_same(0, count(array_filter($prePrepared, static fn(array $entry): bool => $isUninstallProbe((string) ($entry['sql'] ?? '')))), 'pre-update must not even prepare the uninstall option probe');
    assert_same(0, count(array_filter($postPrepared, static fn(array $entry): bool => $isUninstallProbe((string) ($entry['sql'] ?? '')))), 'post-commit must not even prepare the uninstall option probe');
});

test_case('foreground owner keeps pre-mutation work hidden until fatal release', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(2201, 'post', 'publish', 'Fatal boundary host');
    $post->post_content = '<p>BeforeFatalBoundarySignal</p>';
    $GLOBALS['wp_fts_test_posts'][2201] = $post;

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());
        assert_same([2201], array_column(WP_FTS_Plugin::search('BeforeFatalBoundarySignal', ['limit' => 10]), 'doc_id'), 'setup should expose the old canonical projection');

        $fake->queries = [];
        WP_FTS_Plugin::handle_post_pre_update(2201, ['post_content' => '<p>AfterFatalBoundarySignal</p>']);
        $foregroundQueries = $fake->queries;
        $post->post_content = '<p>AfterFatalBoundarySignal</p>';
        // Deliberately omit wp_after_insert_post and leave only the durable
        // pre-mutation row after wp_posts commits.
        $oldResults = WP_FTS_Plugin::search('BeforeFatalBoundarySignal', ['limit' => 10]);
        $newResults = WP_FTS_Plugin::search('AfterFatalBoundarySignal', ['limit' => 10]);
        $fatalFence = $fake->queue[2201] ?? [];

        $beforeAbandonment = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        // The finite deadline alone is not proof of abandonment. An arbitrarily
        // long live request still owns its shared guard and cannot race a
        // worker snapshot after canonical SQL.
        $fake->queue[2201]['available_at'] = time() - 1;
        $liveExpiredWorker = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $liveExpiredFence = $fake->queue[2201] ?? [];

        // Process death closes the guard descriptor. The already-expired row
        // must then recover immediately without a heartbeat or another write
        // from the dead request.
        WP_FTS_Plugin::reset_request_caches();
        $abandonmentWorker = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $recoveredResults = WP_FTS_Plugin::search('AfterFatalBoundarySignal', ['limit' => 10]);
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    $upserts = array_values(array_filter($foregroundQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    assert_same(1, count($upserts), 'the pre-update boundary should cost exactly one single-row queue UPSERT');
    assert_true(strlen($upserts[0] ?? '') < 1048576, 'the fatal-safe foreground statement must stay below 1 MiB');
    assert_same('guarded', $fatalFence['state'] ?? null, 'a killed post-save request must retain an explicit durable fence');
    assert_true((int) ($fatalFence['available_at'] ?? 0) >= time() + 299, 'a killed request should retain a bounded crash-recovery delay');
    assert_same(0, $beforeAbandonment['attempted'] ?? null, 'a fence must remain categorically unclaimable before its abandonment deadline');
    assert_same(0, $liveExpiredWorker['attempted'] ?? null, 'an expired guarded fence must remain unclaimable while its request owner is alive');
    assert_same('guarded', $liveExpiredFence['state'] ?? null, 'a live owner must retain the same durable fence beyond its watchdog deadline');
    assert_same($fatalFence['claim_token'] ?? null, $liveExpiredFence['claim_token'] ?? null, 'worker probes must not replace a live foreground ownership token');
    assert_same([], $oldResults, 'pending work must hide removed stale text immediately after the canonical commit');
    assert_same([], $newResults, 'the unindexed replacement must not appear before a worker commits it');
    assert_same(1, $abandonmentWorker['committed'] ?? null, 'an expired generation should recover immediately after fatal owner release');
    assert_same([2201], array_column($recoveredResults, 'doc_id'), 'crash recovery should index the committed replacement source');
});

test_case('expired mutation fences outrank a continuously full ready backlog', function (): void {
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
    $queue = new WP_FTS_Index_Queue($fake);
    $now = time();
    $readyA = range(50000, 50199);
    $queue->enqueue_many($readyA, $now - 10);
    $postToken = 'guard:' . str_repeat('p', 32);
    $globalToken = 'guard:' . str_repeat('g', 32);
    $queue->fence_post(60001, $postToken, $now + 300);
    $queue->fence_scope(
        'backlog-global-fence',
        $globalToken,
        ['reason' => 'backlog-recovery'],
        $now + 300,
        WP_FTS_Index_Queue::SCOPE_COVERAGE_GLOBAL
    );

    $beforeDeadline = $queue->claim_batch(100, $now, 30);
    assert_same([], array_values(array_filter(
        $beforeDeadline,
        static fn(array $claim): bool => ($claim['kind'] ?? '') === 'scope'
            || (int) ($claim['post_id'] ?? 0) === 60001
    )), 'future fences must remain unclaimable even while a full ready batch exists');
    $queue->acknowledge_many($beforeDeadline, $now);

    // Replenish more than another full batch so recovery cannot depend on an
    // empty normal claim. Also leave one expired lease among the ordinary work
    // to prove the recoverable index orders it by lease expiry.
    $queue->enqueue(50999, $now - 200);
    $leased = $queue->claim_batch(1, $now - 100, 30);
    assert_same(1, count($leased), 'the lease-expiry adversary needs one leased generation');
    $readyB = range(51000, 51199);
    $queue->enqueue_many($readyB, $now - 5);
    $globalKey = 'scope:' . hash('sha256', 'backlog-global-fence');
    $fake->queue[60001]['available_at'] = $now - 1;
    $fake->queue[$globalKey]['available_at'] = $now - 1;

    $fake->queries = [];
    $recovered = $queue->claim_batch(100, $now, 30);
    $workSql = array_values(array_filter(
        array_map(static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query, $fake->queries),
        static fn(string $sql): bool => str_contains($sql, 'wp_fts_work')
    ));
    $recoveredScopes = array_values(array_filter(
        $recovered,
        static fn(array $claim): bool => ($claim['kind'] ?? '') === 'scope'
    ));
    $recoveredPosts = array_values(array_filter(
        $recovered,
        static fn(array $claim): bool => ($claim['kind'] ?? '') === 'post'
    ));
    assert_same(1, count($recoveredScopes), 'one abandoned global scope must outrank a replenished ready backlog');
    assert_same($globalKey, $recoveredScopes[0]['job_key'] ?? null, 'the exact global sentinel should own the bounded scope slot');
    assert_true(in_array(60001, array_column($recoveredPosts, 'post_id'), true), 'the abandoned post fence must occupy the bounded post batch before ready work');
    assert_true(in_array((int) ($leased[0]['post_id'] ?? 0), array_column($recoveredPosts, 'post_id'), true), 'an expired lease must be selected by its indexed expiration without waiting for an empty batch');
    assert_same(2, count($workSql), 'claiming scope plus posts must stay one UPDATE and one confirmation SELECT regardless of backlog size');
    assert_true($queue->acknowledge_scope($recoveredScopes[0]), 'the recovered global generation should acknowledge by exact token');
    $queue->acknowledge_many($recoveredPosts, $now + 1);

    $targetedToken = 'guard:' . str_repeat('t', 32);
    $queue->fence_scope(
        'backlog-targeted-fence',
        $targetedToken,
        ['reason' => 'targeted-backlog-recovery'],
        $now - 1,
        WP_FTS_Index_Queue::SCOPE_COVERAGE_TARGETED,
        'term_taxonomy',
        77
    );
    $targeted = $queue->claim_batch(100, $now, 30);
    $targetedScopes = array_values(array_filter(
        $targeted,
        static fn(array $claim): bool => ($claim['kind'] ?? '') === 'scope'
    ));
    assert_same(1, count($targetedScopes), 'an abandoned targeted fence must also outrank the sustained backlog in one pass');
    assert_same(77, $targetedScopes[0]['scope_subject_id'] ?? null, 'targeted recovery must preserve narrow authority');
    assert_true($queue->acknowledge_scope($targetedScopes[0]), 'the targeted recovered generation should acknowledge exactly once');
});

test_case('foreground owner needs no TTL heartbeat before fatal recovery', function (): void {
    global $wpdb, $wp_current_filter;

    $oldWpdb = $wpdb ?? null;
    $oldCurrentFilter = $wp_current_filter ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(60011, 'post', 'publish', 'Long request host');
    $post->post_content = '<p>BeforeLongRequestResume</p>';
    $GLOBALS['wp_fts_test_posts'][60011] = $post;

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());
        $wp_current_filter = ['add_term_relationship'];
        WP_FTS_Plugin::handle_term_relationship_pre_change(60011, 1, 'category');
        $queriesAfterFirstPre = count($fake->queries);
        WP_FTS_Plugin::handle_term_relationship_pre_change(60011, 2, 'category');
        assert_same($queriesAfterFirstPre, count($fake->queries), 'coalesced pre hooks before TTL must perform zero additional SQL');

        $fake->queue[60011]['available_at'] = time() - 1;
        $tokensProperty = new ReflectionProperty(WP_FTS_Plugin::class, 'mutation_fence_tokens');
        $tokens = $tokensProperty->getValue();
        $tokens['post:60011']['expires_at'] = time() - 1;
        $tokensProperty->setValue(null, $tokens);
        $firstRecovery = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $expiredLiveFence = $fake->queue[60011] ?? [];

        $fake->queries = [];
        WP_FTS_Plugin::handle_term_relationship_pre_change(60011, 3, 'category');
        $continuedQueries = $fake->queries;
        $continuedFence = $fake->queue[60011] ?? [];
        $post->post_content = '<p>AfterLongRequestResume</p>';
        // The same live owner may continue canonical work without refreshing a
        // database deadline. Its guard remains the liveness authority.
        $hiddenBeforeRecovery = WP_FTS_Plugin::search('BeforeLongRequestResume', ['limit' => 10]);
        $newHiddenBeforeRecovery = WP_FTS_Plugin::search('AfterLongRequestResume', ['limit' => 10]);

        // Now simulate the fatal boundary: releasing the request guard makes
        // the already-expired durable generation immediately recoverable.
        WP_FTS_Plugin::reset_request_caches();
        $fatalRecovery = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $visibleAfterRecovery = WP_FTS_Plugin::search('AfterLongRequestResume', ['limit' => 10]);
    } finally {
        if ($oldCurrentFilter === null) {
            unset($wp_current_filter);
        } else {
            $wp_current_filter = $oldCurrentFilter;
        }
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same(0, $firstRecovery['attempted'] ?? null, 'wall-clock expiry must not let a worker race a live foreground owner');
    assert_same('guarded', $expiredLiveFence['state'] ?? null, 'the expired row must remain guarded while its owner guard lives');
    assert_same([], $continuedQueries, 'a live foreground owner must perform no database query solely because wall time passed');
    assert_same($expiredLiveFence['claim_token'] ?? null, $continuedFence['claim_token'] ?? null, 'continued canonical work must retain the original guarded token');
    assert_same($expiredLiveFence['available_at'] ?? null, $continuedFence['available_at'] ?? null, 'continued canonical work must not renew the finite watchdog deadline');
    assert_same([], $hiddenBeforeRecovery, 'continued canonical work must not expose stale text');
    assert_same([], $newHiddenBeforeRecovery, 'continued canonical work must not expose an unindexed replacement');
    assert_same(1, $fatalRecovery['committed'] ?? null, 'fatal guard release should make the expired generation immediately recoverable');
    assert_same([60011], array_column($visibleAfterRecovery, 'doc_id'), 'fatal recovery should index the latest canonical source');
});

test_case('foreground owner keeps an expired bulk sentinel guarded without a heartbeat', function (): void {
    global $wpdb, $wp_current_filter;

    $oldWpdb = $wpdb ?? null;
    $oldCurrentFilter = $wp_current_filter ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        WP_FTS_Plugin::handle_post_pre_update(60021, []);
        WP_FTS_Plugin::handle_post_save(60021, (object) ['ID' => 60021]);
        WP_FTS_Plugin::handle_post_pre_update(60022, []);
        $bulkProperty = new ReflectionProperty(WP_FTS_Plugin::class, 'foreground_bulk_mutation_scope');
        $bulk = $bulkProperty->getValue();
        assert_true(is_array($bulk), 'the second distinct target should install one request-global sentinel');
        $scopeKey = (string) ($bulk['scope_key'] ?? '');
        $jobKey = 'scope:' . hash('sha256', $scopeKey);

        $wp_current_filter = ['add_term_relationship'];
        $beforeRepeat = count($fake->queries);
        WP_FTS_Plugin::handle_term_relationship_pre_change(60022, 1, 'category');
        assert_same($beforeRepeat, count($fake->queries), 'active bulk pre hooks before TTL must remain in-memory only');

        $fake->queue[$jobKey]['available_at'] = time() - 1;
        $queue = new WP_FTS_Index_Queue($fake);
        $claims = $queue->claim_batch(0, time(), 30);
        $scopes = array_values(array_filter($claims, static fn(array $claim): bool => ($claim['kind'] ?? '') === 'scope'));
        $expiredLiveSentinel = $fake->queue[$jobKey] ?? [];

        $bulk['expires_at'] = time() - 1;
        $bulkProperty->setValue(null, $bulk);
        $fake->queries = [];
        WP_FTS_Plugin::handle_term_relationship_pre_change(60022, 2, 'category');
        $continuedQueries = $fake->queries;
        $continuedSentinel = $fake->queue[$jobKey] ?? [];

        WP_FTS_Plugin::reset_request_caches();
        $recoveryClaims = $queue->claim_batch(0, time(), 30);
        $recoveredScopes = array_values(array_filter(
            $recoveryClaims,
            static fn(array $claim): bool => ($claim['kind'] ?? '') === 'scope'
        ));
        $recoveryAcknowledged = isset($recoveredScopes[0])
            ? $queue->acknowledge_scope($recoveredScopes[0])
            : false;
    } finally {
        if ($oldCurrentFilter === null) {
            unset($wp_current_filter);
        } else {
            $wp_current_filter = $oldCurrentFilter;
        }
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same([], $scopes, 'an expired global sentinel must remain unclaimable while its request owner is alive');
    assert_same([], $continuedQueries, 'a live bulk owner must perform no database query solely because wall time passed');
    assert_same('scope', $continuedSentinel['kind'] ?? null, 'the guarded row must retain global scope identity');
    assert_same('global', $continuedSentinel['scope_coverage'] ?? null, 'the guarded sentinel must still suppress the whole corpus');
    assert_same('guarded', $continuedSentinel['state'] ?? null, 'the guarded global boundary must remain guarded beyond its deadline');
    assert_same($expiredLiveSentinel['claim_token'] ?? null, $continuedSentinel['claim_token'] ?? null, 'continued bulk work must retain the original guarded token');
    assert_same($expiredLiveSentinel['available_at'] ?? null, $continuedSentinel['available_at'] ?? null, 'continued bulk work must not renew the watchdog deadline');
    assert_same(1, count($recoveredScopes), 'fatal guard release should make the expired global sentinel immediately claimable');
    assert_same($jobKey, $recoveredScopes[0]['job_key'] ?? null, 'bounded recovery must claim the exact expired global sentinel');
    assert_true($recoveryAcknowledged, 'the recovered global sentinel should acknowledge by its exact generation and token');
});

test_case('concurrent global sentinels return typed unavailable until the last owner hands off', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(60031, 'post', 'publish', 'GlobalVisibilitySignal');
    $post->post_content = '<p>GlobalVisibilitySignal</p>';
    $GLOBALS['wp_fts_test_posts'][60031] = $post;
    $queue = new WP_FTS_Index_Queue($fake);
    $tokenA = str_repeat('a', 32);
    $tokenB = str_repeat('b', 32);

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());
        $queue->fence_scope('public-global-a', $tokenA, [], time() + 300, WP_FTS_Index_Queue::SCOPE_COVERAGE_GLOBAL);
        $queue->fence_scope('public-global-b', $tokenB, [], time() + 300, WP_FTS_Index_Queue::SCOPE_COVERAGE_GLOBAL);
        $firstUnavailable = false;
        try {
            WP_FTS_Plugin::search('GlobalVisibilitySignal', ['limit' => 10]);
        } catch (WP_FTS_Search_Unavailable) {
            $firstUnavailable = true;
        }

        $handoffA = $queue->handoff_foreground_mutation_scope(
            'public-global-a',
            $tokenA,
            [60031],
            [],
            [],
            false,
            [],
            time()
        );
        $secondUnavailable = false;
        try {
            WP_FTS_Plugin::search('GlobalVisibilitySignal', ['limit' => 10]);
        } catch (WP_FTS_Search_Unavailable) {
            $secondUnavailable = true;
        }
        $remainingScopes = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => ($row['kind'] ?? '') === 'scope'
        ));
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(true, $firstUnavailable, 'a durable global sentinel must be an unavailable condition, never a genuine zero-hit page');
    assert_same(true, $handoffA['global_scope_released'] ?? null, 'request A should delete only its own exact sentinel');
    assert_same(true, $secondUnavailable, 'request A handoff must not make request B look like zero results');
    assert_same(1, count($remainingScopes), 'the second request sentinel must remain authoritative');
    assert_same($tokenB, $remainingScopes[0]['claim_token'] ?? null, 'the remaining sentinel must retain request B ownership');
});

test_case('delayed pre-mutation fence closes the canonical-commit interleaving', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(2202, 'post', 'publish', 'Mutation race host');
    $post->post_content = '<p>BeforeMutationRaceSignal</p>';
    $GLOBALS['wp_fts_test_posts'][2202] = $post;

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_pre_update(2202, ['post_content' => '<p>AfterMutationRaceSignal</p>']);
        $preQueries = $fake->queries;
        $preWorker = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same([2202], wp_fts_test_queue_ids($fake), 'a worker must not claim the delayed pre-commit fence');

        $post->post_content = '<p>AfterMutationRaceSignal</p>';
        $betweenHooksResults = WP_FTS_Plugin::search('BeforeMutationRaceSignal', ['limit' => 10]);
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_save(2202, $post, true, null);
        $postQueries = $fake->queries;
        $staleResults = WP_FTS_Plugin::search('BeforeMutationRaceSignal', ['limit' => 10]);
        $finalWorker = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $replacementResults = WP_FTS_Plugin::search('AfterMutationRaceSignal', ['limit' => 10]);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(0, $preWorker['attempted'] ?? null, 'the pre-commit worker must attempt no fenced generation');
    assert_same(0, $preWorker['committed'] ?? null, 'the pre-commit worker must acknowledge no fenced generation');
    assert_same(true, $preWorker['wait_for_next_available'] ?? null, 'the watchdog should sleep until the delayed fence becomes recoverable');
    assert_same(1, count(array_filter($preQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'pre-update should emit one queue UPSERT');
    assert_same(1, count(array_filter($postQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'post-commit hook should emit one replacement queue UPSERT');
    assert_same([], $betweenHooksResults, 'the future fence must hide stale text after canonical commit and before the post hook');
    assert_same([], $staleResults, 'the post-commit generation must hide the stale old projection after the racing acknowledgement');
    assert_same(1, $finalWorker['indexed'] ?? null, 'the replacement generation should index the committed source');
    assert_same([2202], array_column($replacementResults, 'doc_id'), 'the committed replacement should become searchable after its own generation');
});

test_case('newer same-post fence survives stale promotion without fallback rows', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(2207, 'post', 'publish', 'Concurrent mutation host');
    $post->post_content = '<p>BeforeConcurrentMutation</p>';
    $GLOBALS['wp_fts_test_posts'][2207] = $post;
    $queue = new WP_FTS_Index_Queue($fake);
    $tokenA = str_repeat('a', 32);
    $tokenB = str_repeat('b', 32);

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());

        $queue->fence_post(2207, $tokenA, time() + 300, ['request' => 'A']);
        $requestA = $fake->queue[2207] ?? [];
        $queue->fence_post(2207, $tokenB, time() + 300, ['request' => 'B']);
        $requestB = $fake->queue[2207] ?? [];
        $queue->promote_post(2207, $tokenA, time(), ['request' => 'stale-A']);
        $afterStaleA = $fake->queue[2207] ?? [];

        $post->post_content = '<p>RequestBProjection</p>';
        $queue->promote_post(2207, $tokenB, time(), ['request' => 'B']);
        $readyB = $fake->queue[2207] ?? [];
        $worker = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $replacement = WP_FTS_Plugin::search('RequestBProjection', ['limit' => 10]);
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same(1, $requestA['generation'] ?? null, 'request A should create generation one');
    assert_same(2, $requestB['generation'] ?? null, 'request B should atomically supersede request A');
    assert_same('fenced', $requestB['state'] ?? null, 'the newer unmarked request must own an operator-only fence');
    assert_same($tokenB, $requestB['claim_token'] ?? null, 'the newer request token must replace the older token');
    assert_same($requestB, $afterStaleA, 'request A promotion must not alter any field owned by request B');
    assert_same('ready', $readyB['state'] ?? null, 'only request B may make its generation claimable');
    assert_same('', $readyB['claim_token'] ?? null, 'successful promotion should retire the exact request token');
    assert_same(1, $worker['analyzed'] ?? null, 'the winning canonical generation should be analyzed once');
    assert_same(1, $worker['indexed'] ?? null, 'the winning canonical generation should be written once');
    assert_same(1, $worker['committed'] ?? null, 'one canonical queue identity should be acknowledged');
    assert_same([], $fake->queue, 'the winning generation should leave no fallback identity or duplicate work');
    assert_same([2207], array_column($replacement, 'doc_id'), 'the latest committed canonical projection should become searchable');
});

test_case('same-id nested post and relationship mutations release only at the outer boundary', function (): void {
    global $wpdb, $wp_current_filter;

