        WP_FTS_Plugin::handle_term_relationship_pre_change(2208, 8002, 'category');
        $wp_current_filter = ['add_term_relationship', 'set_object_terms'];
        WP_FTS_Plugin::handle_term_relationship_change(2208, [8002], 'category');
        $afterInnerRelationship = $fake->queue[2208] ?? [];
        $wp_current_filter = ['set_object_terms'];
        WP_FTS_Plugin::handle_term_relationship_change(2208, [8001], 'category');
        $relationshipQueries = $fake->queries;
    } finally {
        if ($oldCurrentFilter === null) {
            unset($wp_current_filter);
        } else {
            $wp_current_filter = $oldCurrentFilter;
        }
        $wpdb = $oldWpdb;
    }

    $postUpserts = array_values(array_filter($postBoundaryQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    $relationshipUpserts = array_values(array_filter($relationshipQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    assert_same('guarded', $afterInnerPost['state'] ?? null, 'inner wp_after_insert_post must not release the outer post fence');
    assert_same(0, $betweenPostBoundaries['attempted'] ?? null, 'worker must not cross the still-open outer post mutation');
    assert_same(2, count($postUpserts), 'nested post writes should retain one pre and one outermost post UPSERT');
    assert_same(1, $postWorker['committed'] ?? null, 'outer post boundary should make one exact generation indexable');
    assert_same([2208], array_column($outerProjection, 'doc_id'), 'worker should index only the outermost committed source');
    assert_same([], $innerProjection, 'inner source must never become independently visible');
    assert_same('guarded', $afterInnerRelationship['state'] ?? null, 'inner relationship post hook must not release its outer operation');
    assert_same(2, count($relationshipUpserts), 'nested relationship hooks should retain one pre and one outermost post UPSERT');
});

test_case('relationship fanout delete-add direct-delete and nested multi-add stay two statements', function (): void {
    global $wpdb, $wp_current_filter;

    $oldWpdb = $wpdb ?? null;
    $oldCurrentFilter = $wp_current_filter ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        $fake->queries = [];
        $wp_current_filter = ['add_term_relationship'];
        for ($term = 1; $term <= 1000; $term++) {
            WP_FTS_Plugin::handle_term_relationship_pre_change(2210, $term, 'category');
        }
        $wp_current_filter = ['set_object_terms'];
        WP_FTS_Plugin::handle_term_relationship_change(2210, range(1, 1000), 'category');
        $multiAddQueries = $fake->queries;
        $multiAddRow = $fake->queue[2210] ?? [];

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        $wp_current_filter = ['delete_term_relationships'];
        WP_FTS_Plugin::handle_term_relationship_pre_change(2211, [1, 2], 'category');
        $wp_current_filter = ['deleted_term_relationships'];
        WP_FTS_Plugin::handle_term_relationship_change(2211, [1, 2], 'category');
        $wp_current_filter = ['add_term_relationship'];
        WP_FTS_Plugin::handle_term_relationship_pre_change(2211, 3, 'category');
        $wp_current_filter = ['set_object_terms'];
        WP_FTS_Plugin::handle_term_relationship_change(2211, [3], 'category');
        $deleteAddQueries = $fake->queries;
        $deleteAddRow = $fake->queue[2211] ?? [];

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        $wp_current_filter = ['delete_term_relationships'];
        WP_FTS_Plugin::handle_term_relationship_pre_change(2212, [1], 'category');
        $wp_current_filter = ['deleted_term_relationships'];
        WP_FTS_Plugin::handle_term_relationship_change(2212, [1], 'category');
        $directDeleteBeforeShutdown = $fake->queue[2212] ?? [];
        WP_FTS_Plugin::flush_relationship_mutations();
        $directDeleteQueries = $fake->queries;
        $directDeleteRow = $fake->queue[2212] ?? [];

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        $wp_current_filter = ['add_term_relationship'];
        WP_FTS_Plugin::handle_term_relationship_pre_change(2213, 1, 'category');
        $wp_current_filter = ['add_term_relationship', 'add_term_relationship'];
        for ($term = 2; $term <= 1000; $term++) {
            WP_FTS_Plugin::handle_term_relationship_pre_change(2213, $term, 'category');
        }
        $wp_current_filter = ['add_term_relationship', 'set_object_terms'];
        WP_FTS_Plugin::handle_term_relationship_change(2213, range(2, 1000), 'category');
        $nestedInnerRow = $fake->queue[2213] ?? [];
        $wp_current_filter = ['set_object_terms'];
        WP_FTS_Plugin::handle_term_relationship_change(2213, range(1, 1000), 'category');
        $nestedQueries = $fake->queries;
        $nestedReadyRow = $fake->queue[2213] ?? [];
    } finally {
        if ($oldCurrentFilter === null) {
            unset($wp_current_filter);
        } else {
            $wp_current_filter = $oldCurrentFilter;
        }
        $wpdb = $oldWpdb;
    }

    $upsertCount = static fn(array $queries): int => count(array_filter($queries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    assert_same(2, $upsertCount($multiAddQueries), '1,000 added relationships should issue one pre and one outer post UPSERT');
    assert_same('ready', $multiAddRow['state'] ?? null, 'multi-add should promote at the outer set_object_terms boundary');
    assert_same(2, $upsertCount($deleteAddQueries), 'delete-plus-add replacement should issue one pre and one outer post UPSERT');
    assert_same('ready', $deleteAddRow['state'] ?? null, 'delete-plus-add should not promote between relationship phases');
    assert_same('guarded', $directDeleteBeforeShutdown['state'] ?? null, 'direct delete should stay guarded until the request-end post boundary');
    assert_same(2, $upsertCount($directDeleteQueries), 'direct delete should issue one pre and one shutdown promotion UPSERT');
    assert_same('ready', $directDeleteRow['state'] ?? null, 'request-end flush should promote a completed direct delete');
    assert_same('guarded', $nestedInnerRow['state'] ?? null, 'nested multi-add final hook must not release the outer relationship fence');
    assert_same(2, $upsertCount($nestedQueries), 'nested multi-add should still issue only one pre and outer post UPSERT');
    assert_same('ready', $nestedReadyRow['state'] ?? null, 'outermost set_object_terms should release nested multi-add work');
});

test_case('foreground owner protects coalesced fences and promoted payloads', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = wp_fts_test_backfill_post(2209, 'post', 'publish', 'Protected coalescing host');
    $GLOBALS['wp_fts_test_posts'][2209] = $post;
    $queue = new WP_FTS_Index_Queue($fake);

    try {
        WP_FTS_Plugin::handle_post_pre_update(2209, ['post_content' => '<p>Protected coalescing</p>']);
        $postFence = $fake->queue[2209] ?? [];
        $queue->enqueue_many([2209], null, [
            'index_options' => ['language' => 'pl'],
        ]);
        $afterGenericEnqueue = $fake->queue[2209] ?? [];
        $queue->retry(2209);
        $afterOperatorRetry = $fake->queue[2209] ?? [];
        $fake->queue[2209]['available_at'] = time() - 1;
        $directClaims = $queue->claim_batch(1);
        WP_FTS_Plugin::handle_post_save(2209, $post, true, null);
        $directReady = $fake->queue[2209] ?? [];
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $directSuccessorClaims = $queue->claim_batch(1);
        if (isset($directSuccessorClaims[0])) {
            $queue->acknowledge($directSuccessorClaims[0]);
        }

        WP_FTS_Plugin::reset_request_caches();
        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(99, 'category', ['term_taxonomy_id' => 990]);
        $scopeRows = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $scopeFence = $scopeRows[0] ?? [];
        $queue->enqueue_scope('taxonomy:category:99', [
            'reason' => 'concurrent_scope_coalescing',
        ], null, WP_FTS_Index_Queue::SCOPE_COVERAGE_TARGETED, 'term_taxonomy', 990);
        $scopeKey = (string) ($scopeFence['job_key'] ?? '');
        $afterScopeEnqueue = $fake->queue[$scopeKey] ?? [];
        $fake->queue[$scopeKey]['available_at'] = time() - 1;
        $scopeClaims = $queue->claim_batch(1);
        WP_FTS_Plugin::handle_taxonomy_term_edit(99, 990, 'category');
        $scopeReady = $fake->queue[$scopeKey] ?? [];
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $scopeSuccessorClaims = $queue->claim_batch(1);
        if (isset($scopeSuccessorClaims[0])) {
            $queue->acknowledge_scope($scopeSuccessorClaims[0]);
        }
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same('guarded', $postFence['state'] ?? null, 'post pre hook should start with explicit ownership');
    assert_same('guarded', $afterGenericEnqueue['state'] ?? null, 'generic dependency enqueue must not make a live post fence ready');
    assert_same($postFence['claim_token'] ?? null, $afterGenericEnqueue['claim_token'] ?? null, 'generic enqueue must preserve the foreground liveness token');
    assert_same('guarded', $afterOperatorRetry['state'] ?? null, 'operator retry must not bypass a live post fence');
    assert_same($postFence['claim_token'] ?? null, $afterOperatorRetry['claim_token'] ?? null, 'operator retry must preserve the foreground liveness token');
    assert_same([], $directClaims, 'an expired coalesced direct fence must remain unclaimable while its foreground owner lives');
    assert_same('ready', $directReady['state'] ?? null, 'the matching post hook should promote the guarded generation after canonical commit');
    assert_same('pl', json_decode((string) ($directReady['payload'] ?? ''), true)['index_options']['language'] ?? null, 'post promotion must preserve the newer coalesced indexing payload');
    assert_same(1, count($directSuccessorClaims), 'final guard release should make the promoted direct generation immediately claimable');
    assert_same('post', $directSuccessorClaims[0]['kind'] ?? null, 'the released direct successor must retain exact post authority');
    assert_same('pl', $directSuccessorClaims[0]['payload']['index_options']['language'] ?? null, 'the direct successor claim should retain the coalesced indexing payload');
    assert_same('guarded', $scopeFence['state'] ?? null, 'scope pre hook should start with explicit ownership');
    assert_same('guarded', $afterScopeEnqueue['state'] ?? null, 'generic scope enqueue must not make a live scope fence ready');
    assert_same($scopeFence['claim_token'] ?? null, $afterScopeEnqueue['claim_token'] ?? null, 'scope coalescing must preserve the foreground liveness token');
    assert_same([], $scopeClaims, 'an expired coalesced scope fence must remain unclaimable while its foreground owner lives');
    assert_same('ready', $scopeReady['state'] ?? null, 'the matching scope hook should promote the guarded generation after canonical commit');
    assert_same('concurrent_scope_coalescing', json_decode((string) ($scopeReady['payload'] ?? ''), true)['reason'] ?? null, 'scope promotion must preserve newer coalesced scope intent');
    assert_same(1, count($scopeSuccessorClaims), 'final guard release should make the promoted scope generation immediately claimable');
    assert_same('scope', $scopeSuccessorClaims[0]['kind'] ?? null, 'the released scope successor must retain scope authority');
    assert_same('concurrent_scope_coalescing', $scopeSuccessorClaims[0]['payload']['reason'] ?? null, 'the scope successor claim should retain the coalesced scope intent');
});

test_case('new delayed generation survives a stale worker that already snapshotted old source', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $postId = 2206;
    $post = wp_fts_test_backfill_post($postId, 'post', 'publish', 'Claim-before-fence race');
    $post->post_content = '<p>RaceBaseProjection</p>';
    $GLOBALS['wp_fts_test_posts'][$postId] = $post;
    $queue = new WP_FTS_Index_Queue($fake);
    $activeToken = null;
    $activePrefixProperty = null;

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());
        $post->post_content = '<p>RaceOldProjection</p>';
        $queue->enqueue($postId);

        $acquire = new ReflectionMethod(WP_FTS_Plugin::class, 'acquire_index_lock');
        $acquire->setAccessible(true);
        $activeToken = $acquire->invoke(null, 'claimed-before-fence-test');
        assert_true(is_string($activeToken) && $activeToken !== '', 'stale-worker fixture should acquire the writer lease');
        $activeProperty = new ReflectionProperty(WP_FTS_Plugin::class, 'active_index_writer_token');
        $activeProperty->setAccessible(true);
        $activeProperty->setValue(null, $activeToken);
        $activePrefixProperty = new ReflectionProperty(WP_FTS_Plugin::class, 'active_index_writer_prefix');
        $activePrefixProperty->setAccessible(true);
        $activePrefixProperty->setValue(null, $fake->prefix);

        $claims = $queue->claim_batch(1, null, WP_FTS_Index_Queue::DEFAULT_LEASE_SECONDS, 8388608);
        assert_same(1, count($claims), 'stale worker should claim and snapshot the old canonical source before the fence');
        assert_contains('RaceOldProjection', (string) ($claims[0]['source_snapshot']->post_content ?? ''), 'claimed source snapshot should contain the old canonical projection');

        WP_FTS_Plugin::handle_post_pre_update($postId, ['post_content' => '<p>RaceNewProjection</p>']);
        $fenced = $fake->queue[$postId] ?? [];
        $post->post_content = '<p>RaceNewProjection</p>';

        $defaultSummary = new ReflectionMethod(WP_FTS_Plugin::class, 'default_index_batch_summary');
        $defaultSummary->setAccessible(true);
        $staleSummary = $defaultSummary->invoke(null, 'manual', 1);
        $process = new ReflectionMethod(WP_FTS_Plugin::class, 'process_prepared_claim_batch');
        $process->setAccessible(true);
        $arguments = [$claims, &$staleSummary, WP_FTS_Plugin::runtime_analyzer(), $queue, null];
        $process->invokeArgs(null, $arguments);
        $release = new ReflectionMethod(WP_FTS_Plugin::class, 'release_index_lock');
        $release->setAccessible(true);
        $release->invoke(null, $activeToken);
        $activeProperty->setValue(null, null);
        $activePrefixProperty->setValue(null, null);
        $activeToken = null;

        $afterStaleWorker = $fake->queue[$postId] ?? [];
        $staleVisible = WP_FTS_Plugin::search('RaceOldProjection', ['limit' => 10]);
        $oldAnalysis = WP_FTS_Plugin::runtime_analyzer()->analyze_plain_content('RaceOldProjection', ['document_lang' => 'en']);
        $oldTerm = WP_FTS_TermNamespace::namespace_term(
            (string) ($oldAnalysis[0]['lang'] ?? 'en'),
            (string) ($oldAnalysis[0]['term'] ?? '')
        );
        $stalePhysicalWrite = isset($fake->postings[$oldTerm][$postId]);

        WP_FTS_Plugin::handle_post_save($postId, $post, true, null);
        $ready = $fake->queue[$postId] ?? [];
        $freshSummary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        $newVisible = WP_FTS_Plugin::search('RaceNewProjection', ['limit' => 10]);
        $oldVisibleAfterFresh = WP_FTS_Plugin::search('RaceOldProjection', ['limit' => 10]);
    } finally {
        if (is_string($activeToken) && $activeToken !== '') {
            $release = new ReflectionMethod(WP_FTS_Plugin::class, 'release_index_lock');
            $release->setAccessible(true);
            $release->invoke(null, $activeToken);
            $activeProperty = new ReflectionProperty(WP_FTS_Plugin::class, 'active_index_writer_token');
            $activeProperty->setAccessible(true);
            $activeProperty->setValue(null, null);
        }
        if ($activePrefixProperty instanceof ReflectionProperty) {
            $activePrefixProperty->setValue(null, null);
        }
        $wpdb = $oldWpdb;
    }

    assert_same(2, $fenced['generation'] ?? null, 'pre-hook should supersede the already claimed generation');
    assert_same('guarded', $fenced['state'] ?? null, 'pre-hook should replace the stale worker lease with an explicit guarded boundary');
    assert_true(
        is_string($fenced['claim_token'] ?? null) && ($fenced['claim_token'] ?? '') !== (string) ($claims[0]['token'] ?? ''),
        'the foreground mutation token should revoke the stale worker lease'
    );
    assert_true((int) ($fenced['available_at'] ?? 0) >= time() + 299, 'superseding generation should retain a crash-recovery delay');
    assert_same(2, $afterStaleWorker['generation'] ?? null, 'stale acknowledgement must not remove the newer delayed generation');
    assert_same('guarded', $afterStaleWorker['state'] ?? null, 'stale worker must not make the newer foreground generation claimable');
    assert_same($fenced['claim_token'] ?? null, $afterStaleWorker['claim_token'] ?? null, 'stale worker must not reacquire ownership of the newer generation');
    assert_same(0, $staleSummary['committed'] ?? null, 'stale physical writes must not be reported as acknowledged work');
    assert_same(1, $staleSummary['superseded'] ?? null, 'generation-aware acknowledgement should report the stale claim as superseded');
    assert_true($stalePhysicalWrite, 'stale worker should exercise the hard path by actually writing its old source snapshot');
    assert_same([], $staleVisible, 'newer dirty generation must keep the stale write ineligible');
    assert_same(2, $ready['generation'] ?? null, 'post hook should promote the exact surviving fence generation');
    assert_same('ready', $ready['state'] ?? null, 'matching post hook should release the advisory fence into ready work');
    assert_true((int) ($ready['available_at'] ?? PHP_INT_MAX) <= time(), 'post hook should make the new canonical generation immediately claimable');
    assert_same(1, $freshSummary['indexed'] ?? null, 'fresh worker should index the post-commit source');
    assert_same([2206], array_column($newVisible, 'doc_id'), 'fresh canonical projection should become searchable');
    assert_same([], $oldVisibleAfterFresh, 'fresh replacement should remove the stale worker projection');
});

test_case('targeted and global scope fences remain closed beyond watchdog while their flock owner lives', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        $fake->queries = [];
        WP_FTS_Plugin::handle_taxonomy_term_pre_edit(77, 'category', ['term_taxonomy_id' => 770]);
        $targetedPreQueries = $fake->queries;
        $targetedRows = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $targetedWait = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $targetedRowsAfterWait = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $targetedKey = (string) ($targetedRows[0]['job_key'] ?? '');
        $fake->queue[$targetedKey]['available_at'] = time() - 1;
        $targetedElapsedWait = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $targetedRowsAfterElapsed = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $fake->queries = [];
        WP_FTS_Plugin::handle_taxonomy_term_edit(77, 770, 'category');
        $targetedPostQueries = $fake->queries;
        $targetedReadyRows = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        WP_FTS_Plugin::handle_taxonomy_term_pre_delete(88, 'category');
        $globalPreQueries = $fake->queries;
        $globalRows = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $globalWait = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $globalRowsAfterWait = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $globalKey = (string) ($globalRows[0]['job_key'] ?? '');
        $fake->queue[$globalKey]['available_at'] = time() - 1;
        $globalElapsedWait = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 10]);
        $globalRowsAfterElapsed = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
        $fake->queries = [];
        WP_FTS_Plugin::handle_taxonomy_term_delete(88, 880, 'category', null, []);
        $globalPostQueries = $fake->queries;
        $globalReadyRows = array_values(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'));
    } finally {
        WP_FTS_Plugin::reset_request_caches();
        $wpdb = $oldWpdb;
    }

    assert_same('term_taxonomy', $targetedRows[0]['scope_subject_type'] ?? null, 'term edit should install a targeted visibility fence');
    assert_true((int) ($targetedRows[0]['available_at'] ?? 0) >= time() + 299, 'targeted pre-edit scope should use a five-minute watchdog');
    assert_true(str_starts_with((string) ($targetedRows[0]['claim_token'] ?? ''), 'guard:'), 'targeted pre-edit scope should be tied to the request flock owner');
    assert_same(0, $targetedWait['attempted'] ?? null, 'targeted pre-edit scope must not be claimed before canonical commit');
    assert_same(1, count($targetedRowsAfterWait), 'targeted scope should survive an interleaving worker pass');
    assert_same(0, $targetedElapsedWait['attempted'] ?? null, 'an expired targeted fence must remain excluded while its request flock is live');
    assert_same(1, count($targetedRowsAfterElapsed), 'the live owner must preserve the exact targeted generation beyond its finite deadline');
    assert_true((int) ($targetedReadyRows[0]['available_at'] ?? PHP_INT_MAX) <= time(), 'targeted post-edit hook should make the newer generation ready immediately');
    assert_same(1, count(array_filter($targetedPreQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'targeted pre-edit should issue one scope UPSERT');
    assert_same(1, count(array_filter($targetedPostQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'targeted post-edit should issue one scope UPSERT');

    assert_same('', $globalRows[0]['scope_subject_type'] ?? null, 'term deletion should install a global visibility fence');
    assert_true((int) ($globalRows[0]['available_at'] ?? 0) >= time() + 299, 'global pre-delete scope should use a five-minute watchdog');
    assert_true(str_starts_with((string) ($globalRows[0]['claim_token'] ?? ''), 'guard:'), 'global pre-delete scope should be tied to the request flock owner');
    assert_same(0, $globalWait['attempted'] ?? null, 'global pre-delete scope must not be claimed before canonical commit');
    assert_same(1, count($globalRowsAfterWait), 'global scope should survive an interleaving worker pass');
    assert_same(0, $globalElapsedWait['attempted'] ?? null, 'an expired global fence must remain excluded while its request flock is live');
    assert_same(1, count($globalRowsAfterElapsed), 'the live owner must preserve the exact global generation beyond its finite deadline');
    assert_true((int) ($globalReadyRows[0]['available_at'] ?? PHP_INT_MAX) <= time(), 'global post-delete hook should make the newer generation ready immediately');
    assert_same(1, count(array_filter($globalPreQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'global pre-delete should issue one scope UPSERT');
    assert_same(1, count(array_filter($globalPostQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work'))), 'global post-delete should issue one scope UPSERT');
    assert_same(0, count(array_filter(
        [...$targetedPreQueries, ...$targetedPostQueries, ...$globalPreQueries, ...$globalPostQueries],
        static fn(string $sql): bool => str_contains($sql, 'GET_LOCK') || str_contains($sql, 'IS_USED_LOCK')
    )), 'scope recovery and promotion should remain portable CAS operations without MySQL advisory locks');
});

test_case('worst-case relationship and metadata callback loops remain two tiny UPSERTs', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION] = ['subtitle'];
    $callbackCount = 50000;

    try {
        $fake->queries = [];
        for ($index = 0; $index < $callbackCount; $index++) {
            WP_FTS_Plugin::handle_term_relationship_pre_change(2203, 7000 + $index, 'category');
        }
        for ($index = 0; $index < $callbackCount; $index++) {
            WP_FTS_Plugin::handle_term_relationship_change(2203, [7000 + $index], 'category');
        }
        $relationshipQueries = $fake->queries;

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_meta_pre_update(1, 2204, 'subtitle', 'replacement');
        for ($index = 0; $index < $callbackCount; $index++) {
            WP_FTS_Plugin::handle_post_meta_change(8000 + $index, 2204, 'subtitle', 'replacement');
        }
        WP_FTS_Plugin::flush_post_meta_mutations();
        $metadataQueries = $fake->queries;

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_meta_pre_delete([], 0, 'subtitle', '');
        for ($postId = 1; $postId <= $callbackCount; $postId++) {
            WP_FTS_Plugin::handle_post_meta_change(9000 + $postId, $postId, 'subtitle');
        }
        $globalDeleteQueries = $fake->queries;

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_pre_delete(2205);
        $physicalDeleteFence = $fake->queue[2205] ?? [];
        WP_FTS_Plugin::handle_post_delete(2205);
        $physicalDeleteReady = $fake->queue[2205] ?? [];
        $physicalDeleteQueries = $fake->queries;
    } finally {
        $wpdb = $oldWpdb;
    }

    $relationshipUpserts = array_values(array_filter($relationshipQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    $metadataUpserts = array_values(array_filter($metadataQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    $globalDeleteUpserts = array_values(array_filter($globalDeleteQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    $physicalDeleteUpserts = array_values(array_filter($physicalDeleteQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    assert_same(2, count($relationshipUpserts), '50,000 relationship pre/post callbacks should coalesce to exactly one pre and one post UPSERT');
    assert_same(1, $fake->queue[2203]['generation'] ?? null, 'relationship callbacks should promote their one exact fenced generation');
    assert_same(2, count($metadataUpserts), '50,000 metadata after-actions should coalesce to exactly one pre and one post UPSERT');
    assert_same(1, $fake->queue[2204]['generation'] ?? null, 'selected metadata callbacks should promote their one exact fenced generation');
    assert_same(2, count($globalDeleteUpserts), 'delete-all metadata should use one pre/post global scope pair instead of 50,000 direct rows');
    assert_same(1, count(array_filter($fake->queue, static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope')), 'delete-all metadata should retain one coalesced global watchdog row');
    assert_true((int) ($physicalDeleteFence['available_at'] ?? 0) >= time() + 299, 'before_delete_post should install an unclaimable watchdog fence');
    assert_true((int) ($physicalDeleteReady['available_at'] ?? PHP_INT_MAX) <= time(), 'deleted_post should advance physical deletion work to ready');
    assert_same(2, count($physicalDeleteUpserts), 'physical deletion should use exactly one pre and one post UPSERT');
    foreach ([...$relationshipUpserts, ...$metadataUpserts, ...$globalDeleteUpserts, ...$physicalDeleteUpserts] as $sql) {
        assert_true(strlen($sql) < 1048576, 'every worst-case foreground queue statement must stay below 1 MiB');
    }
});

test_case('metadata no-ops install no filter fence and multi-row updates stay two statements', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION] = ['subtitle'];

    try {
        // WordPress invokes none of the post-check pre-SQL actions for an
        // identical-value update, rejected unique add, missing delete, or a
        // short-circuiting metadata filter. Therefore all four no-op paths do
        // literally zero FTS SQL.
        $fake->queries = [];
        $noOpQueries = $fake->queries;

        for ($metaId = 1; $metaId <= 1000; $metaId++) {
            WP_FTS_Plugin::handle_post_meta_pre_update($metaId, 2214, 'subtitle', 'replacement');
        }
        for ($metaId = 1; $metaId <= 1000; $metaId++) {
            WP_FTS_Plugin::handle_post_meta_change($metaId, 2214, 'subtitle', 'replacement');
        }
        WP_FTS_Plugin::flush_post_meta_mutations();
        $multiRowQueries = $fake->queries;
        $multiRow = $fake->queue[2214] ?? [];
    } finally {
        $wpdb = $oldWpdb;
    }

    $upserts = array_values(array_filter($multiRowQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    assert_same([], $noOpQueries, 'metadata operations that never reach pre-SQL actions must install no fence');
    assert_same(2, count($upserts), '1,000 physical metadata-row callbacks should coalesce to one pre and one final post UPSERT');
    assert_same('ready', $multiRow['state'] ?? null, 'the final metadata post action should promote the shared generation');
    assert_true(strlen($upserts[0] ?? '') < 1048576 && strlen($upserts[1] ?? '') < 1048576, 'multi-row metadata statements must remain below 1 MiB');
});

test_case('sequential dynamic metadata writes share one request-held post fence', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER] =
        static fn(array $options): array => $options;

    try {
        $fake->queries = [];
        for ($index = 1; $index <= 10000; $index++) {
            $key = 'dynamic_field_' . $index;
            WP_FTS_Plugin::handle_post_meta_pre_update($index, 2215, $key, 'replacement');
            WP_FTS_Plugin::handle_post_meta_change($index, 2215, $key, 'replacement');
        }
        $beforeShutdown = $fake->queue[2215] ?? [];
        $beforeShutdownQueries = $fake->queries;
        WP_FTS_Plugin::flush_post_meta_mutations();
        $afterShutdown = $fake->queue[2215] ?? [];
        $afterShutdownQueries = $fake->queries;

        WP_FTS_Plugin::reset_request_caches();
        $fake->queries = [];
        WP_FTS_Plugin::handle_post_meta_pre_update(1, 2216, 'dynamic_failure', 'replacement');
        WP_FTS_Plugin::flush_post_meta_mutations();
        $failedMutation = $fake->queue[2216] ?? [];
        $failedQueries = $fake->queries;
    } finally {
        $wpdb = $oldWpdb;
    }

    $preUpserts = array_values(array_filter($beforeShutdownQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    $allUpserts = array_values(array_filter($afterShutdownQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    $failedUpserts = array_values(array_filter($failedQueries, static fn(string $sql): bool => str_starts_with($sql, 'INSERT INTO wp_fts_work')));
    assert_same(1, count($preUpserts), '10,000 sequential selected metadata API lifecycles should install one request-held fence');
    assert_same('guarded', $beforeShutdown['state'] ?? null, 'workers must not observe an intermediate metadata projection before request shutdown');
    assert_same(2, count($allUpserts), '10,000 sequential selected metadata writes should cost exactly one fence and one promotion');
    assert_same('ready', $afterShutdown['state'] ?? null, 'shutdown should promote the coalesced metadata generation after successful SQL actions');
    assert_same(1, count($failedUpserts), 'a pre-SQL metadata boundary without a post-SQL action should not emit a false promotion');
    assert_same('guarded', $failedMutation['state'] ?? null, 'a failed metadata SQL operation should remain guarded for connection-death recovery');
    assert_true((int) ($failedMutation['available_at'] ?? 0) >= time() + 299, 'failed metadata SQL should retain the bounded crash-recovery delay');
});

