test_case('runtime post hooks queue eligible saves and status changes then processors index them', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = (object) [
        'ID' => 101,
        'post_title' => 'Needle',
        'post_content' => '<p>alpha beta alpha</p>',
        'post_excerpt' => 'RuntimeExcerptSignal',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-07 00:00:00',
        'custom_fields' => [
            'subtitle' => 'RuntimeCustomSignal',
        ],
    ];
    $GLOBALS['wp_fts_test_posts'][101] = $post;
    $GLOBALS['wp_fts_test_options']['wp_fts_index_custom_fields'] = ['subtitle'];
    wp_fts_test_mark_search_takeover_ready();
    $GLOBALS['wp_fts_test_post_meta'][101]['subtitle'] = ['RuntimeCustomSignal'];
    $GLOBALS['wp_fts_test_do_blocks'][$post->post_content] = '<p>alpha beta alpha</p><p>RuntimeRenderedSignal</p>';

    try {
        WP_FTS_Plugin::handle_post_save(101, $post, true);
        WP_FTS_Plugin::handle_post_save(101, $post, true);
        assert_same([101], wp_fts_test_queue_ids($fake), 'each eligible save should durably target its exact post before returning');
        $foregroundScopes = array_values(array_filter(
            $fake->queue,
            static fn(array $row): bool => (string) ($row['kind'] ?? '') === 'scope'
                && (string) ($row['scope_subject_type'] ?? '') === ''
        ));
        assert_same([], $foregroundScopes, 'repeated saves must not create a global scope or suppress unrelated search');
        assert_same(2, $fake->queue[101]['generation'] ?? null, 'each completed save hook should advance the durable desired generation');
        assert_same(1, count($GLOBALS['wp_fts_test_schedule_calls']), 'durable foreground work should schedule one coalesced queue processor event');
        assert_same([], $fake->docs, 'eligible save hooks should not write FTS docs inline');
        assert_same([], $fake->ftsTerms, 'eligible save hooks should not write FTS terms inline');
        assert_same([], $fake->postings, 'eligible save hooks should not write postings inline');
        assert_same([], WP_FTS_Plugin::search('alpha', ['limit' => 10]), 'queued saves should not become searchable before a processor run');

        assert_true(isset($GLOBALS['wp_fts_test_scheduled'][WP_FTS_Plugin::CRON_HOOK]), 'the direct durable enqueue should schedule the bounded processor');
        assert_same(1, count($GLOBALS['wp_fts_test_schedule_calls']), 'duplicate eligible saves should not schedule duplicate queue processor events');
        // The rest of this test represents later requests in the same PHP
        // process. Run the request-end hook so its mutation frontier cannot
        // make those independent lifecycles look like one bulk request.
        WP_FTS_Plugin::flush_foreground_bulk_mutations();

        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION] = [
            'token' => 'active-save-queue-lock',
            'mode' => 'cron',
            'started_at' => time(),
            'expires_at' => time() + 300,
        ];
        $locked = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same(true, $locked['skipped_locked'], 'manual processor should skip when a writer lock is active');
        assert_same([101], wp_fts_test_queue_ids($fake), 'locked processors should preserve queued save work');
        assert_same([], $fake->docs, 'locked processors should not write queued docs');
        unset($GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]);

        $processed = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100, 'source' => 'test-save-queue']);
        assert_same(1, $processed['indexed'], 'a short 100-slot batch should index one queued save and retain its lease through cleanup');
        assert_same(1, $processed['queue_processed'], 'manual processor should report queued save work separately');
        assert_same(0, $processed['backfill_processed'], 'manual processor should not spend capacity on backfill while queued save work fills the batch');
        assert_same([], wp_fts_test_queue_ids($fake), 'processed queued saves should leave the queue empty');
        assert_true(isset($fake->docs[101]) && $fake->docs[101]['is_deleted'] === 0, 'processor should write an active document for queued saves');
        assert_true($fake->ftsTerms !== [], 'processor should write term postings for queued saves');
        assert_same([101], array_column(WP_FTS_Plugin::search('alpha', ['limit' => 10]), 'doc_id'), 'search helper should expose the indexed public post');
        assert_same([101], array_column(WP_FTS_Plugin::search('RuntimeExcerptSignal', ['limit' => 10]), 'doc_id'), 'queued indexing should include extracted excerpts');
        assert_same([101], array_column(WP_FTS_Plugin::search('RuntimeCustomSignal', ['limit' => 10]), 'doc_id'), 'queued indexing should include selected custom fields');
        assert_same([], WP_FTS_Plugin::search('RuntimeRenderedSignal', ['limit' => 10]), 'runtime indexing should not execute dynamic blocks by default');
        $filtered = WP_FTS_Plugin::search('Needle', ['post_statuses' => ['publish']]);
        assert_same([101], array_column($filtered, 'doc_id'), 'queued indexing should keep canonical status filtering in the relational query');
        assert_contains('alpha beta alpha', $fake->docMeta[101]['search_text'] ?? '', 'queued metadata should keep a bounded content-only snippet sidecar');
        assert_true(!str_contains($fake->docMeta[101]['search_text'] ?? '', 'RuntimeExcerptSignal'), 'content previews should not persist excerpt metadata in the snippet sidecar');
        assert_true(!str_contains($fake->docMeta[101]['search_text'] ?? '', 'RuntimeCustomSignal'), 'content previews should not persist custom-field metadata in the snippet sidecar');
        assert_true(!str_contains($fake->docMeta[101]['search_text'] ?? '', 'RuntimeRenderedSignal'), 'default queued metadata should exclude dynamic block output');

        $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER] = static function (array $options): array {
            $options['render_blocks'] = true;
            return $options;
        };
        assert_same(1, WP_FTS_Plugin::invalidate_post_content_dependencies(101), 'unsupported dynamic rendering should still enqueue exact stale-index reconciliation');
        $rendered = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same(1, $rendered['queue_processed'] ?? null, 'the bounded worker should permanently acknowledge the unsupported rendering generation');
        assert_same(1, $rendered['permanently_rejected'] ?? null, 'dynamic rendering should be reported as one permanent analysis rejection');
        assert_same([], array_column(WP_FTS_Plugin::search('RuntimeRenderedSignal', ['limit' => 10]), 'doc_id'), 'the bounded worker must never execute dynamic rendering callbacks');
        assert_same([], array_column(WP_FTS_Plugin::search('alpha', ['limit' => 10]), 'doc_id'), 'permanent dynamic-rendering rejection should remove the stale static index');
        assert_true(!isset($fake->docs[101]), 'permanent dynamic-rendering rejection should delete the stale relational document row');
        $health = WP_FTS_Plugin::search_health();
        assert_same(1, $health['last_batch_queue_processed'] ?? null, 'the permanent rejection should persist its acknowledged queue outcome');
        assert_same('failed', $health['latest_batch_diagnostics']['status'] ?? null, 'health should expose the permanent dynamic-rendering rejection');
        assert_same(1, $health['latest_batch_diagnostics']['permanently_rejected'] ?? null, 'health should identify the permanently rejected document');
        assert_same(null, $rendered['queue_before'] ?? null, 'the worker should not add a pre-batch queue COUNT query for diagnostics');
        assert_same(null, $rendered['queue_after'] ?? null, 'the worker should not add a post-batch queue COUNT query for diagnostics');
        assert_same(1, $rendered['queue_processed'] ?? null, 'the returned batch summary should report queue work without an option write');
        unset($GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER]);

        $statusPost = (object) [
            'ID' => 103,
            'post_title' => 'Status queued',
            'post_content' => '<p>statusqueueneedle body</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-06-07 00:00:00',
        ];
        $GLOBALS['wp_fts_test_posts'][103] = $statusPost;
        WP_FTS_Plugin::handle_post_save(103, $statusPost);
        assert_same([103], wp_fts_test_queue_ids($fake), 'the post-save lifecycle should durably enqueue the changed status before returning');
        assert_true(!isset($fake->docs[103]), 'the post-save lifecycle should not write docs inline');
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $cron = WP_FTS_Plugin::process_scheduled_indexing();
        assert_same(1, $cron['queue_processed'], 'cron processor should consume queued post-save work before backfill');
        assert_true(($fake->docs[103]['is_deleted'] ?? 1) === 0, 'cron processor should index the queued status change');

        $post->post_status = 'trash';
        WP_FTS_Plugin::handle_post_save(101, $post);
        assert_true(!isset($fake->docs[101]), 'the foreground post-save hook should not recreate a document already removed by permanent rejection');
        assert_same([], WP_FTS_Plugin::search('alpha', ['limit' => 10]), 'canonical visibility should hide trashed posts before derived cleanup runs');
        assert_true(in_array(101, wp_fts_test_queue_ids($fake), true), 'the post-save hook should preserve the trash reconciliation generation before returning');
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        WP_FTS_Plugin::process_scheduled_indexing();
        assert_true(!isset($fake->docs[101]), 'the coordinated worker should physically remove the ineligible document');

        $GLOBALS['wp_fts_test_revisions'][102] = true;
        WP_FTS_Plugin::handle_post_save(102, (object) ['ID' => 102, 'post_status' => 'publish', 'post_type' => 'revision'], true);
        assert_same([], wp_fts_test_queue_ids($fake), 'revision saves should not enqueue indexing work');
    } finally {
        $wpdb = $oldWpdb;
    }
});

