test_case('saved field boost settings change runtime ranking after reindex', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $titleMatch = (object) [
        'ID' => 124701,
        'post_title' => 'rankboostneedle',
        'post_content' => '',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-20 00:00:00',
    ];
    $contentMatch = (object) [
        'ID' => 124702,
        'post_title' => 'Body match fixture',
        'post_content' => '<p>rankboostneedle</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-20 00:00:00',
    ];
    $GLOBALS['wp_fts_test_posts'][124701] = $titleMatch;
    $GLOBALS['wp_fts_test_posts'][124702] = $contentMatch;
    $fake->postRows = [$titleMatch, $contentMatch];
    update_post_meta(124701, WP_FTS_Plugin::LANGUAGE_META_KEY, 'en');
    update_post_meta(124702, WP_FTS_Plugin::LANGUAGE_META_KEY, 'en');

    $withBoosts = static function (float $titleBoost, float $contentBoost): array {
        return array_replace(
            WP_FTS_Plugin::default_settings(),
            [
                'field_boosts' => array_replace(
                    WP_FTS_Plugin::default_settings()['field_boosts'],
                    [
                        'title' => $titleBoost,
                        'content' => $contentBoost,
                    ]
                ),
            ]
        );
    };

    $saveBoosts = static function (float $titleBoost, float $contentBoost) use ($withBoosts): void {
        $oldPost = $_POST;
        $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
        $_POST = [
            'option_page' => WP_FTS_Plugin::SETTINGS_OPTION,
            'action' => 'update',
            '_wpnonce' => wp_create_nonce(WP_FTS_Plugin::SETTINGS_OPTION . '-options'),
        ];

        try {
            update_option(
                WP_FTS_Plugin::SETTINGS_OPTION,
                WP_FTS_Plugin::sanitize_settings_for_save($withBoosts($titleBoost, $contentBoost))
            );
        } finally {
            $_POST = $oldPost;
        }
    };
    $drainReconciliation = static function () use ($fake): void {
        for ($pass = 0; $pass < 20 && $fake->queue !== []; $pass++) {
            WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 2]);
        }
        assert_same([], $fake->queue, 'bounded workers should drain profile reconciliation and its direct post work');
        WP_FTS_Plugin::run_scheduled_schema_repair();
        assert_same(true, WP_FTS_Plugin::search_takeover_status()['ready'] ?? false, 'dedicated maintenance should verify the drained index before takeover');
    };

    try {
        wp_fts_test_index_saved_post(124701, $titleMatch, true);
        wp_fts_test_index_saved_post(124702, $contentMatch, true);
        wp_fts_test_mark_search_takeover_ready();

        $saveBoosts(1.0, 8.0);
        assert_true($fake->queue !== [], 'an authorized ranking-profile change should enqueue durable scope reconciliation');
        $drainReconciliation();
        $contentFirst = WP_FTS_Plugin::search_page('rankboostneedle', [
            'lang' => 'en',
            'limit' => 2,
        ]);
        assert_same([124702, 124701], array_column($contentFirst['results'], 'doc_id'), 'higher saved content boost should rank the content match first after bounded reconciliation');
        $term = array_key_first(array_filter(
            $fake->postings,
            static fn(array $rows): bool => isset($rows[124701], $rows[124702])
        ));
        assert_true(is_string($term), 'the analyzed shared query term should have one posting for each document');
        assert_true(($fake->postings[$term][124702] ?? 0) > ($fake->postings[$term][124701] ?? 0), 'the self-contained posting impact should encode the higher content boost');

        $saveBoosts(8.0, 1.0);
        assert_true($fake->queue !== [], 'a second ranking-profile change should enqueue another durable reconciliation');
        $drainReconciliation();
        $titleFirst = WP_FTS_Plugin::search_page('rankboostneedle', [
            'lang' => 'en',
            'limit' => 2,
        ]);
        assert_same([124701, 124702], array_column($titleFirst['results'], 'doc_id'), 'higher saved title boost should rank the title match first after bounded reconciliation');
        assert_true(($fake->postings[$term][124701] ?? 0) > ($fake->postings[$term][124702] ?? 0), 'reindexing should replace the posting impact with the changed title boost');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('disabled auto-index leaves cleanup to explicit reconciliation while canonical visibility stays exact', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $settings = array_replace(WP_FTS_Plugin::default_settings(), ['auto_index' => false]);
    $post = (object) [
        'ID' => 111,
        'post_title' => 'Manual indexing only',
        'post_content' => '<p>manualtransitionneedle remains manual.</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-16 00:00:00',
    ];
    $GLOBALS['wp_fts_test_posts'][111] = $post;
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = $settings;

    try {
        WP_FTS_Plugin::handle_post_save(111, $post, true);
        assert_same([], wp_fts_test_queue_ids($fake), 'disabled auto-index should not queue eligible saves');
        assert_true(!isset($fake->docs[111]), 'disabled auto-index should not index eligible saves inline');

        WP_FTS_Plugin::handle_post_save(111, $post);
        assert_same([], wp_fts_test_queue_ids($fake), 'disabled auto-index should not queue eligible status changes');
        assert_true(!isset($fake->docs[111]), 'disabled auto-index should not index when a post transitions into a searchable status');
        assert_same([], WP_FTS_Plugin::search('manualtransitionneedle', ['limit' => 10]), 'blocked status-change indexing should leave FTS results empty');

        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace($settings, ['auto_index' => true]);
        wp_fts_test_index_saved_post(111, $post, true);
        assert_true(($fake->docs[111]['is_deleted'] ?? 1) === 0, 'test setup should create an active indexed document');

        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = $settings;
        $post->post_status = 'trash';
        WP_FTS_Plugin::handle_post_save(111, $post);
        assert_same([], wp_fts_test_queue_ids($fake), 'disabled auto-index should not enqueue automatic cleanup generations');
        assert_true(isset($fake->docs[111]), 'disabled auto-index should leave derived cleanup to an explicit reindex');
        assert_same([], WP_FTS_Plugin::search('manualtransitionneedle', ['limit' => 10]), 'canonical visibility should still hide the trashed post immediately');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('queue processing preserves posts queued during an active batch', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $post = (object) [
        'ID' => 301,
        'post_title' => 'Concurrent queue',
        'post_content' => '<p>alpha concurrent</p>',
        'post_status' => 'publish',
        'post_type' => 'post',
    ];
    $GLOBALS['wp_fts_test_posts'][301] = $post;
    wp_fts_test_seed_queue($fake, [301, 302]);
    $injected = false;
    $GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields'] = static function (array $fields, object $post) use ($fake, &$injected): array {
        if (!$injected && (int) ($post->ID ?? 0) === 301) {
            $injected = true;
            (new WP_FTS_Index_Queue($fake))->enqueue_many([301, 303]);
        }

        return $fields;
    };

    try {
        assert_same(0, WP_FTS_Plugin::process_queue(1), 'a physical write superseded during its batch must not be reported as durably completed queue work');
        assert_same([301, 302, 303], wp_fts_test_queue_ids($fake), 'queue processor should preserve same-post and new-post saves added after its claim');
        assert_true(
            ($fake->queue[301]['state'] ?? '') === 'ready'
                && ($fake->queue[302]['state'] ?? '') === 'ready'
                && ($fake->queue[303]['state'] ?? '') === 'ready',
            'superseding and newly enqueued generations should remain immediately claimable after the stale claim is acknowledged'
        );
    } finally {
        unset($GLOBALS['wp_fts_test_filters']['wp_fts_post_index_fields']);
        $wpdb = $oldWpdb;
    }
});

