test_case('REST search surface filters private results by capability', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    $public = (object) [
        'ID' => 201,
        'post_title' => 'Public shared',
        'post_content' => '<p>alpha shared</p>',
        'post_status' => 'publish',
        'post_type' => 'post',
    ];
    $private = (object) [
        'ID' => 202,
        'post_title' => 'Private shared',
        'post_content' => '<p>alpha shared</p>',
        'post_status' => 'private',
        'post_type' => 'post',
    ];
    $GLOBALS['wp_fts_test_posts'][201] = $public;
    $GLOBALS['wp_fts_test_posts'][202] = $private;

    try {
        WP_FTS_Plugin::register_rest_routes();
        assert_same([], $GLOBALS['wp_fts_test_rest_routes'], 'REST search route should be absent before explicit opt-in');
        $disabled = WP_FTS_Plugin::rest_search(['q' => 'shared']);
        assert_true($disabled instanceof WP_Error, 'direct REST callback dispatch should also reject requests before opt-in');
        assert_same(404, $disabled->get_error_data()['status'] ?? null, 'disabled direct REST dispatch should use a non-disclosing HTTP 404');
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
            WP_FTS_Plugin::default_settings(),
            ['rest_api_enabled' => true]
        );
        WP_FTS_Plugin::register_rest_routes();
        $route = $GLOBALS['wp_fts_test_rest_routes'][0] ?? null;
        assert_same(WP_FTS_Plugin::REST_NAMESPACE, $route['namespace'] ?? null, 'REST registration should use the plugin namespace');
        assert_same(WP_FTS_Plugin::REST_SEARCH_ROUTE, $route['route'] ?? null, 'REST registration should expose the search route');
        assert_true(is_callable($route['args']['callback'] ?? null), 'REST search route should have a callable callback');
        assert_true(is_callable($route['args']['permission_callback'] ?? null), 'REST search route should have a callable permission callback');
        assert_same(false, $route['args']['args']['q']['required'] ?? null, 'REST q parameter should not block the query alias during route validation');
        assert_same(false, $route['args']['args']['query']['required'] ?? null, 'REST query alias should be optional and validated by the callback');
        assert_same(false, $route['args']['args']['explain']['required'] ?? null, 'REST explain parameter should be optional and callback-gated');

        $storage = wp_fts_test_unleased_storage();
        $analyzer = new WP_FTS_Analyzer();
        wp_fts_test_replace_post($storage, $public, [], $analyzer);
        wp_fts_test_replace_post($storage, $private, ['lang' => 'en'], $analyzer);

        assert_same([201], array_column(WP_FTS_Plugin::search('shared', ['limit' => 10]), 'doc_id'), 'public search should hide indexed private posts without read capability');

        $unauthorizedExplain = WP_FTS_Plugin::rest_search(['q' => 'shared', 'limit' => 10, 'explain' => '1']);
        assert_same(
            ['results', 'has_more', 'next_cursor', 'previous_cursor', 'total', 'total_relation', 'query_lang'],
            array_keys($unauthorizedExplain),
            'unauthorized REST explain should keep the public cursor-page shape without diagnostics'
        );
        assert_same([201], array_column($unauthorizedExplain['results'], 'doc_id'), 'unauthorized REST explain should not leak private rows');

        $GLOBALS['wp_fts_test_caps']['read_private_posts'][0] = true;
        $GLOBALS['wp_fts_test_current_user_id'] = 7;
        $ids = array_column(WP_FTS_Plugin::search('shared', [
            'limit' => 10,
            'post_types' => ['post'],
            'post_statuses' => ['publish', 'private'],
        ]), 'doc_id');
        sort($ids, SORT_NUMERIC);
        assert_same([201, 202], $ids, 'the PHP facade should include explicitly requested private posts for users with the broad capability');

        $response = WP_FTS_Plugin::rest_search(['q' => 'shared', 'limit' => 1]);
        assert_same(
            ['results', 'has_more', 'next_cursor', 'previous_cursor', 'total', 'total_relation', 'query_lang'],
            array_keys($response),
            'REST search without explain should expose the bounded cursor-page contract'
        );
        assert_same(1, count($response['results']), 'REST search should honor the request limit');
        assert_same(201, $response['results'][0]['doc_id'] ?? null, 'REST search should remain on its published canonical scope even for an operator');

        $aliasResponse = WP_FTS_Plugin::rest_search(['query' => 'shared', 'limit' => 1]);
        assert_same(1, count($aliasResponse['results']), 'REST search should accept query as an alias for q');

        $emptyQAliasResponse = WP_FTS_Plugin::rest_search(['q' => ' ', 'query' => 'shared', 'limit' => 1]);
        assert_same(1, count($emptyQAliasResponse['results']), 'REST search should use query when q is present but empty');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('PHP search authorizes non-public statuses against each post type capability map', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $wpdb = new WP_FTS_Test_WPDB();
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_post_types']['library_item'] = (object) [
        'public' => true,
        'exclude_from_search' => false,
        'cap' => (object) [
            'edit_others_posts' => 'edit_others_library_items',
            'read_private_posts' => 'read_private_library_items',
        ],
    ];
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['index_post_types' => ['library_item']]
    );
    wp_fts_test_mark_search_takeover_ready();
    // Generic post capabilities must not authorize a CPT that mapped these
    // operations to different primitive capabilities.
    $GLOBALS['wp_fts_test_caps']['edit_others_posts'][0] = true;
    $GLOBALS['wp_fts_test_caps']['read_private_posts'][0] = true;

    try {
        foreach (['draft', 'private'] as $status) {
            $rejected = null;
            try {
                WP_FTS_Plugin::search('capabilityneedle', [
                    'post_types' => ['library_item'],
                    'post_statuses' => [$status],
                ]);
            } catch (InvalidArgumentException $error) {
                $rejected = $error;
            }
            assert_true($rejected instanceof InvalidArgumentException, "generic post capabilities must not authorize {$status} library items");
            assert_contains('non-public', $rejected?->getMessage() ?? '', "the {$status} rejection should identify the protected visibility scope");
        }

        $GLOBALS['wp_fts_test_caps']['edit_others_library_items'][0] = true;
        $GLOBALS['wp_fts_test_caps']['read_private_library_items'][0] = true;
        assert_same([], WP_FTS_Plugin::search('capabilityneedle', [
            'post_types' => ['library_item'],
            'post_statuses' => ['draft', 'private'],
        ]), 'the exact CPT edit/read capabilities should authorize its otherwise empty protected search scope');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('PHP and REST visibility stay exact inside set-oriented ranking', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['rest_api_enabled' => true]
    );

    try {
        $storage = wp_fts_test_unleased_storage();
        $analyzer = WP_FTS_Plugin::runtime_analyzer();
        for ($offset = 0; $offset < 260; $offset++) {
            $postId = 3000 + $offset;
            $post = (object) [
                'ID' => $postId,
                'post_title' => 'Hidden visibility rank ' . $postId,
                'post_content' => '',
                'post_status' => 'private',
                'post_type' => 'post',
            ];
            $GLOBALS['wp_fts_test_posts'][$postId] = $post;
            wp_fts_test_replace_document_fields($storage, $analyzer, $postId, [[
                'name' => 'content',
                'text' => implode(' ', array_fill(0, 20, 'deepvisibilityneedle')),
                'boost' => 1.0,
            ]], [
                'lang' => 'en',
                'metadata' => [
                    'post_id' => $postId,
                    'post_type' => 'post',
                    'post_status' => 'private',
                    'title' => $post->post_title,
                    'search_text' => 'deepvisibilityneedle',
                ],
            ]);
        }

        $publicId = 4000;
        $public = (object) [
            'ID' => $publicId,
            'post_title' => 'Public result below higher-scoring hidden rows',
            'post_content' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
        ];
        $GLOBALS['wp_fts_test_posts'][$publicId] = $public;
        wp_fts_test_replace_document_fields($storage, $analyzer, $publicId, [[
            'name' => 'content',
            'text' => 'deepvisibilityneedle',
            'boost' => 1.0,
        ]], [
            'lang' => 'en',
            'metadata' => [
                'post_id' => $publicId,
                'post_type' => 'post',
                'post_status' => 'publish',
                'title' => $public->post_title,
                'search_text' => 'deepvisibilityneedle',
            ],
        ]);

        assert_same([$publicId], array_column(WP_FTS_Plugin::search('deepvisibilityneedle', ['limit' => 1, 'lang' => 'en']), 'doc_id'), 'PHP search should rank the readable corpus instead of stopping after 250 hidden rows');
        $queryCountBeforeUnsupported = count($fake->queries);
        foreach (['fast_top_k', 'approximate_top_k', 'exact_top_k', 'exact', 'candidate_cap', 'max_candidates'] as $legacyRetrievalOption) {
            $unsupportedRejected = false;
            try {
                WP_FTS_Plugin::search('deepvisibilityneedle', [
                    'limit' => 1,
                    'lang' => 'en',
                    $legacyRetrievalOption => false,
                ]);
            } catch (InvalidArgumentException $error) {
                $unsupportedRejected = str_contains($error->getMessage(), $legacyRetrievalOption);
            }
            assert_true($unsupportedRejected, "removed {$legacyRetrievalOption} option should be rejected instead of silently ignored");
        }
        assert_same($queryCountBeforeUnsupported, count($fake->queries), 'unsupported search options should fail before database work');
        $restResponse = WP_FTS_Plugin::rest_search(['q' => 'deepvisibilityneedle', 'limit' => 1, 'lang' => 'en']);
        assert_true(
            is_array($restResponse),
            'bounded REST search should return a response rather than exhaust its budget: '
                . ($restResponse instanceof WP_Error ? $restResponse->get_error_code() . ' ' . json_encode($restResponse->get_error_data()) : get_debug_type($restResponse))
        );
        assert_same([$publicId], array_column($restResponse['results'] ?? [], 'doc_id'), 'REST visibility should be applied before ranking and LIMIT');

        $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
        $explained = WP_FTS_Plugin::search_with_explain('deepvisibilityneedle', ['limit' => 1, 'lang' => 'en']);
        assert_same('set_oriented_v6', $explained['explain']['storage'] ?? null, 'operator explain should identify the bounded relational storage path');
        assert_same(1, $explained['explain']['logical_group_count'] ?? null, 'operator explain should expose the bounded logical plan');
        assert_same('unknown', $explained['explain']['interactive_total'] ?? null, 'operator explain should not imply an exhaustive total');
        assert_true(($explained['explain']['query_statements'] ?? 99) <= 3, 'operator explain should report no more than three search statements');

        $restExplained = WP_FTS_Plugin::rest_search([
            'q' => 'deepvisibilityneedle',
            'limit' => 1,
            'lang' => 'en',
            'explain' => '1',
        ]);
        assert_true(
            is_array($restExplained),
            'operator REST explain should stay within its fixed work budget: '
                . ($restExplained instanceof WP_Error ? $restExplained->get_error_code() . ' ' . json_encode($restExplained->get_error_data()) : get_debug_type($restExplained))
        );
        assert_same([$publicId], array_column($restExplained['results'] ?? [], 'doc_id'), 'operator REST explain should preserve exact SQL visibility');
        assert_same('set_oriented_v6', $restExplained['explain']['storage'] ?? null, 'REST explain should identify the set-oriented storage path');
        assert_same('unknown', $restExplained['explain']['interactive_total'] ?? null, 'REST explain should preserve unknown interactive totals');

        $rankQueries = array_values(array_filter(
            $fake->prepared,
            static fn(array $statement): bool => str_starts_with($statement['sql'], '/* wp_fts:rank */')
        ));
        assert_same(4, count($rankQueries), 'each supported PHP or REST request should execute one relational ranking statement');
        foreach ($rankQueries as $rankQuery) {
            $sql = (string) ($rankQuery['sql'] ?? '');
            assert_contains('JOIN wp_posts wp_f ON wp_f.ID = ranked.post_id', $sql, 'canonical WordPress visibility should be joined inside ranking');
            assert_contains("wp_f.post_password = ''", $sql, 'password visibility should be checked before LIMIT');
            assert_contains('LEFT JOIN wp_fts_work dirty_f', $sql, 'dirty generations should be excluded inside ranking');
            assert_true(strpos($sql, "wp_f.post_password = ''") < strrpos($sql, 'LIMIT %d'), 'visibility predicates must precede the page LIMIT');
        }
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('REST search explain is operator-gated and filtered to visible rows', function (): void {
    wp_fts_test_with_rest_explain_index(static function (): void {
        $public = WP_FTS_Plugin::rest_search(['q' => 'parityneedle', 'limit' => 10, 'explain' => 'yes']);
        assert_same(
            ['results', 'has_more', 'next_cursor', 'previous_cursor', 'total', 'total_relation', 'query_lang'],
            array_keys($public),
            'public REST explain requests should keep the normal cursor-page contract without diagnostics'
        );
        assert_same([231], array_column($public['results'], 'doc_id'), 'public REST explain should still filter hidden rows');

        $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;
        $operator = WP_FTS_Plugin::rest_search(['q' => 'parityneedle', 'limit' => 10, 'explain' => '1']);
        $explain = is_array($operator['explain'] ?? null) ? $operator['explain'] : [];

        assert_same([231], array_column($operator['results'], 'doc_id'), 'operator REST explain should keep normal visibility filtering');
        assert_same('set_oriented_v6', $explain['storage'] ?? null, 'operator REST explain should identify relational v6 storage');
        assert_same(1, $explain['logical_group_count'] ?? null, 'operator REST explain should expose one bounded logical group');
        assert_true(($explain['resolved_alternatives'] ?? 0) >= 1, 'operator REST explain should expose the bounded resolved alternative count');
        assert_true(($explain['query_statements'] ?? 99) <= 3, 'operator REST explain should report no more than three search statements');
        assert_same('unknown', $explain['interactive_total'] ?? null, 'operator REST explain should preserve the unknown-total contract');
        assert_true(!array_key_exists('results', $explain), 'operator explain should not trigger per-result diagnostic reads');
    });
});

test_case('REST search explain limits diagnostic reads to the requested visible page', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['rest_api_enabled' => true]
    );
    $GLOBALS['wp_fts_test_caps'][WP_FTS_Plugin::ADMIN_CAPABILITY][0] = true;

    try {
        $storage = wp_fts_test_unleased_storage();
        $analyzer = WP_FTS_Plugin::runtime_analyzer();
        for ($post_id = 5001; $post_id <= 5040; $post_id++) {
            $text = implode(' ', array_fill(0, $post_id === 5040 ? 20 : 1, 'broadexplainneedle'));
            $post = (object) [
                'ID' => $post_id,
                'post_title' => 'Public broad explain ' . $post_id,
                'post_content' => '',
                'post_status' => 'publish',
                'post_type' => 'post',
            ];
            $GLOBALS['wp_fts_test_posts'][$post_id] = $post;
            wp_fts_test_replace_document_fields($storage, $analyzer, $post_id, [[
                'name' => 'content',
                'text' => $text,
                'boost' => 1.0,
            ]], [
                'lang' => 'en',
                'metadata' => [
                    'post_id' => $post_id,
                    'post_type' => 'post',
                    'post_status' => 'publish',
                    'title' => $post->post_title,
                    'search_text' => $text,
                ],
            ]);
        }

        $fake->num_queries = 0;
        $response = WP_FTS_Plugin::rest_search([
            'q' => 'broadexplainneedle',
            'limit' => 1,
            'lang' => 'en',
            'explain' => '1',
        ]);
        assert_true(
            is_array($response),
            'one-result operator explain should not exhaust its SQL budget: '
                . ($response instanceof WP_Error ? $response->get_error_code() . ' ' . json_encode($response->get_error_data()) : get_debug_type($response))
        );
        assert_same([5040], array_column($response['results'] ?? [], 'doc_id'), 'operator explain should return the strongest requested row');
        assert_same(2, $response['explain']['query_statements'] ?? null, 'score-only REST explain should use exactly plan plus rank statements');
        assert_true(!array_key_exists('results', $response['explain'] ?? []), 'one-result explain should not issue per-result diagnostic reads');
        assert_true($fake->num_queries <= 3, 'one-result operator explain should stay within the fixed search statement contract');

        $fake->num_queries = 0;
        $max_response = WP_FTS_Plugin::rest_search([
            'q' => 'broadexplainneedle',
            'limit' => 50,
            'lang' => 'en',
            'explain' => '1',
        ]);
        assert_true(
            is_array($max_response),
            'maximum-page operator explain should not exhaust its SQL budget: '
                . ($max_response instanceof WP_Error ? $max_response->get_error_code() . ' ' . json_encode($max_response->get_error_data()) : get_debug_type($max_response))
        );
        $max_result_ids = array_column($max_response['results'] ?? [], 'doc_id');
        assert_same(40, count($max_result_ids), 'maximum-page operator explain should preserve all available visible results');
        assert_same(2, $max_response['explain']['query_statements'] ?? null, 'maximum-page score-only REST explain should still use two statements');
        assert_true(!array_key_exists('results', $max_response['explain'] ?? []), 'maximum-page explain work should remain independent of result count');
        assert_true($fake->num_queries <= 3, 'maximum-page operator explain should stay within the fixed search statement contract');
    } finally {
        $wpdb = $oldWpdb;
    }
});

