test_case('PHP and REST search reject malformed cursor and scalar boundaries before analysis or SQL', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['rest_api_enabled' => true]
    );

    try {
        $preparedBefore = count($fake->prepared);
        foreach ([
            ['q' => ['not-a-scalar'], 'query' => 'fallback-must-not-run'],
            ['q' => 'needle', 'lang' => ['en']],
            ['q' => 'needle', 'limit' => [10]],
            ['q' => 'needle', 'cursor' => ['opaque']],
            ['q' => 'needle', 'direction' => ['after']],
            ['q' => 'needle', 'explain' => ['1']],
        ] as $request) {
            $response = WP_FTS_Plugin::rest_search($request);
            assert_true($response instanceof WP_Error, 'malformed REST search values should return a typed client error');
            assert_same('wp_fts_invalid_search_request', $response->get_error_code(), 'malformed REST values must not silently become defaults or aliases');
            assert_same(400, $response->get_error_data()['status'] ?? null, 'malformed REST values should return HTTP 400');
        }

        foreach ([false, 0, []] as $cursor) {
            $rejected = null;
            try {
                WP_FTS_Plugin::search_page('needle', ['cursor' => $cursor]);
            } catch (InvalidArgumentException $error) {
                $rejected = $error;
            }
            assert_true($rejected instanceof InvalidArgumentException, 'direct search cursors must be strings or null');
        }

        $emptyCursorRejected = null;
        try {
            WP_FTS_Plugin::search_page('', ['cursor' => 'opaque']);
        } catch (InvalidArgumentException $error) {
            $emptyCursorRejected = $error;
        }
        assert_true($emptyCursorRejected instanceof InvalidArgumentException, 'an empty query must not bypass a supplied cursor invariant');
        assert_same($preparedBefore, count($fake->prepared), 'malformed public search boundaries must reject before analyzer-driven or SQL work');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('REST prefix opt-in stays independent and every request remains statement bounded', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['rest_api_enabled' => true, 'rest_prefix_matching' => false]
    );
    $post = (object) [
        'ID' => 401,
        'post_title' => 'REST prefix host',
        'post_content' => '<p>qzxprefixsignal</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-07-01 00:00:00',
    ];
    $GLOBALS['wp_fts_test_posts'][401] = $post;

    try {
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());

        $forcedByClient = WP_FTS_Plugin::rest_search([
            'q' => 'qzxpref',
            'lang' => 'en',
            'prefix_matching' => '1',
        ]);
        assert_same([], $forcedByClient['results'] ?? null, 'an anonymous request must not turn on REST prefix matching by itself');

        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION]['rest_prefix_matching'] = true;
        $enabled = WP_FTS_Plugin::rest_search(['q' => 'qzxpref', 'lang' => 'en']);
        assert_same([401], array_column($enabled['results'] ?? [], 'doc_id'), 'operator REST prefix opt-in should enable the bounded public prefix path');

        $beforeFirst = $fake->num_queries;
        $first = WP_FTS_Plugin::rest_search(['q' => 'qzxprefixsignal', 'lang' => 'en']);
        $firstQueryCount = $fake->num_queries - $beforeFirst;
        $beforeSecond = $fake->num_queries;
        $second = WP_FTS_Plugin::rest_search(['q' => 'qzxprefixsignal', 'lang' => 'en']);
        $secondQueryCount = $fake->num_queries - $beforeSecond;
        assert_same($first, $second, 'a repeated anonymous request should return the same cursor-page shape');
        assert_true($firstQueryCount >= 1 && $firstQueryCount <= 3, 'the first REST search should use no more than three relational statements');
        assert_true($secondQueryCount >= 1 && $secondQueryCount <= 3, 'a repeated REST search should remain bounded without cache bookkeeping queries');

        $post->post_status = 'private';
        $hiddenAfterChange = WP_FTS_Plugin::rest_search(['q' => 'qzxprefixsignal', 'lang' => 'en']);
        assert_same([], $hiddenAfterChange['results'] ?? null, 'each request should apply current canonical visibility inside ranking');

        $post->post_status = 'publish';
        $filterCalls = 0;
        $allowDecoration = false;
        $GLOBALS['wp_fts_test_filters']['wp_fts_search_results'] = static function (array $rows) use (&$filterCalls, &$allowDecoration): array {
            $filterCalls++;
            if (!$allowDecoration) {
                return [];
            }
            $rows[0]['presentation_marker'] = 'decorated';
            return $rows;
        };
        $removalIgnored = WP_FTS_Plugin::rest_search(['q' => 'qzxprefixsignal', 'lang' => 'en']);
        assert_same([401], array_column($removalIgnored['results'] ?? [], 'doc_id'), 'a presentation filter must not remove storage-authorized page members');
        $allowDecoration = true;
        $decorated = WP_FTS_Plugin::rest_search(['q' => 'qzxprefixsignal', 'lang' => 'en']);
        assert_same([401], array_column($decorated['results'] ?? [], 'doc_id'), 'request-dependent presentation filters should run again without a response cache');
        assert_same('decorated', $decorated['results'][0]['presentation_marker'] ?? null, 'same-position rows may receive presentation-only decoration');
        assert_same(2, $filterCalls, 'the presentation filter should run for each bounded request');

        $GLOBALS['wp_fts_test_filters']['wp_fts_search_results'] = static function (array $rows): array {
            return [['doc_id' => 999999, 'score' => PHP_FLOAT_MAX], ...$rows];
        };
        $injectionRejected = WP_FTS_Plugin::rest_search(['q' => 'qzxprefixsignal', 'lang' => 'en']);
        assert_same([401], array_column($injectionRejected['results'] ?? [], 'doc_id'), 'the page filter must discard IDs that relational SQL did not authorize and rank');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('result decoration cannot change ranked membership ordering or cursor traversal', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_mark_search_takeover_ready();
    $posts = [
        411 => (object) [
            'ID' => 411,
            'post_title' => 'Decoration first',
            'post_content' => '<p>stabledecorationsignal</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-07-02 00:00:00',
        ],
        412 => (object) [
            'ID' => 412,
            'post_title' => 'Decoration second',
            'post_content' => '<p>stabledecorationsignal</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-07-01 00:00:00',
        ],
    ];
    $GLOBALS['wp_fts_test_posts'] = $posts;

    try {
        $storage = wp_fts_test_unleased_storage();
        $analyzer = WP_FTS_Plugin::runtime_analyzer();
        foreach ($posts as $post) {
            wp_fts_test_replace_post($storage, $post, ['lang' => 'en'], $analyzer);
        }

        $baseline = WP_FTS_Plugin::search_page('stabledecorationsignal', ['lang' => 'en', 'limit' => 2]);
        $baselineIds = array_column($baseline['results'], 'doc_id');
        $GLOBALS['wp_fts_test_filters']['wp_fts_search_results'] = static fn(array $rows): array => array_reverse($rows);
        $before = $fake->num_queries;
        $reordered = WP_FTS_Plugin::search_page('stabledecorationsignal', ['lang' => 'en', 'limit' => 2]);
        assert_same($baselineIds, array_column($reordered['results'], 'doc_id'), 'a reordered filter return must be ignored as a whole');
        assert_true($fake->num_queries - $before <= 3, 'rejecting reordered decoration must not issue another candidate or refill query');

        $GLOBALS['wp_fts_test_filters']['wp_fts_search_results'] = static function (array $rows): array {
            $rows[0]['score'] = PHP_FLOAT_MAX;
            $rows[0]['presentation_marker'] = 'accepted';
            return $rows;
        };
        $first = WP_FTS_Plugin::search_page('stabledecorationsignal', ['lang' => 'en', 'limit' => 1]);
        assert_same($baselineIds[0], $first['results'][0]['doc_id'] ?? null, 'same-order decoration must preserve the first ranked ID');
        assert_same($baseline['results'][0]['score'] ?? null, $first['results'][0]['score'] ?? null, 'same-order decoration must not replace the storage-owned score');
        assert_same('accepted', $first['results'][0]['presentation_marker'] ?? null, 'same-order decoration may add a presentation field');
        assert_same(true, $first['has_more'] ?? null, 'presentation decoration must preserve storage-owned page continuation');
        assert_true(is_string($first['next_cursor'] ?? null) && $first['next_cursor'] !== '', 'presentation decoration must preserve the opaque next cursor');

        $second = WP_FTS_Plugin::search_page('stabledecorationsignal', [
            'lang' => 'en',
            'limit' => 1,
            'after_cursor' => $first['next_cursor'],
        ]);
        assert_same($baselineIds[1], $second['results'][0]['doc_id'] ?? null, 'cursor traversal must reach the next storage-ranked ID without duplication');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('REST search rejects abusive complexity before bounded relational execution', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['rest_api_enabled' => true]
    );

    try {
        $tooComplex = WP_FTS_Plugin::rest_search([
            'q' => implode(' ', array_map(static fn(int $index): string => 'budgetterm' . $index, range(1, 13))),
            'lang' => 'en',
        ]);
        assert_true($tooComplex instanceof WP_Error, 'an oversized analyzed REST query should return a bounded client error');
        assert_same('wp_fts_query_too_complex', $tooComplex->get_error_code(), 'REST complexity rejection should use a stable error code');
        assert_same(400, $tooComplex->get_error_data()['status'] ?? null, 'REST complexity rejection should carry HTTP 400 status');
        assert_same([], $fake->prepared, 'query analysis and complexity rejection should issue zero SQL');

        $terms = array_map(static fn(int $index): string => 'boundedterm' . $index, range(1, 12));
        $post = (object) [
            'ID' => 402,
            'post_title' => 'Bounded REST plan',
            'post_content' => '<p>' . implode(' ', $terms) . '</p>',
            'post_excerpt' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_date_gmt' => '2026-07-01 00:00:00',
        ];
        $GLOBALS['wp_fts_test_posts'][402] = $post;
        wp_fts_test_replace_post(wp_fts_test_unleased_storage(), $post, ['lang' => 'en'], WP_FTS_Plugin::runtime_analyzer());
        $fake->prepared = [];
        $fake->num_queries = 0;

        $bounded = WP_FTS_Plugin::rest_search(['q' => implode(' ', $terms), 'lang' => 'en']);
        assert_same([402], array_column($bounded['results'] ?? [], 'doc_id'), 'the maximum admitted logical-group query should remain searchable');
        $searchStatements = array_values(array_filter(
            $fake->prepared,
            static fn(array $statement): bool => str_starts_with((string) ($statement['sql'] ?? ''), '/* wp_fts:')
        ));
        assert_same(2, count($searchStatements), 'a maximum-group score-only REST request should execute one plan and one rank statement');
        assert_true(strlen((string) ($searchStatements[1]['sql'] ?? '')) < 65536, 'the maximum admitted query should generate bounded SQL');
        assert_same(null, $bounded['total'] ?? null, 'maximum-group REST search should not run a synchronous total query');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('search integration boundaries fail closed and sanitize REST failures', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    $reset_boundary = static function () use ($fake): void {
        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
            WP_FTS_Plugin::default_settings(),
            ['rest_api_enabled' => true]
        );
        wp_fts_test_mark_search_takeover_ready();
        $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::DEBUG_ENABLED_FILTER] = static fn(mixed $enabled, string $context): bool => true;
        $fake->failReadQueryPrefix = '/* wp_fts:plan */';
    };
    $reset_boundary();

    try {
        $frontendQuery = new WP_FTS_Test_Query(['s' => 'boundaryneedle', 'posts_per_page' => 10, 'post_type' => 'post']);
        assert_same([], WP_FTS_Plugin::replace_frontend_search_posts(null, $frontendQuery), 'an owned frontend FTS failure must not fall through to an unbounded core LIKE search');
        assert_same(0, $frontendQuery->found_posts, 'frontend failure should not install FTS pagination state');
        $frontendTrace = WP_FTS_Plugin::debug_traces()[0] ?? [];
        assert_same('failed', $frontendTrace['status'] ?? null, 'frontend diagnostics should record the bounded integration failure');
        $frontendTraceJson = json_encode($frontendTrace, JSON_THROW_ON_ERROR);
        assert_true(!str_contains($frontendTraceJson, 'SELECT * FROM'), 'frontend failure diagnostics should redact raw SQL');
        assert_true(!str_contains($frontendTraceJson, 'must-not-render'), 'frontend failure diagnostics should redact secret values');
        assert_true(!str_contains($frontendTraceJson, '#0'), 'frontend failure diagnostics should omit stack traces');

        $reset_boundary();
        $GLOBALS['wp_fts_test_is_admin'] = true;
        $GLOBALS['pagenow'] = 'edit.php';
        $adminQuery = new WP_FTS_Test_Query([
            's' => 'boundaryneedle',
            'posts_per_page' => 10,
            'post_type' => 'post',
            'post_status' => 'publish',
        ]);
        assert_same([], WP_FTS_Plugin::replace_admin_post_search_posts(null, $adminQuery), 'an owned wp-admin FTS failure must not fall through to an unbounded core LIKE search');
        assert_same(0, $adminQuery->found_posts, 'wp-admin failure should not install FTS pagination state');
        assert_same('failed', WP_FTS_Plugin::debug_traces()[0]['status'] ?? null, 'wp-admin diagnostics should record the bounded integration failure');

        $reset_boundary();
        $GLOBALS['wp_fts_test_is_admin'] = false;
        unset($GLOBALS['pagenow']);
        $rest = WP_FTS_Plugin::rest_search(['q' => 'boundaryneedle']);
        assert_true($rest instanceof WP_Error, 'REST FTS exceptions should return a WordPress error response');
        assert_same('wp_fts_search_unavailable', $rest->get_error_code(), 'REST failure should use a stable unavailable code');
        assert_same('Search is temporarily unavailable.', $rest->get_error_message(), 'REST failure should expose only a bounded generic message');
        assert_same(503, $rest->get_error_data()['status'] ?? null, 'REST failure should carry HTTP 503 status');
        $restJson = json_encode([
            'code' => $rest->get_error_code(),
            'message' => $rest->get_error_message(),
            'data' => $rest->get_error_data(),
        ], JSON_THROW_ON_ERROR);
        assert_true(!str_contains($restJson, 'SELECT * FROM'), 'REST failure response should not expose raw SQL');
        assert_true(!str_contains($restJson, 'must-not-render'), 'REST failure response should not expose secret values');
        assert_true(strlen($rest->get_error_message()) <= 80, 'REST unavailable message should remain byte bounded');
    } finally {
        $wpdb = $oldWpdb;
    }
});

