        'post_type' => 'post',
    ];
    $GLOBALS['wp_fts_test_posts'][211] = $private;
    $GLOBALS['wp_fts_test_posts'][212] = $passworded;
    $GLOBALS['wp_fts_test_posts'][213] = $excludedType;
    $GLOBALS['wp_fts_test_posts'][214] = $visible;

    try {
        $storage = wp_fts_test_unleased_storage();
        $analyzer = new WP_FTS_Analyzer();
        wp_fts_test_replace_post($storage, $private, ['lang' => 'en'], $analyzer);
        wp_fts_test_replace_post($storage, $passworded, ['lang' => 'en'], $analyzer);
        wp_fts_test_replace_post($storage, $excludedType, ['lang' => 'en'], $analyzer);
        wp_fts_test_replace_post($storage, $visible, ['lang' => 'en'], $analyzer);

        assert_same([214], array_column(WP_FTS_Plugin::search('shared', ['limit' => 1]), 'doc_id'), 'hidden stale rows should not consume the requested visible result limit');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('canonical WP_Post transport shortens large pages before the third bounded query', function (): void {
    wp_fts_test_reset_wordpress_fakes();
    $publishedCapability = $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION] ?? [];
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
    $fake->searchEpoch = 1;
    $fake->searchEpochIncarnation = str_repeat('e', 32);
    $storage = new WP_FTS_Storage_Mysql($fake);
    $key = WP_FTS_TermNamespace::namespace_term('en', 'canonicaltransport');
    $nearLimitBody = str_repeat('x', 2080000);
    $fake->ftsTerms[$key] = ['doc_freq' => 4];
    $fake->postings[$key] = [];
    for ($postId = 1; $postId <= 4; $postId++) {
        $fake->postings[$key][$postId] = 4096;
        $fake->docs[$postId] = [
            'post_id' => $postId,
            'primary_lang' => 'en',
            'doc_len' => 1,
            'content_hash' => 'canonical-transport-' . $postId,
            'snippet_text' => 'canonicaltransport',
            'indexed_at' => time(),
        ];
        $GLOBALS['wp_fts_test_posts'][$postId] = (object) [
            'ID' => $postId,
            'post_author' => 1,
            'post_date' => '2026-07-18 00:00:00',
            'post_date_gmt' => '2026-07-18 00:00:00',
            'post_content' => $nearLimitBody,
            'post_title' => 'Canonical transport ' . $postId,
            'post_excerpt' => '',
            'post_status' => 'publish',
            'comment_status' => 'closed',
            'ping_status' => 'closed',
            'post_password' => '',
            'post_name' => 'canonical-transport-' . $postId,
            'to_ping' => '',
            'pinged' => '',
            'post_modified' => '2026-07-18 00:00:00',
            'post_modified_gmt' => '2026-07-18 00:00:00',
            'post_content_filtered' => '',
            'post_parent' => 0,
            'guid' => 'https://example.test/?p=' . $postId,
            'menu_order' => 0,
            'post_type' => 'post',
            'post_mime_type' => '',
            'comment_count' => 0,
        ];
    }

    $groups = [[['key' => $key, 'rank' => 0]]];
    $options = [
        'query_lang' => 'en',
        'mode' => 'OR',
        'page_size' => 20,
        'post_types' => ['post'],
        'post_statuses' => ['publish'],
        'include_canonical_post_row' => true,
        'explain' => true,
        'search_ready_incarnation' => (string) ($publishedCapability['incarnation'] ?? ''),
        'search_ready_profile_hash' => (string) ($publishedCapability['profile_hash'] ?? ''),
    ];
    $first = $storage->search_page($groups, $options);
    $firstQueries = array_map(
        static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
        $fake->queries
    );

    assert_same([4, 3], array_column($first['results'], 'doc_id'), 'two near-2 MiB canonical rows should fit while the ordered third row is deferred');
    assert_same(true, $first['has_more'] ?? null, 'a byte-shortened canonical page should retain next-page reachability');
    assert_true(is_string($first['next_cursor'] ?? null) && $first['next_cursor'] !== '', 'a byte-shortened canonical page should issue a signed cursor at its last complete row');
    assert_true((int) ($first['explain']['canonical_page_bytes'] ?? 0) <= 4194304, 'reported canonical payload bytes must remain inside the 4 MiB transport bound');
    assert_same($nearLimitBody, $first['results'][0]['_canonical_post_row']['post_content'] ?? null, 'a retained canonical post body must be complete rather than truncated');
    assert_same(3, count($firstQueries), 'large canonical transport should still execute exactly plan, rank, and hydrate statements');
    assert_true(str_starts_with($firstQueries[0] ?? '', '/* wp_fts:plan */'), 'canonical statement one should resolve the bounded dictionary plan');
    assert_true(str_starts_with($firstQueries[1] ?? '', '/* wp_fts:rank */'), 'canonical statement two should rank and measure only its K+1 rows');
    assert_true(str_starts_with($firstQueries[2] ?? '', '/* wp_fts:hydrate */'), 'canonical statement three should hydrate only complete accepted rows');
    assert_contains('OCTET_LENGTH(wp_size.post_content)', $firstQueries[1] ?? '', 'rank SQL should measure the canonical content LOB without selecting it');
    assert_contains('OCTET_LENGTH(wp_size.post_content_filtered)', $firstQueries[1] ?? '', 'rank SQL should include every canonical longtext column in its byte bound');
    assert_contains(") limited ON snapshot.snapshot_ready = 1\nLEFT JOIN wp_posts wp_size ON wp_size.ID = limited.doc_id", $firstQueries[1] ?? '', 'canonical length measurement should sit outside the limited visibility/ranking relation');
    assert_true(!str_contains($firstQueries[1] ?? '', 'wp_size.post_content AS'), 'rank SQL must not transport canonical LOB values before the page is byte-bounded');
    assert_same(2, substr_count($firstQueries[2] ?? '', 'SELECT %d AS post_id'), 'hydration SQL should contain only the two accepted row ids');

    $fake->queries = [];
    $second = $storage->search_page($groups, array_replace($options, ['cursor' => $first['next_cursor']]));
    assert_same([2, 1], array_column($second['results'], 'doc_id'), 'the cursor after a byte-shortened page should reach every deferred canonical row');
    assert_same(false, $second['has_more'] ?? null, 'the second byte-bounded page should finish the four-row fixture');
    assert_same([4, 3, 2, 1], [
        ...array_column($first['results'], 'doc_id'),
        ...array_column($second['results'], 'doc_id'),
    ], 'canonical byte paging must neither omit nor repeat ranked posts');
    assert_same(3, count($fake->queries), 'each adjacent canonical page should retain the exact three-statement ceiling');

    $GLOBALS['wp_fts_test_posts'][4]->post_content = '';
    $GLOBALS['wp_fts_test_posts'][4]->post_content_filtered = str_repeat('y', 4194305);
    $fake->queries = [];
    $afterPoison = $storage->search_page($groups, array_replace($options, ['page_size' => 2]));
    assert_same([3, 2], array_column($afterPoison['results'], 'doc_id'), 'an old oversized canonical row must be skipped without hiding the following ranked page');
    assert_same(true, $afterPoison['has_more'] ?? null, 'skipping an old oversized row must retain a cursor to later valid results');
    assert_true(is_string($afterPoison['next_cursor'] ?? null) && $afterPoison['next_cursor'] !== '', 'the valid boundary after an oversized row must remain cursor-addressable');
    $oversizedQueries = array_map(
        static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
        $fake->queries
    );
    assert_same(3, count($oversizedQueries), 'skipping an oversized first row should retain the plan/rank/hydrate ceiling');
    assert_same(1, count(array_filter($oversizedQueries, static fn(string $sql): bool => str_starts_with($sql, '/* wp_fts:hydrate */'))), 'only complete rows following an oversized result may enter hydration');
    assert_same(2, substr_count($oversizedQueries[2] ?? '', 'SELECT %d AS post_id'), 'the oversized post ID must not enter hydration');

    $fake->queries = [];
    $afterPoisonNext = $storage->search_page($groups, array_replace($options, [
        'page_size' => 2,
        'cursor' => $afterPoison['next_cursor'],
    ]));
    assert_same([1], array_column($afterPoisonNext['results'], 'doc_id'), 'cursor traversal after an oversized top result must reach the remaining valid document');
});

test_case('worker removes oversized canonical rows before they can poison a result page', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    wp_fts_test_mark_search_takeover_ready();
    $posts = [
        621 => (object) [
            'ID' => 621,
            'post_title' => 'Canonical poison candidate',
            'post_content' => '<p>canonicalpoisonsignal</p>',
            'post_excerpt' => '',
            'post_content_filtered' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_password' => '',
            'post_date_gmt' => '2026-07-02 00:00:00',
        ],
        620 => (object) [
            'ID' => 620,
            'post_title' => 'Reachable canonical result',
            'post_content' => '<p>canonicalpoisonsignal</p>',
            'post_excerpt' => '',
            'post_content_filtered' => '',
            'post_status' => 'publish',
            'post_type' => 'post',
            'post_password' => '',
            'post_date_gmt' => '2026-07-01 00:00:00',
        ],
    ];
    $GLOBALS['wp_fts_test_posts'] = $posts;

    try {
        $storage = wp_fts_test_unleased_storage();
        $analyzer = WP_FTS_Plugin::runtime_analyzer();
        foreach ($posts as $post) {
            wp_fts_test_replace_post($storage, $post, ['lang' => 'en'], $analyzer);
        }
        assert_same([621, 620], array_column(WP_FTS_Plugin::search('canonicalpoisonsignal', ['lang' => 'en']), 'doc_id'), 'the valid fixture should start with both canonical rows ranked');

        $posts[621]->post_content_filtered = str_repeat('z', WP_FTS_Storage_Mysql::MAX_CANONICAL_POST_BYTES + 1);
        WP_FTS_Plugin::handle_post_save(621, $posts[621], true);
        assert_same([620], array_column(WP_FTS_Plugin::search('canonicalpoisonsignal', ['lang' => 'en']), 'doc_id'), 'the dirty fence must hide the old derived row before canonical growth is processed');

        $summary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 1]);
        assert_same(1, $summary['permanently_rejected'] ?? null, 'the worker should classify an oversized canonical row as a permanent bounded-source rejection');
        assert_true(!isset($fake->docs[621]), 'the rejecting worker must physically remove the previously indexed document');
        assert_same([], wp_fts_test_queue_ids($fake), 'the rejecting worker must acknowledge the exact dirty generation');
        $before = $fake->num_queries;
        $after = WP_FTS_Plugin::search('canonicalpoisonsignal', ['lang' => 'en']);
        assert_same([620], array_column($after, 'doc_id'), 'the valid result after an oversized canonical row must remain searchable');
        assert_true($fake->num_queries - $before <= 3, 'canonical rejection must not create a refill or retry search loop');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('front-end main query search is replaced with FTS-ranked WP_Post results', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    $low = (object) [
        'ID' => 501,
        'post_title' => 'Lower front-end rank',
        'post_content' => '<p>frontneedle appears once.</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-12 00:00:00',
    ];
    $high = (object) [
        'ID' => 502,
        'post_title' => 'Higher front-end rank',
        'post_content' => '<p>frontneedle frontneedle frontneedle frontneedle.</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-13 00:00:00',
    ];
    $GLOBALS['wp_fts_test_posts'][501] = $low;
    $GLOBALS['wp_fts_test_posts'][502] = $high;

    try {
        wp_fts_test_index_saved_post(501, $low, true);
        wp_fts_test_index_saved_post(502, $high, true);

        $publicResults = WP_FTS_Plugin::search('frontneedle', ['limit' => 10]);
        assert_same([502, 501], array_column($publicResults, 'doc_id'), 'public PHP search should return the indexed fixture before checking its payload contract');
        assert_true(
            !array_key_exists('_canonical_post_row', $publicResults[0] ?? []),
            'public PHP search payloads should never expose the private canonical-row transport'
        );
        $fake->queries = [];
        $fake->prepared = [];

        $query = new WP_FTS_Test_Query([
            's' => 'frontneedle',
            'posts_per_page' => 10,
            'paged' => 1,
            'post_type' => 'post',
        ]);
        WP_FTS_Plugin::prepare_frontend_search_query($query);
        $posts = WP_FTS_Plugin::replace_frontend_search_posts(null, $query);

        assert_same(true, $query->get('wp_fts_search_candidate'), 'pre_get_posts should mark eligible front-end search queries');
        assert_same([502, 501], array_map(static fn(object $post): int => (int) $post->ID, $posts), 'front-end search should return FTS-ranked post objects');
        assert_same(2, $query->found_posts, 'front-end search should expose the FTS visible total on the query');
        assert_same(1, $query->max_num_pages, 'front-end search should expose max pages from the FTS visible total');
        assert_same(2, WP_FTS_Plugin::filter_frontend_search_found_posts(999, $query), 'found_posts filter should preserve the replacement total');
        $searchQueries = array_map(
            static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
            $fake->queries
        );
        assert_same(3, count($searchQueries), 'front-end takeover should use exactly plan, rank, and canonical-row hydration statements');
        assert_true(str_starts_with($searchQueries[0] ?? '', '/* wp_fts:plan */'), 'front-end statement one should resolve the bounded term plan');
        assert_true(str_starts_with($searchQueries[1] ?? '', '/* wp_fts:rank */'), 'front-end statement two should rank the bounded result page');
        assert_true(str_starts_with($searchQueries[2] ?? '', '/* wp_fts:hydrate */'), 'front-end statement three should hydrate snippets and canonical post rows together');
        assert_contains('wp_h.ID AS canonical_post_ID', $searchQueries[2] ?? '', 'front-end hydration should transport canonical rows without a fourth wp_posts query');

        wp_fts_test_begin_frontend_search_loop($query);
        try {
            $excerpt = WP_FTS_Plugin::frontend_search_excerpt('', $posts[0]);
        } finally {
            wp_fts_test_end_frontend_search_loop($query);
        }
        assert_contains('<mark>frontneedle</mark>', $excerpt, 'front-end excerpts should use highlighted FTS snippets in the replaced main loop');
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('SQL diagnostics stream comments literals and qualified relation names within fixed bounds', function (): void {
    $scanMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_scan_sql_summary');
    $scanMethod->setAccessible(true);
    $summaryMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_sql_query_entry_summary');
    $summaryMethod->setAccessible(true);

    $structured = $scanMethod->invoke(
        null,
        "SELECT 'FROM literal_decoy' AS sample /* JOIN comment_decoy */ "
        . 'FROM `fixture_schema`.`wp_fts_terms` term '
        . 'JOIN (SELECT * FROM `wp_fts_postings`) posting ON posting.term_id = term.term_id '
        . 'JOIN `odd``relation` odd ON odd.term_id = term.term_id'
    );
    assert_same(
        ['wp_fts_terms', 'wp_fts_postings', 'odd`relation'],
        $structured['tables'] ?? null,
        'the SQL lexer should ignore comment/literal decoys, unwrap schemas, descend into derived relations, and decode quoted identifiers'
    );

    $create = $scanMethod->invoke(
        null,
        'CREATE TABLE IF NOT EXISTS `fixture_schema`.`wp_fts_work` (job_key VARBINARY(64))'
    );
    assert_same(['wp_fts_work'], $create['tables'] ?? null, 'the SQL lexer should recognize a qualified TABLE IF NOT EXISTS target');

    $mysqlTokens = $scanMethod->invoke(
        null,
        'SELECT 1--not_a_comment FROM wp_fts_documents STRAIGHT_JOIN wp_posts ON wp_posts.ID = wp_fts_documents.post_id'
    );
    assert_same(
        ['wp_fts_documents', 'wp_posts'],
        $mysqlTokens['tables'] ?? null,
        'the SQL lexer should preserve MySQL minus operators and recognize STRAIGHT_JOIN relation targets'
    );

    $relationLists = $scanMethod->invoke(
        null,
        'DROP TABLE IF EXISTS `fixture_schema`.`relation_one`, "relation_two", [relation_three]'
    );
    assert_same(
        ['relation_one', 'relation_two', 'relation_three'],
        $relationLists['tables'] ?? null,
        'the SQL lexer should stream comma-separated MySQL and SQLite relation identifiers'
    );

    $numericSummary = (string) $summaryMethod->invoke(
        null,
        "SELECT 1e9, 0b1011, B'1010', X'CAFE', .5, -12, \"quoted value\" FROM wp_fts_terms"
    );
    foreach (['1e9', '0b1011', '1010', 'CAFE', 'quoted value'] as $literal) {
        assert_true(!str_contains($numericSummary, $literal), "the SQL preview should redact {$literal} without regex parsing");
    }

    $manyJoins = 'SELECT * FROM relation_00';
    for ($index = 1; $index <= 12; $index++) {
        $manyJoins .= ' JOIN relation_' . str_pad((string) $index, 2, '0', STR_PAD_LEFT) . ' USING (id)';
    }
    $capped = $scanMethod->invoke(null, $manyJoins);
    assert_same(8, count($capped['tables'] ?? []), 'SQL diagnostics should retain at most eight distinct relation names');

    $largeLiteral = str_repeat('x', 4 * 1024 * 1024);
    $largeSql = "SELECT '{$largeLiteral}' AS payload FROM wp_fts_documents JOIN wp_posts ON wp_posts.ID = wp_fts_documents.post_id";
    unset($largeLiteral);
    $memoryBefore = memory_get_usage(true);
    $started = microtime(true);
    $large = $scanMethod->invoke(null, $largeSql);
    $elapsed = microtime(true) - $started;
    $memoryGrowth = max(0, memory_get_usage(true) - $memoryBefore);
    assert_same(['wp_fts_documents', 'wp_posts'], $large['tables'] ?? null, 'a multi-megabyte quoted value must not hide later relation names');
    assert_true(strlen((string) ($large['preview'] ?? '')) <= 241, 'the streaming SQL preview must retain at most its fixed 240-byte limit plus truncation sentinel');
    assert_true($memoryGrowth <= 1024 * 1024, 'the streaming SQL lexer should not allocate a second multi-megabyte statement copy');
    assert_true($elapsed < 2.0, 'the streaming SQL lexer should scan a 4 MiB adversarial literal without pathological runtime');

    $summary = (string) $summaryMethod->invoke(null, $largeSql);
    assert_true(strlen($summary) <= 240, 'the rendered SQL diagnostic summary must stay inside 240 bytes');
    assert_contains('wp_fts_documents', $summary, 'the bounded summary should retain a relation found after the long literal');
    assert_true(!str_contains($summary, str_repeat('x', 32)), 'the bounded summary must redact the quoted literal payload');
});

test_case('SQL diagnostics bound the real wpdb query-capture pipeline for multi-megabyte literals', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $captureMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_sql_query_capture_start');
    $captureMethod->setAccessible(true);
    $finishMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_sql_query_finish_summary');
    $finishMethod->setAccessible(true);

    try {
        $fake->queries = [];
        $capture = $captureMethod->invoke(null);
        $largeSql = "SELECT '" . str_repeat('pipeline-secret-', 262144)
            . "' AS payload FROM wp_fts_documents STRAIGHT_JOIN wp_posts ON wp_posts.ID = wp_fts_documents.post_id";
        $fake->queries[] = [$largeSql, 0.001];
        $memoryBefore = memory_get_usage(true);
        $started = microtime(true);
        $summary = $finishMethod->invoke(null, $capture);
        $elapsed = microtime(true) - $started;
        $memoryGrowth = max(0, memory_get_usage(true) - $memoryBefore);

        assert_same(1, $summary['captured_count'] ?? null, 'the real wpdb snapshot pipeline should capture the adversarial query once');
        assert_same(1, $summary['shown_count'] ?? null, 'the real wpdb snapshot pipeline should emit one bounded summary');
        $entry = (string) ($summary['entries'][0]['summary'] ?? '');
        assert_true(strlen($entry) <= 240, 'the end-to-end wpdb SQL summary must stay inside 240 bytes');
        assert_contains('wp_fts_documents|wp_posts', $entry, 'the end-to-end summary should retain relations located after the multi-megabyte literal');
        assert_true(!str_contains($entry, 'pipeline-secret'), 'the end-to-end wpdb SQL summary must not expose the literal');
        assert_true($memoryGrowth <= 2 * 1024 * 1024, "the end-to-end SQL capture should add at most 2 MiB; observed {$memoryGrowth}");
        assert_true($elapsed < 2.0, "the end-to-end SQL capture should scan the adversarial statement within two seconds; observed {$elapsed}");
    } finally {
        $wpdb = $oldWpdb;
    }
});

test_case('SQL diagnostics never inspect overflow query text beyond the eight-entry display cap', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $captureMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_sql_query_capture_start');
    $captureMethod->setAccessible(true);
    $finishMethod = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_sql_query_finish_summary');
    $finishMethod->setAccessible(true);
    $overflow = new class(str_repeat(' ', 4 * 1024 * 1024)) {
        public int $sqlReads = 0;

        /** Stores an oversized SQL payload whose reads the diagnostic cap must avoid. */
        public function __construct(private string $sql)
        {
        }

        /** Advertises only the synthetic query and elapsed fields to the diagnostic reader. */
        public function __isset(string $name): bool
        {
            return in_array($name, ['query', 'elapsed'], true);
        }

        /** Counts access to the oversized SQL payload and exposes synthetic timing. */
        public function __get(string $name): mixed
        {
            if ($name === 'query') {
                $this->sqlReads++;

                return $this->sql;
            }
            if ($name === 'elapsed') {
                return 0.001;
            }

            return null;
        }
    };

    try {
        $fake->queries = [];
        $capture = $captureMethod->invoke(null);
        for ($index = 0; $index < 8; $index++) {
            $fake->queries[] = ['SELECT 1 FROM wp_fts_documents', 0.001];
        }
        for ($index = 0; $index < 12; $index++) {
            $fake->queries[] = $overflow;
        }
        $summary = $finishMethod->invoke(null, $capture);

        assert_same(20, $summary['captured_count'] ?? null, 'overflow SQL diagnostics should retain the exact captured query count');
        assert_same(8, $summary['shown_count'] ?? null, 'overflow SQL diagnostics should render only the first eight query summaries');
        assert_same(true, $summary['more'] ?? null, 'overflow SQL diagnostics should report undisplayed queries');
        assert_float_near(8.0, (float) ($summary['total_time_ms'] ?? -1), 'overflow SQL diagnostics should sum only the bounded displayed timing window');
        assert_same('partial', $summary['timing_relation'] ?? null, 'overflow SQL diagnostics should label displayed timing as partial');
        assert_same(0, $overflow->sqlReads, 'overflow SQL diagnostics must never read or scan query text after the display cap');
    } finally {
        $wpdb = $oldWpdb;
    }
});

