        'm',
        'meta_compare',
        'meta_compare_key',
        'meta_key',
        'meta_query',
        'meta_type',
        'meta_type_key',
        'meta_value',
        'meta_value_num',
        'menu_order',
        'minute',
        'monthnum',
        'name',
        'p',
        'page_id',
        'pagename',
        'ping_status',
        'post__in',
        'post__not_in',
        'post_mime_type',
        'post_name__in',
        'post_parent',
        'post_parent__in',
        'post_parent__not_in',
        'post_password',
        'posts_per_archive_page',
        'sentence',
        'second',
        'search_columns',
        'showposts',
        'subpost',
        'subpost_id',
        'tag',
        'tag__and',
        'tag__in',
        'tag__not_in',
        'tag_id',
        'tag_slug__and',
        'tag_slug__in',
        'tax_query',
        'taxonomy',
        'term',
        'term_id',
        'title',
        'w',
        'year',
    ];

    try {
        $plugin = new ReflectionClass(WP_FTS_Plugin::class);
        $method = $plugin->getMethod('frontend_search_unsupported_constraint_vars');
        $actual = $method->invoke(null);
        sort($expected, SORT_STRING);
        sort($actual, SORT_STRING);
        assert_same($expected, $actual, 'the production unsupported-key inventory should stay aligned with the audited WP_Query membership fixture');

        foreach ($actual as $key) {
            $query = new WP_FTS_Test_Query([
                's' => 'explicitinventoryneedle',
