        WP_FTS_Plugin::default_settings(),
        ['search_provider_compatibility' => 'respect_existing']
    );
    $optionReads = [];
    $GLOBALS['wp_fts_test_after_get_option'] = static function (string $name) use (&$optionReads): void {
        $optionReads[] = $name;
    };
    $GLOBALS['wp_fts_test_get_site_option_calls'] = [];

    $incoming = [
        (object) [
            'ID' => 850,
            'post_title' => 'raw-provider-payload-title-must-not-leak',
            'provider_payload' => [
                'hits' => ['raw-provider-secret-hit'],
            ],
        ],
    ];
    $query = new WP_FTS_Test_Query([
