    assert_same('respect_existing_provider', $settings['provider_compatibility'] ?? null, 'known-provider diagnostics should include the compatibility mode');
    assert_true(!array_key_exists('known_search_providers', $settings), 'hot search traces should not perform provider discovery');
    assert_true(!array_key_exists('known_search_provider_count', $settings), 'hot search traces should not include a provider-discovery count');
