        assert_same(0, $query->query_vars[$queryVar] ?? null, 'missing-trace final ownership query marker should be cleared');
        assert_same([], WP_FTS_Plugin::debug_traces(), 'missing-trace cleanup should not create or mutate diagnostics');
    } finally {
        WP_FTS_Plugin::reset_request_caches();
    }
});

test_case('final ownership request state is bounded with debug trace eviction', function (): void {
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::DEBUG_ENABLED_FILTER] = static fn(mixed $enabled, string $context): bool => true;

    $plugin = new ReflectionClass(WP_FTS_Plugin::class);
    $maxTracesConstant = $plugin->getReflectionConstant('DEBUG_MAX_TRACES');
    assert_true($maxTracesConstant !== false, 'debug trace cap should be reflectable for final ownership eviction coverage');
    $maxTraces = (int) $maxTracesConstant->getValue();
    $queryVarConstant = $plugin->getReflectionConstant('DEBUG_SEARCH_FINAL_OWNERSHIP_QUERY_VAR');
    assert_true($queryVarConstant !== false, 'final ownership query var should be reflectable for stale key coverage');
    $queryVar = (string) $queryVarConstant->getValue();

    $startTrace = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_start_trace');
    $startTrace->setAccessible(true);
    $rememberOwnership = new ReflectionMethod(WP_FTS_Plugin::class, 'debug_remember_search_final_ownership');
    $rememberOwnership->setAccessible(true);
    $ownershipState = new ReflectionProperty(WP_FTS_Plugin::class, 'search_final_ownership_state');
    $ownershipState->setAccessible(true);

    try {
        $traceIds = [];
        $queryKeys = [];
        $queries = [];
        for ($index = 0; $index < $maxTraces + 2; $index++) {
            $traceId = (int) $startTrace->invoke(null, 'frontend search', 'final ownership eviction ' . $index);
            $query = new WP_FTS_Test_Query(['s' => 'final ownership eviction ' . $index]);
            $queries[] = $query;
            $traceIds[] = $traceId;
            $queryKeys[] = spl_object_id($query);
            $rememberOwnership->invoke(null, $query, $traceId, 'language_fts_from_null', [(object) ['ID' => 910 + $index]]);
        }

        $liveTraceIds = [];
        foreach (WP_FTS_Plugin::debug_traces() as $trace) {
            $liveTraceIds[] = (int) ($trace['id'] ?? 0);
        }

        $state = $ownershipState->getValue();
        assert_true(is_array($state), 'final ownership state should remain inspectable after trace eviction');
        assert_same($maxTraces, count($state), 'final ownership state should not grow past the debug trace cap');
        assert_true(!array_key_exists($queryKeys[0], $state), 'final ownership state for the first evicted trace should be removed');
        assert_true(!array_key_exists($queryKeys[1], $state), 'final ownership state for the second evicted trace should be removed');
        foreach ($state as $row) {
            $stateTraceId = is_array($row) && is_numeric($row['trace_id'] ?? null) ? (int) $row['trace_id'] : 0;
            assert_true(in_array($stateTraceId, $liveTraceIds, true), 'final ownership state should only reference live debug traces after eviction');
        }

        $staleQuery = new WP_FTS_Test_Query(['s' => 'stale reused final ownership key', $queryVar => $traceIds[0]]);
        $staleQueryKey = spl_object_id($staleQuery);
        $state[$staleQueryKey] = [
            'trace_id' => $traceIds[0],
            'origin' => 'language_fts_from_null',
            'expected_signature' => [
                'kind' => 'array',
                'count' => 1,
                'post_ids' => [999],
                'hash' => sha1('stale-evicted-trace-fixture'),
                'comparable' => true,
                'reason' => '',
            ],
        ];
        $ownershipState->setValue(null, $state);
        $tracesBeforeStaleObserver = json_encode(WP_FTS_Plugin::debug_traces(), JSON_THROW_ON_ERROR);
        $stalePosts = [(object) ['ID' => 999]];

        assert_same($stalePosts, WP_FTS_Plugin::observe_final_search_posts($stalePosts, $staleQuery), 'stale evicted trace cleanup should keep the observer read-only');

        $stateAfterStaleObserver = $ownershipState->getValue();
        assert_true(is_array($stateAfterStaleObserver) && !array_key_exists($staleQueryKey, $stateAfterStaleObserver), 'stale reused-key state for an evicted trace should be removed');
        assert_same($tracesBeforeStaleObserver, json_encode(WP_FTS_Plugin::debug_traces(), JSON_THROW_ON_ERROR), 'stale reused-key state should not attach old ownership diagnostics to a live trace');

        unset($queries);
    } finally {
        WP_FTS_Plugin::reset_request_caches();
    }
});

test_case('front-end search replacement avoids admin REST cron secondary and disabled queries', function (): void {
    wp_fts_test_reset_wordpress_fakes();
    $query = new WP_FTS_Test_Query(['s' => 'guardneedle', 'posts_per_page' => 10]);

    $GLOBALS['wp_fts_test_is_admin'] = true;
    assert_same(null, WP_FTS_Plugin::replace_frontend_search_posts(null, $query), 'admin searches should not be hijacked');

    $GLOBALS['wp_fts_test_is_admin'] = false;
    $GLOBALS['wp_fts_test_is_rest'] = true;
    assert_same(null, WP_FTS_Plugin::replace_frontend_search_posts(null, $query), 'REST requests should not be hijacked');

    $GLOBALS['wp_fts_test_is_rest'] = false;
    $GLOBALS['wp_fts_test_is_cron'] = true;
    assert_same(null, WP_FTS_Plugin::replace_frontend_search_posts(null, $query), 'cron requests should not be hijacked');

    $GLOBALS['wp_fts_test_is_cron'] = false;
    $secondary = new WP_FTS_Test_Query(['s' => 'guardneedle', 'posts_per_page' => 10], true, false);
    assert_same(null, WP_FTS_Plugin::replace_frontend_search_posts(null, $secondary), 'secondary front-end search queries should not be hijacked');

    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::FRONTEND_SEARCH_REPLACEMENT_FILTER] = static fn(mixed $replace, mixed $filterQuery): bool => false;
    assert_same(null, WP_FTS_Plugin::replace_frontend_search_posts(null, $query), 'site owners should be able to disable front-end replacement by filter');
    unset($GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::FRONTEND_SEARCH_REPLACEMENT_FILTER]);
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        ['replace_frontend_search' => false]
    );
    assert_same(null, WP_FTS_Plugin::replace_frontend_search_posts(null, $query), 'disabled front-end replacement setting should leave the query to WordPress');
});

test_case('admin Posts list search is replaced with FTS-ranked WP_Post results', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $fake->recordReadQueries = true;
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_is_admin'] = true;
    $GLOBALS['pagenow'] = 'edit.php';
    $GLOBALS['wp_fts_test_caps']['edit_others_posts'][0] = true;
    $GLOBALS['wp_fts_test_caps']['edit_published_posts'][0] = true;
    $GLOBALS['wp_fts_test_caps']['read_private_posts'][0] = true;
    $GLOBALS['wp_fts_test_filters'][WP_FTS_Plugin::DEBUG_ENABLED_FILTER] = static fn(mixed $enabled, string $context): bool => $context === 'admin post search';
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SETTINGS_OPTION] = array_replace(
        WP_FTS_Plugin::default_settings(),
        [
            'recency_boost_strength' => 0.35,
            'recency_boost_half_life_days' => 21.0,
            'prefix_min_length' => 3,
        ]
    );

    $low = (object) [
        'ID' => 551,
        'post_title' => 'Lower admin rank',
        'post_content' => '<p>adminneedle appears once.</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-14 00:00:00',
    ];
    $high = (object) [
        'ID' => 552,
        'post_title' => 'Higher admin rank',
        'post_content' => '<p>adminneedle adminneedle adminneedle adminneedle.</p>',
        'post_excerpt' => '',
        'post_status' => 'publish',
        'post_type' => 'post',
        'post_date_gmt' => '2026-06-14 00:00:00',
    ];
    $GLOBALS['wp_fts_test_posts'][551] = $low;
    $GLOBALS['wp_fts_test_posts'][552] = $high;

    try {
        wp_fts_test_index_saved_post(551, $low, true);
        wp_fts_test_index_saved_post(552, $high, true);
        $fake->queries = [];
        $fake->prepared = [];

        $query = new WP_FTS_Test_Query([
            's' => 'adminneedle',
            'posts_per_page' => 10,
            'paged' => 1,
            'post_type' => 'post',
            'post_status' => 'publish',
        ]);
        WP_FTS_Plugin::prepare_admin_post_search_query($query);
        $query->set('fields', 'all');
        $posts = WP_FTS_Plugin::replace_admin_post_search_posts(null, $query);

        assert_same(true, $query->get('wp_fts_admin_post_search_candidate'), 'pre_get_posts should mark eligible admin Posts list searches');
        assert_same([552, 551], array_map(static fn(object $post): int => (int) $post->ID, $posts), 'admin Posts list search should return FTS-ranked post objects');
        assert_same(2, $query->found_posts, 'admin Posts list search should expose the FTS visible total on the query');
        assert_same(1, $query->max_num_pages, 'admin Posts list search should expose max pages from the FTS visible total');
        assert_same(2, WP_FTS_Plugin::filter_admin_post_search_found_posts(999, $query), 'admin found_posts filter should preserve the replacement total');
        $searchQueries = array_map(
            static fn(mixed $query): string => is_array($query) ? (string) ($query[0] ?? '') : (string) $query,
            $fake->queries
        );
        assert_same(3, count($searchQueries), 'admin Posts takeover should use exactly plan, rank, and canonical-row hydration statements');
        assert_true(str_starts_with($searchQueries[0] ?? '', '/* wp_fts:plan */'), 'admin statement one should resolve the bounded term plan');
        assert_true(str_starts_with($searchQueries[1] ?? '', '/* wp_fts:rank */'), 'admin statement two should rank the bounded result page');
        assert_true(str_starts_with($searchQueries[2] ?? '', '/* wp_fts:hydrate */'), 'admin statement three should hydrate snippets and canonical post rows together');
        assert_contains('wp_h.ID AS canonical_post_ID', $searchQueries[2] ?? '', 'admin hydration should transport canonical rows without a fourth wp_posts query');
        $traces = WP_FTS_Plugin::debug_traces();
        assert_same(1, count($traces), 'admin Posts diagnostics should record one run trace');
        $trace = $traces[0];
        assert_same('admin post search', $trace['context'] ?? null, 'admin diagnostics should record the admin search context');
        $explain = is_array($trace['search_explain'] ?? null) ? $trace['search_explain'] : [];
        assert_same('set_oriented_v6', $explain['storage'] ?? null, 'admin diagnostics should identify the compact relational retrieval path');
        assert_same(1, $explain['logical_group_count'] ?? null, 'admin diagnostics should report the bounded logical query shape');
        assert_same(true, $explain['prefix_range'] ?? null, 'admin Posts search should issue one indexed surface range');
        assert_same('surface_range', $explain['prefix_strategy'] ?? null, 'admin Posts search should pass the saved prefix opt-in through one indexed surface range');
        assert_same(3, $explain['query_statements'] ?? null, 'admin diagnostics should confirm the fixed three-statement page path');
        assert_same('unknown', $explain['interactive_total'] ?? null, 'admin diagnostics should not imply an extra exact-total scan');
        assert_contains('350000 * 1814400', $searchQueries[1] ?? '', 'admin ranking SQL should apply the saved recency strength and 21-day half-life inside the rank query');
    } finally {
        $wpdb = $oldWpdb;
    }
});

