            }

            $cli = test_run_subprocess(
                array_merge(
                    [PHP_BINARY, dirname(__DIR__) . '/tools/import-unimorph-lemma-pack.php'],
                    synthetic_qaa_unimorph_import_args($source, $out)
                ),
