        wp_fts_test_reset_wordpress_fakes();
        $GLOBALS['wp_fts_test_upload_dir'] = $uploads;
        $command = new WP_FTS_WPCLI_Command();
        $command->import_lemma_pack([], synthetic_qaa_lemma_tsv_wpcli_assoc_args($source));

