    assert_same(['中', '文', '中文', '搜', '文搜', '中文搜', '索', '搜索', '文搜索', '中文搜索', '日'], $analyzer->analyze_query('中文搜索 日 x', ['query_lang' => 'zh-Hans']), 'CJK n-grams should stream in end-position order and single chars should bypass min length');
});

