test_case('wp cli diagnose format json emits support bundle with status and explain context', function (): void {
    wp_fts_test_with_cli_search_index(static function (WP_FTS_Test_WPDB $fake): void {
        wp_fts_test_prepare_cli_diagnose_operator_context($fake);

        $raw = wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->diagnose(['needle'], [
                'lang' => 'en',
                'limit' => '1',
                'format' => 'json',
            ]);
        });
        $bundle = wp_fts_test_decode_cli_json_object($raw);

        assert_same('wp-fts-query-diagnostic-bundle-v2', $bundle['schema'] ?? null, 'CLI diagnose JSON should expose the cursor-page bundle schema');
        assert_same('wp fts diagnose', $bundle['tool'] ?? null, 'CLI diagnose JSON should identify the WP-CLI tool');
        assert_same('needle', $bundle['query'] ?? null, 'CLI diagnose JSON should include the bounded query string');
        assert_true(is_array($bundle['query_args'] ?? null), 'CLI diagnose JSON should include effective query args');
        assert_true(is_array($bundle['operator_status'] ?? null), 'CLI diagnose JSON should include operator status context');
        assert_true(is_array($bundle['search'] ?? null), 'CLI diagnose JSON should include the explain-enabled search payload');
        assert_true(is_array($bundle['summary'] ?? null), 'CLI diagnose JSON should include a support summary');

        $status = $bundle['operator_status'];
        assert_same('current', $status['schema_status'] ?? null, 'diagnose operator status should include schema state');
        assert_same('physical', $status['schema_verification'] ?? null, 'explicit diagnose should opt into physical schema verification');
        assert_same(true, $status['physical_schema_checked'] ?? null, 'explicit diagnose should label the physical probe boundary');
        assert_same(false, $status['counts_exact'] ?? null, 'explicit diagnose must not scan the corpus for cosmetic counts');
        assert_same(null, $status['eligible_count'] ?? null, 'explicit diagnose should preserve unknown eligible counts');
        assert_same(null, $status['indexed_count'] ?? null, 'explicit diagnose should preserve unknown indexed counts');
        assert_same(null, $status['remaining_count'] ?? null, 'explicit diagnose should preserve unknown remaining counts');
        assert_same('mysql', $status['storage_backend'] ?? null, 'diagnose operator status should include storage backend');
        assert_true(is_array($status['queue_processor_schedule'] ?? null), 'diagnose operator status should include queue schedule diagnostics');
        assert_true(is_array($status['cron_runner'] ?? null), 'diagnose operator status should include cron runner diagnostics');
        assert_true(is_array($status['search_provider_compatibility'] ?? null), 'diagnose operator status should include provider compatibility context');
        assert_true(is_array($status['language_pack_status'] ?? null), 'diagnose operator status should include language-pack context');
        assert_true(is_array($status['latest_batch_diagnostics'] ?? null), 'diagnose operator status should include latest batch diagnostics');

        $search = $bundle['search'];
        assert_true(array_key_exists('total', $search) && $search['total'] === null, 'diagnose search payload should not compute a visible total');
        assert_same('unknown', $search['total_relation'] ?? null, 'diagnose search payload should expose unknown-total semantics');
        assert_same(true, $search['has_more'] ?? null, 'diagnose search payload should include one-row lookahead state');
        assert_same(1, count($search['results'] ?? []), 'diagnose search payload should honor the requested limit');
        assert_true(is_array($search['explain'] ?? null), 'diagnose search payload should force explain diagnostics');
        assert_same('set_oriented_v6', $search['explain']['storage'] ?? null, 'diagnose explain should identify relational search');
        assert_same(3, $search['explain']['query_statements'] ?? null, 'diagnose explain should include planning, ranking, and metadata hydration');

        $summary = $bundle['summary'];
        assert_same(1, $summary['returned_count'] ?? null, 'diagnose summary should include returned count');
        assert_same('unknown', $summary['total_relation'] ?? null, 'diagnose summary should preserve unknown-total semantics');
        assert_same(true, $summary['has_more'] ?? null, 'diagnose summary should expose page lookahead state');
        assert_same(true, $summary['next_cursor_available'] ?? null, 'diagnose summary should report a next cursor without duplicating it');
        assert_same(true, $summary['explain_available'] ?? null, 'diagnose summary should report bounded explain availability');
        assert_same('mysql', $summary['storage_backend'] ?? null, 'diagnose summary should include storage backend');
        assert_same('en', $summary['query_lang'] ?? null, 'diagnose summary should report the one query language partition');
        assert_same('set_oriented_v6', $summary['relational_plan']['storage'] ?? null, 'diagnose summary should identify the flat relational v6 plan');
        assert_same(1, $summary['relational_plan']['logical_group_count'] ?? null, 'diagnose summary should include the bounded logical group count');
        assert_same(3, $summary['relational_plan']['query_statements'] ?? null, 'diagnose summary should include the complete statement count');
        assert_same('unknown', $summary['relational_plan']['interactive_total'] ?? null, 'diagnose summary should identify unknown interactive totals');
        assert_true(array_key_exists('canonical_page_bytes', $summary['relational_plan'] ?? []), 'diagnose summary should include bounded canonical page bytes');
        assert_same(false, $summary['recency_boost']['enabled'] ?? null, 'diagnose summary should report disabled recency without per-document counters');
        assert_true(!array_key_exists('scoring_now_gmt', $summary['recency_boost'] ?? []), 'disabled recency should not manufacture an empty ranking epoch');
        foreach (['visible_total', 'fast_mode', 'candidate_rows_fetched', 'candidate_rows_considered', 'candidate_docs_considered', 'candidate_docs_scored', 'matched_languages', 'scoring', 'query_plan', 'results'] as $legacyField) {
            assert_true(!array_key_exists($legacyField, $summary), 'diagnose summary should omit the removed ' . $legacyField . ' field');
        }
        assert_same('respect_existing', $summary['provider_compatibility']['mode'] ?? null, 'diagnose summary should include provider compatibility mode');
        assert_contains('SearchWP', (string) ($summary['provider_compatibility']['known_provider_summary'] ?? ''), 'diagnose summary should include known provider summary');
        assert_true(is_string($summary['runtime_language_pack_support']['status'] ?? null), 'diagnose summary should include runtime language-pack support');
        assert_same('active', $summary['lock_state'] ?? null, 'diagnose summary should include lock state');
        assert_same(true, $summary['lock_active'] ?? null, 'diagnose summary should include lock active state');
        assert_same(false, $summary['index_stale'] ?? null, 'a successful facade diagnosis should report a ready index');
        assert_same(true, $summary['pending_work'] ?? null, 'diagnose summary should report pending work context');
    });
});

test_case('wp cli diagnose reuses search query options in args and search payload', function (): void {
    wp_fts_test_with_cli_search_index(static function (WP_FTS_Test_WPDB $fake): void {
        wp_fts_test_prepare_cli_diagnose_operator_context($fake);

        $raw = wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->diagnose(['needle'], [
                'lang' => 'en',
                'mode' => 'AND',
                'limit' => '1',
                'offset' => '0',
                'post_status' => 'publish',
                'post_type' => 'post,page',
                'after' => '2026-06-18',
                'before' => '2026-06-19 23:59:59',
                'recency_boost' => '0.5',
                'recency_boost_half_life_days' => '7',
                'prefix_matching' => '1',
                'prefix_min_length' => '3',
                'snippet' => true,
                'format' => 'json',
            ]);
        });
        $bundle = wp_fts_test_decode_cli_json_object($raw);
        $queryArgs = $bundle['query_args'] ?? [];
        $search = $bundle['search'] ?? [];
        $explain = is_array($search['explain'] ?? null) ? $search['explain'] : [];

        assert_same('en', $queryArgs['lang'] ?? null, 'diagnose query args should reuse --lang parsing');
        assert_same('AND', $queryArgs['mode'] ?? null, 'diagnose query args should reuse --mode parsing');
        assert_same(1, $queryArgs['limit'] ?? null, 'diagnose query args should reuse --limit parsing');
        assert_true(!array_key_exists('offset', $queryArgs), 'diagnose query args should not expose offset pagination');
        assert_same(['publish'], $queryArgs['post_status'] ?? null, 'diagnose query args should reuse --post_status parsing');
        assert_same(['post', 'page'], $queryArgs['post_type'] ?? null, 'diagnose query args should reuse --post_type parsing');
        assert_same('2026-06-18', $queryArgs['after'] ?? null, 'diagnose query args should reuse --after parsing');
        assert_same('2026-06-19 23:59:59', $queryArgs['before'] ?? null, 'diagnose query args should reuse --before parsing');
        assert_same('0.5', $queryArgs['recency_boost_strength'] ?? null, 'diagnose query args should expose the effective recency boost strength');
        assert_true(!array_key_exists('recency_boost', $queryArgs), 'diagnose query args should not duplicate the canonical strength under its CLI alias');
        assert_same('7', $queryArgs['recency_boost_half_life_days'] ?? null, 'diagnose query args should reuse recency half-life parsing');
        assert_same(true, $queryArgs['prefix_matching'] ?? null, 'diagnose query args should reuse prefix matching parsing');
        assert_same(3, $queryArgs['prefix_min_length'] ?? null, 'diagnose query args should reuse prefix minimum parsing');
        assert_true(!array_key_exists('prefix_max_terms', $queryArgs), 'diagnose query args should not expose the removed prefix expansion cap');
        assert_same(true, $queryArgs['snippet'] ?? null, 'diagnose query args should reuse snippet parsing');
        assert_same(true, $queryArgs['explain'] ?? null, 'diagnose query args should report forced explain');

        assert_true(!array_key_exists('offset', $search), 'diagnose search payload should not expose offset pagination');
        assert_same('en', $search['query_lang'] ?? null, 'diagnose search payload should receive language');
        assert_same(1, count($search['results'] ?? []), 'diagnose search payload should return the requested page size');
        assert_true(array_key_exists('snippet', $search['results'][0] ?? []), 'diagnose search payload should receive snippet option');
        assert_same(true, $explain['prefix_range'] ?? null, 'diagnose explain should report the indexed final-prefix surface range');
        assert_same('surface_range', $explain['prefix_strategy'] ?? null, 'diagnose explain should report the indexed final-prefix surface range');
        assert_same(3, $explain['query_statements'] ?? null, 'diagnose explain should retain planning, ranking, and metadata hydration');
    });
});

test_case('wp cli diagnose is read only and omits sensitive diagnostic fields', function (): void {
    wp_fts_test_with_cli_search_index(static function (WP_FTS_Test_WPDB $fake): void {
        $before = wp_fts_test_prepare_cli_diagnose_operator_context($fake);

        $raw = wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->diagnose([str_repeat('needle ', 120)], [
                'lang' => 'en',
                'limit' => '1',
                'format' => 'json',
            ]);
        });
        $bundle = wp_fts_test_decode_cli_json_object($raw);
        $encoded = json_encode($bundle, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);

        assert_same('wp-fts-query-diagnostic-bundle-v2', $bundle['schema'] ?? null, 'diagnose read-only test should still emit the cursor-page bundle');
        assert_true(strlen((string) ($bundle['query'] ?? '')) <= 515, 'diagnose should bound very long query strings');
        assert_true(!str_contains($encoded, 'diagnose-token-must-not-render'), 'diagnose JSON should not expose lock tokens');
        assert_true(!str_contains($encoded, 'searchwp/index.php'), 'diagnose JSON should not expose raw provider basenames');
        assert_true(!str_contains($encoded, 'secret-basename.php'), 'diagnose JSON should not expose unknown provider basenames');
        assert_true(!str_contains($encoded, 'raw-provider-payload-must-not-render'), 'diagnose JSON should not expose arbitrary provider option payloads');
        assert_true(!str_contains($encoded, 'SELECT * FROM'), 'diagnose JSON should not expose raw SQL text');
        assert_true(!str_contains($encoded, 'raw_sql'), 'diagnose JSON should not expose raw SQL fields');

        assert_same([], $GLOBALS['wp_fts_test_added_options'], 'diagnose should not add options');
        assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'diagnose should not update options');
        assert_same([], $GLOBALS['wp_fts_test_deleted_options'], 'diagnose should not delete options');
        assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'diagnose should not schedule queue processors');
        assert_same([], $GLOBALS['wp_fts_test_cleared_hooks'], 'diagnose should not clear scheduled queue processors');
        assert_same($before['options'], $GLOBALS['wp_fts_test_options'], 'diagnose should leave options, queue, health, and lock payload unchanged');
        assert_same($before['docs'], $fake->docs, 'diagnose should not create or mutate index docs');
        assert_same($before['terms'], $fake->ftsTerms, 'diagnose should not write terms');
        assert_same($before['postings'], $fake->postings, 'diagnose should not write postings');
        assert_same($before['docLengths'], $fake->docLengths, 'diagnose should not write doc lengths');
        assert_same($before['docMeta'], $fake->docMeta, 'diagnose should not write doc metadata');
        assert_same($before['meta'], $fake->meta, 'diagnose should not write index meta');
        assert_same($before['postRows'], $fake->postRows, 'diagnose should not mutate source post rows');
        assert_same($before['posts'], $GLOBALS['wp_fts_test_posts'], 'diagnose should not create or mutate WordPress posts');
        assert_same([], $fake->queries, 'diagnose should not run schema repair, indexing, reset, delete, or other storage writes');
        assert_same('diagnose-token-must-not-render', $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::INDEX_LOCK_OPTION]['token'] ?? null, 'diagnose should leave the original lock token stored but unrendered');
    });
});

test_case('wp cli diagnose reports punctuation and CJK worst-case complexity before storage', function (): void {
    wp_fts_test_with_cli_search_index(static function (WP_FTS_Test_WPDB $fake): void {
        wp_fts_test_prepare_cli_diagnose_operator_context($fake);
        $queries = [
            implode(',', array_map(static fn(int $term): string => 'token' . $term, range(1, 30))),
            str_repeat('搜索', 20),
        ];

        foreach ($queries as $query) {
            $fake->prepared = [];
            $fake->queries = [];
            $raw = wp_fts_test_capture_cli(static function () use ($query): void {
                (new WP_FTS_WPCLI_Command())->diagnose([$query], [
                    'lang' => 'en',
                    'limit' => '1',
                    'format' => 'json',
                ]);
            });
            $bundle = wp_fts_test_decode_cli_json_object($raw);
            $search = is_array($bundle['search'] ?? null) ? $bundle['search'] : [];

            assert_same($query, $bundle['query'] ?? null, 'diagnose should report the exact bounded input instead of silently searching a shorter punctuation or CJK query');
            assert_same(false, $bundle['query_truncated'] ?? null, 'the under-512-byte worst-case input should not need byte truncation');
            assert_same([], $search['results'] ?? null, 'a rejected diagnostic query should return no misleading partial results');
            assert_true(
                str_starts_with((string) ($search['explain_unavailable_reason'] ?? ''), 'budget_exceeded: '),
                'diagnose should report the stable relational complexity rejection in its support bundle'
            );
            $searchStatements = array_values(array_filter(
                $fake->prepared,
                static fn(array $entry): bool => str_contains((string) ($entry['sql'] ?? ''), 'FROM wp_fts_terms')
                    || str_contains((string) ($entry['sql'] ?? ''), '/* wp_fts:rank */')
            ));
            assert_same([], $searchStatements, 'over-wide punctuation and CJK diagnostics must be rejected before dictionary or ranking SQL');
            assert_same([], $fake->queries, 'complexity reporting must remain read only');
            assert_same([], $GLOBALS['wp_fts_test_updated_options'], 'visitor query complexity must not latch the index as a runtime failure');
            assert_same([], $GLOBALS['wp_fts_test_schedule_calls'], 'visitor query complexity must not schedule schema repair');
        }
    });
});

test_case('wp cli search accepts recency boost ranking options', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
    $fake = new WP_FTS_Test_WPDB();
    $wpdb = $fake;
    wp_fts_test_reset_wordpress_fakes();

    try {
        $storage = wp_fts_test_unleased_storage();
        $analyzer = WP_FTS_Plugin::runtime_analyzer();
        wp_fts_test_replace_document_fields($storage, $analyzer, 1, [['name' => 'content', 'text' => 'needle cli']], [
            'lang' => 'en',
            'metadata' => [
                'post_id' => 1,
                'post_type' => 'post',
                'post_status' => 'publish',
                'post_date_gmt' => '1970-01-01 00:00:00',
                'title' => 'Old CLI needle',
                'search_text' => 'needle cli',
            ],
        ]);
        wp_fts_test_replace_document_fields($storage, $analyzer, 2, [['name' => 'content', 'text' => 'needle cli']], [
            'lang' => 'en',
            'metadata' => [
                'post_id' => 2,
                'post_type' => 'post',
                'post_status' => 'publish',
                'post_date_gmt' => '2999-01-01 00:00:00',
                'title' => 'New CLI needle',
                'search_text' => 'needle cli',
            ],
        ]);
        wp_fts_test_mark_search_takeover_ready();

        $GLOBALS['wp_fts_quality_cli_format_items'] = [];
        (new WP_FTS_WPCLI_Command())->search(['needle'], [
            'query_lang' => 'en',
            'limit' => '2',
            'recency_boost' => '1',
            'recency_boost_half_life_days' => '7',
        ]);
        $formats = $GLOBALS['wp_fts_quality_cli_format_items'] ?? [];
    } finally {
        $wpdb = $oldWpdb;
    }

    assert_same([2, 1], array_column($formats[0]['items'] ?? [], 'doc_id'), 'CLI recency boost options should let the newer equal-score document rank first');
});

test_case('wp cli search accepts prefix minimum aliases and keeps the complete range', function (): void {
    global $wpdb;

    $oldWpdb = $wpdb ?? null;
