test_case_with_pdo_sqlite_fixture('wp cli reindex scopes default admin statuses while later workers keep explicit publish narrow', function (): void {
    $supportedStatuses = ['publish', 'draft', 'pending', 'future', 'private'];
    $fake = new WP_FTS_V4_Regression_SQLite_WPDB();
    wp_fts_v4_regression_create_schema($fake);
    foreach ($supportedStatuses as $index => $status) {
        wp_fts_v4_regression_add_source_post(
            $fake,
            30 + $index,
            '<p>backfill coverage ' . $status . '</p>',
            ucfirst($status) . ' backfill',
            'post',
            $status,
            '2026-03-07 05:06:07'
        );
    }
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;

    wp_fts_quality_with_wpdb($fake, static function (): void {
        wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->reindex([], [
                'lang' => 'en',
                'limit' => '5',
                'format' => 'json',
            ]);
        });
    });

    assert_same([], array_map('intval', $fake->get_col('SELECT post_id FROM wp_fts_documents ORDER BY post_id')), 'default reindex invocation should not index any source post itself');
    $workerRuns = wp_fts_quality_with_wpdb($fake, static function () use ($fake): array {
        return wp_fts_test_drain_manual_index_phases(
            $fake,
            100,
            static fn(): bool => (int) $fake->get_var(
                "SELECT COUNT(*) FROM wp_fts_work WHERE kind IN ('post','scope')"
            ) === 0
        );
    });
    $workerSummaries = array_column($workerRuns, 'summary');
    assert_same([], array_values(array_filter(
        $workerSummaries,
        static fn(array $summary): bool => ($summary['stop_reason'] ?? '') === 'stale_writer_lease_recovered'
    )), 'a fresh default-status scope must never consume a stale-takeover control phase');
    assert_true(max(array_column($workerRuns, 'statement_count')) <= 20, 'every default-status worker phase must stay inside the complete 20-statement ceiling');
    assert_same([30, 31, 32, 33, 34], array_map('intval', $fake->get_col('SELECT post_id FROM wp_fts_documents ORDER BY post_id')), 'later workers should index every selected admin-searchable post');
    $defaultSelects = array_values(array_filter(
        $fake->queries,
        static fn(string $query): bool => str_starts_with($query, '/* wp_fts:filtered-scope-page */')
    ));
    assert_same(1, count($defaultSelects), 'default limited backfill should use one source selector');
    foreach ($supportedStatuses as $status) {
        assert_contains(
            "WHERE p.post_type = 'post' AND p.post_status = '{$status}' AND p.ID > 0",
            $defaultSelects[0],
            'each default admin-searchable status should use one exact composite-index lane'
        );
    }
    $defaultIndexHint = (new WP_FTS_Storage_Mysql($fake))->filtered_scope_index_hint();
    assert_same(5, substr_count($defaultSelects[0], 'p' . $defaultIndexHint), 'all five default status lanes must force the plugin-owned composite source index');

    $publishOnly = new WP_FTS_V4_Regression_SQLite_WPDB();
    wp_fts_v4_regression_create_schema($publishOnly);
    wp_fts_v4_regression_add_source_post($publishOnly, 40, '<p>public coverage</p>', 'Public backfill');
    wp_fts_v4_regression_add_source_post($publishOnly, 41, '<p>draft coverage</p>', 'Draft backfill', 'post', 'draft');
    wp_fts_test_reset_wordpress_fakes();
    $GLOBALS['wp_fts_test_options'][WP_FTS_Plugin::SCHEMA_VERSION_OPTION] = WP_FTS_Plugin::SCHEMA_VERSION;
    wp_fts_quality_with_wpdb($publishOnly, static function (): void {
        wp_fts_test_capture_cli(static function (): void {
            (new WP_FTS_WPCLI_Command())->reindex([], [
                'post_status' => 'publish',
                'post_type' => 'post',
                'lang' => 'en',
                'limit' => '1',
                'format' => 'json',
            ]);
        });
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
        WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
    });

    assert_same([40], array_map('intval', $publishOnly->get_col('SELECT post_id FROM wp_fts_documents ORDER BY post_id')), 'explicit publish-only CLI reindex must not index a draft');
    $publishSelects = array_values(array_filter(
        $publishOnly->queries,
        static fn(string $query): bool => str_starts_with($query, '/* wp_fts:filtered-scope-page */')
    ));
    assert_same(1, count($publishSelects), 'explicit publish-only CLI reindex should use one bounded source selector');
    assert_contains(
        "WHERE p.post_type = 'post' AND p.post_status = 'publish' AND p.ID > 0",
        $publishSelects[0],
        'explicit --post_status=publish should keep one direct public-only composite-index lane'
    );
    assert_same(2, substr_count($publishSelects[0], 'LIMIT 1'), 'the one selected document should bound both its lane and outer merge');
    assert_same(1, substr_count(
        $publishSelects[0],
        'p' . (new WP_FTS_Storage_Mysql($publishOnly))->filtered_scope_index_hint()
    ), 'the publish-only lane must force the plugin-owned composite source index');
});

test_case_with_pdo_sqlite_fixture('wp cli reindex carries plugin runtime analyzer configuration into later workers', function (): void {
