    )), 'a fresh configured-analyzer scope must never consume a stale-takeover control phase');
    assert_true(max(array_column($workerRuns, 'statement_count')) <= 20, 'every configured-analyzer worker phase must stay inside the complete 20-statement ceiling');
    $terms = array_map(
