    assert_true(!in_array('সিনথ000', $terms, true), 'the later shared worker should not fall back to the Bengali baseline when a valid pack is configured');
    assert_same(0, (int) $fake->get_var("SELECT COUNT(*) FROM wp_fts_work WHERE kind IN ('post','scope')"), 'configured analyzer work should be acknowledged after the explicit worker passes');
});

